using System;
using Newtonsoft.Json;
using Skybrud.Essentials.Time;
using Newtonsoft.Json.Linq;

public class SlackConversationTopic
{
    public string Value { get; }
    public string Creator { get; }
    public DateTime LastSet { get; }

    private SlackConversationTopic(string value, string creator, DateTime lastSet)
    {
        Value = value;
        Creator = creator;
        LastSet = lastSet;
    }

    public static SlackConversationTopic Parse(JObject json)
    {
        if (json == null) throw new ArgumentNullException(nameof(json));

        string value = json["topic"]?.ToString();
        string creator = json["creator"]?.ToString();

        if (long.TryParse(json["last_set"]?.ToString(), out long lastSetUnix))
        {
            DateTime lastSet = DateTimeOffset.FromUnixTimeSeconds(lastSetUnix).DateTime;
            return new SlackConversationTopic(value, creator, lastSet);
        }

        throw new JsonException("Invalid last_set value in JSON.");
    }

    public override string ToString()
    {
        return $"Topic: {Value}, Creator: {Creator}, Last Set: {LastSet}";
    }
}

// Example usage
public class Employee
{
    public static void Main()
    {
        string jsonData = @"{
            'topic': 'Weekly Sync',
            'creator': 'U123456',
            'last_set': 1633046400
        }";

        JObject jsonObject = JObject.Parse(jsonData);
        SlackConversationTopic topic = SlackConversationTopic.Parse(jsonObject);

        Console.WriteLine(topic);
    }
}

