namespace Microsoft.CodeAnalysis.Xaml.OrganizeImports
{
    [ExportLanguageService(typeof(IOrganizeImportsService), StringConstants.XamlLanguageName), Shared]
    internal sealed class XamlOrganizeImportsService : IOrganizeImportsService
    {
        private readonly IXamlOrganizeNamespacesService _organizeService;

        [ImportingConstructor]
        public XamlOrganizeImportsService(IXamlOrganizeNamespacesService organizeService)
        {
            _organizeService = organizeService;
        }

        public async Task<Document> OrganizeImportsAsync(Document document, OrganizeImportsOptions options, CancellationToken cancellationToken)
        {
            if (document.Project.Language != StringConstants.XamlLanguageName)
                return document;

            var originalRoot = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
            if (originalRoot == null)
                return document;

            cancellationToken.ThrowIfCancellationRequested();

            var organizedRoot = await _organizeService.OrganizeNamespacesAsync(
                document, originalRoot, options.PlaceSystemNamespaceFirst, cancellationToken).ConfigureAwait(false);

            if (organizedRoot == null || organizedRoot.IsEquivalentTo(originalRoot))
                return document;

            return document.WithSyntaxRoot(organizedRoot);
        }

        public string SortImportsDisplayStringWithAccelerator
            => Resources.XamlOrganizeNamespaces_UI_SortImports;

        public string SortAndRemoveUnusedImportsDisplayStringWithAccelerator
            => Resources.XamlOrganizeNamespaces_UI_SortAndRemove;
    }

    internal interface IXamlOrganizeNamespacesService
    {
        Task<SyntaxNode> OrganizeNamespacesAsync(
            Document document,
            SyntaxNode root,
            bool placeSystemFirst,
            CancellationToken cancellationToken);
    }

    internal static class StringConstants
    {
        public const string XamlLanguageName = "XAML";
    }

    internal static class Resources
    {
        public static string XamlOrganizeNamespaces_UI_SortImports => "Sort XAML _Namespaces";
        public static string XamlOrganizeNamespaces_UI_SortAndRemove => "_Organize XAML Namespaces";
    }
}

using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Localization;
using OrchardCore.Lucene.Drivers;
using OrchardCore.Navigation;

namespace OrchardCore.Lucene
{
    public class AdminMenu : INavigationProvider
    {
        private readonly IStringLocalizer S;

        public AdminMenu(IStringLocalizer<AdminMenu> localizer)
        {
            S = localizer;
        }

        public Task BuildNavigationAsync(string name, NavigationBuilder builder)
        {
            if (!String.Equals(name, "admin", StringComparison.OrdinalIgnoreCase))
            {
                return Task.CompletedTask;
            }

            builder
                .Add(S["Search"], NavigationConstants.AdminMenuSearchPosition, search => search
                    .AddClass("search").Id("search")
                    .Add(S["Indexing"], S["Indexing"].PrefixPosition(), import => import
                        .Add(S["Lucene Indices"], S["Lucene Indices"].PrefixPosition(), indexes => indexes
                            .Action("Index", "Admin", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.ManageIndexes)
                            .LocalNav())
                        .Add(S["Run Lucene Query"], S["Run Lucene Query"].PrefixPosition(), queries => queries
                            .Action("Query", "Admin", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.ManageIndexes)
                            .LocalNav()))
                    .Add(S["Settings"], settings => settings
                        .Add(S["Search"], S["Search"].PrefixPosition(), entry => entry
                             .Action("Index", "Admin", new { area = "OrchardCore.Settings", groupId = LuceneSettingsDisplayDriver.GroupId })
                             .Permission(Permissions.ManageIndexes)
                             .LocalNav()
                        )));

            return Task.CompletedTask;
        }
    }
}

using System;
 
namespace Matrix
{
    class Matrix
    {
        public int[,] dat = new int[3, 3];
 
        public static Matrix transpose_m(Matrix a)
        {
            Matrix out_ = new Matrix();
 
            for (int i = 0; i < 3; i++)
            {
                for (int j = 0; j < 3; j++)
                {
                    out_.dat[i, j] = a.dat[j, i];
                }
            }
 
            return out_;
        }
 
        public void print()
        {
            for (int i = 0; i < 3; i++)
            {
                for (int j = 0; j < 3; j++)
                {
                    Console.Write(dat[i, j] + " ");
                }
                Console.WriteLine();
            }
        }
    }
 
    class Checker
    {
        static void Main(string[] args)
        {
            Matrix a = new Matrix();
            a.dat[0, 0] = 1;
            a.dat[0, 1] = 2;
            a.dat[0, 2] = 3;
            a.dat[1, 0] = 4;
            a.dat[1, 1] = 5;
            a.dat[1, 2] = 6;
            a.dat[2, 0] = 7;
            a.dat[2, 1] = 8;
            a.dat[2, 2] = 9;
 
            Matrix c = Matrix.transpose_m(a);
            c.print();
        }
    }
}

