    {
        await TestKillAfterAsync(1000);
    }

    [Fact]
    public async Task TestKillAfter2SecondsAsync()
    {
        await TestKillAfterAsync(2000);
    }

    [Fact]
    public async Task TestKillAfter5SecondsAsync()
    {
        await TestKillAfterAsync(5000);
    }

    private async Task TestKillAfterAsync(int delay)
    {
        await ResetAsync();
        _process = new Process
        {
            StartInfo = new ProcessStartInfo
            {
                FileName = "dotnet",
                Arguments = $"exec {TestUtils.HostRootPath}",
                RedirectStandardInput = true,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            }
        };

        _process.Start();
        _process.OutputDataReceived += (sender, args) => Console.WriteLine(args.Data);
        _process.BeginOutputReadLine();

        await Task.Delay(delay);
        await TestKill();

        for (int i = 0; i < 5; i++)
        {
            try
            {
                var result = await ExecuteAsync("Console.WriteLine(\"Test after kill\");");
                Assert.Null(result);
            }
            catch (Exception)
            {
                // Expected exceptions after the host is killed
            }
        }
    }

    private async Task TestKill()
    {
        if (_process != null && !_process.HasExited)
        {
            try
            {
                _process.Kill();
                _process.WaitForExit();
            }
            catch (Exception)
            {
                // Ignore exceptions if the process has already exited
            }
        }
    }

