using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace RosettaCode
{
    class Stack
    {
        static void Main(string[] args)
        {
            Func<TimeSpan, double> TimeToDegrees = (time) =>
                360 * time.Hours / 24.0 +
                360 * time.Minutes / (24 * 60.0) +
                360 * time.Seconds / (24 * 3600.0);
            Func<List<double>, double> MeanAngle = (angles) =>
                {
                    double y_part = 0.0d, x_part = 0.0d;
                    int numItems = angles.Count;
 
                    for (int i = 0; i < numItems; i++)
                    {
                        x_part += Math.Cos(angles[i] * Math.PI / 180);
                        y_part += Math.Sin(angles[i] * Math.PI / 180);
                    }
 
                    return Math.Atan2(y_part / numItems, x_part / numItems) * 180 / Math.PI;
                };
            Func<double, TimeSpan> TimeFromDegrees = (angle) =>
                    new TimeSpan(
                        (int)(24 * 60 * 60 * angle / 360) / 3600,
                        ((int)(24 * 60 * 60 * angle / 360) % 3600 - (int)(24 * 60 * 60 * angle / 360) % 60) / 60,
                        (int)(24 * 60 * 60 * angle / 360) % 60);
            List<double> digitimes = new List<double>();
            TimeSpan digitime;
            string input;
 
            Console.WriteLine("Enter times, end with no input: ");
            do
            {
                input = Console.ReadLine();
                if (!(string.IsNullOrWhiteSpace(input)))
                {
                    if (TimeSpan.TryParse(input, out digitime))
                        digitimes.Add(TimeToDegrees(digitime));
                    else
                        Console.WriteLine("Seems this is wrong input: ignoring time");
                }
            } while (!string.IsNullOrWhiteSpace(input));
 
            if(digitimes.Count() > 0)
                Console.WriteLine("The mean time is : {0}", TimeFromDegrees(360 + MeanAngle(digitimes)));
        }
    }
}

using System;
using System.Linq;
 
class Checker
{
    static double Horner(double[] coefficients, double variable)
    {
        return coefficients.Reverse().Aggregate(
                (accumulator, coefficient) => accumulator * variable + coefficient);
    }
 
    static void Main()
    {
        Console.WriteLine(Horner(new[] { -19.0, 7.0, -4.0, 6.0 }, 3.0));
    }
}

using System;
using System.Windows.Forms;
using Kitware.VTK;

namespace DEMVisualization
{
    public partial class MainForm : Form
    {
        private vtkRenderer renderer;
        private vtkRenderWindow renderWindow;
        private vtkDEMReader demReader;
        private vtkLookupTable lookupTable;
        private vtkImageMapToColors colorMapper;
        private vtkImageActor imageActor;

        public MainForm()
        {
            InitializeComponent();
            InitializeVTKComponents();
        }

        private void InitializeVTKComponents()
        {
            try
            {
                renderer = vtkRenderer.New();
                renderWindow = renderWindowControl1.RenderWindow;
                renderWindow.AddRenderer(renderer);

                demReader = vtkDEMReader.New();
                SetFileName(@"C:\VTK_Data\sainte_helens.dem");
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Initialization Error: {ex.Message}", "VTK Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void SetFileName(string filePath)
        {
            try
            {
                demReader.SetFileName(filePath);
                demReader.Update();

                ConfigureLookupTable();
                CreateColorMapping();
                RenderTerrain();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"File Loading Error: {ex.Message}", "DEM Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private void ConfigureLookupTable()
        {
            lookupTable = vtkLookupTable.New();
            lookupTable.SetTableRange(demReader.GetOutput().GetScalarRange());
            lookupTable.SetHueRange(0.6, 0.0);
            lookupTable.SetSaturationRange(1.0, 1.0);
            lookupTable.SetValueRange(1.0, 1.0);
            lookupTable.Build();
        }

        private void CreateColorMapping()
        {
            colorMapper = vtkImageMapToColors.New();
            colorMapper.SetLookupTable(lookupTable);
            colorMapper.SetInputConnection(demReader.GetOutputPort());
            colorMapper.Update();

            imageActor = vtkImageActor.New();
            imageActor.SetInputConnection(colorMapper.GetOutputPort());
        }

        private void RenderTerrain()
        {
            renderer.AddActor(imageActor);
            renderer.SetBackground(0.1, 0.2, 0.4);
            renderer.ResetCamera();

            renderWindow.Render();
        }

