using System;
using System.Diagnostics;
using System.Threading;
 
public class TimeIt
{
    public static void Main(string[] args)
    {
        var threadMX = new ThreadMXBean();
        assert threadMX.isCurrentThreadCpuTimeSupported();
        threadMX.setThreadCpuTimeEnabled(true);
 
        long start, end;
        start = threadMX.getCurrentThreadCpuTime();
        countTo(100000000);
        end = threadMX.getCurrentThreadCpuTime();
        Console.WriteLine("Counting to 100000000 takes "+(end-start)/1000000+"ms");
        start = threadMX.getCurrentThreadCpuTime();
        countTo(1000000000L);
        end = threadMX.getCurrentThreadCpuTime();
        Console.WriteLine("Counting to 1000000000 takes "+(end-start)/1000000+"ms");
 
    }
 
    public static void countTo(long x){
        Console.WriteLine("Counting...");
        for(long i=0;i<x;i++);
        Console.WriteLine("Done!");
    }
}
 
