using System;

class DiamondTrolls
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        int width = 2 * n - 1;
        int height = 2 * n - 1;
        int topDots = n - 1;
        int heightTop = n - 2;
        int secondDots = 1;
        int bottomDots = 1;

        // Top section
        Console.WriteLine(new string('.', topDots) + new string('*', n) + new string('.', topDots));

        // Middle section
        for (int i = 0; i < heightTop; i++)
        {
            Console.WriteLine(new string('.', topDots - i - 1) + "*" + new string('.', secondDots) + "*" + new string('.', secondDots) + "*" + new string('.', topDots - i - 1));
            secondDots += 2;
        }

        // Full-width row
        Console.WriteLine(new string('*', width));

        // Bottom section
        secondDots -= 4;
        for (int i = 0; i < heightTop; i++)
        {
            Console.WriteLine(new string('.', bottomDots + i) + "*" + new string('.', secondDots) + "*" + new string('.', secondDots) + "*" + new string('.', bottomDots + i));
            secondDots -= 2;
        }

        // Final row
        Console.WriteLine(new string('.', width / 2) + "*" + new string('.', width / 2));
    }
}

public class HttpSendTransportProvider : ISendTransportProvider
{
    private readonly IHttpClientCache _clientCache;
    private readonly IBusHostCollection _hostCollection;
    private readonly IReceivePipelineBuilder _receivePipelineBuilder;
    private readonly IHttpTransportObserver _transportObserver;

    public HttpSendTransportProvider(
        IHttpClientCache clientCache,
        IBusHostCollection hostCollection,
        IReceivePipelineBuilder receivePipelineBuilder,
        IHttpTransportObserver transportObserver)
    {
        _clientCache = clientCache;
        _hostCollection = hostCollection;
        _receivePipelineBuilder = receivePipelineBuilder;
        _transportObserver = transportObserver;
    }

    public async Task<ISendTransport> GetSendTransport(Uri address)
    {
        var host = GetHost(address);
        var sendSettings = GetSendSettings(address);

        var transport = CreateHttpSendTransport(host, sendSettings);

        await _transportObserver.NotifyTransportCreated(transport);

        return transport;
    }

    private HttpHost GetHost(Uri address)
    {
        return _hostCollection.GetHost(address) ?? throw new HttpTransportException($"No host found for {address}");
    }

    private HttpSendSettings GetSendSettings(Uri address)
    {
        return new HttpSendSettings
        {
            Endpoint = address.AbsolutePath,
            Host = address.Host,
            BaseAddress = new Uri($"{address.Scheme}://{address.Host}")
        };
    }

    private ISendTransport CreateHttpSendTransport(HttpHost host, HttpSendSettings sendSettings)
    {
        var httpClient = _clientCache.GetClient(host);
        var pipeline = _receivePipelineBuilder.Build();

        return new HttpSendTransport(
            httpClient,
            pipeline,
            sendSettings,
            _transportObserver
        );
    }
}

