{
    class Account
    {
        static void Main(string[] args)
        {
            // Ludic() is so quick we just call it repeatedly
            Console.WriteLine("First 25: " + string.Join(", ", Ludic(25, -1)));
            Console.WriteLine("Numner of Ludics below 1000: " + Ludic(-1, 1000).Length);
            Console.WriteLine("Ludic 2000 to 2005: " + string.Join(", ", Ludic(2005, -1).Skip(1999)));
 
            Console.Write("Tripples below 250:");
            var x = Ludic(-1, 250);
            for (int i = 0; i < x.Length - 2; i++)
            {
                if (has(x.Skip(i + 1), x[i] + 2) && has(x.Skip(i + 2), x[i] + 6))
                {
                    Console.Write(", ({0} {1} {2})", x[i], x[i] + 2, x[i] + 6);
                }
            }
            Console.WriteLine();
        }
 
        // Ludic returns a slice of Ludic numbers stopping after
        // either n entries or when max is exceeded.
        // Either argument may be <=0 to disable that limit.
        static uint[] Ludic(int n, int max)
        {
            const int maxInt32 = 1 << 31 - 1; // i.e. math.MaxInt32
            if (max > 0 && n < 0)
            {
                n = maxInt32;
            }
            if (n < 1)
            {
                return null;
            }
            if (max < 0)
            {
                max = maxInt32;
            }
            var sieve = new uint[10760]; // XXX big enough for 2005 Ludics
            sieve[0] = 1;
            sieve[1] = 2;
            if (n > 2)
            {
                // We start with even numbers already removed
                for (int i = 2, j = 3; i < sieve.Length; i++, j += 2)
                {
                    sieve[i] = (uint)j;
                }
                // We leave the Ludic numbers in place,
                // k is the index of the next Ludic
                for (int k = 2; k < n; k++)
                {
                    var l = sieve[k];
                    if (l >= max)
                    {
                        n = k;
                        break;
                    }
                    var i = l;
                    l--;
                    // last is the last valid index
                    var last = k + i - 1;
                    for (var j = k + i + 1; j < sieve.Length; i++, j++)
                    {
                        last = k + i;
                        sieve[last] = sieve[j];

