            : base(level, player)
        {
            spriteX = 0;
            Health = MaxHealth = 100;
            Width = 2;
            Height = 2;
            Sprite = Resources.SPRITE_STORE;
        }

        public override void OnFocus()
        {
            base.OnFocus();
            menu = new GuiStoreMenu(this);
            Game.GuiManager.AddGui(menu);
        }

        public override void OnFocusLost()
        {
            base.OnFocusLost();
            if (menu != null)
            {
                Game.GuiManager.RemoveGui(menu);
                menu = null;
            }
        }

        public void SellWood()
        {
            if (Player.Resources.Lumber > 0)
            {
                Player.Resources.Lumber--;
                Player.Resources.Coins += COINS_FOR_LUMBER;
            }
        }

        public override void Remove()
        {
            base.Remove();
            if (menu != null)
            {
                Game.GuiManager.RemoveGui(menu);
                menu = null;
            }
        }

        public override void Render(Viewport viewport)
        {
            base.Render(viewport);
            int x = (int)(Position.X * Tile.TILE_WIDTH - viewport.X);
            int y = (int)(Position.Y * Tile.TILE_HEIGHT - viewport.Y);
            Renderer.DrawSprite(Sprite, x, y, spriteX, 0, Tile.TILE_WIDTH, Tile.TILE_HEIGHT);
        }
    }

