using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Cors.Infrastructure;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Configure CORS policies
        services.AddCors(options =>
        {
            // Default policy allowing any origin, method, and header
            options.AddDefaultPolicy(builder =>
            {
                builder.AllowAnyOrigin()
                       .AllowAnyMethod()
                       .AllowAnyHeader();
            });

            // Policy for a specific origin with credentials
            options.AddPolicy("SpecificOriginWithCredentials", builder =>
            {
                builder.WithOrigins("https://example.com")
                       .AllowAnyMethod()
                       .AllowAnyHeader()
                       .AllowCredentials();
            });

            // Policy for a specific origin with restricted methods
            options.AddPolicy("RestrictedMethods", builder =>
            {
                builder.WithOrigins("https://api.example.com")
                       .WithMethods("GET", "POST")
                       .WithHeaders("Content-Type", "Authorization");
            });
        });

        // Add MVC services
        services.AddMvc();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        // Use custom middleware for culture replacement
        app.UseCultureReplacer();

        // Enable CORS with the default policy
        app.UseCors();

        // Enable CORS with a specific policy
        app.UseCors("SpecificOriginWithCredentials");

        // Configure MVC routing
        app.UseRouting();
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}

