namespace Checker
{
    class Shape
    {
        static void Main(string[] args)
        {
            string[] values = new string[3];
            string tempStr;
            double[] val = new double[3];
            int i, j, isString = 0;
 
            for (i = 0; i < 3; i++)
            {
                Console.Write("Enter {0}{1} value : ", i + 1, (i == 0)? "st" : ((i == 1)? "nd" : "rd"));
                values[i] = Console.ReadLine();
 
                for (j = 0; values[i][j]!= 00; j++)
                {
                    if (((values[i][j] < '0' || values[i][j] > '9') && (values[i][j]!= '.' || values[i][j]!= '-' || values[i][j]!= '+'))
                    || ((values[i][j] == '.' || values[i][j] == '-' || values[i][j] == '+') && (values[i][j + 1] < '0' || values[i][j + 1] > '9')))
                        isString = 1;
                }
            }
 
            if (isString == 0)
            {
                for (i = 0; i < 3; i++)
                    val[i] = Convert.ToDouble(values[i]);
            }
 
            for (i = 0; i < 3 - 1; i++)
            {
                for (j = i + 1; j < 3; j++)
                {
                    if (isString == 0 && val[i] > val[j])
                    {
                        double temp = val[j];
                        val[j] = val[i];
                        val[i] = temp;
                    }
 
                    else if (values[i][0] > values[j][0])
                    {
                        tempStr = values[j];
                        values[j] = values[i];
                        values[i] = tempStr;
                    }
                }
            }
 
            for (i = 0; i < 3; i++)
                isString == 1? Console.WriteLine("{0} = {1}", (char)('X' + i), values[i]) : Console.WriteLine("{0} = {1}", (char)('X' + i), val[i]);
 
            Console.ReadLine();
        }
    }
}

