    class Cache
    {
        // Dictionary to store cipher mappings: key is non-letter sequence, value is a letter.
        static Dictionary<string, char> cipherMapping = new Dictionary<string, char>();

        // List to store all possible decoded messages.
        static List<string> decodedMessages = new List<string>();

        static void Main(string[] args)
        {
            // Read input message and cipher definition.
            string message = Console.ReadLine();
            string cipherDefinition = Console.ReadLine();

            // Parse the cipher definition.
            // Expected pattern: Each mapping begins with a letter (the decoded value)
            // followed by a sequence of non-letter characters (the key).
            int i = 0;
            while (i < cipherDefinition.Length)
            {
                // Expect a letter as the value.
                if (!Char.IsLetter(cipherDefinition[i]))
                {
                    i++;
                    continue;
                }
                char mappedLetter = cipherDefinition[i];
                i++;

                // Build the key: sequence of non-letter characters.
                StringBuilder keyBuilder = new StringBuilder();
                while (i < cipherDefinition.Length && !Char.IsLetter(cipherDefinition[i]))
                {
                    keyBuilder.Append(cipherDefinition[i]);
                    i++;
                }
                string key = keyBuilder.ToString();
                if (!string.IsNullOrEmpty(key))
                {
                    // In case there are duplicate keys, we assume first mapping is used.
                    if (!cipherMapping.ContainsKey(key))
                    {
                        cipherMapping.Add(key, mappedLetter);
                    }
                }
            }

            // Start recursive decoding.
            DecodeMessage(message, 0, new StringBuilder());

            // Sort the list of decoded messages.
            decodedMessages = decodedMessages.Distinct().ToList();
            decodedMessages.Sort();

            // Output the result: first line is the total number of valid decodings.
            Console.WriteLine(decodedMessages.Count);
            foreach (var decoded in decodedMessages)
            {
                Console.WriteLine(decoded);
            }
        }

