public struct CellInfo
{
    public short TraversalCost;
    public CellStatus Status;

    public CellInfo(short defaultCost, CellStatus status)
    {
        TraversalCost = defaultCost;
        Status = status;
    }
}

public enum CellStatus { Unvisited, Open, Closed }

public sealed class CellInfoLayerPool
{
    private const int MaxPoolSize = 100;
    private readonly Stack<CellLayer<CellInfo>> pool = new Stack<CellLayer<CellInfo>>();
    private readonly CellLayer<CellInfo> defaultLayer;
    private readonly object syncRoot = new object();

    public CellInfoLayerPool(Size mapSize, MapGridType gridType)
    {
        defaultLayer = new CellLayer<CellInfo>(gridType, mapSize);
        defaultLayer.Initialize(c => new CellInfo(short.MaxValue, CellStatus.Unvisited));
    }

    public PooledCellInfoLayer Get()
    {
        lock (syncRoot)
        {
            CellLayer<CellInfo> layer;
            if (pool.Count > 0)
            {
                layer = pool.Pop();
            }
            else
            {
                layer = new CellLayer<CellInfo>(defaultLayer.GridType, defaultLayer.Size);
                layer.CopyValuesFrom(defaultLayer);
            }

            return new PooledCellInfoLayer(this, layer);
        }
    }

    private void ReleaseLayer(CellLayer<CellInfo> layer)
    {
        lock (syncRoot)
        {
            if (pool.Count < MaxPoolSize)
            {
                layer.CopyValuesFrom(defaultLayer);
                pool.Push(layer);
            }
        }
    }

    public sealed class PooledCellInfoLayer : IDisposable
    {
        private CellInfoLayerPool pool;
        private CellLayer<CellInfo> layer;

        public CellLayer<CellInfo> Layer => layer;

        internal PooledCellInfoLayer(CellInfoLayerPool pool, CellLayer<CellInfo> layer)
        {
            this.pool = pool;
            this.layer = layer;
        }

        public void Dispose()
        {
            if (pool != null)
            {
                pool.ReleaseLayer(layer);
                pool = null;
                layer = null;
            }
        }
    }
}

