using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace TaxCalculatorTests
{
    public class Produto
    {
        public decimal ValorProduto { get; set; }
        public int QuantidadeProduto { get; set; }
        public decimal PercentualPis { get; set; }
        public decimal ValorIpi { get; set; }

        public Produto(decimal valorProduto, int quantidadeProduto, decimal percentualPis, decimal valorIpi)
        {
            ValorProduto = valorProduto;
            QuantidadeProduto = quantidadeProduto;
            PercentualPis = percentualPis;
            ValorIpi = valorIpi;
        }
    }

    public class FacadeCalculadoraTributacao
    {
        public decimal CalculaPis(Produto produto)
        {
            decimal baseCalculo = produto.ValorProduto * produto.QuantidadeProduto;
            decimal valorIpi = produto.ValorIpi > 0 ? produto.ValorIpi : 0;
            decimal totalBase = baseCalculo + valorIpi;
            return totalBase * (produto.PercentualPis / 100);
        }
    }

    [TestClass]
    public class TaxCalculatorUnitTests
    {
        private FacadeCalculadoraTributacao calculadoraTributacao;

        [TestInitialize]
        public void Setup()
        {
            calculadoraTributacao = new FacadeCalculadoraTributacao();
        }

        [TestMethod]
        public void TesteCalculoPisSemIpi()
        {
            // Arrange
            var produto = new Produto(100m, 2, 1.65m, 0m);
            decimal expectedPis = 3.30m; // (100 * 2) * 1.65%

            // Act
            var resultado = calculadoraTributacao.CalculaPis(produto);

            // Assert
            Assert.AreEqual(expectedPis, resultado);
        }

        [TestMethod]
        public void TesteCalculoPisComIpi()
        {
            // Arrange
            var produto = new Produto(100m, 2, 1.65m, 20m);
            decimal expectedPis = 4.30m; // ((100 * 2) + 20) * 1.65%

            // Act
            var resultado = calculadoraTributacao.CalculaPis(produto);

            // Assert
            Assert.AreEqual(expectedPis, resultado);
        }

        [TestMethod]
        public void TesteCalculoPisComIpiZero()
        {
            // Arrange
            var produto = new Produto(50m, 3, 1.65m, 0m);
