using System;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;

public class FormattedSlider : Slider
{
    private string _autoToolTipFormat;
    private ToolTip _autoToolTip;

    public string AutoToolTipFormat
    {
        get { return _autoToolTipFormat; }
        set { _autoToolTipFormat = value; }
    }

    public FormattedSlider()
    {
        Loaded += OnLoaded;
    }

    private void OnLoaded(object sender, RoutedEventArgs e)
    {
        FieldInfo field = typeof(Slider).GetField("_autoToolTip", BindingFlags.NonPublic | BindingFlags.Instance);
        if (field != null)
        {
            _autoToolTip = field.GetValue(this) as ToolTip;
        }
    }

    protected override void OnThumbDragStarted(DragStartedEventArgs e)
    {
        base.OnThumbDragStarted(e);
        FormatAutoToolTipContent();
    }

    protected override void OnThumbDragDelta(DragDeltaEventArgs e)
    {
        base.OnThumbDragDelta(e);
        FormatAutoToolTipContent();
    }

    private void FormatAutoToolTipContent()
    {
        if (_autoToolTip != null && _autoToolTipFormat != null)
        {
            if (_autoToolTip.Content != null)
            {
                try
                {
                    _autoToolTip.Content = string.Format(_autoToolTipFormat, Value);
                }
                catch (FormatException ex)
                {
                    Console.WriteLine($"Error formatting tooltip: {ex.Message}");
                    // Optionally, provide a default format or handle the error gracefully
                    _autoToolTip.Content = Value.ToString(); // Fallback to default string conversion
                }
            }
        }
    }
}

