namespace Roslyn.VisualStudio.IntegrationTests.VisualBasic
{
    public class BasicKeywordHighlighting : AbstractEditorTest
    {
        protected override string LanguageName => LanguageNames.VisualBasic;

        public BasicKeywordHighlighting()
            : base(nameof(BasicKeywordHighlighting))
        {
        }

        [WpfFact, Trait(Traits.Feature, Traits.Features.Classification)]
        public async Task NavigationBetweenKeywords()
        {
            VisualStudio.Editor.SetText(@"
Module Module1
    Sub Main()
        For i As Integer = 1 To 10
            For j As Integer = 1 To 5
                For k As Integer = 1 To 3
                    If i > 5 Then
                        Console.WriteLine(""Hello"")
                    End If
                Next k
            Next j
        Next i
    End Sub
End Module");

            VisualStudio.Editor.MoveCaret(3, 25);
            await VisualStudio.Workspace.WaitForAsyncOperationsAsync(FeatureAttribute.Classification, HangMitigatingCancellationToken);

            Verify(3);

            VisualStudio.ExecuteCommand("Edit.NextHighlightedReference");
            await VisualStudio.Workspace.WaitForAsyncOperationsAsync(FeatureAttribute.Workspace, HangMitigatingCancellationToken);
            var position = VisualStudio.Editor.GetCaretPosition();
            Assert.Equal(4, position.Line);

            VisualStudio.ExecuteCommand("Edit.NextHighlightedReference");
            await VisualStudio.Workspace.WaitForAsyncOperationsAsync(FeatureAttribute.Workspace, HangMitigatingCancellationToken);
            position = VisualStudio.Editor.GetCaretPosition();
            Assert.Equal(5, position.Line);

            VisualStudio.ExecuteCommand("Edit.NextHighlightedReference");
            await VisualStudio.Workspace.WaitForAsyncOperationsAsync(FeatureAttribute.Workspace, HangMitigatingCancellationToken);
            position = VisualStudio.Editor.GetCaretPosition();
            Assert.Equal(3, position.Line);
        }

        private void Verify(int expectedCount)
        {
            var highlights = VisualStudio.Editor.GetHighlightedReferences();
            Assert.Equal(expectedCount, highlights.Count);
            // Assert.True(highlights.All(h => h.TextSpan.Length == 2)); // Disabled assertion example
        }
    }
}

