using System;
using System.IO;
using System.Linq;
 
public class Account
{
    public static void Main(string[] args)
    {
        var first = true;
        var sc = new Scanner(File.OpenText("input.fasta"));
        while (sc.HasNextLine())
        {
            var line = sc.NextLine();
            if (line[0] == '>')
            {
                if (!first) Console.WriteLine();
                Console.Write(line.Substring(1) + ": ");
                if (first) first = false;
            }
            else if (first)
            {
                Console.WriteLine("Error : File does not begin with '>'");
                break;
            }
            else if (CheckNoSpaces(line))
                Console.Write(line);
            else
            {
                Console.WriteLine("\nError : Sequence contains space(s)");
                break;
            }
        }
        sc.Close();
    }
 
    public static bool CheckNoSpaces(string s)
    {
        return!s.Contains(' ') &&!s.Contains('\t');
    }
}
 
public class Scanner
{
    private readonly TextReader _reader;
    private readonly char[] _buffer = new char[1024];
    private int _index;
    private int _count;
 
    public Scanner(TextReader reader)
    {
        _reader = reader;
    }
 
    public bool HasNextLine()
    {
        return _reader.Peek() >= 0;
    }
 
    public string NextLine()
    {
        var line = new char[_count - _index];
        _reader.Read(_buffer, _index, line.Length);
        _index = _count = 0;
        return new string(line);
    }
 
    public bool HasNext()
    {
        if (_index < _count) return true;
        _index = 0;
        _count = _reader.Read(_buffer, _index, 1024);
        return _count > 0;
    }
}

using System.Collections;
