public class SignDetector : MonoBehaviour
{
    private bool isTextDisplaying = false;
    private string signText = "Press 'L' to read the sign.";
    private string helpText = "Press 'L' to interact with the sign.";
    public string whatItSays = "Welcome to the game!";
    private GUISkin guiSignText;
    private bool showHelpText = false;
    public Texture2D BoxTexture;
    public Font signFont;

    void Start()
    {
        guiSignText = new GUISkin();
        guiSignText.font = signFont;
        guiSignText.label.fontSize = 24;
        guiSignText.label.normal.textColor = Color.white;
    }

    void OnGUI()
    {
        if (showHelpText)
        {
            GUI.DrawTexture(new Rect(Screen.width / 2 - 100, Screen.height - 100, 200, 50), BoxTexture);
            GUI.Label(new Rect(Screen.width / 2 - 100, Screen.height - 100, 200, 50), helpText, guiSignText.label);
        }

        if (isTextDisplaying)
        {
            GUI.DrawTexture(new Rect(Screen.width / 2 - 150, Screen.height / 2 - 50, 300, 100), BoxTexture);
            GUI.Label(new Rect(Screen.width / 2 - 150, Screen.height / 2 - 50, 300, 100), whatItSays, guiSignText.label);
        }
    }

    void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
        {
            showHelpText = true;
        }
    }

    void OnTriggerStay2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
        {
            if (Input.GetKeyDown(KeyCode.L))
            {
                isTextDisplaying = !isTextDisplaying;
            }
        }
    }

    void OnTriggerExit2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
        {
            showHelpText = false;
            RemoveText();
        }
    }

    void RemoveText()
    {
        isTextDisplaying = false;
    }

    void DisplayText()
    {
        isTextDisplaying = true;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using System.Net;
 
class Validator {
    static List<string> GetTitlesFromCategory(string category) {
        string searchQueryFormat = "http://www.rosettacode.org/w/api.php?action=query&list=categorymembers&cmtitle=Category:{0}&format=json{1}";
        List<string> results = new List<string>();
        string cmcontinue = string.Empty;
 
        do {
            string cmContinueKeyValue;
 
            //append continue variable as needed
            if (cmcontinue.Length > 0)
                cmContinueKeyValue = String.Format("&cmcontinue={0}", cmcontinue);
            else
                cmContinueKeyValue = String.Empty;
 
            //execute query
            string query = String.Format(searchQueryFormat, category, cmContinueKeyValue);
            string content = new WebClient().DownloadString(query);
 
            results.AddRange(new Regex("\"title\":\"(.+?)\"").Matches(content).Cast<Match>().Select(x => x.Groups[1].Value));
 
            //detect if more results are available
            cmcontinue = Regex.Match(content, @"{""cmcontinue"":""([^""]+)""}", RegexOptions.IgnoreCase).Groups["1"].Value;
        } while (cmcontinue.Length > 0);
 
        return results;
    }
 
    static string[] GetUnimplementedTasksFromLanguage(string language) {
        List<string> alltasks = GetTitlesFromCategory("Programming_Tasks");
        List<string> lang = GetTitlesFromCategory(language);
 
        return alltasks.Where(x => !lang.Contains(x)).ToArray();
    }
 
    static void Main(string[] args) {
        string[] unimpl = GetUnimplementedTasksFromLanguage(args[0]);
 
        foreach (string i in unimpl) Console.WriteLine(i);
    }
}

using System;
using TvShowReminder.Contracts;
using TvShowReminder.DataSource;

public class RefreshEpisodesCommandHandler : ICommandHandler<RefreshEpisodesCommand>
{
    private readonly ISubscriptionQueryDataSource _subscriptionQueryDataSource;
    private readonly ISubscriptionCommandDataSource _subscriptionCommandDataSource;
    private readonly IEpisodeCommandDataSource _episodeCommandDataSource;
    private readonly IUpdateEpisodesService _updateEpisodesService;

    public RefreshEpisodesCommandHandler(
        ISubscriptionQueryDataSource subscriptionQueryDataSource,
        ISubscriptionCommandDataSource subscriptionCommandDataSource,
        IEpisodeCommandDataSource episodeCommandDataSource,
        IUpdateEpisodesService updateEpisodesService)
    {
        _subscriptionQueryDataSource = subscriptionQueryDataSource;
        _subscriptionCommandDataSource = subscriptionCommandDataSource;
        _episodeCommandDataSource = episodeCommandDataSource;
        _updateEpisodesService = updateEpisodesService;
    }

    public void Handle(RefreshEpisodesCommand command)
    {
        var subscription = _subscriptionQueryDataSource.GetSubscription(command.SubscriptionId);
        if (subscription == null)
            throw new InvalidOperationException("Subscription not found.");

        var lastAirDate = DateTime.UtcNow;
        _subscriptionCommandDataSource.UpdateLastAirDate(subscription.Id, lastAirDate);

        _episodeCommandDataSource.DeleteAllFromSubscription(subscription.Id);

        var newEpisodes = _updateEpisodesService.UpdateEpisodesForSubscription(subscription);
        if (newEpisodes.Any())
        {
            _subscriptionCommandDataSource.SaveLastAirDate(subscription.Id, newEpisodes.Max(e => e.AirDate));
        }
    }
}

