namespace System.Collections
{
    // An abstract contract for dictionary-like collections.
    public interface IDictionary : ICollection
    {
        // Gets or sets the element with the specified key.
        object this[object key] { get; set; }

        // Gets an ICollection containing the keys in the IDictionary.
        ICollection Keys { get; }

        // Gets an ICollection containing the values in the IDictionary.
        ICollection Values { get; }

        // Indicates if the IDictionary is read-only.
        bool IsReadOnly { get; }

        // Indicates if the IDictionary has a fixed size.
        bool IsFixedSize { get; }

        // Determines whether the IDictionary contains an element with the specified key.
        bool Contains(object key);

        // Adds an element with the provided key and value to the IDictionary.
        void Add(object key, object value);

        // Removes all elements from the IDictionary.
        void Clear();

        // Returns an IDictionaryEnumerator for iterating through the IDictionary.
        IDictionaryEnumerator GetEnumerator();

        // Removes the element with the specified key from the IDictionary.
        void Remove(object key);
    }

    // A sample dictionary implementation demonstrating the IDictionary contract.
    public class MyDictionary : IDictionary
    {
        private Hashtable innerTable;

        public MyDictionary()
        {
            innerTable = new Hashtable();
        }

        // Indexer to get or set values by key.
        public object this[object key]
        {
            get
            {
                Contract.Requires(key != null, "Key cannot be null.");
                return innerTable[key];
            }
            set
            {
                Contract.Requires(key != null, "Key cannot be null.");
                innerTable[key] = value;
            }
        }

        // Returns all keys in the dictionary.
        public ICollection Keys
        {
            get { return innerTable.Keys; }
        }

        // Returns all values in the dictionary.
        public ICollection Values
        {
            get { return innerTable.Values; }
        }

        // The dictionary is not read-only.
        public bool IsReadOnly
        {
            get { return false; }
        }

        // The size is dictated by the underlying Hashtable.
        public bool IsFixedSize
        {
            get { return innerTable.IsFixedSize; }
        }

