namespace FakeItEasy.Configuration
{
    using System;
    using System.Linq;
    using System.Linq.Expressions;
    using FakeItEasy.Core;
    using FakeItEasy.Expressions;

    internal partial class PropertySetterConfiguration<TValue>
        : IPropertySetterAnyValueConfiguration<TValue>
    {
        private readonly ParsedCallExpression parsedSetterExpression;

        private readonly Func<ParsedCallExpression, IVoidArgumentValidationConfiguration> voidArgumentValidationConfigurationFactory;

        public PropertySetterConfiguration(
            ParsedCallExpression parsedCallExpression,
            Func<ParsedCallExpression, IVoidArgumentValidationConfiguration> voidArgumentValidationConfigurationFactory)
        {
            this.parsedSetterExpression = parsedCallExpression;
            this.voidArgumentValidationConfigurationFactory = voidArgumentValidationConfigurationFactory;
        }

        public IPropertySetterConfiguration To(TValue value) =>
            this.To(() => value);

        public IPropertySetterConfiguration To(Expression<Func<TValue>> valueConstraint)
        {
            Guard.AgainstNull(valueConstraint, nameof(valueConstraint));

            var newSetterExpression = this.CreateSetterExpressionWithNewValue(valueConstraint);
            var voidArgumentValidationConfiguration = this.CreateArgumentValidationConfiguration(newSetterExpression);
            return AsPropertySetterConfiguration(voidArgumentValidationConfiguration);
        }

        public IAfterCallConfiguredConfiguration<IPropertySetterConfiguration> Throws(Func<IFakeObjectCall, Exception> exceptionFactory) =>
            AsPropertySetterConfiguration(this.CreateArgumentValidationConfiguration(this.parsedSetterExpression))
                .Throws(exceptionFactory);

        public IAfterCallConfiguredConfiguration<IPropertySetterConfiguration> Throws<T>() where T : Exception, new() =>
            this.Throws<IPropertySetterConfiguration, T>();

        public IPropertySetterAfterCallbackConfiguredConfiguration Invokes(Action<IFakeObjectCall> action)
        {
            var voidConfiguration = this.CreateArgumentValidationConfiguration(this.parsedSetterExpression)
                .Invokes(action);

            return AsPropertySetterAfterCallbackConfiguredConfiguration(voidConfiguration);
        }

        public IAfterCallConfiguredConfiguration<IPropertySetterConfiguration> CallsBaseMethod() =>
            AsPropertySetterConfiguration(this.CreateArgumentValidationConfiguration(this.parsedSetterExpression))
                .CallsBaseMethod();

public static class BaseConverter {
 
    /// <summary>
    /// Converts a string to a number
    /// </summary>
    /// <returns>The number.</returns>
    /// <param name="s">The string to convert.</param>
    /// <param name="b">The base number (between 2 and 36).</param>
    public static long stringToLong(string s, int b) {
 
        if ( b < 2 || b > 36 )
            throw new ArgumentException("Base must be between 2 and 36", "b");
 
        checked {
 
            int slen = s.Length;
            long result = 0;
            bool isNegative = false;
 
            for ( int i = 0; i < slen; i++ ) {
 
                char c = s[i];
                int num;
 
                if ( c == '-' ) {
                    // Negative sign
                    if ( i != 0 )
                        throw new ArgumentException("A negative sign is allowed only as the first character of the string.", "s");
 
                    isNegative = true;
                    continue;
                }
 
                if ( c > 0x2F && c < 0x3A )
                    // Numeric character (subtract from 0x30 ('0') to get numerical value)
                    num = c - 0x30;
                else if ( c > 0x40 && c < 0x5B )
                    // Uppercase letter
                    // Subtract from 0x41 ('A'), then add 10
                    num = c - 0x37;  // 0x37 = 0x41 - 10
                else if ( c > 0x60 && c < 0x7B )
                    // Lowercase letter
                    // Subtract from 0x61 ('a'), then add 10
                    num = c - 0x57;  // 0x57 = 0x61 - 10
                else
                    throw new ArgumentException("The string contains an invalid character '" + c + "'", "s");
 
                // Check that the digit is allowed by the base.
 
                if ( num >= b )
                    throw new ArgumentException("The string contains a character '" + c + "' which is not allowed in base " + b, "s");
 
                // Multiply the result by the base, then add the next digit
 
                result *= b;
                result += num;
 
            }
 
            if ( isNegative )
                result = -result;
 
            return result;
 
        }
 
    }
 
    /// <summary>
    /// Converts a number to a string.
    /// </summary>
    /// <returns>The string.</returns>
    /// <param name="n">The number to convert.</param>
    /// <param name="b">The base number (between 2 and 36).</param>
    public static string longToString(long n, int b) {

using System;
using System.Threading.Tasks;

public class Pipeline<TValue>
{
    private Func<Task<Result<TValue>>> _initialOperation;

    public Pipeline(Func<Task<Result<TValue>>> initialOperation)
    {
        _initialOperation = initialOperation;
    }

    public async Task<Result<TValue>> ExecuteAsync()
    {
        return await _initialOperation();
    }
}

public struct Result<TValue>
{
    public TValue Value { get; }
    public Exception Error { get; }
    public bool IsSuccess => Error == null;

    private Result(TValue value, Exception error)
    {
        Value = value;
        Error = error;
    }

    public static Result<TValue> Success(TValue value) => new Result<TValue>(value, null);
    public static Result<TValue> Failure(Exception error) => new Result<TValue>(default, error);
}

public static class PipelineExtensions
{
    public static Pipeline<TValue> Catch<TValue>(
        this Pipeline<TValue> pipeline,
        Action<Exception> errorHandler)
    {
        Func<Task<Result<TValue>>> initialOperation = async () =>
        {
            try
            {
                return await pipeline.ExecuteAsync();
            }
            catch (Exception ex)
            {
                errorHandler(ex);
                return Result<TValue>.Failure(ex);
            }
        };

        return new Pipeline<TValue>(initialOperation);
    }

    public static Pipeline<TNewValue> ContinueWith<TValue, TNewValue>(
        this Pipeline<TValue> pipeline,
        Func<TValue, Task<Result<TNewValue>>> nextOperation)
    {
        Func<Task<Result<TNewValue>>> initialOperation = async () =>
        {
            var result = await pipeline.ExecuteAsync();
            if (result.IsSuccess)
            {
                return await nextOperation(result.Value);
            }
            return Result<TNewValue>.Failure(result.Error);
        };

        return new Pipeline<TNewValue>(initialOperation);
    }

    public static Pipeline<TNewValue> ContinueWithNew<TValue, TNewValue>(
        this Pipeline<TValue> pipeline,
        Func<Task<Result<TNewValue>>> newOperation)
    {
        Func<Task<Result<TNewValue>>> initialOperation = async () =>
        {
            var result = await pipeline.ExecuteAsync();
            if (result.IsSuccess)
            {
                return await newOperation();
            }
            return Result<TNewValue>.Failure(result.Error);
        };

        return new Pipeline<TNewValue>(initialOperation);
    }
}

