public class IamPermissionTester
{
    public async Task<TestPermissionsResponse> TestIamPermissionsAsync(string projectId, string zone, string resource, string[] permissions)
    {
        // Initialize the ReservationsClient asynchronously
        ReservationsClient reservationsClient = await ReservationsClient.CreateAsync();

        // Create the TestPermissionsRequest object
        var testPermissionsRequest = new TestPermissionsRequest
        {
            Permissions = { permissions }
        };

        // Create the TestIamPermissionsReservationRequest object
        var request = new TestIamPermissionsReservationRequest
        {
            Project = projectId,
            Zone = zone,
            Resource = resource,
            TestPermissionsRequestResource = testPermissionsRequest
        };

        // Send the request asynchronously and await the response
        TestPermissionsResponse response = await reservationsClient.TestIamPermissionsAsync(request);

        // Return the response containing the permissions granted
        return response;
    }
}

