namespace ProjectEulerTasks
{
    class Task_0250
    {
        static void Main(string[] args)
        {
            Stopwatch sw = new Stopwatch();
            sw.Start();
            Console.WriteLine("First 25 Ludic numbers:");
            foreach (int i in Ludic(100000).Take(25))
            {
                Console.Write(i + " ");
            }
            Console.WriteLine();
            Console.WriteLine("Ludics below 1000: " + Ludic(1000).Count());
            Console.WriteLine("Ludic numbers 2000 to 2005:");
            foreach (int i in Ludic(100000).Skip(2000).Take(6))
            {
                Console.Write(i + " ");
            }
            Console.WriteLine();
            int[] ludics = Ludic(250).ToArray();
            Console.WriteLine("Ludic triples below 250:");
            foreach (int[] i in ludics.Where(x => ludics.Contains(x + 2) && ludics.Contains(x + 6)).Select(x => new int[] { x, x + 2, x + 6 }))
            {
                Console.WriteLine(i[0] + " " + i[1] + " " + i[2]);
            }
            sw.Stop();
            Console.WriteLine(sw.Elapsed);
        }
        static IEnumerable<int> Ludic(int nmax)
        {
            List<int> ary = Enumerable.Range(2, nmax - 1).ToList();
            while (ary.Count > 0)
            {
                yield return ary[0];
                for (int i = 0; i < ary.Count; i += ary[0])
                {
                    ary[i] = 0;
                }
                ary = ary.Where(x => x!= 0).ToList();
            }
        }
    }
}

using Antlr4.Runtime;
using Rubberduck.VBEditor;

namespace Rubberduck.Parsing
{
    public class QualifiedContext
    {
        public QualifiedMemberName MemberName { get; }
        public QualifiedModuleName ModuleName { get; }
        public ParserRuleContext Context { get; }

        public QualifiedContext(QualifiedMemberName memberName, ParserRuleContext context)
        {
            MemberName = memberName;
            ModuleName = memberName.QualifiedModuleName;
            Context = context;
        }

        public override int GetHashCode()
        {
            return (MemberName, Context).GetHashCode();
        }

        public override bool Equals(object obj)
        {
            return obj is QualifiedContext other && Equals(other);
        }

        protected bool Equals(QualifiedContext other)
        {
            return MemberName.Equals(other.MemberName);
        }

        public static bool operator ==(QualifiedContext left, QualifiedContext right)
        {
            return Equals(left, right);
        }

        public static bool operator !=(QualifiedContext left, QualifiedContext right)
        {
            return !Equals(left, right);
        }
    }

    public class QualifiedContext<TContext> : QualifiedContext where TContext : ParserRuleContext
    {
        public new TContext Context { get; }

        public QualifiedContext(QualifiedMemberName memberName, TContext context) : base(memberName, context)
        {
            Context = context;
        }
        public override int GetHashCode()
        {
            return (MemberName, Context).GetHashCode();
        }

        public override bool Equals(object obj)
        {
            return obj is QualifiedContext<TContext> other && Equals(other);
        }

        protected bool Equals(QualifiedContext<TContext> other)
        {
            return base.Equals(other);
        }

                public static bool operator ==(QualifiedContext<TContext> left, QualifiedContext<TContext> right)
        {
            return Equals(left, right);
        }

        public static bool operator !=(QualifiedContext<TContext> left, QualifiedContext<TContext> right)
        {
            return !Equals(left, right);
        }

    }
}

