using MSR.Data.Entities;
using MSR.Data.Entities.DSL.Selection;
using MSR.Data.Entities.DSL.Selection.Metrics;

public class CommitsByDateAndAuthor
{
    private IRepository repository;
    private Dictionary<string, int[]> yByAuthor;
    private DateTime startDate;
    private DateTime endDate;
    private List<DateTime> datePeriods;

    [Description("Authors")]
    public List<string> Authors { get; private set; }

    public CommitsByDateAndAuthor(DateTime startDate, DateTime endDate)
    {
        this.startDate = startDate;
        this.endDate = endDate;
        this.datePeriods = GenerateDatePeriods(startDate, endDate);
    }

    private List<DateTime> GenerateDatePeriods(DateTime startDate, DateTime endDate)
    {
        var periods = new List<DateTime>();
        for (DateTime date = startDate; date <= endDate; date = date.AddDays(1))
        {
            periods.Add(date);
        }
        return periods;
    }

    public void Init(IRepository repository)
    {
        this.repository = repository;
        Authors = repository.Commits.Select(c => c.Author).Distinct().ToList();
        yByAuthor = new Dictionary<string, int[]>();
        foreach (var author in Authors)
        {
            yByAuthor[author] = new int[datePeriods.Count];
        }
    }

    public void Calc(IRepository repository)
    {
        foreach (var author in Authors)
        {
            for (int i = 0; i < datePeriods.Count - 1; i++)
            {
                var periodStart = datePeriods[i];
                var periodEnd = datePeriods[i + 1];
                var commitsInPeriod = repository.Commits
                    .Where(c => c.Author == author && c.Date >= periodStart && c.Date < periodEnd)
                    .Count();
                yByAuthor[author][i] = commitsInPeriod;
            }
        }
    }

    public void Draw(IGraphView graph)
    {
        graph.Title = "Commits by Date and Author";
        graph.VisualizationType = VisualizationType.LINEWITHPOINTS;
        graph.XAxis.Label = "Date";
        graph.YAxis.Label = "Number of Commits";

        foreach (var author in Authors)
        {
            var dataPoints = new List<DataPoint>();
            for (int i = 0; i < datePeriods.Count - 1; i++)
            {
                dataPoints.Add(new DataPoint(datePeriods[i], yByAuthor[author][i]));
            }
            graph.AddLine(author, dataPoints);
        }
    }
}

