namespace YourNamespace.Financial.Billing
{
    using System;
    using System.ComponentModel.DataAnnotations;

    public class PaymentApplication
    {
        [Key]
        public Guid Id { get; set; }

        [Required]
        public decimal AmountApplied { get; set; }

        public DateTime ApplicationDate { get; set; }

        public Invoice Invoice { get; set; }
        public Guid? InvoiceId { get; set; }

        public InvoiceItem InvoiceItem { get; set; }
        public Guid? InvoiceItemId { get; set; }

        public BillingAccount BillingAccount { get; set; }
        public Guid? BillingAccountId { get; set; }

        public string SecurityToken { get; set; }

        public bool IsActive { get; set; }

        public virtual void OnBuild()
        {
            ApplicationDate = DateTime.UtcNow;
            IsActive = true;
        }

        public virtual void OnPostBuild()
        {
            ValidateAmountApplied();
        }

        public virtual void OnPreDerive()
        {
            EnsureConsistentAllocation();
        }

        public virtual void OnDerive()
        {
            CalculateRemainingBalance();
        }

        public virtual void OnPostDerive()
        {
            UpdateRelatedFinancialRecords();
        }

        private void ValidateAmountApplied()
        {
            if (AmountApplied < 0)
            {
                throw new ArgumentException("Payment amount cannot be negative.");
            }
        }

        private void EnsureConsistentAllocation()
        {
            if (Invoice == null && InvoiceItem == null)
            {
                throw new InvalidOperationException("Payment must be associated with an invoice or invoice item.");
            }
        }

        private void CalculateRemainingBalance()
        {
            if (Invoice != null)
            {
                Invoice.RemainingBalance -= AmountApplied;
            }

            if (InvoiceItem != null)
            {
                InvoiceItem.RemainingBalance -= AmountApplied;
            }
        }

        private void UpdateRelatedFinancialRecords()
        {
            if (BillingAccount != null)
            {
                BillingAccount.TotalPaidAmount += AmountApplied;
            }
        }
    }
}

