namespace CodeGraphSystem
{
    public enum EntityType
    {
        Unknown,
        Symbol
    }

    [DataContract]
    public abstract class Entity
    {
        [DataMember]
        public EntityType Type { get; set; }

        protected Entity(EntityType type)
        {
            Type = type;
        }
    }

    [DataContract]
    public class SymbolReference
    {
        [DataMember]
        public string ReferenceName { get; set; }

        [DataMember]
        public string FileUId { get; set; }

        public SymbolReference() { }

        public SymbolReference(string referenceName, string fileUId)
        {
            ReferenceName = referenceName;
            FileUId = fileUId;
        }
    }

    [DataContract]
    public class Symbol : Entity
    {
        public Symbol() : base(EntityType.Symbol)
        {
            References = new List<SymbolReference>();
        }

        [DataMember]
        public string Name { get; set; }

        [DataMember]
        public string SymbolType { get; set; }

        [DataMember]
        public bool IsExternal { get; set; }

        [DataMember]
        public int LineStart { get; set; }

        [DataMember]
        public int LineEnd { get; set; }

        [DataMember]
        public int ColumnStart { get; set; }

        [DataMember]
        public int ColumnEnd { get; set; }

        [DataMember]
        public string FileUId { get; set; }

        [DataMember]
        public List<SymbolReference> References { get; set; }

        public override string ToString()
        {
            return string.Format("Symbol: {0}, Type: {1}, Lines: {2}-{3}, Columns: {4}-{5}, External: {6}",
                Name, SymbolType, LineStart, LineEnd, ColumnStart, ColumnEnd, IsExternal);
        }

        public bool IsValid()
        {
            return this.Type == EntityType.Symbol &&
                   !string.IsNullOrEmpty(Name) &&
                   !string.IsNullOrEmpty(SymbolType);
        }
    }

    [DataContract]
    public class SymbolResponse
    {
        [DataMember]
        public string Name { get; set; }

        [DataMember]
        public string SymbolType { get; set; }

        [DataMember]
        public int LineStart { get; set; }

        [DataMember]
        public int LineEnd { get; set; }

        [DataMember]
        public int ColumnStart { get; set; }

        [DataMember]
        public int ColumnEnd { get; set; }

        [DataMember]
        public string FileUId { get; set; }

