using System;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;

public class SelectelClient
{
    private readonly HttpClient _httpClient;
    public string StorageUrl { get; private set; }
    public string CDNUrl { get; private set; }
    public string AuthToken { get; private set; }
    public DateTime ExpireAuthToken { get; private set; }

    public SelectelClient(IWebProxy proxy = null)
    {
        var handler = new HttpClientHandler { Proxy = proxy, UseProxy = proxy != null };
        _httpClient = new HttpClient(handler);
    }

    public async Task AuthorizeAsync()
    {
        var authRequest = new AuthRequest();
        var response = await ExecuteAsync<AuthResponse>(authRequest);
        StorageUrl = response.StorageUrl;
        CDNUrl = response.CDNUrl;
        AuthToken = response.AuthToken;
        ExpireAuthToken = DateTime.UtcNow.AddSeconds(response.Ttl);
    }

    public void Authorize() => AuthorizeAsync().GetAwaiter().GetResult();

    public async Task<T> ExecuteAsync<T>(BaseRequest<T> request)
    {
        if (request.RequiresAuth)
        {
            if (string.IsNullOrEmpty(AuthToken) || DateTime.UtcNow > ExpireAuthToken)
                await AuthorizeAsync();
        }

        var requestUrl = request.BuildUrl(StorageUrl);
        if (!string.IsNullOrEmpty(CDNUrl) && requestUrl.StartsWith(StorageUrl))
            requestUrl = CDNUrl + requestUrl.Substring(StorageUrl.Length);

        var httpRequest = new HttpRequestMessage(request.Method, requestUrl);
        if (request.RequiresAuth)
            httpRequest.Headers.Add("X-Auth-Token", AuthToken);

        var response = await _httpClient.SendAsync(httpRequest);
        response.EnsureSuccessStatusCode();
        return await request.ParseResponseAsync(response);
    }
}

public class AuthRequest : BaseRequest<AuthResponse>
{
    public AuthRequest()
    {
        Method = HttpMethod.Get;
        RequiresAuth = false;
    }

    public override string BuildUrl(string baseUrl) => "https://auth.selcdn.ru/";

    public override async Task<AuthResponse> ParseResponseAsync(HttpResponseMessage response)
    {
        return new AuthResponse
        {
            StorageUrl = response.Headers.GetValues("X-Storage-Url").FirstOrDefault(),
            CDNUrl = response.Headers.GetValues("X-CDN-Url").FirstOrDefault(),
            AuthToken = response.Headers.GetValues("X-Auth-Token").FirstOrDefault(),
            Ttl = int.Parse(response.Headers.GetValues("X-TTL").FirstOrDefault())
        };
    }
}

