using System;
using System.Xml;
using Xunit;

public class CreateAttributeTests
{
    [Fact]
    public void CreateAttribute_WithoutNamespace_ReturnsCorrectAttribute()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attribute = xmlDocument.CreateAttribute("attributeName");

        Assert.Equal("attributeName", attribute.Name);
        Assert.Equal("attributeName", attribute.LocalName);
        Assert.Equal("", attribute.Prefix);
        Assert.Equal(string.Empty, attribute.NamespaceURI);
        Assert.Equal("attributeName=\"\"", attribute.OuterXml);
        Assert.Equal(string.Empty, attribute.InnerXml);
        Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
    }

    [Fact]
    public void CreateAttribute_WithEmptyPrefix_ReturnsCorrectAttribute()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attribute = xmlDocument.CreateAttribute(string.Empty, "attributeName", string.Empty);

        Assert.Equal("attributeName", attribute.Name);
        Assert.Equal("attributeName", attribute.LocalName);
        Assert.Equal("", attribute.Prefix);
        Assert.Equal(string.Empty, attribute.NamespaceURI);
        Assert.Equal("attributeName=\"\"", attribute.OuterXml);
        Assert.Equal(string.Empty, attribute.InnerXml);
        Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
    }

    [Fact]
    public void CreateAttribute_WithNamespace_ReturnsCorrectAttribute()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attribute = xmlDocument.CreateAttribute("prefix", "attributeName", "namespaceUri");

        Assert.Equal("prefix:attributeName", attribute.Name);
        Assert.Equal("attributeName", attribute.LocalName);
        Assert.Equal("prefix", attribute.Prefix);
        Assert.Equal("namespaceUri", attribute.NamespaceURI);
        Assert.Equal("prefix:attributeName=\"\"", attribute.OuterXml);
        Assert.Equal(string.Empty, attribute.InnerXml);
        Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
    }
}

