using System;
using System.Collections.Generic;
using System.Linq;
using ShipsServer.Common;
using ShipsServer.Enums;

public class Battle
{
    private const int MaxPlayers = 2;
    private List<Player> _players;

    public int Id { get; private set; }
    public BattleStatus Status { get; private set; }

    public Battle(int id)
    {
        Id = id;
        _players = new List<Player>();
        Status = BattleStatus.Waiting;
    }

    public void AddPlayer(Session session, Board board)
    {
        if (_players.Count >= MaxPlayers)
        {
            throw new InvalidOperationException("Cannot add more players to the battle.");
        }

        Player player = new Player(session, board);
        _players.Add(player);

        if (_players.Count == MaxPlayers)
        {
            Status = BattleStatus.Ready;
        }
    }

    public Player GetPlayer(int idx)
    {
        if (idx < 0 || idx >= _players.Count)
        {
            throw new IndexOutOfRangeException("Player index is out of range.");
        }

        return _players[idx];
    }

    public Player GetPlayerBySession(Session session)
    {
        return _players.FirstOrDefault(player => player.Session == session);
    }

    public Player GetOponentPlayer(Session session)
    {
        return _players.FirstOrDefault(player => player.Session != session);
    }

    public void Finish(Player winner, Player looser)
    {
        if (!_players.Contains(winner) || !_players.Contains(looser))
        {
            throw new InvalidOperationException("Both players must be part of the battle to finish.");
        }

        winner.Statistics.Wins++;
        looser.Statistics.Losses++;

        Status = BattleStatus.Completed;

        // Add any additional cleanup or notifications here
        NotifyPlayers(winner, looser);
    }

    private void NotifyPlayers(Player winner, Player looser)
    {
        foreach (var player in _players)
        {
            player.Notify($"Battle finished! Winner: {winner.Name}, Loser: {looser.Name}");
        }
    }
}

public enum BattleStatus
{
    Waiting,
    Ready,
    Ongoing,
    Completed
