namespace LatinSquares
{
    class Task
    {
        static void Main(string[] args)
        {
            Console.WriteLine("The four reduced latin squares of order 4 are:\n");
            reducedLatinSquares(4, true);
            Console.WriteLine("The size of the set of reduced latin squares for the following orders");
            Console.WriteLine("and hence the total number of latin squares of these orders are:\n");
            for (int n = 1; n < 7; n++)
            {
                int size = reducedLatinSquares(n, false);
                int f = factorial(n - 1);
                f *= f * n * size;
                Console.WriteLine("Order %d: Size %-4d x %d! x %d! => Total %d", n, size, n, n - 1, f);
            }
        }
 
        static int factorial(int n)
        {
            if (n == 0)
                return 1;
            int prod = 1;
            for (int i = 2; i <= n; i++)
                prod *= i;
            return prod;
        }
 
        static int[][] dList(int n, int start)
        {
            start -= 1; // use 0 basing
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = i;
            a[start] = a[0];
            a[0] = start;
            for (int i = 1; i < n; i++)
                a[i] = i;
            int first = a[1];
            // rescursive closure permutes a[1:]
            List<int[]> r = new List<int[]>();
            recurse(n - 1, a, first, r);
            return r.ToArray();
        }
 
        static void recurse(int last, int[] a, int first, List<int[]> r)
        {
            if (last == first)
            {
                // bottom of recursion. you get here once for each permutation.
                // test if permutation is deranged.
                // yes, save a copy with 1 based indexing
                for (int j = 1; j < a.Length; j++)
                {
                    if (j + 1 == a[j])
                        return; // no, ignore it
                }
                int[] b = new int[a.Length];
                for (int j = 0; j < a.Length; j++)
                    b[j] = a[j] + 1;
                r.Add(b);
                return;
            }
            for (int i = last; i > 0; i--)
            {
                int t = a[i];
                a[i] = a[last];
                a[last] = t;
                recurse(last - 1, a, first, r);
                t = a[i];
                a[i] = a[last];
                a[last] = t;

public int[,] Spiral(int n) {
    int[,] result = new int[n, n];
 
    int pos = 0;
    int count = n;
    int value = -n;
    int sum = -1;
 
    do {
        value = -1 * value / n;
        for (int i = 0; i < count; i++) {
            sum += value;
            result[sum / n, sum % n] = pos++;
        }
        value *= n;
        count--;
        for (int i = 0; i < count; i++) {
            sum += value;
            result[sum / n, sum % n] = pos++;
        }
    } while (count > 0);
 
    return result;
}
 
 
// Method to print arrays, pads numbers so they line up in columns
public void PrintArray(int[,] array) {
    int n = (array.GetLength(0) * array.GetLength(1) - 1).ToString().Length + 1;
 
    for (int i = 0; i < array.GetLength(0); i++) {
        for (int j = 0; j < array.GetLength(1); j++) {
            Console.Write(array[i, j].ToString().PadLeft(n, ' '));
        }
        Console.WriteLine();
    }
}

