public class OlapMetadataResolver
{
    private readonly string _connectionString;
    private readonly string _queryTemplate;
    private readonly List<Func<OlapRow, bool>> _filters;

    public OlapMetadataResolver(string connectionString, string queryTemplate)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
        _queryTemplate = queryTemplate ?? throw new ArgumentNullException(nameof(queryTemplate));
        _filters = new List<Func<OlapRow, bool>>();
    }

    public void AddFilter(Func<OlapRow, bool> filter)
    {
        _filters.Add(filter);
    }

    public List<string> Execute(Dictionary<string, object> parameters)
    {
        var results = new List<string>();

        try
        {
            using (var connection = new AdomdConnection(_connectionString))
            {
                connection.Open();

                using (var command = new AdomdCommand(BuildQuery(parameters), connection))
                {
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            var row = BuildRow(reader);
                            if (PassesFilters(row))
                            {
                                results.Add(row.Caption);
                            }
                        }
                    }
                }
            }
        }
        catch (AdomdException ex)
        {
            // Log or handle specific ADOMD connection errors
            throw new InvalidOperationException("OLAP query execution failed", ex);
        }
        catch (Exception ex)
        {
            // Generic error handling
            throw new InvalidOperationException("Metadata retrieval encountered an unexpected error", ex);
        }

        return results;
    }

    private string BuildQuery(Dictionary<string, object> parameters)
    {
        string formattedQuery = _queryTemplate;
        foreach (var param in parameters)
        {
            formattedQuery = formattedQuery.Replace($"@{param.Key}", param.Value?.ToString() ?? string.Empty);
        }
        return formattedQuery;
    }

    private OlapRow BuildRow(IDataReader reader)
    {
        return new OlapRow
        {
            Caption = reader["Caption"]?.ToString() ?? string.Empty,
            UniqueName = reader["UniqueName"]?.ToString() ?? string.Empty,

