using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace TNetD.Network
{
    public delegate void PacketReceivedHandler(NetworkPacket packet);

    public class FakeNetwork
    {
        private struct NetworkPacketQueueEntry
        {
            public Hash Destination;
            public NetworkPacket Packet;
        }

        private readonly ConcurrentDictionary<Hash, PacketReceivedHandler> Listeners = new ConcurrentDictionary<Hash, PacketReceivedHandler>();
        private readonly ConcurrentQueue<NetworkPacketQueueEntry> QueuedPackets = new ConcurrentQueue<NetworkPacketQueueEntry>();
        private readonly AutoResetEvent autoEvent;
        private readonly Timer stateTimer;

        public FakeNetwork()
        {
            autoEvent = new AutoResetEvent(false);
            stateTimer = new Timer(TimerCallback, autoEvent, 100, 100);
        }

        private void TimerCallback(Object stateInfo)
        {
            while (QueuedPackets.TryDequeue(out var entry))
            {
                if (Listeners.TryGetValue(entry.Destination, out var handler))
                {
                    handler(entry.Packet);
                }
            }
        }

        public void SendPacket(Hash destination, NetworkPacket packet)
        {
            QueuedPackets.Enqueue(new NetworkPacketQueueEntry { Destination = destination, Packet = packet });
        }

        public void AttachListener(Hash destination, PacketReceivedHandler handler)
        {
            Listeners.AddOrUpdate(destination, handler, (key, oldValue) => handler);
        }
    }

    public class NetworkPacket { }

    public class Hash { }
}

