namespace MyWebApp.Utilities
{
    public sealed class WebAppContext
    {
        private static readonly ThreadLocal<ControllerBase> _currentController = new ThreadLocal<ControllerBase>();
        private static readonly Dictionary<string, string> _getParameters = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        private static readonly Dictionary<string, string> _postParameters = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        public static ControllerBase CurrentController
        {
            get => _currentController.Value;
            set => _currentController.Value = value;
        }

        public static HttpContextBase HttpContext => new HttpContextWrapper(System.Web.HttpContext.Current);

        public static HttpRequestBase Request => HttpContext.Request;

        public static HttpResponseBase Response => HttpContext.Response;

        public static HttpServerUtilityBase Server => HttpContext.Server;

        public static HttpSessionStateBase Session => HttpContext.Session;

        public static Cache WebCache => HttpContext.Cache;

        public static IReadOnlyDictionary<string, string> GetData => _getParameters;

        public static IReadOnlyDictionary<string, string> PostData => _postParameters;

        public static void Reset()
        {
            _currentController.Value = null;
            _getParameters.Clear();
            _postParameters.Clear();
        }

        public static void LoadParameters()
        {
            _getParameters.Clear();
            foreach (string key in Request.QueryString.Keys)
            {
                _getParameters[key] = Request.QueryString[key];
            }

            _postParameters.Clear();
            foreach (string key in Request.Form.Keys)
            {
                _postParameters[key] = Request.Form[key];
            }
        }

        public static string UrlWithoutExtension(string url)
        {
            int lastDotIndex = url.LastIndexOf('.');
            if (lastDotIndex > -1)
            {
                return url.Substring(0, lastDotIndex);
            }
            return url;
        }

        public static string GetFullUrl()
        {
            return $"{Request.Url.Scheme}://{Request.Url.Host}{Request.Url.PathAndQuery}";
        }

        public static string GetParameter(string name)
        {
            return _getParameters.TryGetValue(name, out var value) ? value : null;
        }

