namespace YourNamespace.iOS
{
    public class ScrollViewExRenderer : ScrollViewRenderer
    {
        private ScrollViewEx _scrollViewEx;

        protected override void OnElementChanged(ElementChangedEventArgs<ScrollView> e)
        {
            base.OnElementChanged(e);
            if (e.NewElement != null)
            {
                _scrollViewEx = (ScrollViewEx)e.NewElement;
                UpdateProperties();
                _scrollViewEx.PropertyChanged += OnScrollViewExPropertyChanged;
            }

            if (e.OldElement != null)
            {
                _scrollViewEx.PropertyChanged -= OnScrollViewExPropertyChanged;
            }
        }

        private void OnScrollViewExPropertyChanged(object sender, System.ComponentModel.PropertyChangedEventArgs e)
        {
            if (e.PropertyName == nameof(ScrollViewEx.ShowHorizontalScrollIndicator) ||
                e.PropertyName == nameof(ScrollViewEx.ShowVerticalScrollIndicator) ||
                e.PropertyName == nameof(ScrollViewEx.BounceEnabled))
            {
                UpdateProperties();
            }
        }

        private void UpdateProperties()
        {
            UpdateHorizontalScroll();
            UpdateVerticalScroll();
            UpdateBounce();
        }

        private void UpdateHorizontalScroll()
        {
            if (_scrollViewEx.ShowHorizontalScrollIndicator)
            {
                ShowingHorizontalScrollIndicator();
            }
            else
            {
                HidesHorizontalScrollIndicator();
            }
        }

        private void UpdateVerticalScroll()
        {
            if (_scrollViewEx.ShowVerticalScrollIndicator)
            {
                ShowingVerticalScrollIndicator();
            }
            else
            {
                HidesVerticalScrollIndicator();
            }
        }

        private void UpdateBounce()
        {
            this.Bounces = _scrollViewEx.BounceEnabled;
        }

        private void ShowingHorizontalScrollIndicator()
        {
            this.ShowsHorizontalScrollIndicator = true;
        }

        private void HidesHorizontalScrollIndicator()
        {
            this.ShowsHorizontalScrollIndicator = false;
        }

        private void ShowingVerticalScrollIndicator()
        {
            this.ShowsVerticalScrollIndicator = true;
        }

using System;
using System.Diagnostics;

[DebuggerDisplay("{Value} (Type: {Type}, Column: {FromColumn})")]
public class Token
{
    private readonly string _token;

    public string Value { get; }
    public TokenType Type { get; }
    public int FromColumn { get; }
    public int Length { get; }
    public string Sentence { get; }

    public Token(string value, TokenType type = TokenType.Unknown, int fromColumn = 0, string sentence = null)
    {
        _token = value ?? throw new ArgumentNullException(nameof(value));
        Value = value.Trim();
        Type = type;
        FromColumn = fromColumn;
        Length = Value.Length;
        Sentence = sentence;
    }

    public Token(char value, TokenType type = TokenType.Character, int fromColumn = 0, string sentence = null)
        : this(value.ToString(), type, fromColumn, sentence)
    {
    }

    public static implicit operator string(Token token) => token?.Value;

    public override string ToString() => Value;

    public override bool Equals(object obj)
    {
        return obj is Token other &&
               string.Equals(Value, other.Value, StringComparison.OrdinalIgnoreCase) &&
               Type == other.Type;
    }

    public override int GetHashCode()
    {
        return HashCode.Combine(
            Value?.ToLowerInvariant(),
            Type
        );
    }

    public static bool operator ==(Token left, Token right)
    {
        return left?.Equals(right) ?? right is null;
    }

    public static bool operator !=(Token left, Token right)
    {
        return !(left == right);
    }

    public bool Matches(string text, bool caseSensitive = false)
    {
        return caseSensitive
            ? Value == text
            : string.Equals(Value, text, StringComparison.OrdinalIgnoreCase);
    }
}

public enum TokenType
{
    Unknown,
    Identifier,
    Keyword,
    Literal,
    Operator,
    Punctuation,
    Character,
    WhiteSpace
}

