    public class UnitStore : Entity
    {
        private const int COINS_FOR_LUMBER = 5;
        private GuiStoreMenu menu;
        private int spriteX = 0;
        private int offsetX = 12, offsetY = 24;
        private bool isDestroyed = false;

        public UnitStore(int x, int y, Player owner)
        {
            this.x = x;
            this.y = y;
            width = 48;
            height = 48;
            Player = owner;
            maxHealth = health = 200;
        }

        public override void OnFocus()
        {
            if (isDestroyed) return;

            base.OnFocus();
            if (menu == null)
            {
                menu = new GuiStoreMenu(this);
                GuiManager.AddGui(menu, true);
            }
        }

        public override void OnFocusLost()
        {
            base.OnFocusLost();
            if (menu != null && !menu.IsRemoved)
                menu.Remove();
        }

        public void SellWood()
        {
            if (Player.LumberAmount > 0)
            {
                int totalCoins = Player.LumberAmount * COINS_FOR_LUMBER;
                Player.CoinsAmount += totalCoins;
                Player.LumberAmount = 0;
            }
        }

        public override void Update()
        {
            base.Update();

            if (health <= 0 && !isDestroyed)
            {
                isDestroyed = true;
                spriteX = 1;
                OnFocusLost();
                Remove();
            }
        }

        public override void Render(RenderHelper renderer)
        {
            renderer.SetWorldView(true);
            renderer.Sprite(x - offsetX, y - offsetY, Resources.SPRITE_STORE,
                           (byte)(Player.Team.ID + 1), spriteX, 0, 0xFF);

            if (isDestroyed)
                renderer.Sprite(x - offsetX, y - offsetY, Resources.SPRITE_STORE_DESTROYED,
                               0, 0, 0, 0xFF);
        }

        public override void Remove()
        {
            base.Remove();
            if (!isDestroyed)
                Level.RemoveEntity(this);
        }
    }

