namespace AbundantOdd
{
    class Solution
    {
        static void Main(string[] args)
        {
            const int max = 25;
            Console.WriteLine("The first {0} abundant odd numbers are:", max);
            int n = AbundantOdd(1, 0, 25, false);
 
            Console.WriteLine("\nThe one thousandth abundant odd number is:");
            AbundantOdd(n, 25, 1000, true);
 
            Console.WriteLine("\nThe first abundant odd number above one billion is:");
            AbundantOdd(1000000001, 0, 1, true);
 
            Console.ReadLine();
        }
 
        static List<int> Divisors(int n)
        {
            List<int> divs = new List<int>();
            divs.Add(1);
            List<int> divs2 = new List<int>();
 
            for (int i = 2; i * i <= n; i++)
            {
                if (n % i == 0)
                {
                    int j = n / i;
                    divs.Add(i);
                    if (i!= j)
                    {
                        divs2.Add(j);
                    }
                }
            }
            divs.AddRange(divs2.Reverse());
 
            return divs;
        }
 
        static int Sum(List<int> divs)
        {
            return divs.Sum();
        }
 
        static string SumStr(List<int> divs)
        {
            StringBuilder sb = new StringBuilder();
            if (divs.Count > 0)
            {
                sb.Append(divs[0]);
                for (int i = 1; i < divs.Count; i++)
                {
                    sb.Append(" + ");
                    sb.Append(divs[i]);
                }
            }
            return sb.ToString();
        }
 
        static int AbundantOdd(int searchFrom, int countFrom, int countTo, bool printOne)
        {
            int count = countFrom;
            int n = searchFrom;
            for (; count < countTo; n += 2)
            {
                List<int> divs = Divisors(n);
                int tot = Sum(divs);
                if (tot > n)
                {
                    count++;
                    if (printOne && count < countTo)
                    {
                        continue;
                    }
                    string s = SumStr(divs);
                    if (printOne)
                    {
                        Console.WriteLine("{0} < {1} = {2}", n, s, tot);
                    }
                    else
                    {

using System;
using System.Reflection;

public abstract class DynamicFieldMapping
{
    protected PropertyInfo Property { get; }
    protected DynamicCustomMapping Mapping { get; }
    protected bool IsNullable { get; }

    protected DynamicFieldMapping(PropertyInfo property, DynamicCustomMapping mapping, bool isNullable)
    {
        Property = property;
        Mapping = mapping;
        IsNullable = isNullable;
    }

    public abstract void ApplyConfiguration();
}

public class DynamicEnumFieldMapping : DynamicFieldMapping
{
    public DynamicEnumFieldMapping(PropertyInfo property, DynamicCustomMapping mapping, bool isNullable)
        : base(property, mapping, isNullable) { }

    public override void ApplyConfiguration()
    {
        Mapping.ConfigureEnumField(Property.Name, Property.PropertyType);
    }
}

public class DynamicPrimitiveFieldMapping : DynamicFieldMapping
{
    public DynamicPrimitiveFieldMapping(PropertyInfo property, DynamicCustomMapping mapping, bool isNullable)
        : base(property, mapping, isNullable) { }

    public override void ApplyConfiguration()
    {
        Mapping.ConfigurePrimitiveField(Property.Name, Property.PropertyType, IsNullable);
    }
}

public static class FieldMappingFactory
{
    public static DynamicFieldMapping CreateDynamicFieldMapping(PropertyInfo property, DynamicCustomMapping mapping)
    {
        Type type = property.PropertyType;
        bool isNullable = false;
        Type underlyingType = type;

        if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(Nullable<>))
        {
            underlyingType = Nullable.GetUnderlyingType(type);
            isNullable = true;
        }

        Type analyzedType = underlyingType;

        if (analyzedType.IsEnum)
            return new DynamicEnumFieldMapping(property, mapping, isNullable);

        TypeCode typeCode = Type.GetTypeCode(analyzedType);
        if (typeCode != TypeCode.Object)
            return new DynamicPrimitiveFieldMapping(property, mapping, isNullable);

        if (analyzedType.IsArray)
            throw new NotSupportedException(SR.UnsupportedTypeArray);

        if (analyzedType.IsGenericParameter)
            throw new NotSupportedException(SR.UnsupportedTypeGenericParameter);

        if (analyzedType.IsGenericType)
            throw new NotSupportedException(SR.UnsupportedTypeGeneric);

        if (analyzedType.IsClass || analyzedType.IsInterface)
            throw new NotSupportedException(string.Format(SR.UnsupportedTypeComplex, analyzedType));

using System;
 
public class IntegerOverflow
{
    public static void Main() {
        unchecked {
            Console.WriteLine("For 32-bit signed integers:");
            Console.WriteLine(-(-2147483647 - 1));
            Console.WriteLine(2000000000 + 2000000000);
            Console.WriteLine(-2147483647 - 2147483647);
            Console.WriteLine(46341 * 46341);
            Console.WriteLine((-2147483647 - 1) / -1);
            Console.WriteLine();
 
            Console.WriteLine("For 64-bit signed integers:");
            Console.WriteLine(-(-9223372036854775807L - 1));
            Console.WriteLine(5000000000000000000L + 5000000000000000000L);
            Console.WriteLine(-9223372036854775807L - 9223372036854775807L);
            Console.WriteLine(3037000500L * 3037000500L);
            Console.WriteLine((-9223372036854775807L - 1) / -1);
            Console.WriteLine();
 
            Console.WriteLine("For 32-bit unsigned integers:");
            //Negating a 32-bit unsigned integer will convert it to a signed 64-bit integer.
            Console.WriteLine(-4294967295U);
            Console.WriteLine(3000000000U + 3000000000U);
            Console.WriteLine(2147483647U - 4294967295U);
            Console.WriteLine(65537U * 65537U);
            Console.WriteLine();
 
            Console.WriteLine("For 64-bit unsigned integers:");
            // The - operator cannot be applied to 64-bit unsigned integers; it will always give a compile-time error.
            //Console.WriteLine(-18446744073709551615UL);
            Console.WriteLine(10000000000000000000UL + 10000000000000000000UL);
            Console.WriteLine(9223372036854775807UL - 18446744073709551615UL);
            Console.WriteLine(4294967296UL * 4294967296UL);
            Console.WriteLine();
        }
 
        int i = 2147483647;
        Console.WriteLine(i + 1);
        try {
            checked { Console.WriteLine(i + 1); }
        } catch (OverflowException) {
            Console.WriteLine("Overflow!");
        }
    }
 
}

