using System.Collections;
 
namespace ProjectEulerTasks
{
    class Task_301 : Task
    {
        public override void Solve()
        {
            int d = 17;
            Stopwatch sw = new Stopwatch();
            sw.Start();
            int z = IteratedSquareDigit(d);
            sw.Stop();
            Console.WriteLine("d=({0}) in the range 1 to {1}", d, (int)Math.Pow(10, d) - 1);
            Console.WriteLine("{0} numbers produce 1 and {1} numbers produce 89", z, (int)Math.Pow(10, d) - 1 - z);
            Console.WriteLine("Time passed: {0} sec", sw.Elapsed.TotalSeconds);
        }
 
        private int IteratedSquareDigit(int d)
        {
            int[] f = new int[d + 1];
            for (int i = 0; i < f.Length; i++)
            {
                f[i] = Factorial(i);
            }
            Func<int, int> g = (n) =>
            {
                int res = n.ToString().Select(c => (int)Char.GetNumericValue(c)).Sum(d => d * d);
                return res == 89? 0 : res;
            };
 
            int[] table = new int[d * 81 + 1];
            for (int i = 0; i < table.Length; i++)
            {
                table[i] = i == 0? 1 : (i = g(i)) == 89? 0 : i;
            }
            for (int i = 0; i < table.Length; i++)
            {
                while (table[i] > 1)
                {
                    table[i] = table[table[i]];
                }
            }
            int z = 0;
            for (int i = 0; i < (int)Math.Pow(10, d); i++)
            {
                int[] rc = new int[d];
                int j = 0;
                while (i > 0)
                {
                    rc[j++] = i % 10;
                    i /= 10;
                }
                if (table[rc.Select(n => n * n).Sum()] == 0)
                {
                    continue;
                }
                int[] nn = new int[10];
                for (int k = 0; k < rc.Length; k++)
                {
                    nn[rc[k]]++;
                }
                int gn = f[d];
                for (int k = 0; k < nn.Length; k++)
                {
                    gn /= f[nn[k]];
                }
                z += gn;
            }
            return z;
        }
 
        private int Factorial(int n)
        {
            int res = 1;
            for (int i = 2; i <= n; i++)
            {
                res *= i;
            }
            return res;
        }
    }
}

