namespace Orchard.SEO.Drivers {
    public class MetaDriver : ContentPartDriver<MetaPart> {
        private readonly IWorkContextAccessor _wca;
        private readonly IResourceManager _resourceManager;

        public Localizer T { get; set; }

        public MetaDriver(
            IWorkContextAccessor workContextAccessor,
            IResourceManager resourceManager) {
            _wca = workContextAccessor;
            _resourceManager = resourceManager;
            T = NullLocalizer.Instance;
        }

        protected override DriverResult Display(MetaPart part, string displayType, dynamic shapeHelper) {
            if (displayType == "Detail") {
                SetMetadata(part);
                return ContentShape("Parts_Meta", () => shapeHelper.Parts_Meta(Part: part));
            }
            return null;
        }

        protected override DriverResult Editor(MetaPart part, dynamic shapeHelper) {
            return ContentShape("Parts_Meta_Edit", () =>
                shapeHelper.EditorTemplate(
                    TemplateName: "Parts/Meta",
                    Model: part,
                    Prefix: Prefix
                )
            );
        }

        protected override DriverResult Editor(MetaPart part, IUpdateModel updater, dynamic shapeHelper) {
            updater.TryUpdateModel(part, Prefix, null, null);
            return Editor(part, shapeHelper);
        }

        private void SetMetadata(MetaPart part) {
            var workContext = _wca.GetContext();
            var metadata = new List<MetaEntry>();

            if (!string.IsNullOrWhiteSpace(part.MetaDescription)) {
                metadata.Add(new MetaEntry {
                    Name = "description",
                    Content = part.MetaDescription
                });
            }

            if (!string.IsNullOrWhiteSpace(part.MetaKeywords)) {
                metadata.Add(new MetaEntry {
                    Name = "keywords",
                    Content = part.MetaKeywords
                });
            }

            foreach (var entry in metadata) {
                _resourceManager.SetMeta(new MetaEntry {
                    Name = entry.Name,
                    Content = HttpUtility.HtmlEncode(entry.Content)
                });
            }
        }
    }

