using System;
using System.Collections.Generic;
using System.Linq;

public interface IMappingContext
{
    Type TargetType { get; }
}

public abstract class DataSourceBase
{
    protected int Priority { get; private set; }
    protected HashSet<Type> SupportedTypes { get; private set; }

    protected DataSourceBase(int priority = 0)
    {
        Priority = priority;
        SupportedTypes = new HashSet<Type>();
    }

    protected DataSourceBase(IEnumerable<Type> supportedTypes, int priority = 0)
    {
        Priority = priority;
        SupportedTypes = new HashSet<Type>(supportedTypes ?? Enumerable.Empty<Type>());
    }

    public virtual bool CanMap(IMappingContext context)
    {
        if (context?.TargetType == null)
            return false;

        return SupportedTypes.Contains(context.TargetType) ||
               SupportedTypes.Any(type => type.IsAssignableFrom(context.TargetType));
    }

    public abstract bool TryMap(IMappingContext context, out object result);

    protected void AddSupportedType(Type type)
    {
        if (type == null)
            throw new ArgumentNullException(nameof(type));

        SupportedTypes.Add(type);
    }

    protected void RemoveSupportedType(Type type)
    {
        if (type == null)
            throw new ArgumentNullException(nameof(type));

        SupportedTypes.Remove(type);
    }
}

public class DataSourcePropertyType : DataSourceBase
{
    private readonly Func<IMappingContext, object> _generationStrategy;

    public DataSourcePropertyType(
        Func<IMappingContext, object> generationStrategy,
        IEnumerable<Type> supportedTypes,
        int priority = 0) : base(supportedTypes, priority)
    {
        _generationStrategy = generationStrategy ?? throw new ArgumentNullException(nameof(generationStrategy));
    }

    public override bool TryMap(IMappingContext context, out object result)
    {
        result = null;

        if (!CanMap(context))
            return false;

        try
        {
            result = _generationStrategy(context);
            return true;
        }
        catch
        {
            return false;
        }
    }
}

using MassTransit.HttpTransport.Configuration;
using MassTransit.Pipeline;
using MassTransit.Topology;
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

namespace MassTransit.HttpTransport
{
    public class HttpSendTransportProvider : ISendTransportProvider
    {
        private readonly IHttpHostCollection _hosts;
        private readonly HttpClientCache _clientCache;
        private readonly IReceivePipe _receivePipe;
        private readonly ISendTopology _sendTopology;

        public HttpSendTransportProvider(IHttpHostCollection hosts, HttpClientCache clientCache, IReceivePipe receivePipe, ISendTopology sendTopology)
        {
            _hosts = hosts;
            _clientCache = clientCache;
            _receivePipe = receivePipe;
            _sendTopology = sendTopology;
        }

        public async Task<ISendTransport> GetSendTransport(Uri address)
        {
            var hostAddress = new Uri(address.GetLeftPart(UriPartial.Authority));
            var host = _hosts.GetHost(hostAddress);
            var client = _clientCache.GetClient(host);
            return new HttpSendTransport(client, _receivePipe, _sendTopology);
        }
    }

    public class HttpSendTransport : ISendTransport
    {
        private readonly HttpClient _client;
        private readonly IReceivePipe _receivePipe;
        private readonly ISendTopology _sendTopology;

        public HttpSendTransport(HttpClient client, IReceivePipe receivePipe, ISendTopology sendTopology)
        {
            _client = client;
            _receivePipe = receivePipe;
            _sendTopology = sendTopology;
        }

        public async Task Send<T>(SendContext<T> context) where T : class
        {
            var content = new StringContent(context.Serialize(), System.Text.Encoding.UTF8, "application/json");
            var response = await _client.PostAsync(context.DestinationAddress.PathAndQuery, content);
            response.EnsureSuccessStatusCode();
        }

        public Task ConnectSendObserver(ISendObserver observer) => Task.CompletedTask;
    }

    public class HttpClientCache
    {
        private readonly ConcurrentDictionary<Uri, HttpClient> _clients = new();
        public HttpClient GetClient(HttpHost host) => _clients.GetOrAdd(host.Address, _ => new HttpClient { BaseAddress = host.Address });
    }

    public class HttpHost
    {
        public Uri Address { get; }
        public HttpHost(Uri address) => Address = address;
    }
}

