[Flags]
public enum BalloonFlags
{
    None = 0x00,
    Info = 0x01,
    Warning = 0x02,
    Error = 0x03,
    User = 0x04,
    NoSound = 0x10,
    LargeIcon = 0x20,
    RespectQuietTime = 0x40,
    XPStyle = 0x80
}

public class NotificationManager
{
    private const int WM_TRAYICON = 0x800;
    private const int NIF_MESSAGE = 0x01;
    private const int NIF_ICON = 0x02;
    private const int NIF_TIP = 0x04;
    private const int NIF_STATE = 0x08;
    private const int NIF_INFO = 0x10;

    [StructLayout(LayoutKind.Sequential)]
    public struct NOTIFYICONDATA
    {
        public int cbSize;
        public IntPtr hwnd;
        public int uID;
        public int uFlags;
        public int uCallbackMessage;
        public IntPtr hIcon;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)]
        public string szTip;
        public int dwState;
        public int dwStateMask;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 256)]
        public string szInfo;
        public int uTimeout;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)]
        public string szInfoTitle;
        public BalloonFlags dwInfoFlags;
    }

    [DllImport("shell32.dll")]
    private static extern bool Shell_NotifyIcon(int dwMessage, ref NOTIFYICONDATA lpdata);

    public static void ShowBalloonNotification(
        IntPtr windowHandle,
        string title,
        string message,
        BalloonFlags flags)
    {
        NOTIFYICONDATA iconData = new NOTIFYICONDATA
        {
            cbSize = Marshal.SizeOf(typeof(NOTIFYICONDATA)),
            hwnd = windowHandle,
            uFlags = NIF_INFO,
            szInfoTitle = title,
            szInfo = message,
            dwInfoFlags = flags,
            uTimeout = 5000
        };

        Shell_NotifyIcon(0x01, ref iconData);
    }
}

