    {
        int number;
        if (!ReadInteger(out number))
        {
            return;
        }

        int value;
        if (!ReadBitValue(out value))
        {
            return;
        }

        int position;
        if (!ReadBitPosition(out position))
        {
            return;
        }

        int newNumber = ModifyBit(number, value, position);

        Console.WriteLine($"Original number: {number}");
        Console.WriteLine($"Modified number: {newNumber}");
    }

    static bool ReadInteger(out int number)
    {
        Console.WriteLine("Enter an integer:");
        string input = Console.ReadLine();
        if (!int.TryParse(input, out number))
        {
            Console.WriteLine("Error: Invalid integer.");
            return false;
        }
        return true;
    }

    static bool ReadBitValue(out int value)
    {
        Console.WriteLine("Enter the bit value (0 or 1):");
        string input = Console.ReadLine();
        if (!int.TryParse(input, out value))
        {
            Console.WriteLine("Error: Bit value must be an integer.");
            return false;
        }
        if (value != 0 && value != 1)
        {
            Console.WriteLine("Error: Bit value must be 0 or 1.");
            return false;
        }
        return true;
    }

    static bool ReadBitPosition(out int position)
    {
        Console.WriteLine("Enter the bit position (0-31):");
        string input = Console.ReadLine();
        if (!int.TryParse(input, out position))
        {
            Console.WriteLine("Error: Bit position must be an integer.");
            return false;
        }
        if (position < 0 || position > 31)
        {
            Console.WriteLine("Error: Bit position must be between 0 and 31.");
            return false;
        }
        return true;
    }

    static int ModifyBit(int number, int value, int position)
    {
        int mask = 1 << position;
        if (value == 1)
        {
            return number | mask;
        }
        else
        {
            return number & ~mask;
        }
    }
}

