    class Game
    {
        static void Main(string[] args)
        {
            // Sample classes for reflection
            Super sup = new Super("sup");
            Sub sub = new Sub("sub", 0, "I", "two");

            // get enumerable methods on an object and its ancestors
            var methods = GetMethodNames(sub);

            // get enumerable properties on an object and its ancestors
            var properties = GetPropertyNames(sub);

            // alternate way to get enumerable method names on an object and its ancestors
            var methods2 = GetMethodNames2(sub);

            // get enumerable & non-enumerable method names set directly on an object
            var methods3 = GetMethodNames3(sub);

            // get enumerable method names set directly on an object
            var methods4 = GetMethodNames4(sub);

            // get enumerable method names & values set directly on an object
            var methods5 = GetMethodNames5(sub);
        }

        // get enumerable methods on an object and its ancestors
        public static List<string> GetMethodNames(object obj)
        {
            var methods = new List<string>();
            foreach (var p in obj.GetType().GetProperties())
            {
                if (p.PropertyType.IsSubclassOf(typeof(Delegate)))
                {
                    methods.Add(p.Name);
                }
            }
            return methods;
        }

        // get enumerable properties on an object and its ancestors
        public static List<string> GetPropertyNames(object obj)
        {
            var properties = new List<string>();
            foreach (var p in obj.GetType().GetProperties())
            {
                properties.Add(p.Name);
            }
            return properties;
        }

        // alternate way to get enumerable method names on an object and its ancestors
        public static List<string> GetMethodNames2(object obj)
        {
            return GetPropertyNames(obj)
               .Where(p => obj.GetType().GetProperty(p).PropertyType.IsSubclassOf(typeof(Delegate))).ToList();
        }

        // get enumerable & non-enumerable method names set directly on an object
        public static List<string> GetMethodNames3(object obj)
        {
            return obj.GetType().GetProperties().Where(p => p.PropertyType.IsSubclassOf(typeof(Delegate))).Select(p => p.Name).ToList();
        }

