using System;
using System.Collections.Generic;

public class DjangoVariable
{
    public string Name { get; set; }
}

public class BlockParseInfo
{
    public string BlockName { get; set; }
    public IEnumerable<DjangoVariable> Variables { get; set; }
}

public class CompletionInfo
{
    public IEnumerable<string> Suggestions { get; set; }
}

public class BlockClassification
{
    public IEnumerable<Tuple<int, int, string>> Spans { get; set; }
}

public abstract class DjangoBlock
{
    public abstract BlockParseInfo Parse(string block);
    public abstract CompletionInfo GetCompletions(int position);
    public abstract BlockClassification GetSpans();
}

public class DjangoIfOrIfNotEqualBlock : DjangoBlock
{
    private DjangoVariable[] _args;

    public DjangoIfOrIfNotEqualBlock(DjangoVariable[] args)
    {
        _args = args;
    }

    public static DjangoIfOrIfNotEqualBlock Parse(string block)
    {
        // Simplified parsing logic
        var args = new List<DjangoVariable>();
        var parts = block.Split(new[] { ' ', '=' }, StringSplitOptions.RemoveEmptyEntries);
        for (int i = 1; i < parts.Length; i += 2)
        {
            args.Add(new DjangoVariable { Name = parts[i] });
        }
        return new DjangoIfOrIfNotEqualBlock(args.ToArray());
    }

    public override BlockParseInfo Parse(string block)
    {
        var variables = new List<DjangoVariable>();
        foreach (var arg in _args)
        {
            variables.Add(arg);
        }
        return new BlockParseInfo { BlockName = "if", Variables = variables };
    }

    public override CompletionInfo GetCompletions(int position)
    {
        var suggestions = new List<string> { "True", "False" };
        foreach (var arg in _args)
        {
            suggestions.Add(arg.Name);
        }
        return new CompletionInfo { Suggestions = suggestions };
    }

    public override BlockClassification GetSpans()
    {
        var spans = new List<Tuple<int, int, string>>();
        int position = 0;
        foreach (var arg in _args)
        {
            spans.Add(Tuple.Create(position, arg.Name.Length, "variable"));
            position += arg.Name.Length + 1; // +1 for space or equals
        }
        return new BlockClassification { Spans = spans };
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
public class Manager
{
    public static void Main()
    {
        var countryCity = new List<(string, string)>
        {
            ("UK", "London"),
            ("US", "New York"),
            ("US", "Birmingham"),
            ("UK", "Birmingham"),
        };
 
        var citySorted = countryCity.OrderBy(x => x.Item2).ToList();
        var countrySorted = countryCity.OrderBy(x => x.Item1).ToList();
 
        Console.WriteLine("Original:");
        foreach (var x in countryCity)
        {
            Console.WriteLine($"{x.Item1} {x.Item2}");
        }
 
        Console.WriteLine("\nWhen sorted by city:");
        foreach (var x in citySorted)
        {
            Console.WriteLine($"{x.Item1} {x.Item2}");
        }
 
        Console.WriteLine("\nWhen sorted by county:");
        foreach (var x in countrySorted)
        {
            Console.WriteLine($"{x.Item1} {x.Item2}");
        }
    }
}

