public class CommitsByDateAndAuthor
{
    private Dictionary<string, Dictionary<DateTime, int>> yByAuthor;
    private List<string> Authors;
    private List<DateTime> x;
    private List<int> y;
    private List<DateTime> dates;

    public void Init(IRepository repository)
    {
        Authors = repository.GetCommits()
            .Select(c => c.Author)
            .Distinct()
            .ToList();

        yByAuthor = new Dictionary<string, Dictionary<DateTime, int>>();
        foreach (var author in Authors)
        {
            yByAuthor[author] = new Dictionary<DateTime, int>();
        }

        dates = repository.GetCommits()
            .Select(c => c.Date.Date)
            .Distinct()
            .OrderBy(d => d)
            .ToList();
    }

    public void Calc(IRepository repository)
    {
        foreach (var date in dates)
        {
            var commitsOnDate = repository.GetCommits()
                .Where(c => c.Date.Date == date)
                .ToList();

            foreach (var author in Authors)
            {
                int commitCount = commitsOnDate.Count(c => c.Author == author);
                yByAuthor[author][date] = commitCount;
            }
        }
    }

    public void Draw(IGraphView graph)
    {
        graph.SetVisualizationType(VisualizationType.LINEWITHPOINTS);

        foreach (var author in Authors)
        {
            x = new List<DateTime>();
            y = new List<int>();

            foreach (var date in dates)
            {
                x.Add(date);
                y.Add(yByAuthor[author].ContainsKey(date) ? yByAuthor[author][date] : 0);
            }

            graph.AddSeries(author, x, y);
        }

        graph.Render();
    }
}

using System;
using System.Diagnostics;

[DebuggerDisplay("Token = {Value}, Type = {Type}, Sentence = {Sentence}, Column = {FromColumn}")]
public class Token
{
    private string _token;

    public TokenType Type { get; set; }
    public Sentence Sentence { get; set; }
    public int FromColumn { get; set; }
    public int ToColumn { get; set; }

    public Token(string token)
    {
        _token = token;
        Length = token.Length;
    }

    public Token(char token) : this(token.ToString()) { }

    public Token(string token, TokenType type) : this(token)
    {
        Type = type;
    }

    public string Value
    {
        get { return _token; }
        set { _token = value; Length = value.Length; }
    }

    public int Length { get; private set; }

    public static implicit operator string(Token token)
    {
        return token.Value;
    }

    public override string ToString()
    {
        return Value;
    }

    public override bool Equals(object obj)
    {
        if (obj == null) return false;
        if (obj is string) return Value.Equals((string)obj, StringComparison.OrdinalIgnoreCase);
        if (obj is Token) return Value.Equals(((Token)obj).Value, StringComparison.OrdinalIgnoreCase);
        return false;
    }

    public override int GetHashCode()
    {
        return Value.GetHashCode();
    }

    public static bool operator ==(Token a, string b)
    {
        if (ReferenceEquals(a, null) && ReferenceEquals(b, null)) return true;
        if (ReferenceEquals(a, null) || ReferenceEquals(b, null)) return false;
        return a.Value.Equals(b, StringComparison.OrdinalIgnoreCase);
    }

    public static bool operator !=(Token a, string b)
    {
        return !(a == b);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace TaxicabNumber
{
    class Processor
    {
        static void Main(string[] args)
        {
            IDictionary<long, IList<Tuple<int, int>>> taxicabNumbers = GetTaxicabNumbers(2006);
            PrintTaxicabNumbers(taxicabNumbers);
            Console.ReadKey();
        }
 
        private static IDictionary<long, IList<Tuple<int, int>>> GetTaxicabNumbers(int length)
        {
            SortedList<long, IList<Tuple<int, int>>> sumsOfTwoCubes = new SortedList<long, IList<Tuple<int, int>>>();
 
            for (int i = 1; i < int.MaxValue; i++)
            {
                for (int j = 1; j < int.MaxValue; j++)
                {
                    long sum = (long)(Math.Pow((double)i, 3) + Math.Pow((double)j, 3));
 
                    if (!sumsOfTwoCubes.ContainsKey(sum))
                    {
                        sumsOfTwoCubes.Add(sum, new List<Tuple<int, int>>());
                    }
 
                    sumsOfTwoCubes[sum].Add(new Tuple<int, int>(i, j));
 
                    if (j >= i)
                    {
                        break;
                    }
                }
 
                // Found that you need to keep going for a while after the length, because higher i values fill in gaps
                if (sumsOfTwoCubes.Count(t => t.Value.Count >= 2) >= length * 1.1)
                {
                    break;
                }
            }
 
            IDictionary<long, IList<Tuple<int, int>>> values = (from t in sumsOfTwoCubes where t.Value.Count >= 2 select t)
                .Take(2006)
                .ToDictionary(u => u.Key, u => u.Value);
 
            return values;
        }
 
        private static void PrintTaxicabNumbers(IDictionary<long, IList<Tuple<int, int>>> values)
        {
            int i = 1;
 
            foreach (long taxicabNumber in values.Keys)
            {
                StringBuilder output = new StringBuilder().AppendFormat("{0,10}\t{1,4}", i, taxicabNumber);
 
                foreach (Tuple<int, int> numbers in values[taxicabNumber])
                {
                    output.AppendFormat("\t= {0}^3 + {1}^3", numbers.Item1, numbers.Item2);
                }
 
                if (i <= 25 || (i >= 2000 && i <= 2006))
                {
                    Console.WriteLine(output.ToString());
                }
 
                i++;
            }
        }
    }
}

