using System;
using System.Runtime.InteropServices;
using SolidEdgeFramework;
using SolidEdgePart;
using SolidEdgeFrameworkSupport;

class Stack
{
    static void Main(string[] args)
    {
        Application application = null;
        Documents documents = null;
        PartDocument partDocument = null;
        RefPlanes refPlanes = null;
        ProfileSets profileSets = null;
        ProfileSet profileSet = null;
        Profiles profiles = null;
        Profile profile = null;
        Circles2d circles2d = null;
        Circle2d circle2d = null;
        double x = 0.0, y = 0.0;
        double radius = 10.0;

        try
        {
            OleMessageFilter.Register();

            // Connect to a running instance of Solid Edge
            application = (Application)Marshal.GetActiveObject("SolidEdge.Application");
            application.Visible = true;

            // Get the documents collection
            documents = application.Documents;

            // Create a new part document
            partDocument = (PartDocument)documents.Add("SolidEdge.PartDocument");

            // Get the reference planes collection
            refPlanes = partDocument.RefPlanes;

            // Get the profile sets collection
            profileSets = partDocument.ProfileSets;

            // Add a profile set
            profileSet = profileSets.Add(refPlanes.Item(1));

            // Get the profiles collection
            profiles = profileSet.Profiles;

            // Add a profile
            profile = profiles.Add(FeaturePropertyConstants.igProfilePlaneFront);

            // Get the circles2d collection
            circles2d = profile.Circles2d;

            // Add a circle by center and radius
            circle2d = circles2d.AddByCenterRadius(x, y, radius);

            // Get the center point of the circle
            circle2d.GetCenterPoint(ref x, ref y);

            // Output the center coordinates of the circle
            Console.WriteLine($"Circle Center: ({x}, {y})");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
        finally
        {
            OleMessageFilter.Unregister();

            // Release COM objects to fully kill Solid Edge process from running in the background
            if (circle2d != null) Marshal.ReleaseComObject(circle2d);
            if (circles2d != null) Marshal.ReleaseComObject(circles2d);
            if (profile != null) Marshal.ReleaseComObject(profile);
            if (profiles != null) Marshal.ReleaseComObject(profiles);

