using System;

public class IndexOptions : IEquatable<IndexOptions>
{
    public bool Unique { get; set; }
    public bool IgnoreCase { get; set; }
    public bool TrimWhitespace { get; set; }
    public bool EmptyStringToNull { get; set; }
    public bool RemoveAccents { get; set; }

    public IndexOptions()
    {
        Unique = false;
        IgnoreCase = false;
        TrimWhitespace = false;
        EmptyStringToNull = false;
        RemoveAccents = false;
    }

    public bool Equals(IndexOptions other)
    {
        if (other == null)
        {
            return false;
        }

        return Unique == other.Unique &&
               IgnoreCase == other.IgnoreCase &&
               TrimWhitespace == other.TrimWhitespace &&
               EmptyStringToNull == other.EmptyStringToNull &&
               RemoveAccents == other.RemoveAccents;
    }

    public override bool Equals(object obj)
    {
        return Equals(obj as IndexOptions);
    }

    public override int GetHashCode()
    {
        // Implement a proper hash code calculation based on the properties
        // This is a simple example and may not be suitable for all cases
        return HashCode.Combine(Unique, IgnoreCase, TrimWhitespace, EmptyStringToNull, RemoveAccents);
    }

    public IndexOptions Clone()
    {
        return new IndexOptions
        {
            Unique = this.Unique,
            IgnoreCase = this.IgnoreCase,
            TrimWhitespace = this.TrimWhitespace,
            EmptyStringToNull = this.EmptyStringToNull,
            RemoveAccents = this.RemoveAccents
        };
    }

    public override string ToString()
    {
