using System;
using System.IO;
using System.Linq;

public interface IResourceBlock
{
    void LoadClusterData();
    void DeleteClusterData();
}

public class StructureBspClusterBlock : IResourceBlock
{
    private GeometryBlockInfo _geometryBlockInfo;
    private StructureBspClusterDataBlockNew _clusterData;
    private byte[] _vertexBuffer;
    private long[] _resourcePointers;
    private int[] _resourceLengths;

    public StructureBspClusterBlock(GeometryBlockInfo geometryBlockInfo)
    {
        _geometryBlockInfo = geometryBlockInfo;
        _resourcePointers = new long[_geometryBlockInfo.ResourceCount];
        _resourceLengths = new int[_geometryBlockInfo.ResourceCount];
    }

    public long GetResourcePointer(int index)
    {
        if (index < 0 || index >= _resourcePointers.Length)
            throw new ArgumentOutOfRangeException(nameof(index));
        return _resourcePointers[index];
    }

    public int GetResourceLength(int index)
    {
        if (index < 0 || index >= _resourceLengths.Length)
            throw new ArgumentOutOfRangeException(nameof(index));
        return _resourceLengths[index];
    }

    public void SetResourcePointer(int index, long pointer)
    {
        if (index < 0 || index >= _resourcePointers.Length)
            throw new ArgumentOutOfRangeException(nameof(index));
        _resourcePointers[index] = pointer;
    }

    public void SetResourceLength(int index, int length)
    {
        if (index < 0 || index >= _resourceLengths.Length)
            throw new ArgumentOutOfRangeException(nameof(index));
        _resourceLengths[index] = length;
    }

    public void LoadClusterData()
    {
        using (var stream = new MemoryStream(_geometryBlockInfo.CachedResourceData))
        {
            using (var reader = new BinaryReader(stream))
            {
                for (int i = 0; i < _geometryBlockInfo.ResourceCount; i++)
                {
                    stream.Seek(_resourcePointers[i], SeekOrigin.Begin);
                    _clusterData = new StructureBspClusterDataBlockNew(reader);
                    _vertexBuffer = reader.ReadBytes(_resourceLengths[i]);
                }
            }
        }
    }

    public void DeleteClusterData()
    {
        _vertexBuffer = null;
        _clusterData = null;
    }

    public bool IsClusterDataLoaded()
    {
        return _clusterData != null && _vertexBuffer != null;
    }

    public StructureBspClusterDataBlockNew GetClusterData()
    {
        return _clusterData;
    }
}

