public class StressTests
{
    private const int TimeoutMilliseconds = 5000;
    private const int TerminationDelayMilliseconds = 2000;
    private InteractiveHost _host;

    [Fact]
    public async Task TestKill()
    {
        _host = new InteractiveHost();
        await RunStressTestAsync();
        await _host.DisposeAsync();
    }

    private async Task RunStressTestAsync()
    {
        for (int i = 0; i < 5; i++)
        {
            var executionTask = ExecuteAsync();
            var terminationTask = KillHostAfterAsync();

            await Task.WhenAny(executionTask, terminationTask);
            await ResetAsync();
        }
    }

    private async Task ExecuteAsync()
    {
        try
        {
            var result = await _host.ExecuteAsync("1 + 1", TimeoutMilliseconds);
            Console.WriteLine($"Execution Result: {result}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Execution Error: {ex.Message}");
        }
    }

    private async Task KillHostAfterAsync()
    {
        await Task.Delay(TerminationDelayMilliseconds);
        Console.WriteLine("Terminating host...");

        try
        {
            _host.Terminate();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Termination Error: {ex.Message}");
        }
    }

    private async Task ResetAsync()
    {
        Console.WriteLine("Resetting host...");
        try
        {
            await _host.ResetAsync();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Reset Error: {ex.Message}");
        }
    }
}

