namespace TaxCalculationModule
{
    public class Product
    {
        public decimal Value { get; set; }
        public int Quantity { get; set; }
        public decimal PISPercentage { get; set; }
        public decimal? IPI { get; set; }

        public Product(decimal value, int quantity, decimal pisPercentage, decimal? ipi = null)
        {
            Value = value;
            Quantity = quantity;
            PISPercentage = pisPercentage;
            IPI = ipi;
        }
    }

    public class TaxCalculationResult
    {
        public decimal BaseValue { get; set; }
        public decimal TaxAmount { get; set; }
    }

    public class TaxCalculationFacade
    {
        public TaxCalculationResult CalculatePIS(Product product)
        {
            // Calculate base: normally unit value * quantity
            decimal baseValue = product.Value * product.Quantity;

            // If IPI is provided and is greater than zero, add it per unit
            if (product.IPI.HasValue && product.IPI.Value > 0)
            {
                baseValue = (product.Value + product.IPI.Value) * product.Quantity;
            }

            // Calculate the PIS tax based on the percentage provided
            decimal taxAmount = baseValue * (product.PISPercentage / 100);
            return new TaxCalculationResult { BaseValue = baseValue, TaxAmount = taxAmount };
        }
    }
}

