namespace RosettaCodeData
{
    class Runner
    {
        static void Main(string[] args)
        {
            string data = ">Rosetta_Example_1\nTHERECANBENOSPACE\n>Rosetta_Example_2\nTHERECANBESEVERAL\nLINESBUTTHEYALLMUST\nBECONCATENATED";
            Console.WriteLine(fasta_format(data));
            Console.ReadLine();
        }
 
        static string fasta_format(string strings)
        {
            List<string> outList = new List<string>();
            string text = "";
            foreach (string line in strings.Split('\n'))
            {
                if (line[0] == '>')
                {
                    if (text!= "")
                    {
                        outList.Add(text);
                    }
                    text = line.Substring(1) + ": ";
                }
                else
                {
                    text += line;
                }
            }
            if (text!= "")
            {
                outList.Add(text);
            }
            return string.Join("\n", outList);
        }
    }
}

using System;
 
public class Stack
{
    public static void table(string title, string mode)
    {
        int f, b;
        Console.WriteLine("\n\033[1m{0}\033[m\n bg\t fg\n", title);
        for (b = 40; b <= 107; b++) {
            if (b == 48) b = 100;
            Console.Write("{0}\t\033[{1}{2}m", b, mode, b);
            for (f = 30; f <= 97; f++) {
                if (f == 38) f = 90;
                Console.Write("\033[{0}m{1} ", f, f);
            }
            Console.WriteLine("\033[m");
        }
    }
 
    public static void Main()
    {
        int fg, bg, blink, inverse;
 
        table("normal ( ESC[22m or ESC[m )", "22;");
        table("bold ( ESC[1m )", "1;");
        table("faint ( ESC[2m ), not well supported", "2;");
        table("italic ( ESC[3m ), not well supported", "3;");
        table("underline ( ESC[4m ), support varies", "4;");
        table("blink ( ESC[5m )", "5;");
        table("inverted ( ESC[7m )", "7;");
    }
}

