namespace DataSourceFramework
{
    public interface IMappingContext
    {
        Type TargetMemberType { get; }
    }

    public abstract class DataSourceBase
    {
        public int Priority { get; private set; }

        protected DataSourceBase(int priority)
        {
            Priority = priority;
        }

        public abstract bool TryMap(IMappingContext context, out object value);
    }

    public abstract class DataSourcePropertyType : DataSourceBase
    {
        public IReadOnlyCollection<Type> SupportedTypes { get; }

        protected DataSourcePropertyType(IReadOnlyCollection<Type> supportedTypes, int priority)
            : base(priority)
        {
            if (supportedTypes == null || !supportedTypes.Any())
                throw new ArgumentException("Supported types must not be null or empty.", nameof(supportedTypes));

            SupportedTypes = supportedTypes;
        }

        protected bool IsTypeSupported(Type targetType)
        {
            return SupportedTypes.Any(type => type == targetType);
        }

        public override bool TryMap(IMappingContext context, out object value)
        {
            if (context == null)
                throw new ArgumentNullException(nameof(context));

            Type targetType = context.TargetMemberType;
            if (IsTypeSupported(targetType))
            {
                value = GenerateValue(targetType);
                return true;
            }
            value = null;
            return false;
        }

        protected abstract object GenerateValue(Type targetType);
    }

    public class NumericDataSource : DataSourcePropertyType
    {
        public NumericDataSource()
            : base(new List<Type> { typeof(int), typeof(double) }, 100)
        {
        }

        protected override object GenerateValue(Type targetType)
        {
            if (targetType == typeof(int))
                return 42;
            if (targetType == typeof(double))
                return 3.14;
            return null;
        }
    }

    public class SimpleMappingContext : IMappingContext
    {
        public Type TargetMemberType { get; private set; }

        public SimpleMappingContext(Type targetMemberType)
        {
            TargetMemberType = targetMemberType;
        }
    }

