    public static class WalletManagerExtensions
    {
        public static BitcoinAddress GetUnusedAddress(this IWalletManager walletManager,
            string walletName = null, string accountName = null)
        {
            if (!walletManager.Wallets.Any())
                throw new WalletException("No wallets found in node instance");

            walletName ??= walletManager.Wallets.First().Name;
            accountName ??= WalletManager.DefaultAccount;

            var accountReference = new WalletAccountReference(walletName, accountName);
            return walletManager.GetUnusedAddress(accountReference);
        }

        public static Wallet GetFirstWallet(this IWalletManager walletManager)
        {
            return walletManager.Wallets.FirstOrDefault()
                ?? throw new WalletException("No wallets available");
        }

        public static HdAccount GetDefaultAccount(this Wallet wallet)
        {
            return wallet.AccountsRoot.First().Accounts.First()
                ?? throw new WalletException("No accounts available");
        }
    }
