using System;

namespace FunctionalPipeline
{
    // Represents the result produced from a pipeline operation.
    public class Result<T>
    {
        public bool IsSuccess { get; }
        public T Value { get; }
        public Exception Error { get; }

        private Result(bool isSuccess, T value, Exception error)
        {
            IsSuccess = isSuccess;
            Value = value;
            Error = error;
        }

        public static Result<T> Success(T value)
        {
            return new Result<T>(true, value, null);
        }

        public static Result<T> Failure(Exception error)
        {
            return new Result<T>(false, default(T), error);
        }
    }

    // A deferred or scheduled pipeline holding a result producing operation.
    public class Pipeline<T>
    {
        private readonly Func<Result<T>> _operation;

        // ExceptionHandler is used to handle any exceptions thrown during execution.
        public Func<Exception, Result<T>> ExceptionHandler { get; set; }

        public Pipeline(Func<Result<T>> operation)
        {
            _operation = operation;
            // Default exception handling: wrap the exception as a failure result.
            ExceptionHandler = (ex) => Result<T>.Failure(ex);
        }

        // Executes the pipeline operation with exception handling.
        public Result<T> Execute()
        {
            try
            {
                return _operation();
            }
            catch (Exception ex)
            {
                return ExceptionHandler(ex);
            }
        }
    }

    // A static class holding extension methods that enable chaining operations.
    public static class PipelineExtensions
    {
        // Attaches a custom exception handler to the pipeline.
        public static Pipeline<T> Catch<T>(this Pipeline<T> pipeline, Func<Exception, Result<T>> handler)
        {
            pipeline.ExceptionHandler = handler;
            return pipeline;
        }

        // Continues the pipeline with an action that uses the successful result.
        // If the pipeline result is a failure, the continuation is skipped.
        public static Pipeline<T> ContinueWith<T>(this Pipeline<T> pipeline, Action<T> continuation)
        {
            return new Pipeline<T>(() =>
            {
                var result = pipeline.Execute();
                if (result.IsSuccess)
                {
                    try
                    {
                        continuation(result.Value);
                        return result;
                    }

