public class CellInfoLayerPool : IDisposable
{
    private readonly Stack<PooledCellInfoLayer> pool = new Stack<PooledCellInfoLayer>();
    private readonly object lockObject = new object();
    private readonly int maxPoolSize;
    private readonly Size mapSize;

    public CellInfoLayerPool(int maxPoolSize, Size mapSize)
    {
        this.maxPoolSize = maxPoolSize;
        this.mapSize = mapSize;
    }

    public PooledCellInfoLayer Get()
    {
        lock (lockObject)
        {
            if (pool.Count > 0)
            {
                return pool.Pop();
            }
            else
            {
                return new PooledCellInfoLayer(this, mapSize);
            }
        }
    }

    public void ReturnLayer(PooledCellInfoLayer layer)
    {
        lock (lockObject)
        {
            if (pool.Count < maxPoolSize)
            {
                layer.Reset();
                pool.Push(layer);
            }
        }
    }

    public void Dispose()
    {
        lock (lockObject)
        {
            while (pool.Count > 0)
            {
                var layer = pool.Pop();
                layer.Dispose();
            }
        }
    }
}

public class PooledCellInfoLayer : IDisposable
{
    private readonly CellInfoLayerPool pool;
    private readonly CellLayer<CellInfo> layer;

    public PooledCellInfoLayer(CellInfoLayerPool pool, Size mapSize)
    {
        this.pool = pool;
        this.layer = new CellLayer<CellInfo>(mapSize);
        InitializeLayer();
    }

    public CellLayer<CellInfo> Layer => layer;

    public void Reset()
    {
        InitializeLayer();
    }

    private void InitializeLayer()
    {
        for (int x = 0; x < layer.Width; x++)
        {
            for (int y = 0; y < layer.Height; y++)
            {
                layer[x, y] = new CellInfo { Cost = 1, Status = CellStatus.Open };
            }
        }
    }

    public void Dispose()
    {
        pool.ReturnLayer(this);
    }
}

public struct CellLayer<T>
{
    public int Width { get; }
    public int Height { get; }
    private readonly T[,] grid;

    public CellLayer(Size size)
    {
        Width = size.Width;
        Height = size.Height;
        grid = new T[Width, Height];
    }

    public T this[int x, int y]
    {
        get => grid[x, y];
        set => grid[x, y] = value;
    }
}

public struct CellInfo
{
    public int Cost { get; set; }
    public CellStatus Status { get; set; }
}

public enum CellStatus
{
    Open,
    Closed,
    Blocked
}

