        public void InvalidNamedConnectedStringThrows()
        {
            var settings = new Dictionary<string, string>
            {
                { Environment.ConnectionStringName, "InvalidConnection" }
            };

            Assert.Throws<HibernateException>(() => _connectionProvider.Configure(settings));
        }

        [Test]
        public void ConnectionStringInSettingsOverrideNamedConnectionSTring()
        {
            var settings = new Dictionary<string, string>
            {
                { Environment.ConnectionStringName, "NamedConnection" },
                { Environment.ConnectionString, "DirectConnection" }
            };

            _connectionProvider.Configure(settings);
            Assert.AreEqual("DirectConnection", _connectionProvider.GetConnectionString());
        }

        [Test]
        public void CanGetNamedConnectionStringFromConfiguration()
        {
            var settings = new Dictionary<string, string>
            {
                { Environment.ConnectionStringName, "ValidConnection" }
            };

            var configurations = new Dictionary<string, string>
            {
                { "ValidConnection", "ValidConnectionString" }
            };

            _connectionProvider.Configure(settings, configurations);
            Assert.AreEqual("ValidConnectionString", _connectionProvider.GetConnectionString());
        }
    }

