            for (int i = 0; i < MessageCount; i++)
            {
                _simpleBus.Send(new Message2 { Content = "Test message" });
            }

            _stopwatch.Stop();
            Console.WriteLine($"Simple Bus: Processed {MessageCount} messages in {_stopwatch.ElapsedMilliseconds} ms.");
            Assert.AreEqual(MessageCount, _consumer.ReceivedCount);
