{
    [Header("UI Elements")]
    public Text winnerText;
    public Text player1Text;
    public Text player2Text;
    public Text nextLeftPlayers;
    public Text nextRightPlayers;

    private const int maxRetries = 3;

    public override void OnActivation()
    {
        winnerText.text = "Loading results...";
        player1Text.text = "";
        player2Text.text = "";
        nextLeftPlayers.text = "";
        nextRightPlayers.text = "";

        StartCoroutine(LoadMatchInfo());
        StartCoroutine(LoadUpcomingMatches());
    }

    public override void OnDeactivation()
    {
        // Reset UI elements or clear them if needed
    }

    private IEnumerator LoadMatchInfo()
    {
        int retries = 0;
        while (retries < maxRetries)
        {
            yield return StartCoroutine(GetMatchInfo((matchInfo) =>
            {
                if (matchInfo != null)
                {
                    OnMatchInfoDownloaded(matchInfo);
                }
                else
                {
                    Debug.LogWarning("Failed to retrieve match info, retrying...");
                    retries++;
                }
            }));

            if (retries < maxRetries)
                break; // Break if successfully got data
        }
    }

    private IEnumerator LoadUpcomingMatches()
    {
        int retries = 0;
        while (retries < maxRetries)
        {
            yield return StartCoroutine(GetUpcomingMatches((upcomingMatches) =>
            {
                if (upcomingMatches != null)
                {
                    OnUpcomingMatchesDownloaded(upcomingMatches);
                }
                else
                {
                    Debug.LogWarning("Failed to retrieve upcoming matches, retrying...");
                    retries++;
                }
            }));

            if (retries < maxRetries)
                break; // Break if successfully got data
        }
    }

    private void OnMatchInfoDownloaded(MatchInfo matchInfo)
    {
        player1Text.text = matchInfo.Player1Name;
        player2Text.text = matchInfo.Player2Name;
        winnerText.text = DetermineWinner(matchInfo);
    }

    private void OnUpcomingMatchesDownloaded(List<MatchInfo> upcomingMatches)
    {
        if (upcomingMatches.Count > 0)
        {
            nextLeftPlayers.text = upcomingMatches[0].Player1Name + " vs " + upcomingMatches[0].Player2Name;

