public abstract class SerializeBase
{
    public Encoding Encoder { get; set; } = Encoding.UTF8;

    public abstract byte[] Serialize(object obj);

    public abstract object Deserialize(byte[] data, Type type);

    public T Deserialize<T>(byte[] data)
    {
        return (T)Deserialize(data, typeof(T));
    }

    public static SerializeBase GetInstance()
    {
        return new BinarySerialize();
    }
}

public class BinarySerialize : SerializeBase
{
    public override byte[] Serialize(object obj)
    {
        if (obj == null)
            return new byte[0];

        var type = obj.GetType();
        var fields = type.GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
        var length = 0;

        foreach (var field in fields)
        {
            var fieldType = field.FieldType;
            if (fieldType == typeof(string))
            {
                var strValue = (string)field.GetValue(obj);
                var bytes = Encoder.GetBytes(strValue);
                length += sizeof(int) + bytes.Length;
            }
            else if (fieldType.IsValueType)
            {
                length += Marshal.SizeOf(fieldType);
            }
        }

        var result = new byte[length];
        var offset = 0;

        foreach (var field in fields)
        {
            var fieldType = field.FieldType;
            if (fieldType == typeof(string))
            {
                var strValue = (string)field.GetValue(obj);
                var bytes = Encoder.GetBytes(strValue);
                var lengthBytes = BitConverter.GetBytes(bytes.Length);
                Array.Copy(lengthBytes, 0, result, offset, sizeof(int));
                offset += sizeof(int);
                Array.Copy(bytes, 0, result, offset, bytes.Length);
                offset += bytes.Length;
            }
            else if (fieldType.IsValueType)
            {
                var value = field.GetValue(obj);
                var bytes = BitConverter.GetBytes(value);
                Array.Copy(bytes, 0, result, offset, bytes.Length);
                offset += bytes.Length;
            }
        }

        return result;
    }

    public override object Deserialize(byte[] data, Type type)
    {
        var obj = Activator.CreateInstance(type);
        var fields = type.GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
        var offset = 0;

        foreach (var field in fields)
        {
            var fieldType = field.FieldType;

