public class CommitsByDateAndAuthor : DatePeriodVisualization
{
    private Dictionary<string, List<int>> yByAuthor;
    private List<DateTime> dates;
    public List<string> Authors { get; private set; }

    public override void Init()
    {
        base.Init();
        Authors = Repository.Selection.Commits()
            .Select(c => c.Author)
            .Distinct()
            .OrderBy(a => a)
            .ToList();
        yByAuthor = new Dictionary<string, List<int>>();
        dates = new List<DateTime>();
    }

    public override void Calc()
    {
        if (Authors == null || Authors.Count == 0) return;

        DateTime start = StartDate.Date;
        DateTime end = EndDate.Date;
        TimeSpan interval = TimeSpan.FromDays(7);

        dates.Clear();
        for (var dt = start; dt <= end; dt = dt.Add(interval))
        {
            dates.Add(dt);
        }

        foreach (var author in Authors)
        {
            var counts = new List<int>();
            for (int i = 0; i < dates.Count - 1; i++)
            {
                var periodStart = dates[i];
                var periodEnd = dates[i + 1];

                var count = Repository.Selection.Commits()
                    .Where(c => c.Author == author && c.Date >= periodStart && c.Date < periodEnd)
                    .Count();

                counts.Add(count);
            }
            yByAuthor[author] = counts;
        }
    }

    public override void Draw()
    {
        if (dates.Count < 2 || yByAuthor == null) return;

        var firstDate = dates.First();
        var xValues = dates
            .Take(dates.Count - 1)
            .Select(d => (int)(d - firstDate).TotalDays)
            .ToList();

        var chart = new Chart
        {
            Title = "Commit Activity Timeline",
            XAxis = { Title = "Days Since First Commit" },
            YAxis = { Title = "Commits per Week" }
        };

        foreach (var author in Authors)
        {
            if (!yByAuthor.ContainsKey(author)) continue;

            var series = new Series
            {
                Name = author,
                Type = SeriesType.Line,
                MarkerType = MarkerType.Circle
            };

            for (int i = 0; i < xValues.Count; i++)
            {
                series.Points.Add(new DataPoint(xValues[i], yByAuthor[author][i]));
            }

            chart.Series.Add(series);
        }

