namespace Fugu.Text
{
    public class Text : IEnumerable<char>
    {
        public static Text Empty => new Text();

        private StringBuilder _stringBuilder;

        private bool _valueDirty = false;

        private string _value;

        public Text()
            : this(null)
        {
        }

        public Text(string value)
        {
            _value = value ?? string.Empty;
        }

        public char this[int index]
        {
            get
            {
                if (index < 0)
                {
                    throw new ArgumentOutOfRangeException(nameof(index));
                }
                if (!_valueDirty)
                {
                    if (_value.Length <= index)
                    {
                        throw new ArgumentOutOfRangeException(nameof(index));
                    }
                    return _value[index];
                }
                else
                {
                    if (_stringBuilder.Length <= index)
                    {
                        throw new ArgumentOutOfRangeException(nameof(index));
                    }
                    return _stringBuilder[index];
                }
            }
        }

        public string Value
        {
            get
            {
                if (_valueDirty)
                {
                    _value = _stringBuilder.ToString();
                    _valueDirty = false;
                    _stringBuilder.Length = 0;
                }
                return _value;
            }
            set
            {
                _value = value ?? string.Empty;
                _valueDirty = false;
                if (_stringBuilder != null)
                {
                    _stringBuilder.Length = 0;
                }
            }
        }

        public int Length
        {
            get
            {
                if (!_valueDirty)
                {
                    return _value?.Length ?? 0;
                }
                else
                {
                    return _stringBuilder.Length;
                }
            }
        }

        public void Clear()
        {
            if (!_valueDirty)
            {
                _value = null;
            }
            else
            {
                _stringBuilder.Length = 0;
            }
        }

        public char[] ToCharArray()
        {
            return Value.ToCharArray();
        }

