[ComImport]
[Guid("00021500-0000-0000-C000-000000000046")]
[InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
public interface IQueryInfo
{
    [PreserveSig]
    int GetInfoTip(
        [In] QITIPF dwFlags,
        [Out, MarshalAs(UnmanagedType.LPWStr)] out string ppwszTip
    );

    [PreserveSig]
    int GetInfoFlags(
        [Out] out QITIPF pdwFlags
    );
}

[Flags]
public enum QITIPF
{
    QITIPF_DEFAULT = 0x00000000,
    QITIPF_USENAME = 0x00000001,
    QITIPF_LINKNOTARGET = 0x00000002,
    QITIPF_LINKUSETARGET = 0x00000004,
    QITIPF_IGNOREMIME = 0x00000008
}

public static class ShellInfoHelper
{
    public static string RetrieveShellItemTooltip(IQueryInfo queryInfo)
    {
        try
        {
            if (queryInfo == null)
                return string.Empty;

            queryInfo.GetInfoTip(QITIPF.QITIPF_DEFAULT, out string tooltipText);
            return tooltipText ?? string.Empty;
        }
        catch (Exception)
        {
            return string.Empty;
        }
        finally
        {
            Marshal.ReleaseComObject(queryInfo);
        }
    }
}

