public class BillingExample : MonoBehaviour
{
    public DefaultPreviewButton initButton;
    public DefaultPreviewButton purchaseButton;
    public DefaultPreviewButton consumeButton;
    public AndroidMessage errorMessage;

    private bool isPaymentInitialized = false;
    private bool hasPurchasedProduct = false;

    void FixedUpdate()
    {
        // Update UI buttons based on payment system initialization status
        initButton.Enabled = !isPaymentInitialized;
        purchaseButton.Enabled = isPaymentInitialized;
        consumeButton.Enabled = isPaymentInitialized && hasPurchasedProduct;
    }

    public void Init()
    {
        if (!isPaymentInitialized)
        {
            GPaymnetManagerExample.Instance.InitializePaymentSystem();
            isPaymentInitialized = true;
            Debug.Log("Payment system initialized.");
        }
        else
        {
            errorMessage.Show("Payment system is already initialized.");
        }
    }

    public void SuccessPurchase()
    {
        if (isPaymentInitialized)
        {
            GPaymnetManagerExample.Instance.PurchaseProduct("product_id", OnPurchaseSuccess, OnPurchaseFailed);
        }
        else
        {
            errorMessage.Show("Payment system is not initialized.");
        }
    }

    public void FailPurchase()
    {
        if (isPaymentInitialized)
        {
            GPaymnetManagerExample.Instance.PurchaseProduct("invalid_product_id", OnPurchaseSuccess, OnPurchaseFailed);
        }
        else
        {
            errorMessage.Show("Payment system is not initialized.");
        }
    }

    public void ConsumeProduct()
    {
        if (isPaymentInitialized && hasPurchasedProduct)
        {
            GPaymnetManagerExample.Instance.ConsumeProduct("product_id", OnConsumeSuccess, OnConsumeFailed);
        }
        else
        {
            errorMessage.Show("Cannot consume product. Either payment system is not initialized or product is not owned.");
        }
    }

    private void OnPurchaseSuccess(string productId)
    {
        hasPurchasedProduct = true;
        Debug.Log($"Purchase successful for product: {productId}");
    }

    private void OnPurchaseFailed(string error)
    {
        errorMessage.Show($"Purchase failed: {error}");
    }

    private void OnConsumeSuccess(string productId)
    {
        hasPurchasedProduct = false;
        Debug.Log($"Product consumed: {productId}");
    }

    private void OnConsumeFailed(string error)
    {
        errorMessage.Show($"Consume failed: {error}");

