        // Initialize the text that will be displayed on the sign
        whatItSays = signText;

        // Ensure there's a background texture for the GUI box
        if (BoxTexture == null)
        {
            BoxTexture = new Texture2D(1, 1);
            BoxTexture.SetPixel(0, 0, new Color(0f, 0f, 0f, 0.7f));
            BoxTexture.Apply();
        }

        // Ensure a font is assigned, default to Arial if not provided
        if (signFont == null)
        {
            signFont = Font.CreateDynamicFontFromOSFont("Arial", 16);
        }
    }

    // OnGUI is called for rendering and handling GUI events.
    void OnGUI()
    {
        // Create a GUIStyle for our text
        GUIStyle guiStyle = new GUIStyle();
        guiStyle.font = signFont;
        guiStyle.normal.textColor = Color.white;
        guiStyle.wordWrap = true;

        // Display help text prompt if active and sign text is not showing
        if (showHelpText && !isTextDisplaying)
        {
            GUI.Box(new Rect(10, Screen.height - 60, 220, 50), "");
            GUI.Label(new Rect(20, Screen.height - 50, 200, 30), helpText, guiStyle);
        }

        // If the sign text is active, display it in a centered box
        if (isTextDisplaying)
        {
            int boxWidth = Screen.width / 2;
            int boxHeight = Screen.height / 4;
            int boxX = (Screen.width - boxWidth) / 2;
            int boxY = (Screen.height - boxHeight) / 2;

            // Draw a background box for the sign text
            GUI.DrawTexture(new Rect(boxX, boxY, boxWidth, boxHeight), BoxTexture);

