namespace WallNetCore.Helper
{
    public class ExtendedRandom : Random
    {
        private const int HalfwayInt = int.MaxValue / 2;

        public ExtendedRandom() : base(Guid.NewGuid().GetHashCode()) { }
        public ExtendedRandom(int seed) : base(seed) { }

        public bool NextBool()
        {
            return NextInt32() > HalfwayInt;
        }

        public double NextDouble(double max)
        {
            Validate.IsGreaterThanZero(max, nameof(max));
            return InternalNextDouble(0, max);
        }

        public double NextDouble(double min, double max)
        {
            Validate.IsLessThan(min, max, nameof(min), nameof(max));
            return InternalNextDouble(min, max);
        }

        public float NextFloat()
        {
            return NextFloat(float.MaxValue);
        }

        public float NextFloat(float max)
        {
            Validate.IsGreaterThanZero(max, nameof(max));
            return InternalNextFloat(0, max);
        }

        public float NextFloat(float min, float max)
        {
            Validate.IsLessThan(min, max, nameof(min), nameof(max));
            return InternalNextFloat(min, max);
        }

        private double InternalNextDouble(double min, double max)
        {
            return min + (max - min) * NextDouble();
        }

        private float InternalNextFloat(float min, float max)
        {
            byte[] randomBytes = new byte[4];
            NextBytes(randomBytes);
            int randomInt = BitConverter.ToInt32(randomBytes, 0);
            float randomFloat = WallMath.IntToFloat(randomInt);
            return min + (max - min) * randomFloat;
        }
    }

    public static class Validate
    {
        public static void IsGreaterThanZero(double value, string paramName)
        {
            if (value <= 0)
                throw new ArgumentOutOfRangeException(paramName, value, "Value must be greater than zero.");
        }

        public static void IsLessThan(double min, double max, string minParamName, string maxParamName)
        {
            if (min >= max)
                throw new ArgumentOutOfRangeException(minParamName, min, $"Value must be less than {maxParamName}.");
        }
    }

