    {
        public LogsController(IAsyncDocumentSession session, ILogger<LogsController> logger)
            : base(session, logger)
        {
        }

        // GET: api/logs?skip=0&take=10&level=Error&sortOption=Recent
        [HttpGet]
        public async Task<ActionResult<PagedList<StructuredLog>>> GetAll(
            [FromQuery] int skip = 0,
            [FromQuery] int take = 10,
            [FromQuery] string level = null,
            [FromQuery] LogSort sortOption = LogSort.Recent)
        {
            // Build the base query.
            var query = _session.Query<StructuredLog>();

            // Apply filtering by log level if provided.
            if (!string.IsNullOrEmpty(level))
            {
                query = query.Where(log => log.Level == level);
            }

