using System;
using System.Collections.Generic;
using System.Data;
using Microsoft.AnalysisServices.AdomdClient;
using NBi.Core;
using NBi.Core.Data;

public class OlapCommand : StructureDiscoveryCommand
{
    private readonly string connectionString;
    private readonly string commandText;
    private readonly List<Func<OlapRow, bool>> filters;

    public OlapCommand(string connectionString, string commandText, List<Func<OlapRow, bool>> filters)
    {
        this.connectionString = connectionString;
        this.commandText = commandText;
        this.filters = filters;
    }

    public List<string> Execute()
    {
        List<OlapRow> values = new List<OlapRow>();
        try
        {
            using (var connection = new AdomdConnection(connectionString))
            {
                connection.Open();
                using (var command = new AdomdCommand(commandText, connection))
                {
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            OlapRow row = BuildRow(reader);
                            if (IsValid(row))
                            {
                                values.Add(row);
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error executing OLAP command: {ex.Message}");
        }

        return ExtractCaptions(values);
    }

    private OlapRow BuildRow(IDataReader reader)
    {
        OlapRow row = new OlapRow
        {
            Id = reader["Id"]?.ToString(),
            Name = reader["Name"]?.ToString(),
            Value = reader["Value"] != DBNull.Value ? Convert.ToDouble(reader["Value"]) : (double?)null
        };
        return row;
    }

    private bool IsValid(OlapRow row)
    {
        foreach (var filter in filters)
        {
            if (!filter(row))
            {
                return false;
            }
        }
        return true;
    }

    private List<string> ExtractCaptions(List<OlapRow> values)
    {
        List<string> captions = new List<string>();
        foreach (var value in values)
        {
            captions.Add(value.Name);
        }
        return captions;
    }
}

public class OlapRow
{
    public string Id { get; set; }
    public string Name { get; set; }
    public double? Value { get; set; }
}

