namespace Cache
{
    class Validator
    {
        static void Main(string[] args)
        {
            int[] F = new int[20];
            int[] M = new int[20];
            for (int i = 0; i < 20; i++)
            {
                F[i] = F(i);
                M[i] = M(i);
            }
            Console.WriteLine(string.Join(",", F));
            Console.WriteLine(string.Join(",", M));
            Console.ReadLine();
        }
        static int F(int n)
        {
            return n == 0? 1 : n - M(F(n - 1));
        }
        static int M(int n)
        {
            return n == 0? 0 : n - F(M(n - 1));
        }
    }
}

