using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;
using IBM.Watson.DeveloperCloud.Services.VisualRecognition.v3;

public class TextRecognitionResultDisplay : MonoBehaviour
{
    [SerializeField] private Text m_Text;
    [SerializeField] private TextRecogTopLevelMultiple textRecognitionResults;

    private void Awake()
    {
        if (textRecognitionResults == null)
        {
            Debug.LogWarning("No text recognition results available.");
            return;
        }

        DisplayTextRecognitionResults();
    }

    private void DisplayTextRecognitionResults()
    {
        if (textRecognitionResults == null || textRecognitionResults.images == null)
        {
            m_Text.text = "No images processed.";
            return;
        }

        System.Text.StringBuilder resultBuilder = new System.Text.StringBuilder();
        resultBuilder.AppendLine($"Total Images Processed: {textRecognitionResults.images.Length}");
        resultBuilder.AppendLine("----------------------------");

        foreach (TextRecogTopLevelSingle imageResult in textRecognitionResults.images)
        {
            resultBuilder.AppendLine($"Image: {imageResult.source_image}");
            resultBuilder.AppendLine($"Status: {(imageResult.success ? "Successfully Processed" : "Processing Failed")}");

            if (imageResult.words != null && imageResult.words.Length > 0)
            {
                resultBuilder.AppendLine("Detected Text Details:");

                int currentLineNumber = 1;
                foreach (TextRecogOneWord wordDetail in imageResult.words)
                {
                    if (wordDetail.line_number != currentLineNumber)
                    {
                        resultBuilder.AppendLine($"\nLine {wordDetail.line_number}:");
                        currentLineNumber = wordDetail.line_number;
                    }

                    resultBuilder.AppendLine(
                        $"- Word: '{wordDetail.word}' " +
                        $"(Confidence: {wordDetail.confidence:P2}, " +
                        $"Location: X:{wordDetail.location.x} Y:{wordDetail.location.y})"
                    );
                }
            }
            else
            {
                resultBuilder.AppendLine("No text detected in this image.");
            }

            resultBuilder.AppendLine("----------------------------");
        }

        m_Text.text = resultBuilder.ToString();
    }
}

