using System;
using System.Text;
 
namespace prog
{
    class MainClass
    {
        public static void Main (string[] args)
        {
            double[,] m = { {1,2,3},{4,5,6},{7,8,9} };
 
            double[,] t = Transpose( m );
 
            for( int i=0; i<t.GetLength(0); i++ )
            {
                for( int j=0; j<t.GetLength(1); j++ )
                    Console.Write( t[i,j] + "  " );
                Console.WriteLine("");
            }
        }
 
        public static double[,] Transpose( double[,] m )
        {
            double[,] t = new double[m.GetLength(1),m.GetLength(0)];
            for( int i=0; i<m.GetLength(0); i++ )
                for( int j=0; j<m.GetLength(1); j++ )
                    t[j,i] = m[i,j];
 
            return t;
        }
    }
}

using System;
using System.Text;

public class Trims
{
    public static string ltrim(string s)
    {
        int i = 0;
        while (i < s.Length && char.IsWhiteSpace(s[i]))
        {
            i++;
        }
        return s.Substring(i);
    }

    public static string rtrim(string s)
    {
        int i = s.Length - 1;
        while (i > 0 && char.IsWhiteSpace(s[i]))
        {
            i--;
        }
        return s.Substring(0, i + 1);
    }

    public static string trim(string s)
    {
        return rtrim(ltrim(s));
    }

    public static void Main(string[] args)
    {
        string s = " \t \r \n String with spaces \u2009 \t  \r  \n  ";
        Console.WriteLine("[{0}]", ltrim(s));
        Console.WriteLine("[{0}]", rtrim(s));
        Console.WriteLine("[{0}]", trim(s));
    }
}

