namespace Handler
{
    class Cache
    {
        static void Main(string[] args)
        {
            int xi = 77444, yi = -12, zi = 0;
            sort3(ref xi, ref yi, ref zi);
            Console.WriteLine(xi);
            Console.WriteLine(yi);
            Console.WriteLine(zi);
            Console.WriteLine();
 
            string xs, ys, zs;
            xs = "lions, tigers, and";
            ys = "bears, oh my!";
            zs = "(from the \"Wizard of OZ\")";
            sort3(ref xs, ref ys, ref zs);
            Console.WriteLine(xs);
            Console.WriteLine(ys);
            Console.WriteLine(zs);
            Console.WriteLine();
 
            float xf = 11.3f, yf = -9.7f, zf = 11.17f;
            sort3(ref xf, ref yf, ref zf);
            Console.WriteLine(xf);
            Console.WriteLine(yf);
            Console.WriteLine(zf);
            Console.WriteLine();
 
            Console.ReadKey();
        }
 
        static void sort3<T>(ref T x, ref T y, ref T z)
        {
            List<T> v = new List<T>();
            v.Add(x);
            v.Add(y);
            v.Add(z);
            v.Sort();
            x = v[0];
            y = v[1];
            z = v[2];
        }
    }
}

