namespace TemplateProcessing
{
    // Base template block providing common functionality.
    public abstract class TemplateBlock
    {
        public string RawText { get; protected set; }
        public int StartPosition { get; protected set; }
        public int EndPosition { get; protected set; }

        protected TemplateBlock(string rawText, int start, int end)
        {
            RawText = rawText;
            StartPosition = start;
            EndPosition = end;
        }

        // Returns code completion suggestions based on context.
        public abstract IList<CompletionItem> GetCompletions();

        // Returns syntax classification spans for visual analysis.
        public abstract IList<SyntaxSpan> GetSpans();
    }

    // Represents specific conditional logic block, e.g., if or if not equal.
    public class IfConditionBlock : TemplateBlock
    {
        // Store parsed variable expressions from the template arguments.
        public List<VariableExpression> Variables { get; private set; }

        private IfConditionBlock(string rawText, int start, int end, List<VariableExpression> variables)
            : base(rawText, start, end)
        {
            Variables = variables;
        }

        // Parses a raw command and returns a structured IfConditionBlock.
        public static IfConditionBlock Parse(string commandText, int startPosition)
        {
            // For simplicity, assume commandText is something like "if var1 != var2"
            // We'll split the command text and treat tokens after the command as variables.
            string[] tokens = commandText.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            List<VariableExpression> variables = new List<VariableExpression>();

            // Skip the first token (the command, e.g., "if").
            foreach (var token in tokens.Skip(1))
            {
                // Clean token removing potential operators like "!=" if present.
                string cleaned = token.Replace("!=", string.Empty);
                if (!string.IsNullOrWhiteSpace(cleaned))
                {
                    variables.Add(new VariableExpression(cleaned.Trim()));
                }
            }

            // Here, endPosition is derived from start + length of commandText.
            return new IfConditionBlock(commandText, startPosition, startPosition + commandText.Length, variables);
        }

