public partial class FormSheetFieldSigBox : Form {
    private SheetFieldDef _sheetFieldDef;
    private SheetDef _sheetDef;
    private bool _isReadOnly;

    public FormSheetFieldSigBox(SheetFieldDef sheetFieldDef, SheetDef sheetDef, bool isReadOnly) {
        InitializeComponent();
        _sheetFieldDef = sheetFieldDef;
        _sheetDef = sheetDef;
        _isReadOnly = isReadOnly;
    }

    private void FormSheetFieldSigBox_Load(object sender, EventArgs e) {
        if (_isReadOnly) {
            ConfigureReadOnlyMode();
        }

        PopulateFieldProperties();
        SetupValidationControls();
    }

    private void ConfigureReadOnlyMode() {
        textXPos.ReadOnly = true;
        textYPos.ReadOnly = true;
        textWidth.ReadOnly = true;
        textHeight.ReadOnly = true;
        checkRequired.Enabled = false;
        butOK.Enabled = false;
        butDelete.Enabled = false;
    }

    private void PopulateFieldProperties() {
        textXPos.Text = _sheetFieldDef.XPos.ToString();
        textYPos.Text = _sheetFieldDef.YPos.ToString();
        textWidth.Text = _sheetFieldDef.Width.ToString();
        textHeight.Text = _sheetFieldDef.Height.ToString();
        checkRequired.Checked = _sheetFieldDef.IsRequired;
    }

    private void SetupValidationControls() {
        textXPos.Validating += ValidateNumericInput;
        textYPos.Validating += ValidateNumericInput;
        textWidth.Validating += ValidateNumericInput;
        textHeight.Validating += ValidateNumericInput;
    }

    private void ValidateNumericInput(object sender, System.ComponentModel.CancelEventArgs e) {
        TextBox textBox = sender as TextBox;
        if (!int.TryParse(textBox.Text, out int value)) {
            MessageBox.Show("Please enter a valid numeric value.");
            e.Cancel = true;
        }
    }

    private bool ValidateFieldBounds() {
        int xPos = int.Parse(textXPos.Text);
        int yPos = int.Parse(textYPos.Text);
        int width = int.Parse(textWidth.Text);
        int height = int.Parse(textHeight.Text);

        if (xPos < 0 || yPos < 0 || width <= 0 || height <= 0) {
            MessageBox.Show("Invalid field dimensions.");
            return false;
        }

        if (xPos + width > _sheetDef.Width || yPos + height > _sheetDef.Height) {
            MessageBox.Show("Field extends beyond sheet boundaries.");
            return false;
        }

        return true;
    }

