using UnityEngine;
using UnityEngine.EventSystems;
using System.Collections.Generic;

public enum ModuleItemType
{
    CargoModule,
    HardpointModule
}

[System.Serializable]
public class ShipModuleController
{
    public ModuleItemType moduleType;
    public string moduleName;
    public bool isSlotCompatible;
    public int moduleSize;
}

public class ShipModulesDropTarget : MonoBehaviour, IDropHandler
{
    public PlayerShip playerShip;
    public int slotIndex;
    public ModuleItemType allowedModuleType;

    private void Awake()
    {
        playerShip = FindObjectOfType<PlayerShip>();
    }

    public void OnDrop(PointerEventData eventData)
    {
        CargoHoldListItem draggedItem = eventData.pointerDrag.GetComponent<CargoHoldListItem>();

        if (draggedItem == null)
        {
            Debug.LogWarning("Invalid module drop attempt");
            return;
        }

        ShipModuleController moduleToEquip = draggedItem.moduleData;

        if (!ValidateModuleDrop(moduleToEquip))
        {
            NotifyInvalidModuleDrop();
            return;
        }

        ProcessModuleDrop(moduleToEquip);
    }

    private bool ValidateModuleDrop(ShipModuleController moduleToEquip)
    {
        if (moduleToEquip.moduleType != allowedModuleType)
            return false;

        if (!moduleToEquip.isSlotCompatible)
            return false;

        return true;
    }

    private void ProcessModuleDrop(ShipModuleController moduleToEquip)
    {
        ShipModuleController currentModule = playerShip.GetModuleAtSlot(slotIndex);

        if (currentModule != null)
        {
            // Swap or replace existing module
            playerShip.RemoveModuleFromSlot(slotIndex);
            playerShip.AddModuleToCargo(currentModule);
        }

        playerShip.EquipModuleToSlot(slotIndex, moduleToEquip);
        RemoveDraggedItemFromCargo(moduleToEquip);
    }

    private void RemoveDraggedItemFromCargo(ShipModuleController moduleToEquip)
    {
        playerShip.RemoveModuleFromCargo(moduleToEquip);
    }

    private void NotifyInvalidModuleDrop()
    {
        // Display error message or play sound
        Debug.LogWarning($"Cannot drop module to slot {slotIndex}");
    }
}

public class PlayerShip : MonoBehaviour
{
    public List<ShipModuleController> cargoModules;
    public ShipModuleController[] hardpointModules;

    public void AddModuleToCargo(ShipModuleController module)
    {
        cargoModules.Add(module);
    }

    public void RemoveModuleFromCargo(ShipModuleController module)
    {
        cargoModules.Remove(module);

using System;
using TvShowReminder.Contracts;
using TvShowReminder.DataSource;

namespace TvShowReminder.Handlers
{
    public class RefreshSubscriptionCommand
    {
        public Guid SubscriptionId { get; set; }
    }

    public interface ISubscriptionQueryDataSource
    {
        Subscription GetSubscription(Guid subscriptionId);
    }

    public interface ISubscriptionCommandDataSource
    {
        void UpdateSubscription(Subscription subscription);
        void DeleteEpisodes(Guid subscriptionId);
    }

    public interface IEpisodeUpdateService
    {
        // Returns new air date if available, else null
        DateTime? UpdateEpisodes(Subscription subscription);
    }

    public class RefreshSubscriptionHandler
    {
        private readonly ISubscriptionQueryDataSource _queryDataSource;
        private readonly ISubscriptionCommandDataSource _commandDataSource;
        private readonly IEpisodeUpdateService _updateService;

        public RefreshSubscriptionHandler(
            ISubscriptionQueryDataSource queryDataSource,
            ISubscriptionCommandDataSource commandDataSource,
            IEpisodeUpdateService updateService)
        {
            _queryDataSource = queryDataSource;
            _commandDataSource = commandDataSource;
            _updateService = updateService;
        }

        public void Handle(RefreshSubscriptionCommand command)
        {
            // Retrieve the subscription
            var subscription = _queryDataSource.GetSubscription(command.SubscriptionId);
            if (subscription == null)
                throw new Exception("Subscription not found.");

            // Reset the last air date to now to clear outdated data.
            subscription.LastAirDate = DateTime.Now;

            // Remove all previously stored episode information.
            _commandDataSource.DeleteEpisodes(subscription.Id);

            // Refresh episode data and possibly get a new air date.
            DateTime? newAirDate = _updateService.UpdateEpisodes(subscription);

            // If a new air date is returned, update the subscription.
            if (newAirDate.HasValue)
            {
                subscription.LastAirDate = newAirDate.Value;
            }

            // Persist the updated subscription.
            _commandDataSource.UpdateSubscription(subscription);
        }
    }

    // Example subscription model.
    public class Subscription
    {
        public Guid Id { get; set; }
        public DateTime LastAirDate { get; set; }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
namespace LineComposer
{
    public class LineComposer<T> : IEnumerable<string>
    {
        private readonly IEnumerable<T> _words;
        private readonly int _width;
        private string _current;
 
        public LineComposer(IEnumerable<T> words, int width)
        {
            _words = words;
            _width = width;
        }
 
        public IEnumerator<string> GetEnumerator()
        {
            var enumerator = _words.GetEnumerator();
            while (true)
            {
                if (!enumerator.MoveNext())
                {
                    if (_current!= null)
                    {
                        yield return _current;
                        _current = null;
                    }
                    yield break;
                }
 
                var next = enumerator.Current;
 
                if (_current == null)
                {
                    _current = string.Empty;
                }
 
                while (true)
                {
                    var word = next.ToString();
                    if (_width <= _current.Length + word.Length)
                    {
                        _current = word;
                        // If the first word itself is too long, avoid producing an
                        // empty line. Continue instead with the next word.
                        if (!string.IsNullOrEmpty(_current))
                        {
                            yield return _current;
                        }
                        break;
                    }
 
                    if (!string.IsNullOrEmpty(_current))
                    {
                        _current += " ";
                    }
 
                    _current += word;
 
                    if (!enumerator.MoveNext())
                    {
                        yield return _current;
                        yield break;
                    }
 
                    next = enumerator.Current;
                }
