        public Message2(Guid id) { Id = id; }
    }

    // Consumer that processes messages and tracks count
    public class Message2Consumer
    {
        public int ProcessCount { get; private set; }
        public Message2 LastProcessed { get; private set; }
        public void Handle(Message2 message)
        {
            ProcessCount++;
            LastProcessed = message;
        }
    }

