        public void Handle(Message1 message)
        {
            if (_pipe != null && _consumer != null)
            {
                Message2 translated = _pipe.Translate(message);
                _consumer.Handle(translated);
            }
        }

        // For validation
        public Message2Consumer GetConsumer() => _consumer;
    }

