public class InitializeSimpleMembershipAttribute : ActionFilterAttribute
{
    private static volatile bool _initialized;
    private static readonly object _initializerLock = new object();

    public override void OnActionExecuting(ActionExecutingContext filterContext)
    {
        EnsureInitialized();
        base.OnActionExecuting(filterContext);
    }

    private static void EnsureInitialized()
    {
        if (!_initialized)
        {
            lock (_initializerLock)
            {
                LazyInitializer.EnsureInitialized(ref _initialized, () =>
                {
                    new SimpleMembershipInitializer().Initialize();
                    return true;
                });
            }
        }
    }

    private class SimpleMembershipInitializer
    {
        public void Initialize()
        {
            try
            {
                Database.SetInitializer<UsersContext>(null);

                using (var context = new UsersContext())
                {
                    if (!context.Database.Exists())
                    {
                        context.Database.Create();
                    }
                }

                WebSecurity.InitializeDatabaseConnection(
                    "DefaultConnection",
                    "UserProfile",
                    "UserId",
                    "UserName",
                    autoCreateTables: true);
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException(
                    "Simple Membership initialization failed. Verify database configuration and connection string.",
                    ex);
            }
        }
    }
}

