using System;
using System.Reflection;

public abstract class DynamicFieldMapping
{
    protected DynamicFieldMapping(Type type, string fieldName, DynamicCustomMapping mapping, bool isNullable)
    {
        Type = type;
        FieldName = fieldName;
        Mapping = mapping;
        IsNullable = isNullable;
    }

    public Type Type { get; }
    public string FieldName { get; }
    public DynamicCustomMapping Mapping { get; }
    public bool IsNullable { get; }

    public static DynamicFieldMapping CreateDynamicFieldMapping(PropertyInfo property, DynamicCustomMapping mapping)
    {
        if (property == null) throw new ArgumentNullException(nameof(property));
        if (mapping == null) throw new ArgumentNullException(nameof(mapping));

        var type = property.PropertyType;
        var typeInfo = type.GetTypeInfo();
        var fieldName = property.Name;
        bool isNullable = false;

        if (typeInfo.IsGenericType && typeInfo.GetGenericTypeDefinition() == typeof(Nullable<>))
        {
            isNullable = true;
            type = Nullable.GetUnderlyingType(type);
            typeInfo = type.GetTypeInfo();
        }

        if (typeInfo.IsArray || typeInfo.ContainsGenericParameters || typeInfo.IsGenericTypeDefinition)
        {
            throw new LightDataException(SR.DataMappingUnsupportFieldType);
        }

        if (typeInfo.IsEnum)
        {
            return new DynamicEnumFieldMapping(type, fieldName, mapping, isNullable);
        }

        if (typeInfo.IsPrimitive || type == typeof(string) || type == typeof(decimal) || type == typeof(DateTime) || type == typeof(Guid))
        {
            return new DynamicPrimitiveFieldMapping(type, fieldName, mapping, isNullable);
        }

        throw new LightDataException(SR.DataMappingUnsupportFieldType);
    }
}

