{
    public DynamicEnumFieldMapping(Type type, string fieldName, DynamicCustomMapping mapping, bool isNullable)
        : base(type, fieldName, mapping, isNullable)
    {
    }
}

public class DynamicPrimitiveFieldMapping : DynamicFieldMapping
{
    public DynamicPrimitiveFieldMapping(Type type, string fieldName, DynamicCustomMapping mapping, bool isNullable)
        : base(type, fieldName, mapping, isNullable)
