using System;
using System.Collections;
using System.Collections.Generic;
 
namespace SieveOfEratosthenes
{
    class Counter
    {
        static void Main(string[] args)
        {
            int maxprime = int.Parse(args[0]);
            var primelist = GetAllPrimesLessThan(maxprime);
            foreach (int prime in primelist)
            {
                Console.WriteLine(prime);
            }
            Console.WriteLine("Count = " + primelist.Count);
            Console.ReadLine();
        }
 
        private static List<int> GetAllPrimesLessThan(int maxPrime)
        {
            var primes = new List<int>();
            var maxSquareRoot = (int)Math.Sqrt(maxPrime);
            var eliminated = new BitArray(maxPrime + 1);
 
            for (int i = 2; i <= maxPrime; ++i)
            {
                if (!eliminated[i])
                {
                    primes.Add(i);
                    if (i <= maxSquareRoot)
                    {
                        for (int j = i * i; j <= maxPrime; j += i)
                        {
                            eliminated[j] = true;
                        }
                    }
                }
            }
            return primes;
        }
    }
}

using System.Collections;
using System.IO;
using UnityEngine;
using UnityEditor;
using Magicolo.GeneralTools;

public class PDEditorHelper : MonoBehaviour
{
    public PDPlayer pdPlayer;
    public List<PDEditorModule> modules;
    public PDEditorModule defaultModule;
    private Texture2D icon;

    private void OnEnable()
    {
        icon = Resources.Load<Texture2D>("PDPlayerIcon");
        EditorApplication.hierarchyWindowItemOnGUI += OnHierarchyWindowItemGUI;
    }

    private void OnDisable()
    {
        EditorApplication.hierarchyWindowItemOnGUI -= OnHierarchyWindowItemGUI;
    }

    private void OnDrawGizmos()
    {
        if (pdPlayer == null || modules == null) return;

        Gizmos.color = Color.blue;

        foreach (var module in modules)
        {
            if (module == null) continue;

            Gizmos.DrawWireSphere(module.transform.position, module.spatializationRange);
            Handles.Label(module.transform.position, module.name);
        }

        if (defaultModule != null)
        {
            Gizmos.color = Color.green;
            Gizmos.DrawWireSphere(defaultModule.transform.position, defaultModule.spatializationRange);
            Handles.Label(defaultModule.transform.position, defaultModule.name);
        }
    }

    private void OnHierarchyWindowItemGUI(int instanceID, Rect selectionRect)
    {
        var obj = EditorUtility.InstanceIDToObject(instanceID) as PDPlayer;
        if (obj == null) return;

        Rect iconRect = new Rect(selectionRect.x + 4, selectionRect.y, 16, 16);
        GUI.DrawTexture(iconRect, icon);
    }
}

