[TestFixture]
public class FirstDayOfWeekTests
{
    [Test]
    public void FirstDayOfWeek_DefaultMondayStart_CorrectDateReturned()
    {
        // Arrange
        DateTime testDate = new DateTime(2023, 5, 17);  // Wednesday
        DateTime expectedFirstDay = new DateTime(2023, 5, 15);  // Monday

        // Act
        DateTime actualFirstDay = testDate.FirstDayOfWeek();

        // Assert
        Assert.AreEqual(expectedFirstDay, actualFirstDay);
        Assert.AreEqual(DayOfWeek.Monday, actualFirstDay.DayOfWeek);
    }

    [Test]
    public void FirstDayOfWeek_CustomSundayStart_CorrectDateReturned()
    {
        // Arrange
        DateTime testDate = new DateTime(2023, 5, 17);  // Wednesday
        DateTime expectedFirstDay = new DateTime(2023, 5, 14);  // Sunday

        // Act
        DateTime actualFirstDay = testDate.FirstDayOfWeek(DayOfWeek.Sunday);

        // Assert
        Assert.AreEqual(expectedFirstDay, actualFirstDay);
        Assert.AreEqual(DayOfWeek.Sunday, actualFirstDay.DayOfWeek);
    }

    [Test]
    public void FirstDayOfWeek_WeekendDate_CorrectDateReturned()
    {
        // Arrange
        DateTime testDate = new DateTime(2023, 5, 20);  // Saturday
        DateTime expectedFirstDay = new DateTime(2023, 5, 15);  // Monday (default)

        // Act
        DateTime actualFirstDay = testDate.FirstDayOfWeek();

        // Assert
        Assert.AreEqual(expectedFirstDay, actualFirstDay);
        Assert.AreEqual(DayOfWeek.Monday, actualFirstDay.DayOfWeek);
    }

    [Test]
    public void FirstDayOfWeek_CustomWeekStart_CrossMonthBoundary()
    {
        // Arrange
        DateTime testDate = new DateTime(2023, 1, 3);  // Tuesday
        DateTime expectedFirstDay = new DateTime(2022, 12, 31);  // Saturday

        // Act
        DateTime actualFirstDay = testDate.FirstDayOfWeek(DayOfWeek.Saturday);

        // Assert
        Assert.AreEqual(expectedFirstDay, actualFirstDay);
        Assert.AreEqual(DayOfWeek.Saturday, actualFirstDay.DayOfWeek);
    }

    [Test]
    public void FirstDayOfWeek_EdgeCase_YearStart()
    {
        // Arrange
        DateTime testDate = new DateTime(2023, 1, 1);  // Sunday
        DateTime expectedFirstDay = new DateTime(2023, 1, 1);  // Same day (Sunday start)

        // Act
        DateTime actualFirstDay = testDate.FirstDayOfWeek(DayOfWeek.Sunday);

        // Assert
        Assert.AreEqual(expectedFirstDay, actualFirstDay);
        Assert.AreEqual(DayOfWeek.Sunday, actualFirstDay.DayOfWeek);
    }
}

