using System;

public class InvariantIntStringPair : IComparable<InvariantIntStringPair>
{
    private string stringValue;
    private int value;
    private int originalIndex;

    public InvariantIntStringPair(string stringValue, int value, int originalIndex)
    {
        this.stringValue = stringValue;
        this.value = value;
        this.originalIndex = originalIndex;
    }

    public int GetOriginalIndex()
    {
        return originalIndex;
    }

    public override bool Equals(object obj)
    {
        if (obj is InvariantIntStringPair other)
        {
            return Equals(other);
        }
        return false;
    }

    public bool Equals(string stringValue, int value)
    {
        return this.stringValue.Equals(stringValue, StringComparison.Ordinal) && this.value == value;
    }

    public bool Equals(InvariantIntStringPair other)
    {
        if (other == null) return false;
        return stringValue.Equals(other.stringValue, StringComparison.Ordinal) && value == other.value;
    }

    public override int GetHashCode()
    {
        return stringValue.GetHashCode() ^ value.GetHashCode();
    }

    public int CompareTo(InvariantIntStringPair other)
    {
        if (other == null) return 1;
        int stringComparison = stringValue.CompareTo(other.stringValue);
        if (stringComparison != 0)
        {
            return stringComparison;
        }
        return value.CompareTo(other.value);
    }

    public override string ToString()
    {
        return $"Index: {originalIndex}, String: {stringValue}, Value: {value}";
    }

    public static void Main(string[] args)
    {
        InvariantIntStringPair pair1 = new InvariantIntStringPair("test", 1, 0);
        InvariantIntStringPair pair2 = new InvariantIntStringPair("test", 2, 1);
        InvariantIntStringPair pair3 = new InvariantIntStringPair("example", 1, 2);

        Console.WriteLine(pair1.ToString());
        Console.WriteLine(pair2.ToString());

        Console.WriteLine($"Are pair1 and pair2 equal? {pair1.Equals(pair2)}");
        Console.WriteLine($"Comparing pair1 and pair2: {pair1.CompareTo(pair2)}");

        Console.WriteLine($"Are pair1 and pair3 equal? {pair1.Equals(pair3)}");
        Console.WriteLine($"Comparing pair1 and pair3: {pair1.CompareTo(pair3)}");
    }
}

