public static string lcs(string a, string b)
{
    int aLen = a.Length;
    int bLen = b.Length;
    if (aLen == 0 || bLen == 0)
    {
        return "";
    }
    else if (a[aLen - 1] == b[bLen - 1])
    {
        return lcs(a.Substring(0, aLen - 1), b.Substring(0, bLen - 1)) + a[aLen - 1];
    }
    string x = lcs(a, b.Substring(0, bLen - 1));
    string y = lcs(a.Substring(0, aLen - 1), b);
    if (x.Length > y.Length)
    {
        return x;
    }
    return y;
}

using System;
 
namespace Subleq {
    class Tree {
        static void Main(string[] args) {
            int[] mem = {
                15, 17, -1, 17, -1, -1, 16, 1, -1, 16,
                3, -1, 15, 15, 0, 0, -1, 72, 101, 108,
                108, 111, 44, 32, 119, 111, 114, 108, 100, 33,
                10, 0,
            };
 
            int instructionPointer = 0;
 
            do {
                int a = mem[instructionPointer];
                int b = mem[instructionPointer + 1];
 
                if (a == -1) {
                    mem[b] = Console.Read();
                }
                else if (b == -1) {
                    Console.Write((char)mem[a]);
                }
                else {
                    mem[b] -= mem[a];
                    if (mem[b] < 1) {
                        instructionPointer = mem[instructionPointer + 2];
                        continue;
                    }
                }
 
                instructionPointer += 3;
            } while (instructionPointer >= 0);
        }
    }
}

