                {
                    builder.AllowAnyOrigin()
                        .WithMethods("GET", "POST", "HEAD")
                        .WithHeaders("Accept", "Content-Type", "Origin");
                });

                options.AddPolicy("AllowSpecificOrigin", builder =>
                {
                    builder.WithOrigins("http://trusted.com", "https://trusted-subdomain.com")
                        .WithMethods("PUT", "DELETE", "OPTIONS")
                        .WithHeaders("X-Custom-Header", "Authorization")
                        .SetPreflightMaxAge(System.TimeSpan.FromSeconds(3600));
                });

                options.AddPolicy("WithCredentials", builder =>
                {
                    builder.WithOrigins("https://secure.example.com")
                        .AllowAnyMethod()
                        .AllowAnyHeader()
                        .AllowCredentials()
                        .ExposeHeaders("X-Additional-Info");
                });

                options.AddPolicy("WithCredentialsAnyOrigin", builder =>
                {
                    builder.AllowAnyOrigin()
                        .WithMethods("PUT", "POST")
                        .WithHeaders("Authorization", "Content-Type", "X-Requested-With")
                        .AllowCredentials()
                        .ExposeHeaders("X-Server-Time", "X-Request-ID");
                });
            });

            services.AddControllers();
            services.AddSwaggerGen();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
