using System;
using System.Collections.Generic;
 
public class MianChowla
{
    public static bool Contains(int[] is, int s)
    {
        foreach (int i in is)
        {
            if (s == i)
            {
                return true;
            }
        }
        return false;
    }
 
    public static int[] MianChowla(int n)
    {
        int[] mc = new int[n];
        mc[0] = 1;
        List<int> is = new List<int>();
        is.Add(2);
        int sum;
        for (int i = 1; i < n; i++)
        {
            int le = is.Count;
            jloop:
            for (int j = mc[i - 1] + 1; ; j++)
            {
                mc[i] = j;
                for (int k = 0; k <= i; k++)
                {
                    sum = mc[k] + j;
                    if (Contains(is.ToArray(), sum))
                    {
                        is.RemoveRange(0, le);
                        continue jloop;
                    }
                    is.Add(sum);
                }
                break;
            }
        }
        return mc;
    }
 
    public static void Main()
    {
        int[] mc = MianChowla(100);
        Console.WriteLine("The first 30 terms of the Mian-Chowla sequence are:");
        Console.WriteLine(string.Join(", ", mc, 0, 30));
        Console.WriteLine("\nTerms 91 to 100 of the Mian-Chowla sequence are:");
        Console.WriteLine(string.Join(", ", mc, 90, 10));
    }
}

