using System.Web.Mvc;
using WebMatrix.WebData;

public class InitializeSimpleMembershipAttribute : ActionFilterAttribute
{
    private static SimpleMembershipInitializer _initializer;
    private static readonly object _initializerLock = new object();
    private static bool _isInitialized;

    public override void OnActionExecuting(ActionExecutingContext filterContext)
    {
        EnsureInitialized();
        base.OnActionExecuting(filterContext);
    }

    private void EnsureInitialized()
    {
        if (!_isInitialized)
        {
            lock (_initializerLock)
            {
                if (!_isInitialized)
                {
                    try
                    {
                        _initializer = new SimpleMembershipInitializer();
                        _initializer.Initialize();
                        _isInitialized = true;
                    }
                    catch (Exception ex)
                    {
                        // Ideally, log the exception to your logging framework
                        throw new InvalidOperationException("Could not initialize Simple Membership", ex);
                    }
                }
            }
        }
    }

    private class SimpleMembershipInitializer
    {
        public void Initialize()
        {
            // Create the database if it doesn't exist
            Database.SetInitializer(new CreateDatabaseIfNotExists<MembershipContext>());
            using (var context = new MembershipContext())
            {
                context.Database.Initialize(force: true);
            }

            // Initialize the Simple Membership Provider
            try
            {
                if (!WebSecurity.Initialized)
                {
                    WebSecurity.InitializeDatabaseConnection(
                        "DefaultConnection",
                        "UserProfile",
                        "UserId",
                        "UserName",
                        autoCreateTables: true);
                }
            }
            catch (Exception ex)
            {
                // Log exception
                throw new InvalidOperationException("Could not initialize database connection", ex);
            }
        }
    }
}

