namespace Evolution.Framework.Service.SystemManage
{
    public interface IDutyService
    {
        Task<List<RoleEntity>> GetList();
        Task<RoleEntity> GetForm(string keyValue);
        Task Delete(string keyValue);
        Task Save(RoleEntity roleEntity, string keyValue);
    }

    public class DutyService : IDutyService
    {
        private readonly IDutyRepository service;
        private readonly IHttpClientFactory _clientFactory;

        public DutyService(IDutyRepository service, IHttpClientFactory clientFactory)
        {
            this.service = service;
            _clientFactory = clientFactory;
        }

        public async Task<List<RoleEntity>> GetList()
        {
            var client = _clientFactory.CreateClient();
            var response = await client.GetAsync("https://your-api-endpoint/roles"); // Replace with your actual API endpoint
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<List<RoleEntity>>(content);
        }

        public async Task<RoleEntity> GetForm(string keyValue)
        {
            var client = _clientFactory.CreateClient();
            var response = await client.GetAsync($"https://your-api-endpoint/roles/{keyValue}"); // Replace with your actual API endpoint
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<RoleEntity>(content);
        }

        public async Task Delete(string keyValue)
        {
            await service.DeleteAsync(keyValue);
        }

        public async Task Save(RoleEntity roleEntity, string keyValue)
        {
            if (string.IsNullOrEmpty(keyValue))
            {
                roleEntity.Category = "Default";
                await service.InsertAsync(roleEntity);
            }
            else
            {
                roleEntity.Id = keyValue;
                await service.UpdateAsync(roleEntity);
            }
        }
    }
}

