public class OlapCommand : StructureDiscoveryCommand
{
    private readonly string _commandText;
    private readonly IEnumerable<IPostCommandFilter> _postFilters;
    private readonly string _commandDescription;

    public OlapCommand(string commandText, IEnumerable<IPostCommandFilter> postFilters, string commandDescription)
    {
        _commandText = commandText;
        _postFilters = postFilters;
        _commandDescription = commandDescription;
    }

    public override IEnumerable<string> Execute()
    {
        List<string> captions = new List<string>();
        using (AdomdConnection connection = new AdomdConnection("YourConnectionStringHere"))
        {
            try
            {
                connection.Open();
                using (AdomdDataReader reader = ExecuteReader(connection))
                {
                    while (reader.Read())
                    {
                        OlapRow row = BuildRow(reader);
                        if (_postFilters.All(filter => filter.IsValid(row)))
                        {
                            captions.Add(row.Caption);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Trace.WriteLineIf(Trace.Listeners.Count > 0, $"Error executing command: {_commandDescription}. Exception: {ex.Message}");
                throw new ConnectionException($"Error executing command: {_commandDescription}", ex);
            }
        }
        return captions;
    }

    private OlapRow BuildRow(AdomdDataReader reader)
    {
        var values = new Dictionary<string, object>();
        for (int i = 0; i < reader.FieldCount; i++)
        {
            values[reader.GetName(i)] = reader.GetValue(i);
        }
        return new OlapRow(values);
    }

    private AdomdDataReader ExecuteReader(AdomdConnection connection)
    {
        using (AdomdCommand command = new AdomdCommand(_commandText, connection))
        {
            try
            {
                return command.ExecuteReader();
            }
            catch (Exception ex)
            {
                Trace.WriteLineIf(Trace.Listeners.Count > 0, $"Error executing reader for command: {_commandDescription}. Exception: {ex.Message}");

