using System;
using System.Reflection;

public abstract class DynamicFieldMapping { }

public class DynamicEnumFieldMapping : DynamicFieldMapping { }

public class DynamicPrimitiveFieldMapping : DynamicFieldMapping { }

public class DynamicCustomMapping
{
    public string MappingName { get; set; }
}

public static class FieldMappingFactory
{
    public static DynamicFieldMapping CreateDynamicFieldMapping(PropertyInfo property, DynamicCustomMapping customMapping)
    {
        if (property == null)
            throw new ArgumentNullException(nameof(property));
        if (customMapping == null)
            throw new ArgumentNullException(nameof(customMapping));

        Type propertyType = property.PropertyType;
        Type underlyingType = Nullable.GetUnderlyingType(propertyType) ?? propertyType;

        if (underlyingType.IsArray)
            throw new NotSupportedException(SR.UnsupportedArrayType);

        if (underlyingType.IsGenericParameter)
            throw new NotSupportedException(SR.UnsupportedGenericType);

        if (underlyingType.IsEnum)
            return new DynamicEnumFieldMapping();

        if (IsPrimitiveType(underlyingType))
            return new DynamicPrimitiveFieldMapping();

        throw new NotSupportedException(SR.UnsupportedType);
    }

    private static bool IsPrimitiveType(Type type)
    {
        return type.IsPrimitive || type == typeof(string) || type == typeof(decimal) || type == typeof(DateTime);
    }
}

public static class SR
{
    public static string UnsupportedArrayType => "Array types are not supported.";
    public static string UnsupportedGenericType => "Generic parameter types are not supported.";
    public static string UnsupportedType => "The specified type is not supported.";
}

