namespace DynamicUI
{
    public interface IValueEditor
    {
        void UpdateValue(object newValue);
        void SetEditable(bool editable);
    }

    public interface IEditorOwner
    {
        void OnValueChanged(string key, object newValue);
    }

    public class BooleanValueEditor : UserControl, IValueEditor
    {
        private IEditorOwner _owner;
        private string _propertyKey;
        private CheckBox _toggle;

        private BooleanValueEditor(IEditorOwner owner, string propertyKey, bool initialValue, bool isReadOnly)
        {
            _owner = owner;
            _propertyKey = propertyKey;
            InitializeComponents(initialValue, !isReadOnly);
        }

        private void InitializeComponents(bool initialValue, bool isEditable)
        {
            _toggle = new CheckBox
            {
                Content = "Boolean Value",
                IsChecked = initialValue,
                IsEnabled = isEditable,
                Margin = new Thickness(5)
            };
            _toggle.Checked += Toggle_Checked;
            _toggle.Unchecked += Toggle_Unchecked;
            this.Content = _toggle;
        }

        private void Toggle_Checked(object sender, RoutedEventArgs e)
        {
            NotifyOwner(true);
        }

        private void Toggle_Unchecked(object sender, RoutedEventArgs e)
        {
            NotifyOwner(false);
        }

        private void NotifyOwner(bool newValue)
        {
            // Propagate change to the external owner.
            _owner?.OnValueChanged(_propertyKey, newValue);
        }

        public void UpdateValue(object newValue)
        {
            if (newValue is bool boolVal)
            {
                _toggle.IsChecked = boolVal;
            }
            else
            {
                throw new ArgumentException("Invalid value type. Expected boolean.");
            }
        }

        public void SetEditable(bool editable)
        {
            _toggle.IsEnabled = editable;
        }

        // Factory method to create a BooleanValueEditor instance.
        public static BooleanValueEditor Create(IEditorOwner owner, string propertyKey,
                                                  bool initialValue, bool isReadOnly)
        {
            return new BooleanValueEditor(owner, propertyKey, initialValue, isReadOnly);
        }
    }
}

