public class Order
{
    public static void Main()
    {
        Console.WriteLine(lcs("thisisatest", "testing123testing"));
    }

    public static string lcs(string xstr, string ystr)
    {
        if (xstr.Length == 0 || ystr.Length == 0)
            return "";

        var x = xstr.Substring(0, 1);
        var xs = xstr.Substring(1);
        var y = ystr.Substring(0, 1);
        var ys = ystr.Substring(1);

        if (x == y)
            return x + lcs(xs, ys);
        else
            return new string[] { lcs(xstr, ys), lcs(xs, ystr) }.OrderByDescending(x => x.Length).First();
    }
}

