public class RecognizeTextResult : MonoBehaviour
{
    // UI element to display results
    public Text m_Text;

    // Example data structure for handling recognition results
    [System.Serializable]
    public class TextRecogTopLevelSingle
    {
        public string text;
        public List<WordInfo> words;
    }

    [System.Serializable]
    public class WordInfo
    {
        public string word;
        public float score;
        public float[] location; // Should contain positions (x, y)
    }

    [System.Serializable]
    public class TextRecogTopLevelMultiple
    {
        public List<TextRecogTopLevelSingle> images;
    }

    private void Awake()
    {
        // Initialize the display
        DisplayRecognitionResults();
    }

    private void DisplayRecognitionResults()
    {
        var recognitionResults = AppData.Instance.RecognitionResults;

        if (recognitionResults == null || recognitionResults.images.Count == 0)
        {
            m_Text.text = "No recognition results available.";
            return;
        }

        string displayText = "Recognition Results:\n";
        displayText += $"Total Images Processed: {recognitionResults.images.Count}\n\n";

        foreach (var imageResult in recognitionResults.images)
        {
            displayText += $"Image Text: {imageResult.text}\n";
            displayText += "Recognized Words:\n";

            foreach (var word in imageResult.words)
            {
                displayText += $"{word.word} (Score: {word.score}) at Location: {FormatLocation(word.location)}\n";
            }
            displayText += "\n";
        }

        m_Text.text = displayText;
    }

    private string FormatLocation(float[] location)
    {
        return location.Length == 2 ? $"[{location[0]}, {location[1]}]" : "N/A";
    }
}

