    public class veSliderBool : UserControl
    {
        private CheckBox tbBoolean;
        private InBase _owner;
        private JSValue _value;
        private bool _isReadOnly;

        public veSliderBool()
        {
            InitializeComponent();
            SetupEventHandlers();
        }

        private void InitializeComponent()
        {
            tbBoolean = new CheckBox
            {
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Center
            };
            Content = tbBoolean;
        }

        private void SetupEventHandlers()
        {
            tbBoolean.Checked += cbBool_Checked;
            tbBoolean.Unchecked += cbBool_Unchecked;
            tbBoolean.GotFocus += OnControlFocused;
            tbBoolean.LostFocus += OnControlUnfocused;
        }

        public void Create(InBase owner, JSValue value)
        {
            _owner = owner;
            _value = value;
            UpdateCheckboxState();
            UpdateControlStatus();
        }

        private void UpdateCheckboxState()
        {
            if (_value != null)
            {
                tbBoolean.IsChecked = ConvertToBoolean(_value);
            }
        }

        private void UpdateControlStatus()
        {
            tbBoolean.IsEnabled = !_isReadOnly;
        }

        private bool ConvertToBoolean(JSValue value)
        {
            if (value == null)
                return false;

            if (value.Type == Types.Boolean)
                return value.As<bool>();

            return Convert.ToBoolean(value.Value);
        }

        private void cbBool_Checked(object sender, RoutedEventArgs e)
        {
            ValueChanged(true);
        }

        private void cbBool_Unchecked(object sender, RoutedEventArgs e)
        {
            ValueChanged(false);
        }

        private void ValueChanged(bool newValue)
        {
            if (_owner != null)
            {
                _owner.ValueChanged(_value, new JSBoolean(newValue));
            }
        }

