public class DefaultDbContext : IdentityDbContext
{
    private static DefaultDbContext _instance;

    public static string ConnectionString { get; set; }

    public DbSet<Ban> Ban { get; set; }
    public DbSet<Character> Character { get; set; }
    public DbSet<Group> Group { get; set; }
    public DbSet<GroupMember> GroupMember { get; set; }
    public DbSet<Property> Property { get; set; }
    public DbSet<Job> Job { get; set; }
    public DbSet<Vehicle> Vehicle { get; set; }

    public static DefaultDbContext Instance
    {
        get
        {
            if (_instance == null)
            {
                _instance = new DefaultDbContext();
            }
            return _instance;
        }
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        if (!optionsBuilder.IsConfigured)
        {
            optionsBuilder.UseMySql(ConnectionString, ServerVersion.AutoDetect(ConnectionString));
        }
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<Ban>()
            .HasOne(b => b.Account)
            .WithMany(a => a.Bans)
            .HasForeignKey(b => b.AccountId);

        modelBuilder.Entity<Character>()
            .HasOne(c => c.Account)
            .WithMany(a => a.Characters)
            .HasForeignKey(c => c.AccountId);

        modelBuilder.Entity<GroupMember>()
            .HasKey(gm => new { gm.GroupId, gm.AccountId });

        modelBuilder.Entity<GroupMember>()
            .HasOne(gm => gm.Group)
            .WithMany(g => g.Members)
            .HasForeignKey(gm => gm.GroupId);

        modelBuilder.Entity<GroupMember>()
            .HasOne(gm => gm.Account)
            .WithMany(a => a.GroupMemberships)
            .HasForeignKey(gm => gm.AccountId);

        // modelBuilder.Entity<Ban>()
        //     .HasOne(b => b.Issuer)
        //     .WithMany(a => a.IssuedBans)
        //     .HasForeignKey(b => b.IssuerId);
    }
}

