namespace DelegateDecompiler.EntityFramework
{
    class AsyncDecompiledQueryable : DecompiledQueryable, IDbAsyncEnumerable
    {
        private readonly IQueryable inner;

        public AsyncDecompiledQueryable(IQueryProvider provider, IQueryable inner) : base(provider, inner)
        {
            this.inner = inner;
        }

        public IDbAsyncEnumerator GetAsyncEnumerator()
        {
            IDbAsyncEnumerable asyncEnumerable = inner as IDbAsyncEnumerable;
            if (asyncEnumerable == null)
            {
                throw new InvalidOperationException("The source IQueryable doesn't implement IDbAsyncEnumerable.");
            }
            return asyncEnumerable.GetAsyncEnumerator();
        }
    }

    class AsyncDecompiledQueryable<T> : DecompiledQueryable<T>, IDbAsyncEnumerable<T>
    {
        private readonly IQueryable<T> inner;

        protected internal AsyncDecompiledQueryable(IQueryProvider provider, IQueryable<T> inner)
            : base(provider, inner)
        {
            this.inner = inner;
        }

        IDbAsyncEnumerator IDbAsyncEnumerable.GetAsyncEnumerator()
        {
            IDbAsyncEnumerable<T> asyncEnumerable = inner as IDbAsyncEnumerable<T>;
            if(asyncEnumerable == null)
            {
                throw new InvalidOperationException("The source IQueryable doesn't implement IDbAsyncEnumerable<T>.");
            }
            return asyncEnumerable.GetAsyncEnumerator();
        }

        public IDbAsyncEnumerator<T> GetAsyncEnumerator()
        {
            IDbAsyncEnumerable<T> asyncEnumerable = inner as IDbAsyncEnumerable<T>;
            if (asyncEnumerable == null)
            {
                throw new InvalidOperationException("The source IQueryable doesn't implement IDbAsyncEnumerable<T>.");
            }
            return asyncEnumerable.GetAsyncEnumerator();
        }
    }
}

using Google.Cloud.BigQuery.Reservation.V1;
using Google.Protobuf.WellKnownTypes;
using System;
using System.Threading.Tasks;

public class Graph
{
    public static async Task Main(string[] args)
    {
        string projectId = "your-project-id";
        string location = "us-central1";
        string reservationId = "sample-reservation";
        long newSlotCapacity = 1000;

        ReservationUpdater updater = new ReservationUpdater();

        try
        {
            Reservation updatedReservation = await updater.UpdateReservationAsync(
                projectId, location, reservationId, newSlotCapacity);

            Console.WriteLine($"Updated reservation: {updatedReservation.Name}");
            Console.WriteLine($"New slot capacity: {updatedReservation.SlotCapacity}");
            Console.WriteLine($"Multi-region: {updatedReservation.MultiRegionAuxiliary}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during reservation update: {ex.Message}");
        }
    }
}

public class ReservationUpdater
{
    public async Task<Reservation> UpdateReservationAsync(
        string projectId,
        string location,
        string reservationId,
        long newSlotCapacity)
    {
        ReservationServiceClient client = await ReservationServiceClient.CreateAsync();

        string reservationName = ReservationName.Format(projectId, location, reservationId);

        Reservation updatedConfig = new Reservation
        {
            Name = reservationName,
            SlotCapacity = newSlotCapacity,
            IgnoreIdleSlots = false
        };

        FieldMask mask = new FieldMask();
        mask.Paths.Add("slot_capacity");
        mask.Paths.Add("ignore_idle_slots");

        UpdateReservationRequest request = new UpdateReservationRequest
        {
            Reservation = updatedConfig,
            UpdateMask = mask
        };

        Reservation response = await client.UpdateReservationAsync(request);
        return response;
    }
}

