class YahooSearch {
    private string query;
    private string content;
    private int page;
 
    const string yahoo = "http://search.yahoo.com/search?";
 
    public YahooSearch(string query) : this(query, 0) { }
 
    public YahooSearch(string query, int page) {
        this.query = query;
        this.page = page;
        this.content = new WebClient()
            .DownloadString(
                string.Format(yahoo + "p={0}&b={1}", query, this.page * 10 + 1)
            );
    }
 
    public YahooResult[] Results {
        get {
            List<YahooResult> results = new List<YahooResult>();
 
            Func<string, string, string> substringBefore = (str, before) =>
            {
                int iHref = str.IndexOf(before);
                return iHref < 0 ? "" : str.Substring(0, iHref);
            };
            Func<string, string, string> substringAfter = (str, after) =>
            {
                int iHref = str.IndexOf(after);
                return iHref < 0 ? "" : str.Substring(iHref + after.Length);
            };
            Converter<string, string> getText = p =>
                Regex.Replace(p, "<[^>]*>", x => "");
 
            Regex rx = new Regex(@"
                <li>
                    <div \s class=""res"">
                        <div>
                            <h3>
                                <a \s (?'LinkAttributes'[^>]+)>
                                    (?'LinkText' .*?)
                                (?></a>)
                            </h3>
                        </div>
                        <div \s class=""abstr"">
                            (?'Abstract' .*?)
                        (?></div>)
                        .*?
                    (?></div>)
                </li>",
                RegexOptions.IgnorePatternWhitespace
                | RegexOptions.ExplicitCapture
            );
            foreach (Match e in rx.Matches(this.content)) {
                string rurl = getText(substringBefore(substringAfter(
                    e.Groups["LinkAttributes"].Value, @"href="""), @""""));
                string rtitle = getText(e.Groups["LinkText"].Value);
                string rcontent = getText(e.Groups["Abstract"].Value);
 
                results.Add(new YahooResult(rurl, rtitle, rcontent));
            }
            return results.ToArray();
        }
    }
 
    public YahooSearch NextPage() {
        return new YahooSearch(this.query, this.page + 1);
    }

using NServiceBus;
using NServiceBus.Logging;
using NServiceBus.Outbox;
using NServiceBus.SqlServer;
using NServiceBus.Transport.AzureServiceBus;
using StructureMap;
using System;
using System.Data.SqlClient;

public class ServiceBusEndPointConfigureAndRun
{
    private readonly IContainer _container;
    private IEndpointInstance _endpoint;
    private readonly EmployerAccountsConfiguration _configuration;

    public ServiceBusEndPointConfigureAndRun(EmployerAccountsConfiguration configuration, IContainer container)
    {
        _configuration = configuration;
        _container = container;
    }

    public void ConfigureAndStartServiceBusEndpoint()
    {
        var endpointConfiguration = new EndpointConfiguration(_configuration.ServiceBusEndpointName);
        endpointConfiguration.License(_configuration.NServiceBusLicense);

        var transport = endpointConfiguration.UseTransport<AzureServiceBusTransport>();
        transport.ConnectionString(_configuration.ServiceBusConnectionString);
        transport.UseForwardingTopology();

        var persistence = endpointConfiguration.UsePersistence<SqlPersistence>();
        persistence.SqlDialect<SqlDialect.MsSqlServer>();
        persistence.ConnectionBuilder(() => new SqlConnection(_configuration.DatabaseConnectionString));
        persistence.Schema("NServiceBus");

        endpointConfiguration.SendFailedMessagesTo("error");
        endpointConfiguration.EnableOutbox().KeepMessagesFor(TimeSpan.FromDays(30));
        endpointConfiguration.UseSerialization<NewtonsoftJsonSerializer>();
        endpointConfiguration.EnableInstallers();

        LogManager.Use<NLogFactory>();
        endpointConfiguration.UseUnitOfWork();

        endpointConfiguration.UseContainer<StructureMapBuilder>(c => c.ExistingContainer(_container));

        _endpoint = Endpoint.Start(endpointConfiguration).GetAwaiter().GetResult();
        _container.Configure(c => c.For<IMessageSession>().Use(_endpoint));
    }

    public void StopServiceBusEndpoint()
    {
        try
        {
            _endpoint?.Stop().GetAwaiter().GetResult();
        }
        catch
        {
            // Handle or log shutdown exceptions
        }
    }
}

