namespace YourNamespace.Controllers
{
    [Authorize(Roles = "Admin")]
    [ApiController]
    [Route("api/[controller]")]
    public class LogsController : ControllerBase
    {
        private readonly IAsyncDocumentSession _dbSession;
        private readonly ILogger<LogsController> _logger;

        public LogsController(IAsyncDocumentSession dbSession, ILogger<LogsController> logger)
        {
            _dbSession = dbSession;
            _logger = logger;
        }

        [HttpGet]
        public async Task<IActionResult> GetAll(int skip = 0, int take = 10, string level = null, string sort = "timestamp")
        {
            try
            {
                var query = _dbSession.Query<StructuredLog>();

                if (!string.IsNullOrEmpty(level))
                {
                    query = query.Where(log => log.Level == level);
                }

                if (sort == "timestamp")
                {
                    query = query.OrderByDescending(log => log.Timestamp);
                }

                var logs = await query.Skip(skip).Take(take).ToListAsync();
                var totalCount = await query.CountAsync();

                var pagedList = new PagedList<StructuredLog>(logs, totalCount, skip, take);
                return Ok(pagedList);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error retrieving logs");
                return StatusCode(500, "Internal server error");
            }
        }

        [HttpDelete("{id}")]
        public async Task<IActionResult> Delete(string id)
        {
            try
            {
                var log = await _dbSession.LoadAsync<StructuredLog>(id);
                if (log == null)
                {
                    return NotFound();
                }

                _dbSession.Delete(log);
                await _dbSession.SaveChangesAsync();

                return NoContent();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error deleting log with ID: {Id}", id);
                return StatusCode(500, "Internal server error");
            }
        }
    }

