public class Grains
{
    public static void Main()
    {
        string[] animals = {
            "fly",
            "spider",
            "bird",
            "cat",
            "dog",
            "goat",
            "cow",
            "horse"
        };
        string[] verses = {
            "I don't know why she swallowed that fly.\nPerhaps she'll die\n",
            "That wiggled and jiggled and tickled inside her",
            "How absurd, to swallow a bird",
            "Imagine that. She swallowed a cat",
            "What a hog to swallow a dog",
            "She just opened her throat and swallowed that goat",
            "I don't know how she swallowed that cow",
            "She's dead of course"
        };
 
        for (int i = 0; i < animals.Length; i++)
        {
            Console.WriteLine("There was an old lady who swallowed a {0}\n{1}\n", animals[i], verses[i]);
            for (int j = i; j > 0 && i < animals.Length - 1; j--)
            {
                Console.WriteLine("She swallowed the {0} to catch the {1}\n", animals[j], animals[j-1]);
                if (j == 1)
                {
                    Console.WriteLine("{0}\n", verses[0]);
                }
            }
        }
    }
}

