namespace MyApplication.Navigation
{
    // Implements the navigation provider for the administrative interface.
    public class AdminMenu : INavigationProvider
    {
        // The localization instance for localized labels.
        private readonly IStringLocalizer<AdminMenu> S;

        // Constructor using dependency injection for localization.
        public AdminMenu(IStringLocalizer<AdminMenu> localizer)
        {
            S = localizer;
        }

        // The main method to build the navigation menu asynchronously.
        public async Task BuildNavigationAsync(INavigationBuilder builder)
        {
            // Check whether the current context is the admin area.
            if (!builder.IsInNavigation("admin"))
            {
                return;
            }

            // Build the top-level menu for the Search Module.
            builder
                .Add(S["Modules"], modules => modules
                    .Add(S["Search Module"], searchModule => searchModule
                        .Action("Index", "Admin", new { area = "OrchardCore.Lucene" })
                        .Permission(Permissions.ManageSearchModule)
                        .Position("5")
                        .Add(S["Indexes"], indexes => indexes
                            .Action("List", "Index", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.ManageIndexes)
                            .Position("1")
                        )
                        .Add(S["Query Search"], query => query
                            .Action("Query", "Search", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.RunSearchQueries)
                            .Position("2")
                        )
                        .Add(S["Settings"], settings => settings
                            .Action("Settings", "Configuration", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.ManageSearchSettings)
                            .Position("3")
                        )
                    )
                );

            // Possibly perform additional asynchronous operations before registering menu.
            await Task.CompletedTask;
        }
    }

