using UnityEngine;
using UnityEngine.EventSystems;

// Main drop target class handling module drag-and-drop actions.
public class ShipModulesDropTarget : MonoBehaviour, IDropHandler
{
    private ShipModulesController modulesController;

    void Awake()
    {
        // Retrieve the module controller from the local player's ship.
        if (PlayerShip.LocalPlayer == null)
        {
            Debug.LogError("Local player ship is not available.");
            return;
        }
        modulesController = PlayerShip.LocalPlayer.GetComponent<ShipModulesController>();
        if (modulesController == null)
        {
            Debug.LogError("ShipModulesController component missing on the player ship.");
        }
    }

    // Central handler for drop events.
    public void OnDrop(PointerEventData eventData)
    {
        if (eventData.pointerDrag == null)
        {
            Debug.LogError("No object is being dragged.");
            return;
        }

        // Retrieve module information from the dragged object.
        DraggedModuleInfo draggedInfo = eventData.pointerDrag.GetComponent<DraggedModuleInfo>();
        if (draggedInfo == null)
        {
            Debug.LogError("Dragged object does not have module information.");
            return;
        }

        // Decide action based on the origin of the dragged module.
        if (draggedInfo.IsFromCargo)
        {
            OnDropCargoItem(draggedInfo);
        }
        else
        {
            OnDropHardpointModule(draggedInfo);
        }
    }

    // Handle drops coming from cargo items.
    private void OnDropCargoItem(DraggedModuleInfo moduleInfo)
    {
        // Attempt to find the first available slot.
        ShipModuleController targetSlot = modulesController.GetAvailableSlot();
        if (targetSlot == null)
        {
            Debug.LogError("No available module slot to equip the cargo item.");
            return;
        }

        // If the target slot already has a module, swap it back to cargo.
        if (targetSlot.HasModule())
        {
            ShipModuleController existingModule = targetSlot.GetModule();
            modulesController.SwapModuleToCargo(existingModule);
        }

        // Equip the new module into the target slot.
        bool equipped = targetSlot.EquipModule(moduleInfo.ModuleData);
        if (!equipped)
        {
            Debug.LogError("Failed to equip cargo module.");
        }
        else
        {
            Debug.Log("Cargo module equipped successfully.");
        }
    }

