namespace RubyCSharpIntegration
{
    public class State
    {
        private Dictionary<string, Func<List<object>, object>> definedMethods;
        private Dictionary<string, object> variables;

        public State()
        {
            definedMethods = new Dictionary<string, Func<List<object>, object>>();
            variables = new Dictionary<string, object>();
        }

        public void DefineCliMethod(string methodName, Func<List<object>, object> method)
        {
            definedMethods[methodName] = method;
        }

        public object CallMethod(string methodName, List<object> args)
        {
            if (definedMethods.ContainsKey(methodName))
                return definedMethods[methodName](args);
            throw new Exception($"Method {methodName} is not defined.");
        }

        public void SetVariable(string name, object value)
        {
            variables[name] = value;
        }

        public object GetVariable(string name)
        {
            if (variables.ContainsKey(name))
                return variables[name];
            throw new Exception($"Variable {name} is not defined.");
        }
    }

    public class RubyRunner
    {
        private State state;

        public RubyRunner()
        {
            state = new State();
            InitializeMethods();
        }

        private void InitializeMethods()
        {
            state.DefineCliMethod("print_message", args =>
            {
                if (args.Count > 0 && args[0] is string message)
                {
                    MessageBox.Show(message, "Message", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return null;
                }
                throw new ArgumentException("Invalid arguments for print_message");
            });

            state.DefineCliMethod("add", args =>
            {
                if (args.Count == 2 && args[0] is double a && args[1] is double b)
                {
                    return a + b;
                }
                throw new ArgumentException("Invalid arguments for add");
            });

            state.DefineCliMethod("set_variable", args =>
            {
                if (args.Count == 2)
                {
                    state.SetVariable(args[0].ToString(), args[1]);
                    return null;
                }
                throw new ArgumentException("Invalid arguments for set_variable");
            });

