using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.NodeServices;
using Microsoft.AspNetCore.SpaServices.Prerendering;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public static class HttpRequestExtensions
{
    public static IRequest AbstractRequestInfo(this HttpRequest request)
    {
        return new Request
        {
            Url = $"{request.Scheme}://{request.Host}{request.Path}{request.QueryString}",
            Origin = request.Headers["Origin"].ToString(),
            Path = request.Path.ToString(),
            Query = request.Query.ToDictionary(x => x.Key, x => x.Value.ToString()),
            Headers = request.Headers.ToDictionary(x => x.Key, x => x.Value.ToString()),
            UserAgent = request.Headers["User-Agent"].ToString(),
            Protocol = request.Protocol
        };
    }

    public static async Task<RenderToStringResult> BuildPrerender(
        this HttpContext context,
        INodeServices nodeServices,
        string modulePath,
        TransferData transferData = null,
        TimeSpan? timeout = null)
    {
        try
        {
            var request = context.Request.AbstractRequestInfo();
            var renderOptions = new RenderToStringOptions
            {
                RequestUrl = request.Url,
                TransferData = transferData ?? new TransferData(),
                MaximumWaitTime = timeout ?? TimeSpan.FromSeconds(30),
                BootModulePath = modulePath,
                RequestDetails = new RequestDetails
                {
                    OriginUrl = request.Origin,
                    Request = request
                }
            };

            return await nodeServices.InvokeAsync<RenderToStringResult>(
                modulePath,
                renderOptions
            );
        }
        catch (Exception ex)
        {
            // Logging or custom error handling
            return new RenderToStringResult
            {
                Html = string.Empty,
                StatusCode = 500
            };
        }
    }
}

