public class EndScreenController : MonoBehaviour
{
    public Text winnerText;
    public Text player1Text;
    public Text player2Text;
    public Text nextLeftPlayers;
    public Text nextRightPlayers;

    private string matchId = "12345";
    private string tournamentId = "T001";

    private void OnEnable()
    {
        OnActivation();
    }

    private void OnDisable()
    {
        OnDeactivation();
    }

    private void OnActivation()
    {
        winnerText.text = "Loading...";
        player1Text.text = "Player 1: Loading...";
        player2Text.text = "Player 2: Loading...";
        nextLeftPlayers.text = "Loading...";
        nextRightPlayers.text = "Loading...";

        StartCoroutine(DownloadMatchInfo());
        StartCoroutine(DownloadUpcomingMatches());
    }

    private void OnDeactivation()
    {
        winnerText.text = "";
        player1Text.text = "";
        player2Text.text = "";
        nextLeftPlayers.text = "";
        nextRightPlayers.text = "";
    }

    private IEnumerator DownloadMatchInfo()
    {
        // Simulate a network request
        yield return new WaitForSeconds(2);

        MatchInfo matchInfo = new MatchInfo
        {
            Winner = "Player 1",
            Player1Points = 150,
            Player2Points = 120
        };

        OnMatchInfoDownloaded(matchInfo);
    }

    private IEnumerator DownloadUpcomingMatches()
    {
        // Simulate a network request
        yield return new WaitForSeconds(2);

        UpcomingMatches upcomingMatches = new UpcomingMatches
        {
            Matches = new Match[]
            {
                new Match { Bot1 = new Bot { Name = "Bot A" }, Bot2 = new Bot { Name = "Bot B" } },
                new Match { Bot1 = new Bot { Name = "Bot C" }, Bot2 = new Bot { Name = "Bot D" } },
                new Match { Bot1 = new Bot { Name = "Bot E" }, Bot2 = new Bot { Name = "Bot F" } }
            }
        };

        OnUpcomingMatchesDownloaded(upcomingMatches);
    }

    private void OnMatchInfoDownloaded(MatchInfo matchInfo)
    {
        if (string.IsNullOrEmpty(matchInfo.Winner))
        {
            winnerText.text = "It's a draw!";
        }
        else
        {
            winnerText.text = $"Winner: {matchInfo.Winner}";
        }

        player1Text.text = $"Player 1: {matchInfo.Player1Points} {(matchInfo.Player1Points > 0 ? "+" : "")}";
        player2Text.text = $"Player 2: {matchInfo.Player2Points} {(matchInfo.Player2Points > 0 ? "+" : "")}";
    }

using System;
 
class Service
{
  static int F(int n)
  {
    if (n == 0) return 1;
    return n - M(F(n-1));
  }
 
  static int M(int n)
  {
    if (n == 0) return 0;
    return n - F(M(n-1));
  }
 
  static void Main(string[] args)
  {
    for (int i = 0; i < 20; i++)
    {
      Console.Write("{0} ", F(i));
    }
    Console.WriteLine();
    for (int i = 0; i < 20; i++)
    {
      Console.Write("{0} ", M(i));
    }
    Console.WriteLine();
  }
}

