namespace Harshad
{
    class Library
    {
        static void Main(string[] args)
        {
            int count = 0;
            List<int> harshads = new List<int>();
            for (int n = 1; count < 20; ++n)
            {
                if (isHarshad(n))
                {
                    count++;
                    harshads.Add(n);
                }
            }
            Console.WriteLine(string.Join(" ", harshads));
            int h = 1000;
            while (!isHarshad(++h));
            Console.WriteLine(h);
            Console.ReadKey();
        }
        static bool isHarshad(int n)
        {
            int s = 0;
            string n_str = n.ToString();
            for (int i = 0; i < n_str.Length; ++i)
            {
                s += int.Parse(n_str.Substring(i, 1));
            }
            return n % s == 0;
        }
    }
}

