namespace GameManagementSystem.Data
{
    public class DefaultDbContext : IdentityDbContext<Account>
    {
        private static DefaultDbContext _instance;
        private static readonly object _lockObject = new object();

        public static DefaultDbContext Instance
        {
            get
            {
                if (_instance == null)
                {
                    lock (_lockObject)
                    {
                        if (_instance == null)
                        {
                            _instance = new DefaultDbContext();
                        }
                    }
                }
                return _instance;
            }
        }

        public DbSet<Account> Accounts { get; set; }
        public DbSet<Ban> Bans { get; set; }
        public DbSet<Character> Characters { get; set; }
        public DbSet<Group> Groups { get; set; }
        public DbSet<GroupMember> GroupMembers { get; set; }
        public DbSet<Property> Properties { get; set; }
        public DbSet<Job> Jobs { get; set; }
        public DbSet<Vehicle> Vehicles { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            if (!optionsBuilder.IsConfigured)
            {
                optionsBuilder.UseMySql(
                    ConnectionString.Default,
                    ServerVersion.AutoDetect(ConnectionString.Default),
                    options => options.EnableRetryOnFailure()
                );
            }
            base.OnConfiguring(optionsBuilder);
        }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);

            modelBuilder.Entity<Account>()
                .HasMany(a => a.Characters)
                .WithOne(c => c.Account)
                .HasForeignKey(c => c.AccountId);

            modelBuilder.Entity<Account>()
                .HasMany(a => a.Bans)
                .WithOne(b => b.Account)
                .HasForeignKey(b => b.AccountId);

            modelBuilder.Entity<Group>()
                .HasMany(g => g.GroupMembers)
                .WithOne(gm => gm.Group)
                .HasForeignKey(gm => gm.GroupId);

            modelBuilder.Entity<Account>()
                .HasMany(a => a.Properties)
                .WithOne(p => p.Owner)
                .HasForeignKey(p => p.OwnerId);
        }
    }

