public class WebCrawlerIndexer
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, bool> _visitedUrls;
    private readonly int _maxDepth;
    private readonly HashSet<string> _excludedTags;

    public WebCrawlerIndexer(int maxDepth = 3)
    {
        _httpClient = new HttpClient();
        _visitedUrls = new ConcurrentDictionary<string, bool>();
        _maxDepth = maxDepth;
        _excludedTags = new HashSet<string> { "script", "style", "meta", "head" };
    }

    public async Task CrawlWebsiteAsync(string startUrl)
    {
        try
        {
            await ProcessUrlAsync(startUrl, 0);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Crawling error: {ex.Message}");
        }
    }

    private async Task ProcessUrlAsync(string url, int currentDepth)
    {
        if (currentDepth > _maxDepth ||
            _visitedUrls.ContainsKey(url) ||
            !IsValidUrl(url))
        {
            return;
        }

        _visitedUrls[url] = true;

        try
        {
            string htmlContent = await FetchWebPageContentAsync(url);
            var extractedLinks = ExtractLinks(htmlContent, url);
            var processedContent = ProcessPageContent(htmlContent);

            IndexContent(url, processedContent);

            await Task.WhenAll(
                extractedLinks.Select(link =>
                    ProcessUrlAsync(link, currentDepth + 1)
                )
            );
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Processing error for {url}: {ex.Message}");
        }
    }

    private async Task<string> FetchWebPageContentAsync(string url)
    {
        HttpResponseMessage response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }

    private List<string> ExtractLinks(string htmlContent, string baseUrl)
    {
        var linkPattern = @"href\s*=\s*(?:[""'](?<url>[^""']+)[""']|(?<url>\S+))";
        var matches = Regex.Matches(htmlContent, linkPattern, RegexOptions.IgnoreCase);

        return matches
            .Cast<Match>()
            .Select(m => m.Groups["url"].Value)
            .Where(link => IsValidLink(link, baseUrl))
            .ToList();
    }

