using System;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;

public static class LinqExtensions
{
    public static PropertyInfo ExtractPropertyInfo<T>(this Expression<Func<T, object>> expression)
    {
        if (expression.Body is UnaryExpression unaryExpr)
        {
            if (unaryExpr.Operand is MemberExpression memberExpr)
            {
                return memberExpr.Member as PropertyInfo;
            }
        }
        else if (expression.Body is MemberExpression memberExpression)
        {
            return memberExpression.Member as PropertyInfo;
        }

        throw new ArgumentException("Invalid expression format. Expected a property expression.");
    }

    public static FieldInfo ExtractFieldInfo<T>(this Expression<Func<T, object>> expression)
    {
        if (expression.Body is UnaryExpression unaryExpr)
        {
            if (unaryExpr.Operand is MemberExpression memberExpr)
            {
                return memberExpr.Member as FieldInfo;
            }
        }
        else if (expression.Body is MemberExpression memberExpression)
        {
            return memberExpression.Member as FieldInfo;
        }

        throw new ArgumentException("Invalid expression format. Expected a field expression.");
    }

    public static MemberInfo ExtractMemberInfo<T>(this Expression<Func<T, object>> expression)
    {
        if (expression == null) throw new ArgumentNullException(nameof(expression));

        if (expression.Body is UnaryExpression unaryExpr)
        {
            if (unaryExpr.Operand is MemberExpression memberExpr)
            {
                return memberExpr.Member;
            }
        }
        else if (expression.Body is MemberExpression memberExpression)
        {
            return memberExpression.Member;
        }

        throw new ArgumentException("Invalid expression format. Expected a member expression.");
    }
}

