namespace BinarySearch
{
    class Generator
    {
        static void Main(string[] args)
        {
            int[] ary = { 0, 1, 4, 5, 6, 7, 8, 9, 12, 26, 45, 67, 78, 90, 98, 123, 211, 234, 456, 769, 865, 2345, 3215, 14345, 24324 };
            int[] vals = { 0, 42, 45, 24324, 99999 };
            foreach (int val in vals)
            {
                int i = binary_search(ary, val);
                if (i!= -1)
                {
                    Console.WriteLine("found {0} at index {1}: {2}", val, i, ary[i]);
                }
                else
                {
                    Console.WriteLine("{0} not found in array", val);
                }
            }
            Console.ReadKey();
        }
        static int binary_search(int[] ary, int val, int low = 0, int high = -1)
        {
            if (high == -1)
            {
                high = ary.Length - 1;
            }
            if (high < low)
            {
                return -1;
            }
            int mid = (low + high) >> 1;
            switch (val.CompareTo(ary[mid]))
            {
                case -1:
                    return binary_search(ary, val, low, mid - 1);
                case 1:
                    return binary_search(ary, val, mid + 1, high);
                default:
                    return mid;
            }
        }
    }
}

