namespace ProjectEuler
{
    class Problem92
    {
        static void Main(string[] args)
        {
            // array bounds is sort of random here, it's big enough for 64bit unsigned.
            ulong[] sums = new ulong[32 * 81 + 1];
            sums[0] = 1;
            sums[1] = 0;
            for (int n = 1; ; n++)
            {
                for (int i = n * 81; i > 0; i--)
                {
                    for (int j = 1; j < 10; j++)
                    {
                        int s = j * j;
                        if (s > i) break;
                        sums[i] += sums[i - s];
                    }
                }

                ulong count89 = 0;
                for (int i = 1; i < n * 81 + 1; i++)
                {
                    if (!is89(i)) continue;

                    if (sums[i] > ulong.MaxValue - count89)
                    {
                        Console.WriteLine("counter overflow for 10^" + n);
                        return;
                    }
                    count89 += sums[i];
                }

                Console.WriteLine("1->10^" + n + ": " + count89);
            }
        }

        static bool is89(int x)
        {
            while (true)
            {
                int s = 0;
                do s += (x % 10) * (x % 10); while ((x /= 10) > 0);

                if (s == 89) return true;
                if (s == 1) return false;
                x = s;
            }
        }
    }
}

