    // Specialized event representing an instance managed halt in preparation for restart.
    public class InstanceHaltedForRestartEvent : IInstanceStateEvent
    {
        private const string HALT_FOR_RESTART_METHOD = "InstanceManager.HaltForRestart";
        public LogRecord LogRecord { get; private set; }
        public DateTime EventTime => this.LogRecord.Timestamp;
        public string Description => "Instance has been halted by the Instance Manager in preparation for a restart.";
        public bool IsTerminating => true;
        public bool IsStarting => false;

        private InstanceHaltedForRestartEvent(LogRecord record)
        {
            Debug.Assert(record.MethodName == HALT_FOR_RESTART_METHOD,
                "LogRecord method does not match InstanceHaltedForRestartEvent type.");
            this.LogRecord = record;
        }

        // Checks if the provided log record corresponds to a halt-for-restart event.
        public static bool IsInstanceHaltedForRestart(LogRecord record)
        {
            return record != null &&
                   string.Equals(record.MethodName, HALT_FOR_RESTART_METHOD, StringComparison.Ordinal);
        }

        // Creates an instance of the event from a valid log record.
        public static InstanceHaltedForRestartEvent FromLogRecord(LogRecord record)
        {
            if (!IsInstanceHaltedForRestart(record))
            {
                throw new ArgumentException("The provided log record does not match a halt-for-restart event.", nameof(record));
            }
            return new InstanceHaltedForRestartEvent(record);
        }
    }

