using System;
 
public class BananaFanaBoFana
{
    public static void printVerse(string name)
    {
        string x = name.ToLower().Capitalize();
        string y = x[0] switch
        {
            'A' => x.ToLower(),
            'E' => x.ToLower(),
            'I' => x.ToLower(),
            'O' => x.ToLower(),
            'U' => x.ToLower(),
            _ => x.Substring(1)
        };
        string b = "b" + y;
        string f = "f" + y;
        string m = "m" + y;
        switch (x[0])
        {
            case 'B':
                b = y;
                break;
            case 'F':
                f = y;
                break;
            case 'M':
                m = y;
                break;
            default:
                break;
        }
        Console.WriteLine($"{x}, {x}, bo-{b}");
        Console.WriteLine($"Banana-fana fo-{f}");
        Console.WriteLine($"Fee-fi-mo-{m}");
        Console.WriteLine($"{x}!\n");
    }
 
    public static void Main(string[] args)
    {
        new string[] { "Gary", "Earl", "Billy", "Felix", "Mary", "Steve" }.ForEach(printVerse);
    }
}
 
public static class StringExtensions
{
    public static string Capitalize(this string s)
    {
        return s.Substring(0, 1).ToUpper() + s.Substring(1);
    }
}

using System;
 
public class TimeMean
{
    public struct digitime
    {
        public int hour;
        public int minute;
        public int second;
    }
 
    public static double timeToDegrees(digitime time)
    {
        return (360 * time.hour / 24.0 + 360 * time.minute / (24 * 60.0) + 360 * time.second / (24 * 3600.0));
    }
 
    public static digitime timeFromDegrees(double angle)
    {
        digitime d = new digitime();
        double totalSeconds = 24 * 60 * 60 * angle / 360;
 
        d.second = (int)totalSeconds % 60;
        d.minute = ((int)totalSeconds % 3600 - d.second) / 60;
        d.hour = (int)totalSeconds / 3600;
 
        return d;
    }
 
    public static double meanAngle(double[] angles, int size)
    {
        double y_part = 0, x_part = 0;
        int i;
 
        for (i = 0; i < size; i++)
        {
            x_part += Math.Cos(angles[i] * Math.PI / 180);
            y_part += Math.Sin(angles[i] * Math.PI / 180);
        }
 
        return Math.Atan2(y_part / size, x_part / size) * 180 / Math.PI;
    }
 
    public static void Main()
    {
        digitime[] set;
        digitime meanTime;
        int inputs, i;
        double[] angleSet;
        double angleMean;
 
        Console.Write("Enter number of inputs : ");
        inputs = Convert.ToInt32(Console.ReadLine());
        set = new digitime[inputs];
        angleSet = new double[inputs];
        Console.WriteLine("\n\nEnter the data separated by a space between each unit : ");
 
        for (i = 0; i < inputs; i++)
        {
            string[] input = Console.ReadLine().Split(' ');
            set[i].hour = Convert.ToInt32(input[0]);
            set[i].minute = Convert.ToInt32(input[1]);
            set[i].second = Convert.ToInt32(input[2]);
            angleSet[i] = timeToDegrees(set[i]);
        }
 
        meanTime = timeFromDegrees(360 + meanAngle(angleSet, inputs));
 
        Console.WriteLine("\n\nThe mean time is : {0}:{1}:{2}", meanTime.hour, meanTime.minute, meanTime.second);
    }
}

