using System;
using System.Collections.Generic;

/// <summary>
/// A specialized equality comparer for byte arrays that provides precise element-wise comparison.
/// </summary>
public sealed class ByteArrayEqualityComparer : IEqualityComparer<byte[]>
{
    /// <summary>
    /// A singleton instance of the ByteArrayEqualityComparer to reduce memory allocation.
    /// </summary>
    public static readonly ByteArrayEqualityComparer Instance = new ByteArrayEqualityComparer();

    /// <summary>
    /// Determines whether two byte arrays are equal by comparing their length and individual elements.
    /// </summary>
    /// <param name="x">The first byte array to compare.</param>
    /// <param name="y">The second byte array to compare.</param>
    /// <returns>True if both arrays are equal, otherwise false.</returns>
    public bool Equals(byte[] x, byte[] y)
    {
        // Handle reference equality and null scenarios
        if (ReferenceEquals(x, y))
            return true;

        if (x == null || y == null)
            return false;

        // Compare array lengths first for quick differentiation
        if (x.Length != y.Length)
            return false;

        // Perform byte-by-byte comparison
        return ByteEquals(x, y);
    }

    /// <summary>
    /// Performs a precise byte-by-byte comparison of two byte arrays.
    /// </summary>
    /// <param name="x">The first byte array.</param>
    /// <param name="y">The second byte array.</param>
    /// <returns>True if all bytes are identical, otherwise false.</returns>
    private bool ByteEquals(byte[] x, byte[] y)
    {
        for (int i = 0; i < x.Length; i++)
        {
            if (x[i] != y[i])
                return false;
        }
        return true;
    }

    /// <summary>
    /// Generates a hash code for a byte array using a multiplicative approach.
    /// </summary>
    /// <param name="obj">The byte array to generate a hash code for.</param>
    /// <returns>A hash code representing the byte array's contents.</returns>
    public int GetHashCode(byte[] obj)
    {
        if (obj == null)
            return 0;

        unchecked
        {
            int hash = 17; // Prime number base
            const int multiplier = 31; // Another prime number for distribution

            // Incorporate each byte into the hash code
            foreach (byte b in obj)
            {
                hash = hash * multiplier + b;
            }

            return hash;
        }
    }
}

