// Trait configuration holding notification settings for capture events.
public class CaptureNotificationInfo : ITraitInfo
{
    [TraitParameter(Optional = false)]
    public readonly string NewOwnerNotification = "CaptureSuccess";

    [TraitParameter(Optional = false)]
    public readonly string NewOwnerVoice = "Strong";

    [TraitParameter(Optional = false)]
    public readonly string LoseNotification = "LostControl";

    [TraitParameter(Optional = false)]
    public readonly string LoseNewOwnerVoice = "Regret";

    // BitSet representing capture types (e.g., unit or building capture).
    [TraitParameter(Optional = true)]
    public readonly BitSet<CaptureType> CaptureTypes = BitSet<CaptureType>.Empty;
}

// Interface for objects that handle capture events.
public interface INotifyCapture
{
    void OnCapture(IAiActor actor, Owner previousOwner, Owner newOwner, CaptureType captureType);
}

// Implementation that plays audio notifications on capture events.
public class CaptureNotification : INotifyCapture
{
    readonly CaptureNotificationInfo info;

    public CaptureNotification(Actor self, CaptureNotificationInfo info)
    {
        this.info = info;
    }

    public void OnCapture(IAiActor actor, Owner previousOwner, Owner newOwner, CaptureType captureType)
    {
        // Only process supported capture types.
        if (!info.CaptureTypes.Contains(captureType))
            return;

        // Determine faction voice for new owner events.
        string newOwnerFaction = newOwner.FactionName;
        string newOwnerAudio = ComposeAudioCommand(info.NewOwnerNotification, info.NewOwnerVoice, newOwnerFaction);
        GameSoundSystem.Play(newOwnerAudio, newOwner);

        // Determine faction voice for previous owner events.
        string previousOwnerFaction = previousOwner.FactionName;
        string loseOwnerAudio = ComposeAudioCommand(info.LoseNotification, info.LoseNewOwnerVoice, previousOwnerFaction);
        GameSoundSystem.Play(loseOwnerAudio, previousOwner);
    }

    string ComposeAudioCommand(string notification, string voice, string faction)
    {
        // Combine notification parameters into a command string.
        return $"{notification}_{voice}_{faction}";
    }
}

// Sample supporting enum for capture types.
public enum CaptureType
{
    Unit,
    Building
}

