    public class EqualityExpression
    {
        public RelationalExpression Left { get; set; }
        public EqualityExpressionTail Tail { get; set; }

        public static EqualityExpression Parse(TokenReader reader)
        {
            EqualityExpression equalityExpr = new EqualityExpression();
            // Parse the left-hand side as a relational expression
            equalityExpr.Left = RelationalExpression.Parse(reader);

            // Lookahead: If next token is an equality operator "==" or "!=" then parse the equality tail
            Token token = reader.CurrentToken;
            if (token != null && (token.Value == "==" || token.Value == "!="))
            {
                equalityExpr.Tail = EqualityExpressionTail.Parse(reader);
            }
            return equalityExpr;
        }

        public Expression AsExpressionTree()
        {
            // Placeholder for converting the equality expression parse tree into an executable expression
            throw new NotImplementedException();
        }
    }

