    {
        // Internal variable indicating the equality operator type ("==" or "!=")
        internal string _type;
        public RelationalExpression Right { get; set; }
        public EqualityExpressionTail Next { get; set; }

        public static EqualityExpressionTail Parse(TokenReader reader)
        {
            EqualityExpressionTail tail = new EqualityExpressionTail();

            // Read the equality operator token
            Token opToken = reader.CurrentToken;
            if (opToken == null || (opToken.Value != "==" && opToken.Value != "!="))
                throw new Exception("Expected equality operator but found " + (opToken?.Value ?? "null"));
            tail._type = opToken.Value;
            reader.ReadToken(); // Consume the equality operator

            // Parse the following relational expression
            tail.Right = RelationalExpression.Parse(reader);

            // Check for nested chained equality operators
            Token nextToken = reader.CurrentToken;
            if (nextToken != null && (nextToken.Value == "==" || nextToken.Value == "!="))
            {
                tail.Next = EqualityExpressionTail.Parse(reader);
            }
            return tail;
        }

