    [AttributeUsage(AttributeTargets.Class | AttributeTargets.Method, AllowMultiple = false, Inherited = true)]
    public sealed class InitializeSimpleMembershipAttribute : ActionFilterAttribute
    {
        private static SimpleMembershipInitializer _initializer;
        private static object _initializerLock = new object();
        private static bool _isInitialized;

        public override void OnActionExecuting(ActionExecutingContext filterContext)
        {
            // Ensure ASP.NET Simple Membership is initialized only once per app start
            LazyInitializer.EnsureInitialized(ref _initializer, ref _isInitialized, ref _initializerLock);
        }

        private class SimpleMembershipInitializer
        {
            public SimpleMembershipInitializer()
            {
                Database.SetInitializer<UsersContext>(null);

                try
                {
                    using (var context = new UsersContext())
                    {
                        if (!context.Database.Exists())
                        {
                            // Create the SimpleMembership database without Entity Framework migration schema
                            ((IObjectContextAdapter)context).ObjectContext.CreateDatabase();
                        }
                    }

                    WebSecurity.InitializeDatabaseConnection("DefaultConnection", "UserProfile", "UserId", "UserName", autoCreateTables: true);
                }
                catch (Exception ex)
                {
                    throw new InvalidOperationException("The ASP.NET Simple Membership database could not be initialized. For more information, please see http://go.microsoft.com/fwlink/?LinkId=256588", ex);
                }
            }
        }
    }
}

using System;
using System.IO;
using System.Windows.Forms;
using Kitware.VTK;

namespace DEMVisualization
{
    public class MainForm : Form
    {
        private RenderWindowControl renderWindowControl;

        public MainForm()
        {
            InitializeComponent();
        }

        private void InitializeComponent()
        {
            this.renderWindowControl = new RenderWindowControl();
            this.SuspendLayout();
            //
            // renderWindowControl
            //
            this.renderWindowControl.Dock = DockStyle.Fill;
            this.renderWindowControl.Load += new EventHandler(this.RenderWindowControl_Load);
            //
            // MainForm
            //
            this.ClientSize = new System.Drawing.Size(800, 600);
            this.Controls.Add(this.renderWindowControl);
            this.Name = "MainForm";
            this.Text = "DEM Visualization";
            this.ResumeLayout(false);
        }

        private void RenderWindowControl_Load(object sender, EventArgs e)
        {
            try
            {
                ProcessDEMData();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error processing DEM data: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void ProcessDEMData()
        {
            // Retrieve the data path from the environment variable
            string dataDir = Environment.GetEnvironmentVariable("VTK_DATA_ROOT") ?? "";
            if (string.IsNullOrEmpty(dataDir))
            {
                throw new Exception("VTK_DATA_ROOT environment variable is not set.");
            }
            string demFilePath = Path.Combine(dataDir, "Data", "terrain.dem");
            if (!File.Exists(demFilePath))
            {
                throw new Exception("DEM file not found: " + demFilePath);
            }

            // Read the DEM data using vtkDEMReader
            vtkDEMReader demReader = vtkDEMReader.New();
            demReader.SetFileName(demFilePath);
            demReader.Update();

            // Get the scalar range from the DEM data
            double[] range = new double[2];
            demReader.GetOutput().GetScalarRange(range);

            // Configure the lookup table for color mapping
            vtkLookupTable lookupTable = vtkLookupTable.New();
            lookupTable.SetTableRange(range[0], range[1]);
