using System;
using Magentaize.Net.LMCL.JsonLite.Serialization;

namespace Magentaize.Net.LMCL.JsonLite.Serialization
{
    /// <summary>
    /// Represents a JSON contract specialized for string type serialization
    /// </summary>
    internal sealed class JsonStringContract : JsonPrimitiveContract
    {
        /// <summary>
        /// Initializes a new instance of the JsonStringContract class
        /// </summary>
        /// <param name="underlyingType">The underlying type for the contract</param>
        public JsonStringContract(Type underlyingType)
            : base(underlyingType)
        {
            // Configure contract type specifically for string
            ContractType = JsonContractType.String;

            // Set default serialization options for string type
            ConfigureStringSerializationOptions();
        }

        /// <summary>
        /// Configures specific serialization options for string contracts
        /// </summary>
        private void ConfigureStringSerializationOptions()
        {
            // Implement default string serialization behaviors
            DefaultValueHandling = JsonDefaultValueHandling.Ignore;
            NullValueHandling = JsonNullValueHandling.Include;

            // Optional: Add specific string-related serialization configurations
            TrimStringValues = true;
            ConvertEmptyStringToNull = false;
        }

        /// <summary>
        /// Determines if empty strings should be converted to null during serialization
        /// </summary>
        public bool ConvertEmptyStringToNull { get; set; }

        /// <summary>
        /// Indicates whether string values should be trimmed during serialization
        /// </summary>
        public bool TrimStringValues { get; set; }

        /// <summary>
        /// Validates and preprocesses string values before serialization
        /// </summary>
        /// <param name="value">The string value to preprocess</param>
        /// <returns>The processed string value</returns>
        internal string PreprocessStringValue(string value)
        {
            if (value == null)
                return null;

            // Apply trimming if configured
            if (TrimStringValues)
                value = value.Trim();

            // Convert empty string to null if configured
            if (ConvertEmptyStringToNull && string.IsNullOrWhiteSpace(value))
                return null;

            return value;
        }
    }
}

