    /// <summary>
    /// Represents a generic LDAP string with validation and conversion support.
    /// </summary>
    public class LdapString
    {
        // Internal storage for the LDAP string value.
        private readonly string _value;

        /// <summary>
        /// Gets the LDAP string value.
        /// </summary>
        public string Value
        {
            get { return _value; }
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="LdapString"/> class.
        /// </summary>
        /// <param name="value">The string value representing LDAP data.</param>
        public LdapString(string value)
        {
            if (value == null)
            {
                throw new ArgumentNullException(nameof(value));
            }
            // Basic validation could be performed here.
            _value = value;
        }

        /// <summary>
        /// Converts an array of signed bytes (sbyte) into an LDAP string.
        /// </summary>
        /// <param name="bytes">The array of signed bytes.</param>
        /// <returns>The converted string representation.</returns>
        protected static string ConvertFromSByteArray(sbyte[] bytes)
        {
            if (bytes == null)
            {
                throw new ArgumentNullException(nameof(bytes));
            }
            // Convert sbyte[] to byte[] for proper encoding handling.
            byte[] unsignedBytes = new byte[bytes.Length];
            for (int i = 0; i < bytes.Length; i++)
            {
                unsignedBytes[i] = (byte)bytes[i];
            }
            // Assuming UTF-8 encoding for LDAP string representation.
            return Encoding.UTF8.GetString(unsignedBytes);
        }
    }

