namespace Omu.ValueInjecter
{
    public class FlatLoopValueInjection : LoopValueInjectionBase
    {
        protected override void Inject(object source, object target)
        {
            foreach (PropertyDescriptor t in target.GetProps())
            {
                var t1 = t;
                var es = UberFlatter.Flat(t.Name, source, type => TypesMatch(type, t1.PropertyType));

                if (es.Count() == 0) continue;
                var endpoint = es.First();
                if(endpoint == null) continue;
                var val = endpoint.Property.GetValue(endpoint.Component);

                if (AllowSetValue(val))
                    t.SetValue(target, SetValue(val));
            }
        }

        protected virtual bool TypesMatch(Type sourceType, Type targetType)
        {
            return targetType == sourceType;
        }

        protected virtual object SetValue(object sourcePropertyValue)
        {
            return sourcePropertyValue;
        }
    }

    public abstract class FlatLoopValueInjection<TSourceProperty, TTargetProperty> : LoopValueInjectionBase
    {
        protected override void Inject(object source, object target)
        {
            foreach (PropertyDescriptor t in target.GetProps())
            {
                if (t.PropertyType != typeof(TTargetProperty)) continue;

                var values = UberFlatter.Flat(t.Name, source, type => type == typeof(TSourceProperty));

                if (values.Count() == 0) continue;

                var val = values.First().Property.GetValue(values.First().Component);

                if (AllowSetValue(val))
                    t.SetValue(target, SetValue((TSourceProperty)val));
            }
        }

        protected abstract TTargetProperty SetValue(TSourceProperty sourceValues);

    }
}

using System;
using System.Reflection;

public abstract class DynamicFieldMapping
{
    public abstract object Map(object sourceValue, Type targetType);
}

public class DynamicPrimitiveFieldMapping : DynamicFieldMapping
{
    public override object Map(object sourceValue, Type targetType)
    {
        if (sourceValue == null)
            return null;

        try
        {
            if (targetType.IsEnum)
            {
                return Enum.Parse(targetType, sourceValue.ToString(), true);
            }

            if (targetType.IsGenericType && targetType.GetGenericTypeDefinition() == typeof(Nullable<>))
            {
                var underlyingType = Nullable.GetUnderlyingType(targetType);
                return Convert.ChangeType(sourceValue, underlyingType);
            }

            return Convert.ChangeType(sourceValue, targetType);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException($"Cannot map value {sourceValue} to type {targetType}", ex);
        }
    }
}

public class DynamicEnumFieldMapping : DynamicFieldMapping
{
    public override object Map(object sourceValue, Type targetType)
    {
        if (sourceValue == null)
            return null;

        try
        {
            if (!targetType.IsEnum)
                throw new ArgumentException("Target type must be an enum");

            if (sourceValue is string stringValue)
            {
                return Enum.Parse(targetType, stringValue, true);
            }

            return Enum.ToObject(targetType, sourceValue);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException($"Cannot map enum value {sourceValue} to type {targetType}", ex);
        }
    }
}

public class DynamicCustomMapping : DynamicFieldMapping
{
    private readonly Func<object, Type, object> _customMapper;

    public DynamicCustomMapping(Func<object, Type, object> customMapper)
    {
        _customMapper = customMapper ?? throw new ArgumentNullException(nameof(customMapper));
    }

    public override object Map(object sourceValue, Type targetType)
    {
        return _customMapper(sourceValue, targetType);
    }
}

public static class DynamicFieldMappingFactory
{
    public static DynamicFieldMapping CreateDynamicFieldMapping(PropertyInfo propertyInfo)
    {
        var targetType = propertyInfo.PropertyType;
        var typeInfo = targetType.GetTypeInfo();

        if (typeInfo.IsEnum)
        {
            return new DynamicEnumFieldMapping();
        }

public abstract class BaseIntentHandler<TContext, TRequest, TResponse>
    where TContext : class
    where TRequest : class
    where TResponse : class
{
    protected readonly ILogger<BaseIntentHandler<TContext, TRequest, TResponse>> _logger;
    protected readonly CancellationTokenSource _cancellationTokenSource;

    public enum IntentType
    {
        Create,
        Update,
        Delete,
        Resume,
        Patch
    }

    public enum LockType
    {
        Exclusive,
        Shared,
        None
    }

    public struct Requirement
    {
        public bool IsRequired { get; set; }
        public string ValidationRule { get; set; }
        public object ExpectedValue { get; set; }
    }

    protected BaseIntentHandler(ILogger<BaseIntentHandler<TContext, TRequest, TResponse>> logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cancellationTokenSource = new CancellationTokenSource();
    }

    public virtual async Task<TResponse> InvokeAsync(
        TContext context,
        TRequest request,
        IntentType intentType,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var validationResult = await ValidateAsync(context, request, intentType, cancellationToken);

            if (!validationResult.IsValid)
            {
                return HandleInvalidRequest(validationResult);
            }

            return await ProcessIntentAsync(context, request, intentType, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing upload intent");
            return HandleErrorResponse(ex);
        }
        finally
        {
            _cancellationTokenSource.Cancel();
        }
    }

    protected abstract Task<ValidationResult> ValidateAsync(
        TContext context,
        TRequest request,
        IntentType intentType,
        CancellationToken cancellationToken);

    protected abstract Task<TResponse> ProcessIntentAsync(
        TContext context,
        TRequest request,
        IntentType intentType,
        CancellationToken cancellationToken);

    protected virtual TResponse HandleInvalidRequest(ValidationResult validationResult)
    {
        _logger.LogWarning("Invalid request: {ValidationErrors}", validationResult.Errors);
        return CreateErrorResponse(HttpStatusCode.BadRequest, validationResult.Errors);
    }

    protected virtual TResponse HandleErrorResponse(Exception exception)
    {

