using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using Pomelo.EntityFrameworkCore.MySql.Infrastructure;

public class Account : IdentityUser { }

public class DefaultDbContext : IdentityDbContext<Account>
{
    public static readonly string ConnectionString = "server=localhost;user=root;password=;database=appdb;";
    private static DefaultDbContext _instance;

    public static DefaultDbContext Instance => _instance ??= new DefaultDbContext();

    private DefaultDbContext() : base() { }

    public DbSet<Ban> Ban { get; set; }
    public DbSet<Character> Character { get; set; }
    public DbSet<Group> Group { get; set; }
    public DbSet<GroupMember> GroupMember { get; set; }
    public DbSet<Property> Property { get; set; }
    public DbSet<Job> Job { get; set; }
    public DbSet<Vehicle> Vehicle { get; set; }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseMySql(ConnectionString,
            ServerVersion.AutoDetect(ConnectionString),
            mySqlOptions => mySqlOptions.SchemaBehavior(MySqlSchemaBehavior.Ignore));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<Ban>(entity =>
        {
            entity.HasOne(b => b.Target)
                .WithMany(u => u.Bans)
                .HasForeignKey(b => b.TargetId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Character>(entity =>
        {
            entity.HasOne(c => c.Account)
                .WithMany(u => u.Characters)
                .HasForeignKey(c => c.AccountId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Group>(entity =>
        {
            entity.HasOne(g => g.Owner)
                .WithMany()
                .HasForeignKey(g => g.OwnerId)
                .OnDelete(DeleteBehavior.Restrict);
        });

        modelBuilder.Entity<GroupMember>(entity =>
        {
            entity.HasOne(gm => gm.Group)
                .WithMany(g => g.Members)
                .HasForeignKey(gm => gm.GroupId);

            entity.HasOne(gm => gm.Member)
                .WithMany()
                .HasForeignKey(gm => gm.MemberId);
        });
    }
}

