        [Fact]
        public async Task TestFormatDocumentAsync()
        {
            string markup = @"
                class Tree {
                    static void Main(string[] args) {
                        Console.WriteLine(""Hello World!"");
                    }
                }";
            string expected = @"
class Tree
{
    static void Main(string[] args)
    {
        Console.WriteLine(""Hello World!"");
    }
}";

            var workspace = CreateTestWorkspace(markup);
            var documentURI = workspace.GetDocumentUri("Test.cs");
            var documentText = workspace.CurrentSolution.GetDocument(documentURI).GetTextAsync().Result.ToString();

            var results = await RunFormatDocumentAsync(workspace, documentURI);

            var actualText = ApplyTextEdits(documentText, results);
            Assert.Equal(expected, actualText);
