namespace OOPDemo
{
    public class PublicClass
    {
        public void PublicMethod() => Console.WriteLine("Public method called");
        private void PrivateMethod() => Console.WriteLine("Private method blocked");
    }

    internal class InternalClass
    {
        protected void ProtectedMethod() => Console.WriteLine("Protected method invoked");
    }

    public class InternalClassChild : InternalClass
    {
        public void InvokeParentProtectedMehtod() => ProtectedMethod();
    }

    public abstract class AbstractClass
    {
        public abstract void AbtractMethod();
        public virtual void VirtualMethod() => Console.WriteLine("Base virtual method");
    }

    public class ImplementingClass : AbstractClass
    {
        public override void AbtractMethod() => Console.WriteLine("Abstract method implemented");
        public override void VirtualMethod() => Console.WriteLine("Overridden virtual method");
    }

    public static class StaticClass
    {
        static StaticClass() => Console.WriteLine("Static initializer");
        public static void StaticMethod() => Console.WriteLine("Static method called");
    }

    public sealed class SealedClass
    {
        public void SealedMethod() => Console.WriteLine("Sealed class method");
    }

    class Writer
    {
