using System;
using OpenRA.Network;
using OpenRA.Widgets;

namespace OpenRA.Mods.Common.Widgets.Logic
{
    public class GameTimerLogic
    {
        [ObjectCreator.UseCtor]
        public GameTimerLogic(Widget widget, OrderManager orderManager, World world)
        {
            var timer = widget.GetOrNull<LabelWidget>("GAME_TIMER");
            var status = widget.GetOrNull<LabelWidget>("GAME_TIMER_STATUS");
            var startTick = Ui.LastTickTime;

            Func<bool> shouldShowStatus = () => (world.Paused || world.Timestep != Game.Timestep)
                && (Ui.LastTickTime - startTick) / 1000 % 2 == 0;

            Func<string> statusText = () =>
            {
                if (world.Paused || world.Timestep == 0)
                    return "Paused";

                if (world.Timestep == 1)
                    return "Max Speed";

                return "{0}% Speed".F(Game.Timestep * 100 / world.Timestep);
            };

            if (timer != null)
            {
                timer.GetText = () =>
                {
                    if (status == null && shouldShowStatus())
                        return statusText();

                    return WidgetUtils.FormatTime(world.WorldTick);
                };
            }

            if (status != null)
            {
                // Blink the status line
                status.IsVisible = shouldShowStatus;
                status.GetText = statusText;
            }

            var percentage = widget.GetOrNull<LabelWidget>("GAME_TIMER_PERCENTAGE");
            if (percentage != null)
            {
                var connection = orderManager.Connection as ReplayConnection;
                if (connection != null && connection.TickCount != 0)
                    percentage.GetText = () => "({0}%)".F(orderManager.NetFrameNumber * 100 / connection.TickCount);
                else
                    timer.Bounds.Width += percentage.Bounds.Width;
            }
        }
    }
}

public class FlatLoopValueInjection<TSource, TTarget>
    where TSource : class
    where TTarget : class, new()
{
    private readonly TSource _source;
    private readonly IEnumerable<string> _excludedProperties;
    private readonly Func<string, string, bool> _propertyMatchStrategy;

    public FlatLoopValueInjection(
        TSource source,
        IEnumerable<string> excludedProperties = null,
        Func<string, string, bool> propertyMatchStrategy = null)
    {
        _source = source;
        _excludedProperties = excludedProperties ?? Enumerable.Empty<string>();
        _propertyMatchStrategy = propertyMatchStrategy ?? DefaultPropertyMatchStrategy;
    }

    public TTarget Inject()
    {
        var target = new TTarget();
        var sourceProperties = TypeDescriptor.GetProperties(_source);
        var targetProperties = TypeDescriptor.GetProperties(target);

        foreach (PropertyDescriptor targetProperty in targetProperties)
        {
            if (ShouldSkipProperty(targetProperty.Name))
                continue;

            var matchingSourceProperty = FindMatchingSourceProperty(
                targetProperty,
                sourceProperties);

            if (matchingSourceProperty != null &&
                TypesMatch(matchingSourceProperty.PropertyType, targetProperty.PropertyType))
            {
                var sourceValue = matchingSourceProperty.GetValue(_source);

                if (AllowSetValue(sourceValue, targetProperty.PropertyType))
                {
                    SetValue(target, targetProperty, sourceValue);
                }
            }
        }

        return target;
    }

    private bool ShouldSkipProperty(string propertyName)
    {
        return _excludedProperties.Contains(propertyName);
    }

    private PropertyDescriptor FindMatchingSourceProperty(
        PropertyDescriptor targetProperty,
        PropertyDescriptorCollection sourceProperties)
    {
        return sourceProperties
            .Cast<PropertyDescriptor>()
            .FirstOrDefault(sp => _propertyMatchStrategy(sp.Name, targetProperty.Name));
    }

    private bool DefaultPropertyMatchStrategy(string sourceName, string targetName)
    {
        return sourceName.Equals(targetName, StringComparison.OrdinalIgnoreCase);
    }

    private bool TypesMatch(Type sourceType, Type targetType)
    {
        return targetType.IsAssignableFrom(sourceType) ||
               (targetType.IsGenericType && sourceType.IsGenericType &&
                targetType.GetGenericTypeDefinition() == sourceType.GetGenericTypeDefinition());
    }

