namespace Sorting
{
    class Builder
    {
        static void Main(string[] args)
        {
            var strings = new[] { "Here", "are", "some", "sample", "strings", "to", "be", "sorted" };
 
            void PrintArray(string message, string[] array)
            {
                Console.Write($"{message} [");
                for (var index = 0; index < array.Length; index++)
                {
                    var string = array[index];
                    Console.Write(index == array.Length - 1? string : $"{string}, ");
                }
                Console.WriteLine("]");
            }
 
            PrintArray("Unsorted:", strings);
 
            Array.Sort(strings, (first, second) =>
            {
                var lengthDifference = second.Length - first.Length;
                return lengthDifference == 0? string.Compare(first, second, true) : lengthDifference;
            });
 
            PrintArray("Sorted:", strings);
        }
    }
}

