namespace GnomeSort
{
    class Counter
    {
        static void Main(string[] args)
        {
            int[] a = { 3, 4, 2, 5, 1, 6 };
            int i = 1, j = 2, size = a.Length;
            while (i < size)
            {
                if (a[i - 1] <= a[i])
                {
                    i = j;
                    j++;
                }
                else
                {
                    int temp = a[i - 1];
                    a[i - 1] = a[i];
                    a[i] = temp;
                    i--;
                    if (i == 0)
                    {
                        i = j;
                        j++;
                    }
                }
            }
            foreach (int x in a)
            {
                Console.Write(x + " ");
            }
            Console.ReadKey();
        }
    }
}

