using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;
using static System.Math;
using static System.Convert;
using static System.Environment;

public class MianChowla
{
    public static void Main()
    {
        var genMianChowla = MianChowlas();
        WriteLine(
            "Mian-Chowla terms 1-30:" + NewLine +
            string.Join(", ", Take(30, genMianChowla)) + NewLine +
            NewLine +
            "Mian-Chowla terms 91-100:" + NewLine +
            string.Join(", ", Take(10, Drop(60, genMianChowla)))
        );
    }

    // mianChowlas :: Gen [Int]
    public static IEnumerable<int> MianChowlas()
    {
        var mcs = new List<int> { 1 };
        var sumSet = new HashSet<int> { 2 };
        var x = 1;
        while (true)
        {
            yield return x;
            (sumSet, mcs, x) = NextMC(sumSet, mcs, x);
        }
    }

    // nextMC :: Set Int -> [Int] -> Int -> (Set Int, [Int], Int)
    public static (HashSet<int> sumSet, List<int> mcs, int x) NextMC(HashSet<int> setSums, List<int> mcs, int n)
    {
        // Set of sums -> Series up to n -> Next term in series
        Func<int, bool> valid = x =>
        {
            foreach (var m in mcs)
            {
                if (setSums.Contains(x + m)) return false;
            }
            return true;
        };
        var x = Until(valid, x => 1 + x, n);
        return (
            SumList(mcs, x)
           .Aggregate(
                setSums,
                (a, n) => { a.Add(n); return a; }
            ),
            mcs.Concat(new List<int> { x }).ToList(),
            x
        );
    }

    // sumList :: [Int] -> Int -> [Int]
    public static IEnumerable<int> SumList(List<int> xs, int n)
    {
        // Series so far -> additional term -> new sums
        return new List<int> { 2 * n }.Concat(xs.Select(x => n + x));
    }

    // drop :: Int -> [a] -> [a]
    public static IEnumerable<T> Drop<T>(int n, IEnumerable<T> xs)
    {
        return xs.Skip(n);
    }

    // take :: Int -> [a] -> [a]
    public static IEnumerable<T> Take<T>(int n, IEnumerable<T> xs)
    {
        return xs.Take(n);
    }

    // until :: (a -> Bool) -> (a -> a) -> a -> a
    public static T Until<T>(Func<T, bool> p, Func<T, T> f, T x)
    {
        var v = x;
        while (!p(v)) v = f(v);
        return v;
    }
}

