namespace ConnectionProviderTests
{
    // Mock connection provider for testing configuration behavior.
    public class MockConnectionProvider : DriverConnectionProvider
    {
        // Expose the resolved connection string for assertions.
        public string ResolvedConnectionString { get; private set; }

        // Simulated configuration source for named connection strings.
        private static readonly Dictionary<string, string> NamedConnectionStrings =
            new Dictionary<string, string>
            {
                { "ValidName", "Data Source=ValidServer;Initial Catalog=ValidDB;" }
            };

        // Override Configure to set up connection strings based on provided settings.
        public override void Configure(IDictionary<string, string> settings)
        {
            // Check if an explicit connection string is provided.
            if (settings.ContainsKey(Environment.ConnectionString))
            {
                ResolvedConnectionString = settings[Environment.ConnectionString];
            }
            // Otherwise, check if a named connection string is specified.
            else if (settings.ContainsKey(Environment.ConnectionStringName))
            {
                string name = settings[Environment.ConnectionStringName];
                if (NamedConnectionStrings.ContainsKey(name))
                {
                    ResolvedConnectionString = NamedConnectionStrings[name];
                }
                else
                {
                    // Throw an exception if the named connection string does not exist.
                    throw new Exception("No connection string named '" + name + "' found.");
                }
            }
            else
            {
                // No connection string configuration provided.
                throw new Exception("No connection string configuration provided.");
            }

            // Call base configuration if necessary.
            base.Configure(settings);
        }
    }

