using System;
 
public class Utils
{
    public static void Main()
    {
        for (int arity = 2; arity <= 10; arity++)
            Console.WriteLine("fib(" + arity + "): " + fib(arity, 15));
        for (int arity = 2; arity <= 10; arity++)
            Console.WriteLine("lucas(" + arity + "): " + lucas(arity, 15));
    }
 
    public static int[] fib(int arity, int len)
    {
        return nacci(nacci(new int[] { 1, 1 }, arity, arity), arity, len);
    }
 
    public static int[] lucas(int arity, int len)
    {
        return nacci(nacci(new int[] { 2, 1 }, arity, arity), arity, len);
    }
 
    public static int[] nacci(int[] a, int arity, int len)
    {
        while (a.Length < len)
        {
            int sum = 0;
            for (int i = Math.Max(0, a.Length - arity); i < a.Length; i++)
                sum += a[i];
            Array.Resize(ref a, a.Length + 1);
            a[a.Length - 1] = sum;
        }
        return a;
    }
}

