[Export(typeof(IOrganizeImportsService))]
public class XamlOrganizeImportsService : IOrganizeImportsService
{
    private readonly IXamlOrganizeNamespacesService _namespaceService;

    public XamlOrganizeImportsService(IXamlOrganizeNamespacesService namespaceService)
    {
        _namespaceService = namespaceService ?? throw new ArgumentNullException(nameof(namespaceService));
    }

    public async Task<string> OrganizeImportsAsync(string xamlContent, OrganizeImportsOptions options)
    {
        try
        {
            var xamlDocument = await ParseXamlAsync(xamlContent);
            var organizedNamespaces = _namespaceService.OrganizeNamespaces(xamlDocument, options);

            return FormatDocument(organizedNamespaces);
        }
        catch (Exception ex)
        {
            // Handle exceptions appropriately
            Console.WriteLine($"Error: {ex.Message}");
            return xamlContent;
        }
    }

    private async Task<XamlDocument> ParseXamlAsync(string xamlContent)
    {
        // Simulate asynchronous parsing
        return await Task.Run(() => XamlDocument.Parse(xamlContent));
    }

    private string FormatDocument(IEnumerable<string> organizedNamespaces)
    {
        // Combine the organized namespaces and format the XAML
        return string.Join(Environment.NewLine, organizedNamespaces);
    }

    public string GetSortDisplayString() => "Sort Namespaces";

    public string GetRemoveUnusedDisplayString() => "Remove Unused Namespaces";

    public string GetOrganizeDisplayString() => "Organize Namespaces for XAML";
}

