namespace Utilities.Core.DateTime
{
    /// <summary>
    /// Provides extension methods for DateTime operations.
    /// </summary>
    public static class DateTimeExtensions
    {
        /// <summary>
        /// Returns the first day of the week for the specified date.
        /// By default, the first day is considered Monday.
        /// </summary>
        /// <param name="date">The date from which to calculate the week's start.</param>
        /// <param name="firstDayOfWeek">The day considered as the start of the week. Defaults to Monday.</param>
        /// <returns>A DateTime representing the first day of the week.</returns>
        public static DateTime FirstDayOfWeek(this DateTime date, DayOfWeek firstDayOfWeek = DayOfWeek.Monday)
        {
            // Continue subtracting one day until we reach the configured first day of the week.
            while (date.DayOfWeek != firstDayOfWeek)
            {
                date = date.AddDays(-1);
            }
            return date;
        }
    }
}

