// Assuming a functional programming library provides these types and methods
public static class OptionExtensions
{
    public static Option<T> ToOption<T>(this T value) => new Option<T>(value);
    public static bool IsEmpty<T>(this Option<T> option) => !option.HasValue;
    public static bool NonEmpty<T>(this Option<T> option) => option.HasValue;
    public static T Get<T>(this Option<T> option) => option.Value;
    public static T GetOrElse<T>(this Option<T> option, T defaultValue) => option.HasValue ? option.Value : defaultValue;
    public static Option<T> OrElse<T>(this Option<T> option, Option<T> alternative) => option.HasValue ? option : alternative;
    public static Option<U> Map<T, U>(this Option<T> option, Func<T, U> mapper) => option.HasValue ? mapper(option.Value).ToOption() : Option<U>.None;
    public static Option<U> FlatMap<T, U>(this Option<T> option, Func<T, Option<U>> mapper) => option.HasValue ? mapper(option.Value) : Option<U>.None;
    public static U Match<T, U>(this Option<T> option, Func<T, U> some, Func<U> none) => option.HasValue ? some(option.Value) : none();
    public static IEnumerable<T> ToEnumerable<T>(this Option<T> option) => option.HasValue ? new[] { option.Value } : Enumerable.Empty<T>();
}

public struct Option<T>
{
    private readonly T _value;
    public bool HasValue { get; }

    private Option(T value)
    {
        _value = value;
        HasValue = true;
    }

    public static Option<T> None => new Option<T>();

    public T Value
    {
        get
        {
            if (!HasValue) throw new InvalidOperationException("Option has no value.");
            return _value;
        }
    }
}

