namespace ShipsServer.Models
{
    public class Battle
    {
        public int Id { get; set; }
        public BattleStatus Status { get; private set; }
        private List<Player> _players;

        public Battle(int id)
        {
            Id = id;
            Status = BattleStatus.Waiting;
            _players = new List<Player>();
        }

        public bool AddPlayer(Player player)
        {
            if (_players.Count >= Constants.MAX_BATTLE_PLAYERS)
            {
                return false;
            }
            _players.Add(player);
            if (_players.Count == Constants.MAX_BATTLE_PLAYERS)
            {
                Status = BattleStatus.InProgress;
            }
            return true;
        }

        public Player GetPlayer(int index)
        {
            if (index < 0 || index >= _players.Count)
            {
                return null;
            }
            return _players[index];
        }

        public Player GetPlayerBySession(Session session)
        {
            return _players.FirstOrDefault(p => p.Session.Id == session.Id);
        }

        public Player GetOponentPlayer(Player player)
        {
            return _players.FirstOrDefault(p => p.Id != player.Id);
        }

        public void Finish(Player winner, Player loser)
        {
            if (Status != BattleStatus.InProgress)
            {
                throw new InvalidOperationException("Battle is not in progress.");
            }

            winner.BattleStatistics.Wins++;
            winner.BattleStatistics.LastBattleTimestamp = Time.UnixTimeNow();
            loser.BattleStatistics.Losses++;
            loser.BattleStatistics.LastBattleTimestamp = Time.UnixTimeNow();

            Status = BattleStatus.Finished;
        }
    }

