public class BillingExample : MonoBehaviour
{
    public EnabledButton initButton;
    public EnabledButton[] initBoundButtons;

    private bool isInited = false;
    private GPaymnetManagerExample paymentManager;

    private const string ANDROID_TEST_PURCHASED = "android.test.purchased";
    private const string ANDROID_TEST_ITEM_UNAVAILABLE = "android.test.item_unavailable";

    void Start()
    {
        paymentManager = GPaymnetManagerExample.Client;
        UpdateButtonStates();
    }

    void Update()
    {
        if (paymentManager.IsConnectionInProgress)
            UpdateButtonStates();
    }

    public void Init()
    {
        paymentManager.Connect();
    }

    public void SuccsesPurchase()
    {
        if (!isInited)
        {
            ShowError("System not initialized");
            return;
        }
        paymentManager.PurchaseProduct(ANDROID_TEST_PURCHASED, true);
    }

    public void FailPurchase()
    {
        if (!isInited)
        {
            ShowError("System not initialized");
            return;
        }
        paymentManager.PurchaseProduct(ANDROID_TEST_ITEM_UNAVAILABLE, false);
    }

    public void ConsumeProduct()
    {
        if (!paymentManager.VerifyInventory(ANDROID_TEST_PURCHASED))
        {
            ShowError("Product not owned");
            return;
        }
        paymentManager.ConsumePurchase(ANDROID_TEST_PURCHASED);
    }

    private void UpdateButtonStates()
    {
        isInited = paymentManager.IsServiceConnected;

        initButton.SetState(!isInited);
        foreach (var btn in initBoundButtons)
        {
            btn.SetState(isInited);
        }
    }

    private void ShowError(string message)
    {
        Debug.LogError($"BILLING ERROR: {message}");
        // Implementation would show UI error message
    }
}

