using System.IO;
using System.Collections.Generic;

public class SqlAnywhereBatchParserTests
{
    [Test]
    public void TestSingleLineCommentWithoutGo()
    {
        string sql = "-- This is a comment\nSELECT * FROM Table1;";
        List<string> statements = ParseSql(sql);

        Assert.AreEqual(1, statements.Count);
        Assert.AreEqual("SELECT * FROM Table1;", statements[0].Trim());
    }

    [Test]
    public void TestTwoStatementsWithoutGo()
    {
        string sql = "SELECT * FROM Table1;\nSELECT * FROM Table2;";
        List<string> statements = ParseSql(sql);

        Assert.AreEqual(2, statements.Count);
        Assert.AreEqual("SELECT * FROM Table1;", statements[0].Trim());
        Assert.AreEqual("SELECT * FROM Table2;", statements[1].Trim());
    }

    [Test]
    public void TestSingleLineCommentAndTwoStatementsWithoutGo()
    {
        string sql = "-- This is a comment\nSELECT * FROM Table1;\nSELECT * FROM Table2;";
        List<string> statements = ParseSql(sql);

        Assert.AreEqual(2, statements.Count);
        Assert.AreEqual("SELECT * FROM Table1;", statements[0].Trim());
        Assert.AreEqual("SELECT * FROM Table2;", statements[1].Trim());
    }

    private List<string> ParseSql(string sql)
    {
        List<string> statements = new List<string>();
        StringReader reader = new StringReader(sql);
        TextReaderSource source = new TextReaderSource(reader);
        SqlAnywhereBatchParser parser = new SqlAnywhereBatchParser();

        parser.SqlText += (sender, e) =>
        {
            statements.Add(e.SqlText);
        };

        parser.Process(source);

        return statements;
    }

    private class TextReaderSource : ISource
    {
        private readonly TextReader _reader;

        public TextReaderSource(TextReader reader)
        {
            _reader = reader;
        }

        public int Read()
        {
            return _reader.Read();
        }
    }
}

