namespace CustomDictionaryFramework
{
    public interface IDictionaryBase : ICollection
    {
        // Indexer for direct key-based access
        object this[object key] { get; set; }

        // Collection property for keys
        ICollection Keys { get; }

        // Collection property for values
        ICollection Values { get; }

        // Method to check if dictionary contains specific key
        bool Contains(object key);

        // Method to add key-value pair
        void Add(object key, object value);

        // Method to remove specific key-value pair
        void Remove(object key);

        // Method to clear entire dictionary
        void Clear();

        // Indicates whether dictionary is read-only
        bool IsReadOnly { get; }

        // Indicates whether dictionary has fixed size
        bool IsFixedSize { get; }
    }

    // Generic implementation of dictionary interface
    public class CustomDictionary : IDictionaryBase
    {
        private Hashtable _internalStorage;

        // Constructor
        public CustomDictionary()
        {
            _internalStorage = new Hashtable();
        }

        // Indexer implementation
        public object this[object key]
        {
            get => _internalStorage[key];
            set => _internalStorage[key] = value;
        }

        // Keys collection
        public ICollection Keys => _internalStorage.Keys;

        // Values collection
        public ICollection Values => _internalStorage.Values;

        // Synchronization root
        public object SyncRoot => _internalStorage.SyncRoot;

        // Thread-safety indicator
        public bool IsSynchronized => _internalStorage.IsSynchronized;

        // Read-only flag
        public bool IsReadOnly => false;

        // Fixed size flag
        public bool IsFixedSize => false;

        // Total count of elements
        public int Count => _internalStorage.Count;

        // Method to check key existence
        public bool Contains(object key) => _internalStorage.Contains(key);

        // Method to add key-value pair
        public void Add(object key, object value) => _internalStorage.Add(key, value);

        // Method to remove specific key
        public void Remove(object key) => _internalStorage.Remove(key);

        // Method to clear dictionary
        public void Clear() => _internalStorage.Clear();

        // Enumeration support
        public IEnumerator GetEnumerator() => _internalStorage.GetEnumerator();

using System;
using System.Collections.Generic;
