namespace Palindromes
{
    class Order
    {
        static void Main(string[] args)
        {
            // read file into memory as one big block
            var data = File.ReadAllText("unixdict.txt");
            // copy the block, split it up into words
            var words = data.Split(new[] { "\n" }, StringSplitOptions.None);
            // optional, free the first block for garbage collection
            data = null;
            // put words in a map, also determine length of longest word
            var m = new Dictionary<string, bool>();
            var longest = 0;
            foreach (var w in words)
            {
                m[w] = true;
                if (w.Length > longest)
                {
                    longest = w.Length;
                }
            }
            // allocate a buffer for reversing words
            var r = new byte[longest];
            // iterate over word list
            var sem = 0;
            var five = new List<string>();
            foreach (var w in words)
            {
                // first, delete from map.  this prevents a palindrome from matching
                // itself, and also prevents it's reversal from matching later.
                m.Remove(w);
                // use buffer to reverse word
                var last = w.Length - 1;
                for (var i = 0; i < w.Length; i++)
                {
                    r[i] = w[last - i];
                }
                var rs = Encoding.ASCII.GetString(r, 0, w.Length);
                // see if reversed word is in map, accumulate results
                if (m.ContainsKey(rs))
                {
                    sem++;
                    if (five.Count < 5)
                    {
                        five.Add(w + "/" + rs);
                    }
                }
            }
            // print results
            Console.WriteLine(sem + " pairs");
            Console.WriteLine("examples:");
            foreach (var e in five)
            {
                Console.WriteLine("  " + e);
            }
        }
    }
}

