    private bool statusBlinkState;
    private const int BlinkInterval = 500; // Milliseconds

    public GameTimerLogic(LabelWidget timeLabel, LabelWidget statusLabel,
                           OrderManager orderManager, World world)
    {
        this.timeLabel = timeLabel;
        this.statusLabel = statusLabel;
        this.orderManager = orderManager;
        this.world = world;
        this.replayConnection = world.GameContext.ReplayConnection;

        lastUpdateTime = Environment.TickCount;
        statusBlinkState = false;
    }

    public void Update()
    {
        int currentTime = Environment.TickCount;
        UpdateTimerDisplay(currentTime);
        UpdateStatusDisplay(currentTime);
    }

    private void UpdateTimerDisplay(int currentTime)
    {
        string formattedTime = FormatTime(world.GameTime);
        timeLabel.Text = formattedTime;

        if (replayConnection != null)
        {
            double replayProgress = CalculateReplayProgress();
            timeLabel.Text += $" ({replayProgress:P0})";
        }
    }

    private void UpdateStatusDisplay(int currentTime)
    {
        if (currentTime - lastUpdateTime >= BlinkInterval)
        {
            statusBlinkState = !statusBlinkState;
            lastUpdateTime = currentTime;
        }

        if (ShouldShowStatus())
        {
            string status = GetStatusText();
            statusLabel.Text = statusBlinkState ? status : string.Empty;
        }
        else
        {
            statusLabel.Text = string.Empty;
        }
    }

    private string FormatTime(int gameTime)
    {
        int minutes = gameTime / (60 * 24);
        int seconds = (gameTime % (60 * 24)) / 24;
        return $"{minutes:D2}:{seconds:D2}";
    }

    private bool ShouldShowStatus()
    {
        return world.IsPaused ||
               orderManager.GameSpeed != 1 ||
               replayConnection != null;
    }

    private string GetStatusText()
    {
        if (world.IsPaused)
            return "PAUSED";

        if (replayConnection != null)
            return $"REPLAY ({orderManager.GameSpeed}x)";

        return $"{orderManager.GameSpeed}x";
    }

