        private readonly LabelWidget timer;
        private readonly LabelWidget status;
        private readonly LabelWidget percentage;
        private readonly World world;
        private readonly OrderManager orderManager;
        private readonly Widget widget;
        private readonly double blinkInterval;
        private DateTime lastBlinkTime;
        private bool blinkStatus;

        public GameTimerLogic(Widget widget, World world, OrderManager orderManager)
        {
            this.widget = widget;
            this.world = world;
            this.orderManager = orderManager;
            timer = widget.GetWidget<LabelWidget>("timer");
            status = widget.GetWidget<LabelWidget>("status");
            percentage = widget.GetWidget<LabelWidget>("percentage");
            blinkInterval = 0.5; // seconds
            lastBlinkTime = DateTime.Now;

            timer.GetText = () => FormatTime(world.CurrentTick);

            status.GetText = () =>
            {
                UpdateBlink();
                if (world.IsPaused)
                    return blinkStatus ? "Paused" : "";
                if (world.SimulationSpeed >= 2.0)
                    return blinkStatus ? "Max Speed" : "";
                if (world.SimulationSpeed > 1.0)
                    return string.Format("{0}%", (int)(world.SimulationSpeed * 100));
                return "";
            };

            percentage.GetText = () =>
            {
                if (orderManager != null && orderManager.IsReplay)
                {
                    double percent = CalculateReplayPercentage(orderManager);
                    return string.Format("{0:0}%", percent);
                }
                return "";
            };
        }

        private void UpdateBlink()
        {
            DateTime now = DateTime.Now;
            if ((now - lastBlinkTime).TotalSeconds >= blinkInterval)
            {
                blinkStatus = !blinkStatus;
                lastBlinkTime = now;
            }
        }

        private string FormatTime(int tick)
        {
            // Convert game ticks to MM:SS (assuming 60 ticks per second)
            int totalSeconds = tick / 60;
            int minutes = totalSeconds / 60;
            int seconds = totalSeconds % 60;
            return string.Format("{0:00}:{1:00}", minutes, seconds);
