public class CommitsByDateAndAuthor : VisualizationBase
{
    private Dictionary<string, Dictionary<DateTime, int>> authorCommitCounts;
    private List<string> authors;
    private DateTime startDate;
    private DateTime endDate;

    public CommitsByDateAndAuthor(DateTime startDate, DateTime endDate)
    {
        authors = new List<string>();
        authorCommitCounts = new Dictionary<string, Dictionary<DateTime, int>>();
        this.startDate = startDate;
        this.endDate = endDate;
    }

    public void Init(Repository repository)
    {
        authors = repository.GetUniqueAuthors();
        foreach (string author in authors)
        {
            authorCommitCounts[author] = new Dictionary<DateTime, int>();
            for (DateTime date = startDate; date <= endDate; date = date.AddDays(1))
            {
                authorCommitCounts[author][date] = 0;
            }
        }
    }

    public void Calc(Repository repository)
    {
        foreach (string author in authors)
        {
            var commits = repository.GetCommitsByAuthor(author, startDate, endDate);
            foreach (var commit in commits)
            {
                DateTime commitDate = commit.Date.Date;
                if (authorCommitCounts[author].ContainsKey(commitDate))
                {
                    authorCommitCounts[author][commitDate]++;
                }
            }
        }
    }

    public void Draw()
    {
        foreach (var author in authorCommitCounts.Keys)
        {
            var dataPoints = authorCommitCounts[author]
                .Where(x => x.Value > 0)
                .Select(x => new { Date = x.Key, Commits = x.Value })
                .ToList();

            Graph graph = new Graph();
            graph.Title = $"Commits by {author} from {startDate.ToShortDateString()} to {endDate.ToShortDateString()}";
            graph.XAxisTitle = "Date";
            graph.YAxisTitle = "Number of Commits";

            foreach (var point in dataPoints)
            {
                graph.AddDataPoint(point.Date, point.Commits);
            }

            graph.Render();
        }
    }
}

