class LongestIncreasingSubsequence
{
    static void Main()
    {
        Console.WriteLine("Enter a sequence of integers (space-separated):");

        // Read input and convert to integer array
        int[] numberArray = Console.ReadLine()
            .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
            .Select(int.Parse)
            .ToArray();

        // Handle edge cases
        if (numberArray.Length == 0)
        {
            Console.WriteLine("No sequence provided.");
            return;
        }

        if (numberArray.Length == 1)
        {
            Console.WriteLine($"Longest increasing subsequence: {numberArray[0]}");
            return;
        }

        // Initialize tracking variables
        int startCurrentId = 0;
        int maxStartID = 0;
        int currentIncreasingSeqLength = 1;
        int maxIncreasingSeqLength = 1;

        // Iterate through array to find longest increasing subsequence
        for (int i = 1; i < numberArray.Length; i++)
        {
            if (numberArray[i] > numberArray[i - 1])
            {
                currentIncreasingSeqLength++;

                // Update longest sequence if current sequence is longer
                if (currentIncreasingSeqLength > maxIncreasingSeqLength)
                {
                    maxIncreasingSeqLength = currentIncreasingSeqLength;
                    maxStartID = startCurrentId;
                }
            }
            else
            {
                // Reset current sequence parameters
                startCurrentId = i;
                currentIncreasingSeqLength = 1;
            }
        }

        // Extract and print longest increasing subsequence
        int[] resultArray = numberArray
            .Skip(maxStartID)
            .Take(maxIncreasingSeqLength)
            .ToArray();

        Console.WriteLine($"Longest increasing subsequence: {string.Join(" ", resultArray)}");
        Console.WriteLine($"Subsequence length: {maxIncreasingSeqLength}");
    }
}

using System;
using System.Collections.Generic;
 
namespace PrimeDecomposition
{
    class Reader
    {
        static void Main(string[] args)
        {
            GetPrimes(12);
        }
 
        static List<int> GetPrimes(decimal n)
        {
            List<int> storage = new List<int>();
            while (n > 1)
            {
                int i = 1;
                while (true)
                {
                    if (IsPrime(i))
                    {
                        if (((decimal)n / i) == Math.Round((decimal) n / i))
                        {
                            n /= i;
                            storage.Add(i);
                            break;
                        }
                    }
                    i++;
                }
            }
            return storage;
        }
 
        static bool IsPrime(int n)
        {
            if (n <= 1) return false;
            for (int i = 2; i <= Math.Sqrt(n); i++)
                if (n % i == 0) return false;
            return true;
        }
    }
}

using UnityEngine;

public class SignDetector : MonoBehaviour
{
    public string whatItSays = "Default sign text.";
    public string helpText = "Press 'L' to interact";
    public Texture2D BoxTexture;
    public Font signFont;
    public KeyCode interactionKey = KeyCode.L;

    private bool isTextDisplaying = false;
    private bool showHelpText = false;
    private string signText = "";
    private GUIStyle boxStyle;
    private GUIStyle helpStyle;

    void Start()
    {
        InitializeStyles();
    }

    private void InitializeStyles()
    {
        boxStyle = new GUIStyle(GUI.skin.box);
        boxStyle.richText = true;
        boxStyle.font = signFont;
        boxStyle.normal.background = BoxTexture;
        boxStyle.alignment = TextAnchor.MiddleCenter;
        boxStyle.padding = new RectOffset(20, 20, 10, 10);
        boxStyle.wordWrap = true;

        helpStyle = new GUIStyle();
        helpStyle.fontSize = 14;
        helpStyle.normal.textColor = Color.yellow;

        if (BoxTexture == null)
            Debug.LogWarning("BoxTexture missing in SignDetector!");
        if (signFont == null)
            Debug.LogWarning("Sign font not assigned!");
    }

    void Update()
    {
        if (showHelpText && Input.GetKeyDown(interactionKey))
        {
            ToggleTextDisplay();
        }
    }

    private void ToggleTextDisplay()
    {
        if (isTextDisplaying)
            RemoveText();
        else
            DisplayText();
    }

    private void OnTriggerStay2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
            showHelpText = true;
    }

    private void OnTriggerExit2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
        {
            showHelpText = false;
            RemoveText();
        }
    }

    private void DisplayText()
    {
        signText = "<b><size=24>" + whatItSays + "</size></b>";
        isTextDisplaying = true;
    }

    private void RemoveText()
    {
        signText = "";
        isTextDisplaying = false;
    }

    void OnGUI()
    {
        if (showHelpText)
        {
            GUI.Label(new Rect(10, Screen.height - 40, 300, 40), helpText, helpStyle);
        }

        if (isTextDisplaying)
        {
            GUI.Box(new Rect(Screen.width/2 - 250, Screen.height/2 - 150, 500, 300), signText, boxStyle);
        }
    }
}

