using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
 
public class Semordnilap
{
    public static void Main()
    {
        try
        {
            Semordnilap("unixdict.txt");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.ToString());
        }
    }
 
    public static void Semordnilap(string filename)
    {
        var seen = new HashSet<string>();
        var count = 0;
        foreach (var line in File.ReadLines(filename))
        {
            var word = line.ToLower();
            var rev = new string(word.Reverse().ToArray());
            if (seen.Contains(rev))
            {
                if (count < 5)
                {
                    Console.WriteLine($"{word}\t{rev}");
                }
                count++;
            }
            else
            {
                seen.Add(word);
            }
        }
        Console.WriteLine($"\nSemordnilap pairs found: {count}");
    }
}

