namespace System.Collections
{
    public interface IDictionary : ICollection
    {
        // Indexer to access values by key
        object this[object key] { get; set; }

        // Collection of keys in the dictionary
        ICollection Keys { get; }

        // Collection of values in the dictionary
        ICollection Values { get; }

        // Indicates whether the dictionary is read-only
        bool IsReadOnly { get; }

        // Indicates whether the dictionary has a fixed size
        bool IsFixedSize { get; }

        // Adds a key-value pair to the dictionary
        void Add(object key, object value);

        // Checks if the dictionary contains a specific key
        bool Contains(object key);

        // Removes all key-value pairs from the dictionary
        void Clear();

        // Returns an enumerator that iterates through the dictionary
        IDictionaryEnumerator GetEnumerator();

        // Removes the key-value pair with the specified key
        void Remove(object key);
    }

    public interface IDictionaryEnumerator : IEnumerator
    {
        // Gets the key of the current dictionary entry
        object Key { get; }

        // Gets the value of the current dictionary entry
        object Value { get; }

        // Gets both the key and value of the current dictionary entry
        DictionaryEntry Entry { get; }
    }

    public struct DictionaryEntry
    {
        private object _key;
        private object _value;

        public DictionaryEntry(object key, object value)
        {
            _key = key;
            _value = value;
        }

        public object Key
        {
            get { return _key; }
            set { _key = value; }
        }

        public object Value
        {
            get { return _value; }
            set { _value = value; }
        }
    }
}

using System;

public class JsonStringContract : JsonPrimitiveContract
{
    public JsonStringContract(Type underlyingType) : base(underlyingType)
    {
        ContractType = JsonContractType.String;
    }

    public override bool IsString => true;

    public override object ReadJsonValue(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
    {
        if (reader.TokenType == JsonToken.Null)
        {
            return null;
        }

        if (reader.TokenType == JsonToken.String)
        {
            return reader.Value.ToString();
        }

        throw new JsonSerializationException($"Unexpected token type '{reader.TokenType}' when reading string.");
    }

    public override void WriteJsonValue(JsonWriter writer, object value, JsonSerializer serializer)
    {
        if (value == null)
        {
            writer.WriteNull();
        }
        else
        {
            writer.WriteValue(value.ToString());
        }
    }
}

