        private readonly int _value;
        private readonly int _originalIndex;

        // Constructor that accepts text, a numeric value, and an original index.
        public Key(string text, int value, int originalIndex)
        {
            if (text == null)
                throw new ArgumentNullException(nameof(text));
            _text = text;
            _value = value;
            _originalIndex = originalIndex;
        }

        // Returns the preserved original index.
        public int GetOriginalIndex()
        {
            return _originalIndex;
        }

        // Returns a concatenated textual representation of the key's contents.
        public override string ToString()
        {
            return string.Format("{0}:{1} (Index: {2})", _text, _value, _originalIndex);
        }

        // Implements comparison based on text (using ordinal comparison) and then numeric value.
        public int CompareTo(Key other)
        {
            if (other == null)
                return 1; // non-null is greater than null

            int textComparison = string.Compare(_text, other._text, StringComparison.Ordinal);
            if (textComparison != 0)
                return textComparison;

            return _value.CompareTo(other._value);
        }

        // Overloaded equality check comparing the instance against another Key instance.
        public bool Equals(Key other)
        {
            if (other == null)
                return false;
            return string.Equals(_text, other._text, StringComparison.Ordinal) &&
                   _value == other._value;
        }

        // Overrides Object.Equals to use the custom equality logic.
        public override bool Equals(object obj)
        {
            return Equals(obj as Key);
        }

        // Provides a hash function consistent with the Equals method.
        public override int GetHashCode()
        {
            unchecked
            {
                int hash = 17;
                hash = hash * 23 + _text.GetHashCode();
                hash = hash * 23 + _value.GetHashCode();
                return hash;
            }
        }

        // Overloaded equality check using separate text and numeric value parameters.

