using System;

class DiamondTrolls
{
    static void Main()
    {
        Console.WriteLine("Enter the size of the diamond (integer): ");
        int n;

        // Read and parse user input
        while (!int.TryParse(Console.ReadLine(), out n) || n < 3)
        {
            Console.WriteLine("Please enter a valid integer greater than or equal to 3.");
        }

        // Calculate dimensions of the diamond
        int width = 2 * n - 1;
        int heightTop = n - 1;
        int heightBottom = n - 1;

        // Print top part of the diamond
        for (int i = 0; i < heightTop; i++)
        {
            int topDots = heightTop - i;
            int stars = 2 * i + 1;

            Console.Write(new String('.', topDots));
            Console.Write(new String('*', stars));
            Console.WriteLine(new String('.', topDots));
        }

        // Print the middle solid line of the diamond
        Console.Write(new String('*', width));
        Console.WriteLine();

        // Print bottom part of the diamond
        for (int i = heightBottom - 1; i >= 0; i--)
        {
            int bottomDots = heightBottom - i;
            int stars = 2 * i + 1;

            Console.Write(new String('.', bottomDots));
            Console.Write(new String('*', stars));
            Console.WriteLine(new String('.', bottomDots));
        }
    }
}

using UnityEngine;

public class Cheat : MonoBehaviour
{
    public enum InventoryType { Ship, Base }

    public InventoryType inventoryType;
    private InventoryModel model;
    private InventoryController controller;

    void Start()
    {
        // Initialize the inventory model and controller
        model = FindObjectOfType<InventoryModel>();
        if (model == null)
        {
            Debug.LogError("InventoryModel not found!");
            return;
        }

        var controllers = FindObjectsOfType<InventoryController>();
        foreach (var c in controllers)
        {
            if ((inventoryType == InventoryType.Ship && c is ShipInventoryController) ||
                (inventoryType == InventoryType.Base && c is BaseInventoryController))
            {
                controller = c;
                break;
            }
        }

        if (controller == null)
        {
            Debug.LogError("InventoryController not found for the specified type!");
        }
    }

    public void AddItems()
    {
        if (controller == null)
        {
            Debug.LogError("InventoryController is not initialized!");
            return;
        }

        // Predefined set of items to add
        int[] itemIDs = { 101, 102, 103, 104, 105 };
        int[] quantities = { 5, 3, 2, 7, 1 };

        for (int i = 0; i < itemIDs.Length; i++)
        {
            controller.AddItem(itemIDs[i], quantities[i]);
            Debug.Log($"Added {quantities[i]} of item {itemIDs[i]} to {inventoryType} inventory.");
        }
    }

    void Update()
    {
        // Example: Press 'C' to trigger the cheat
        if (Input.GetKeyDown(KeyCode.C))
        {
            AddItems();
        }
    }
}

