[Desc("Manage audio notifications when an actor is captured")]
public class CaptureNotificationInfo : ITraitInfo
{
    [Desc("Sound notification when captured")]
    public string CapturedSound = string.Empty;

    [Desc("Sound notification for new owner")]
    public string NewOwnerSound = string.Empty;

    [Desc("Preferred voice faction")]
    public string VoiceFaction = "gdi";

    public object Create(ActorInitializer init) => new CaptureNotification(this);
}

public class CaptureNotification : INotifyCapture
{
    private readonly CaptureNotificationInfo info;
    private readonly World world;

    public CaptureNotification(CaptureNotificationInfo notificationInfo)
    {
        info = notificationInfo;
        world = notificationInfo.World;
    }

    public void OnCapture(Actor self, Actor capturing, Player oldOwner, Player newOwner, BitSet<CaptureType> captureTypes)
    {
        if (capturing == null || oldOwner == null || newOwner == null)
            return;

        PlayNotification(self, capturing, oldOwner, newOwner);
    }

    private void PlayNotification(Actor self, Actor capturing, Player oldOwner, Player newOwner)
    {
        string capturedNotification = GetNotificationSound(self, oldOwner, false);
        string newOwnerNotification = GetNotificationSound(self, newOwner, true);

        if (!string.IsNullOrEmpty(capturedNotification))
            world.AudioEngine.Play(capturedNotification, self.CenterPosition);

        if (!string.IsNullOrEmpty(newOwnerNotification))
            world.AudioEngine.Play(newOwnerNotification, self.CenterPosition);
    }

    private string GetNotificationSound(Actor actor, Player owner, bool isNewOwner)
    {
        string voiceFaction = info.VoiceFaction ?? owner.Faction.InternalName;
        string soundKey = isNewOwner ? info.NewOwnerSound : info.CapturedSound;

        return world.AudioEngine.CheckSoundFile($"{voiceFaction}.{soundKey}")
            ?? soundKey;
    }
}

using System;
public static class IteratedDigitsSquaring
{
    public static void Main() {
        Console.WriteLine(Count89s(1_000_000));
        Console.WriteLine(Count89s(100_000_000));
    }
 
    public static int Count89s(int limit) {
        if (limit < 1) return 0;
        int[] end = new int[Math.Min(limit, 9 * 9 * 9 + 2)];
        int result = 0;
 
        for (int i = 1; i < end.Length; i++) {
            for (end[i] = i; end[i] != 1 && end[i] != 89; end[i] = SquareDigitSum(end[i])) { }
            if (end[i] == 89) result++;
        }
        for (int i = end.Length; i < limit; i++) {
            if (end[SquareDigitSum(i)] == 89) result++;
        }
        return result;
 
        int SquareDigitSum(int n) {
            int sum = 0;
            while (n > 0) {
                int digit = n % 10;
                sum += digit * digit;
                n /= 10;
            }
            return sum;
        }
    }
 
}

