[Authorize(Roles = "Admin")]
[ApiController]
[Route("api/[controller]")]
public class LogAdministrationController : ControllerBase
{
    private readonly IDocumentStore _documentStore;
    private readonly ILogger<LogAdministrationController> _logger;

    public LogAdministrationController(
        IDocumentStore documentStore,
        ILogger<LogAdministrationController> logger)
    {
        _documentStore = documentStore;
        _logger = logger;
    }

    public enum LogSort
    {
        Newest,
        Oldest,
        MostFrequent
    }

    public class StructuredLog
    {
        public string Id { get; set; }
        public LogLevel Level { get; set; }
        public string Message { get; set; }
        public DateTime Timestamp { get; set; }
        public int OccurrenceCount { get; set; }
        public string StackTrace { get; set; }
    }

    public class PagedList<T>
    {
        public IEnumerable<T> Items { get; set; }
        public int TotalCount { get; set; }
        public int PageNumber { get; set; }
        public int PageSize { get; set; }
    }

    [HttpGet]
    public async Task<ActionResult<PagedList<StructuredLog>>> GetAll(
        [FromQuery] LogLevel? level = null,
        [FromQuery] LogSort sortBy = LogSort.Newest,
        [FromQuery] int pageNumber = 1,
        [FromQuery] int pageSize = 20)
    {
        using var session = _documentStore.OpenAsyncSession();

        var query = session.Query<StructuredLog>();

        if (level.HasValue)
            query = query.Where(log => log.Level == level.Value);

        query = sortBy switch
        {
            LogSort.Newest => query.OrderByDescending(log => log.Timestamp),
            LogSort.Oldest => query.OrderBy(log => log.Timestamp),
            LogSort.MostFrequent => query.OrderByDescending(log => log.OccurrenceCount),
            _ => query.OrderByDescending(log => log.Timestamp)
        };

        var totalCount = await query.CountAsync();

        var pagedResults = await query
            .Skip((pageNumber - 1) * pageSize)
            .Take(pageSize)
            .ToListAsync();

        return Ok(new PagedList<StructuredLog>
        {
            Items = pagedResults,
            TotalCount = totalCount,
            PageNumber = pageNumber,
            PageSize = pageSize
        });
    }

