using System;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;

namespace ReflectionExtensions
{
    /// <summary>
    /// Provides extension methods for extracting reflection metadata from lambda expressions.
    /// </summary>
    public static class LinqExtensions
    {
        /// <summary>
        /// Extracts member information (property or field) from a lambda expression.
        /// </summary>
        /// <typeparam name="T">The type of the object containing the member.</typeparam>
        /// <typeparam name="TMember">The type of the member.</typeparam>
        /// <param name="expression">A lambda expression accessing a member (property or field).</param>
        /// <returns>The MemberInfo for the accessed member.</returns>
        /// <exception cref="ArgumentNullException">Thrown if the expression is null.</exception>
        /// <exception cref="ArgumentException">Thrown if the expression does not represent a member access.</exception>
        public static MemberInfo ExtractMemberInfo<T, TMember>(this Expression<Func<T, TMember>> expression)
        {
            if (expression == null)
                throw new ArgumentNullException(nameof(expression), "The expression cannot be null.");

            MemberExpression memberExp = null;

            // Check if the expression body is a direct member access.
            if (expression.Body is MemberExpression directMember)
            {
                memberExp = directMember;
            }
            // Check if the expression body includes a conversion (e.g., boxing of a value type)
            else if (expression.Body is UnaryExpression unaryExp &&
                     unaryExp.NodeType == ExpressionType.Convert &&
                     unaryExp.Operand is MemberExpression convertedMember)
            {
                memberExp = convertedMember;
            }
            else
            {
                throw new ArgumentException("The provided expression does not indicate a valid member access.", nameof(expression));
            }

            return memberExp.Member;
        }

        /// <summary>
        /// Extracts property information from a lambda expression.
        /// </summary>
        /// <typeparam name="T">The type of the object containing the property.</typeparam>
        /// <typeparam name="TProperty">The type of the property.</typeparam>
        /// <param name="expression">A lambda expression accessing a property.</param>

