    public static void Main()
    {
        Console.WriteLine("Are these strings numeric?");
        string[] strings = new string[] { "1", "3.14", "-100", "1e2", "NaN", "rose" };
        foreach (string s in strings)
        {
            Console.WriteLine("  {0,4} -> {1}", s, IsNumeric(s));
