using System;
using System.Linq;
using System.Linq.Expressions;
using Microsoft.Azure.Cosmos.Table;

public static class TableServiceExtensionMethods
{
    /// <summary>
    /// Converts a standard IQueryable to a CloudTableQuery with enhanced capabilities
    /// </summary>
    /// <typeparam name="TElement">The type of table entity</typeparam>
    /// <param name="source">The source IQueryable collection</param>
    /// <returns>A specialized CloudTableQuery</returns>
    public static CloudTableQuery<TElement> AsTableServiceQuery<TElement>(
        this IQueryable<TElement> source) where TElement : TableEntity, new()
    {
        if (source == null)
            throw new ArgumentNullException(nameof(source));

        var tableQuery = source as CloudTableQuery<TElement>;
        if (tableQuery != null)
            return tableQuery;

        var context = source.Provider as TableQueryProvider<TElement>;
        if (context == null)
        {
            throw new InvalidOperationException(
                "The source IQueryable does not support Azure Table Storage querying.");
        }

        return new CloudTableQuery<TElement>(
            source.Expression,
            context,
            new TableQueryOptions
            {
                TakeCount = null,
                RetryPolicy = new ExponentialRetry(TimeSpan.FromSeconds(1), 3)
            }
        );
    }

    /// <summary>
    /// Applies server-side pagination and result limiting
    /// </summary>
    public static CloudTableQuery<TElement> Take<TElement>(
        this CloudTableQuery<TElement> query,
        int count) where TElement : TableEntity, new()
    {
        if (query == null)
            throw new ArgumentNullException(nameof(query));

        return query.WithOptions(new TableQueryOptions
        {
            TakeCount = count
        });
    }
}

