namespace Dasher
{
    /// <summary>
    /// Represents an empty message, used as a placeholder in generic types to signify the absence of a message body.
    /// </summary>
    [ExcludeFromCodeCoverage]
    public sealed class Empty
    {
        /// <summary>
        /// Private constructor to prevent instantiation.
        /// </summary>
        private Empty()
        {
            throw new NotSupportedException("The Empty class cannot be instantiated.");
        }

        /// <summary>
        /// Gets the singleton instance of the Empty class.
        /// </summary>
        public static Empty Instance { get; } = new Empty();

        /// <summary>
        /// Ensures that the Empty class can be serialized as a zero-element MsgPack map.
        /// </summary>
        /// <returns>A zero-element MsgPack map representation.</returns>
        public byte[] ToMsgPack()
        {
            // MsgPack map header with 0 elements
            return new byte[] { 0x80 };
        }

        /// <summary>
        /// Deserializes a zero-element MsgPack map into an Empty instance.
        /// </summary>
        /// <param name="data">The MsgPack data to deserialize.</param>
        /// <returns>An instance of the Empty class.</returns>
        public static Empty FromMsgPack(byte[] data)
        {
            if (data == null || data.Length != 1 || data[0] != 0x80)
            {
                throw new ArgumentException("Invalid MsgPack data for Empty type.");
            }
            return Instance;
        }

        /// <summary>
        /// Returns a string that represents the current object.
        /// </summary>
        /// <returns>A string that represents the current object.</returns>
        public override string ToString()
        {
            return "Empty";
        }

        /// <summary>
        /// Determines whether the specified object is equal to the current object.
        /// </summary>
        /// <param name="obj">The object to compare with the current object.</param>
        /// <returns>true if the specified object is equal to the current object; otherwise, false.</returns>
        public override bool Equals(object obj)
        {
            return obj is Empty;
        }

        /// <summary>
        /// Serves as the default hash function.
        /// </summary>
        /// <returns>A hash code for the current object.</returns>
        public override int GetHashCode()
        {
            return typeof(Empty).GetHashCode();
        }
    }
}

using System;

public class SafeAddition
{
    private static double stepDown(double d)
    {
        return Math.NextAfter(d, Double.NegativeInfinity);
    }

    private static double stepUp(double d)
    {
        return Math.NextUp(d);
    }

    private static double[] safeAdd(double a, double b)
    {
        return new double[] { stepDown(a + b), stepUp(a + b) };
    }

    public static void Main(string[] args)
    {
        double a = 1.2;
        double b = 0.03;
        double[] result = safeAdd(a, b);
        Console.Write(string.Format("({0} + {1}) is in the range {2}..{3}", a, b, result[0], result[1]));
    }
}

