namespace MAC_Vendor_Lookup
{
    class Converter
    {
        static void Main(string[] args)
        {
            if (args.Length!= 1)
                Console.WriteLine("Usage : {0} <MAC address>", args[0]);
            else
            {
                string str = "http://api.macvendors.com/" + args[1];
                WebRequest request = WebRequest.Create(str);
                WebResponse response = request.GetResponse();
                Stream dataStream = response.GetResponseStream();
                StreamReader reader = new StreamReader(dataStream);
                string responseFromServer = reader.ReadToEnd();
                checkResponse(responseFromServer);
                reader.Close();
                response.Close();
            }
        }
 
        static void checkResponse(string str)
        {
            string refStr = "Vendor not found";
            int len = str.Length, flag = 1, i;
 
            if (len < 16)
                Console.WriteLine(str);
            else
            {
                for (i = 0; i < len && i < 16; i++)
                    flag = flag && (refStr[i] == str[i]);
 
                flag == 1? Console.WriteLine("N/A") : Console.WriteLine(str);
            }
        }
    }
}

