    [Serializable]
    internal class UsernamePasswordCredentials : AbstractCredentials, ICredentials
    {
        private byte[] _password;

        public UsernamePasswordCredentials()
        { }

        public UsernamePasswordCredentials(string username, string password)
        {
            SetUsername(username);
            SetPassword(password);
        }

        public string GetPassword() => _password == null ? null : Encoding.UTF8.GetString(_password);

        public string GetUsername() => Principal;

        public void SetPassword(string password)
        {
            _password = password == null ? null : Encoding.UTF8.GetBytes(password);
        }

        public void SetUsername(string username)
        {
            Principal = username;
        }

        public override string ToString()
        {
            return "UsernamePasswordCredentials{Principal='" + Principal + "'}";
        }

        public void SetPrincipal(string username)
        {
            Principal = username;
        }

        public string GetPrincipal()
        {
            return Principal;
        }
    }
}

