namespace ProjectEuler
{
    class Generator
    {
        static void Main(string[] args)
        {
            var c = Cubes(1201);
            var it = c.Combinations(2);
            var m = new Dictionary<long, List<List<long>>>();
            foreach (var x in it)
            {
                var sum = x[0] + x[1];
                if (!m.ContainsKey(sum))
                {
                    m.Add(sum, new List<List<long>>());
                }
                m[sum].Add(x);
            }
            var result = new List<Tuple<long, List<List<long>>>>();
            foreach (var k in m.Keys)
            {
                if (m[k].Count > 1)
                {
                    result.Add(new Tuple<long, List<List<long>>>(k, m[k]));
                }
            }
            result.Sort((x, y) => x.Item1.CompareTo(y.Item1));
            foreach (var f in result)
            {
                Console.WriteLine(f);
            }
        }
        static List<long> Cubes(long n)
        {
            var cube_vector = new List<long>();
            for (long i = 1; i <= n; i++)
            {
                cube_vector.Add(i * i * i);
            }
            return cube_vector;
        }
    }
}

using Xunit;
 using Microsoft.AspNetCore.Mvc;
 using Moq;
 using System.Threading.Tasks;
