 public class ContestantsController_GetContestantsAttempts_Should
 {
  [Fact]
  public async Task ReturnOk_WhenContestantExistsAndHasAttempts()
  {
  // Arrange
  var mediatorMock = new Mock<IMediator>();
  mediatorMock.Setup(m => m.Send(It.IsAny<GetContestantAttemptsQuery>(), default))
  .ReturnsAsync(new List<ContestantAttempt> { new ContestantAttempt() });
  var controller = new ContestantsController(mediatorMock.Object);

  // Act
  var result = await controller.GetContestantsAttempts(Guid.NewGuid());

  // Assert
  Assert.IsType<OkObjectResult>(result.Result);
  }

  [Fact]
  public async Task ReturnNotFound_WhenContestantDoesNotExist()
  {
  // Arrange
  var mediatorMock = new Mock<IMediator>();
  mediatorMock.Setup(m => m.Send(It.IsAny<GetContestantAttemptsQuery>(), default))
  .ReturnsAsync((List<ContestantAttempt>)null);
  var controller = new ContestantsController(mediatorMock.Object);

  // Act
  var result = await controller.GetContestantsAttempts(Guid.NewGuid());

  // Assert
  Assert.IsType<NotFoundResult>(result.Result);
  }

  [Fact]
  public async Task ReturnBadRequest_WhenContestantIdIsInvalid()
  {
  // Arrange
  var mediatorMock = new Mock<IMediator>();
  var controller = new ContestantsController(mediatorMock.Object);

  // Act
  var result = await controller.GetContestantsAttempts(Guid.Empty);

  // Assert
  Assert.IsType<BadRequestObjectResult>(result.Result);
  }
 }

 public interface IMediator
 {
  Task<List<ContestantAttempt>> Send(GetContestantAttemptsQuery query, CancellationToken cancellationToken);
 }

 public class ContestantsController : ControllerBase
 {
  private readonly IMediator _mediator;
  public ContestantsController(IMediator mediator)
  {
  _mediator = mediator;
  }

  [HttpGet("api/contestants/{contestantId}/attempts")]
  public async Task<ActionResult<IEnumerable<ContestantAttempt>>> GetContestantsAttempts(Guid contestantId)
  {
  if (contestantId == Guid.Empty)
  {
  return BadRequest("Invalid contestant ID.");
  }
  var attempts = await _mediator.Send(new GetContestantAttemptsQuery(contestantId), default);
  if (attempts == null)
  {
  return NotFound();
  }
  return Ok(attempts);
  }
 }

 public class GetContestantAttemptsQuery
 {
  public Guid ContestantId { get; set; }
  public GetContestantAttemptsQuery(Guid contestantId)
  {
  ContestantId = contestantId;
  }
 }

