public static void Reverse(int[] a, int n)
{
    if (n == 0)
    {
        return;
    }
    else
    {
        int temp = a[0];
        a[0] = a[n - 1];
        a[n - 1] = temp;
        Reverse(a, n - 1);
    }
}

