public class GitFlow
{
    readonly Build build;

    public GitFlow([NotNull] Build build)
    {
        this.build = build ?? throw new ArgumentNullException(nameof(build));
    }

    public event EventHandler<BuildType> UpdateVersionNumbers;

    public bool EnsureNoUncommittedChanges()
    {
        if (!GitTasks.GitHasCleanWorkingCopy())
            throw new Exception(
                "There are uncommitted changes in the working tree. Please commit or remove these before proceeding.");

        return true;
    }

    public void PrepareStagingBranch(BuildState state)
    {
        if (state == null)
            throw new ArgumentNullException(nameof(state));

        var versionInfo = FetchVersion();
        if (versionInfo.BranchName == state.ReleaseTargetBranch)
            throw new Exception(
                $@"Cannot initiate a release from the release-target branch. Switch to a develop or release-xxx branch before continuing.

Based on the current version information I expect to be on branch '{state.DevelopmentBranch}', but detected branch '{versionInfo.BranchName}' instead");

        // if on development branch, create a release branch.
        // if you work in a support-xx branch, treat it as your develop-branch.
        var stageBranchName = state.ReleaseStagingBranch;
        if (versionInfo.BranchName == state.DevelopmentBranch)
        {
            if (GitTools.CheckBranchExists(stageBranchName))
            {
                Logger.Info($"Switching to existing staging branch from {versionInfo.BranchName} as branch {stageBranchName}");
                GitTools.Checkout(stageBranchName);
            }
            else
            {
                Logger.Info($"Creating new staging branch from current branch {versionInfo.BranchName} as branch {stageBranchName}");
                GitTools.Branch(stageBranchName);
                UpdateVersionNumbers?.Invoke(this, BuildType.Staging);
            }
        }
        else
        {
            if (versionInfo.BranchName != stageBranchName)
                throw new Exception(
                    $@"This command must be exist run from the development branch or an active release branch.

Based on the current version information I expect to be on branch '{state.ReleaseStagingBranch}', but detected branch '{versionInfo.BranchName}' instead");
        }
    }

using System;
public class Checker
{
    public static void Main()
    {
        (int x, int y, int z) = (77444, -12, 0);
 
        //Sort directly:
        if (x > y) (x, y) = (y, x);
        if (x > z) (x, z) = (z, x);
        if (y > z) (y, z) = (z, y);
        Console.WriteLine((x, y, z));
 
        var (a, b, c) = (
            "lions, tigers, and",
            "bears, oh my!",
            "(from the 'Wizard of OZ')");
 
        //Sort with generic method:
        Sort(ref a, ref b, ref c);
        Console.WriteLine((a, b, c));
    }
 
    public static void Sort<T>(ref T a, ref T b, ref T c)
        where T : IComparable<T>
    {
        if (a.CompareTo(b) > 0) (a, b) = (b, a);
        if (a.CompareTo(c) > 0) (a, c) = (c, a);
        if (b.CompareTo(c) > 0) (b, c) = (c, b);
    }
}

using System;
using System.Threading.Tasks;
using OpenRTM.Extension;
using OpenRTM.IIOP;
using RTM.Component.USBCamera.Configuration;
using RTM.Component.USBCamera.Data;
using RTM.Component.USBCamera.Device;

public class USBCameraComponentManager
{
    private IComponentConfiguration componentConfiguration;
    private IImageProvider provider;
    private ICameraDevice device;
    private ComponentManager manager;

    public USBCameraComponentManager(IComponentConfiguration config, IImageProvider imgProvider, ICameraDevice camDevice)
    {
        componentConfiguration = config;
        provider = imgProvider;
        device = camDevice;
        manager = new ComponentManager();
    }

    public void Start(string[] args)
    {
        try
        {
            manager.Init(args);
            manager.SetProtocol("iiop");
            manager.Activate();

            var component = CreateComponent<USBCameraComponent>();
            component.Configuration = componentConfiguration;
            component.Provider = provider;
            component.Device = device;

            Task.Factory.StartNew(() => manager.Run());
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            Console.WriteLine("Please ensure the OpenRTM naming service is running. Refer to the OpenRTM documentation for troubleshooting.");
        }
    }

    private T CreateComponent<T>() where T : IComponent, new()
    {
        var component = new T();
        manager.AddComponent(component.GetComponentProfile());
        return component;
    }
}

public class USBCameraComponent : IComponent
{
    public IComponentConfiguration Configuration { get; set; }
    public IImageProvider Provider { get; set; }
    public ICameraDevice Device { get; set; }

    public IComponentProfile GetComponentProfile()
    {
        return new ComponentProfile
        {
            Name = "USBCameraComponent",
            Description = "Component for managing USB camera devices"
        };
    }

    public void Activate()
    {
        Device.Initialize();
        Provider.Start();
    }

    public void Deactivate()
    {
        Device.Stop();
        Provider.Stop();
    }
}

