namespace ErosionSimulation
{
    public partial class ErosionConfigurationForm : Form, IDisposable
    {
        private GUILayer.ErosionIterativeSystem _system;
        private ErosionSettingsSchemaLoader _schemaLoader;
        private PreviewWindow _previewWindow;
        private IPropertyContext _propertyContext;

        public ErosionConfigurationForm()
        {
            InitializeComponent();
            InitializeErosionSystem();
            ConfigureUserInterface();
        }

        private void InitializeErosionSystem()
        {
            _schemaLoader = new ErosionSettingsSchemaLoader();
            _system = new GUILayer.ErosionIterativeSystem();
            _propertyContext = CreatePropertyContext();
        }

        private IPropertyContext CreatePropertyContext()
        {
            var propertySource = new GUILayer.BasicPropertySource();
            var schemaContext = _schemaLoader.LoadSchema("ErosionSettings");

            return new PropertyContext(propertySource, schemaContext);
        }

        private void ConfigureUserInterface()
        {
            _previewWindow = new PreviewWindow(_system);
            _previewWindow.Dock = DockStyle.Fill;
            previewPanel.Controls.Add(_previewWindow);

            propertyGrid.SelectedObject = _propertyContext;
            iterationTrackBar.ValueChanged += HandleIterationUpdate;
        }

        private void HandleIterationUpdate(object sender, EventArgs e)
        {
            int iterations = iterationTrackBar.Value;
            for (int i = 0; i < iterations; i++)
            {
                DoTick();
            }
            _previewWindow.Refresh();
        }

        private void DoTick()
        {
            try
            {
                _system.Iterate();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Iteration Error: {ex.Message}", "System Error");
            }
        }

        private void Load(string configurationPath)
        {
            try
            {
                _system.LoadConfiguration(configurationPath);
                _propertyContext.Refresh();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Load Error: {ex.Message}", "Configuration Error");
            }
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                _system?.Dispose();

