[TestFixture]
public class FirstDayOfWeekTests
{
    [Test]
    public void TestFirstDayOfWeek_DefaultFirstDayOfWeek_ReturnsCorrectDate()
    {
        DateTime date = new DateTime(2023, 10, 15); // A Sunday
        DateTime result = date.FirstDayOfWeek();
        Assert.AreEqual(new DateTime(2023, 10, 9), result); // Monday of the same week
    }

    [Test]
    public void TestFirstDayOfWeek_DefaultFirstDayOfWeek_ReturnsCorrectDayOfWeek()
    {
        DateTime date = new DateTime(2023, 10, 15); // A Sunday
        DateTime result = date.FirstDayOfWeek();
        Assert.AreEqual(DayOfWeek.Monday, result.DayOfWeek);
    }

    [Test]
    public void TestFirstDayOfWeek_CustomFirstDayOfWeek_ReturnsCorrectDate()
    {
        DateTime date = new DateTime(2023, 10, 15); // A Sunday
        DateTime result = date.FirstDayOfWeek(DayOfWeek.Sunday);
        Assert.AreEqual(new DateTime(2023, 10, 15), result); // Sunday of the same week
    }

    [Test]
    public void TestFirstDayOfWeek_CustomFirstDayOfWeek_ReturnsCorrectDayOfWeek()
    {
        DateTime date = new DateTime(2023, 10, 15); // A Sunday
        DateTime result = date.FirstDayOfWeek(DayOfWeek.Sunday);
        Assert.AreEqual(DayOfWeek.Sunday, result.DayOfWeek);
    }

    [Test]
    public void TestFirstDayOfWeek_DefaultFirstDayOfWeek_MiddleOfWeek_ReturnsCorrectDate()
    {
        DateTime date = new DateTime(2023, 10, 12); // A Thursday
        DateTime result = date.FirstDayOfWeek();
        Assert.AreEqual(new DateTime(2023, 10, 9), result); // Monday of the same week
    }

    [Test]
    public void TestFirstDayOfWeek_DefaultFirstDayOfWeek_MiddleOfWeek_ReturnsCorrectDayOfWeek()
    {
        DateTime date = new DateTime(2023, 10, 12); // A Thursday
        DateTime result = date.FirstDayOfWeek();
        Assert.AreEqual(DayOfWeek.Monday, result.DayOfWeek);
    }

    [Test]
    public void TestFirstDayOfWeek_CustomFirstDayOfWeek_MiddleOfWeek_ReturnsCorrectDate()
    {
        DateTime date = new DateTime(2023, 10, 12); // A Thursday
        DateTime result = date.FirstDayOfWeek(DayOfWeek.Sunday);
        Assert.AreEqual(new DateTime(2023, 10, 8), result); // Sunday of the same week
    }

    [Test]
    public void TestFirstDayOfWeek_CustomFirstDayOfWeek_MiddleOfWeek_ReturnsCorrectDayOfWeek()
    {
        DateTime date = new DateTime(2023, 10, 12); // A Thursday
        DateTime result = date.FirstDayOfWeek(DayOfWeek.Sunday);
        Assert.AreEqual(DayOfWeek.Sunday, result.DayOfWeek);
    }

