namespace Hailstone
{
    class Queue
    {
        static void Main(string[] args)
        {
            var h = hailstone(27);
            Console.WriteLine(h.Count);
            Console.WriteLine(h.Take(4).SequenceEqual(new List<int> { 27, 82, 41, 124 }));
            Console.WriteLine(h.Skip(h.Count - 4).SequenceEqual(new List<int> { 8, 4, 2, 1 }));
            Console.WriteLine(hailstone(100000).Max(x => x.Count));
            Console.ReadLine();
        }
 
        static List<int> hailstone(int n)
        {
            var seq = new List<int> { n };
            while (n > 1)
            {
                n = (n & 1) == 1? 3 * n + 1 : n / 2;
                seq.Add(n);
            }
            return seq;
        }
    }
}

