    public class StructureBspClusterBlock
    {
        private int resourcePointer;
        private int resourceLength;

        public StructureBspClusterDataBlockNew[] ClusterData { get; private set; }
        public GlobalGeometryBlockInfoBlock[] GeometryBlockInfo { get; set; }
        public bool IsClusterDataLoaded => ClusterData != null;

        public void LoadClusterData()
        {
            if (IsClusterDataLoaded) return;

            var resourceStream = GetResourceFromCache(GlobalGeometryBlockResourceBlock.TypeEnum.VertexBuffer);
            using (var binaryReader = new BinaryReader(resourceStream))
            {
                resourceStream.Position = resourcePointer;
                int count = binaryReader.ReadInt32();
                ClusterData = new StructureBspClusterDataBlockNew[count];

                for (int i = 0; i < count; i++)
                {
                    ClusterData[i] = new StructureBspClusterDataBlockNew();
                    ClusterData[i].Read(binaryReader);
                }
            }

            MapVertexBuffersToSections();
        }

        private void MapVertexBuffersToSections()
        {
            var vertexBuffers = GetResourceFromCache(
                GlobalGeometryBlockResourceBlock.TypeEnum.VertexBuffer,
                resourcePointer,
                resourceLength).ToArray();

            foreach (var section in GeometryBlockInfo)
            {
                section.VertexBuffer.Data = vertexBuffers
                    .First(x => x.ResourceHeader.ResourceType ==
                        GlobalGeometryBlockResourceBlock.TypeEnum.VertexBuffer)
                    .ResourceData;
            }
        }

        public void DeleteClusterData()
        {
            ClusterData = null;
            ReleaseVertexBufferMemory();
        }

        private void ReleaseVertexBufferMemory()
        {
            foreach (var section in GeometryBlockInfo)
            {
                section.VertexBuffer.Data = null;
            }
        }

        public int GetResourcePointer() => resourcePointer;
        public void SetResourcePointer(int pointer) => resourcePointer = pointer;
        public int GetResourceLength() => resourceLength;
        public void SetResourceLength(int length) => resourceLength = length;

