using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public class SceneTransitionManager : MonoBehaviour
{
    public static SceneTransitionManager Instance { get; private set; }

    [Header("Fade Settings")]
    [SerializeField] private Image fadeOverlay;
    [SerializeField] private float fadeSpeed = 2.0f;

    private bool isTransitioning = false;
    private float fadeDirection = 0f;

    private void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    private void Start()
    {
        if (fadeOverlay == null)
        {
            Debug.LogError("Fade Overlay Image not assigned!");
            enabled = false;
        }
    }

    public void BeginFade(float direction)
    {
        if (!isTransitioning)
        {
            fadeDirection = direction;
            StartCoroutine(FadeRoutine());
        }
    }

    private IEnumerator FadeRoutine()
    {
        isTransitioning = true;
        float alpha = fadeDirection > 0 ? 0f : 1f;

        while ((fadeDirection > 0 && alpha < 1f) || (fadeDirection < 0 && alpha > 0f))
        {
            alpha += fadeDirection * fadeSpeed * Time.deltaTime;
            fadeOverlay.color = new Color(fadeOverlay.color.r, fadeOverlay.color.g, fadeOverlay.color.b, Mathf.Clamp01(alpha));
            yield return null;
        }

        isTransitioning = false;
    }

    public void ChangeLevel(int sceneIndex)
    {
        if (!isTransitioning)
        {
            StartCoroutine(TransitionToScene(sceneIndex));
        }
    }

    public void ChangeLevelRelative(int relativeIndex)
    {
        if (!isTransitioning)
        {
            int currentSceneIndex = SceneManager.GetActiveScene().buildIndex;
            int targetSceneIndex = Mathf.Clamp(currentSceneIndex + relativeIndex, 0, SceneManager.sceneCountInBuildSettings - 1);
            StartCoroutine(TransitionToScene(targetSceneIndex));
        }
    }

    public void ResetCurrentLevel()
    {
        if (!isTransitioning)
        {
            int currentSceneIndex = SceneManager.GetActiveScene().buildIndex;
            StartCoroutine(TransitionToScene(currentSceneIndex));
        }
    }

    private IEnumerator TransitionToScene(int sceneIndex)
    {
        BeginFade(1f);

        yield return new WaitUntil(() => !isTransitioning);

        AsyncOperation asyncLoad = SceneManager.LoadSceneAsync(sceneIndex);

using System;
using System.Collections.Generic;
using System.Linq;
 
class Validator
{
    static IEnumerable<int> ForwardDifference(IEnumerable<int> sequence, uint order = 1u)
    {
        switch (order)
        {
            case 0u:
                return sequence;
            case 1u:
                return sequence.Skip(1).Zip(sequence, (next, current) => next - current);
            default:
                return ForwardDifference(ForwardDifference(sequence), order - 1u);
        }
    }
 
    static void Main()
    {
        IEnumerable<int> sequence = new[] { 90, 47, 58, 29, 22, 32, 55, 5, 55, 73 };
        do
        {
            Console.WriteLine(string.Join(", ", sequence));
        } while ((sequence = ForwardDifference(sequence)).Any());
    }
}

using UnityEngine;
using UnityEngine.UI;
using IBM.Watson.DeveloperCloud.Services.VisualRecognition.v3;
using System.Collections.Generic;

public class TextRecognitionDisplay : MonoBehaviour
{
    public Text m_Text;

    void Awake()
    {
        if (AppData.Instance != null && AppData.Instance.RecognizeTextResult != null)
        {
            DisplayTextRecognitionResults(AppData.Instance.RecognizeTextResult);
        }
        else
        {
            m_Text.text = "No text recognition results available.";
        }
    }

    private void DisplayTextRecognitionResults(RecognizeTextResult recognizeTextResult)
    {
        if (recognizeTextResult == null || recognizeTextResult.Images == null || recognizeTextResult.Images.Count == 0)
        {
            m_Text.text = "No images processed.";
            return;
        }

        string resultText = $"Processed {recognizeTextResult.Images.Count} images:\n\n";

        foreach (var image in recognizeTextResult.Images)
        {
            resultText += $"Image: {image.ImageIndex + 1}\n";

            if (image.Text == null || image.Text.TextRecogTopLevelMultiple == null || image.Text.TextRecogTopLevelMultiple.Words == null)
            {
                resultText += "No text found in this image.\n\n";
                continue;
            }

            foreach (var word in image.Text.TextRecogTopLevelMultiple.Words)
            {
                resultText += $"Line: {word.LineNumber}, Word: {word.Word}, Confidence: {word.Confidence:F2}, Location: ({word.Location.Left}, {word.Location.Top}, {word.Location.Width}, {word.Location.Height})\n";
            }

            resultText += "\n";
        }

        m_Text.text = resultText;
    }
}

