namespace ScriptingFramework
{
    // Enumeration for categorizing narrowing type conversions
    public enum NarrowingLevel
    {
        None = 0,           // No risk of data loss
        One = 1,            // Preferred narrowing conversion
        Two = 2,            // Moderate narrowing conversion with some risk
        Three = 3,          // Significant narrowing conversion risk
        All = 4             // Conversion that is deemed unsafe
    }

    // Class to handle conversions and method overload resolution
    public class ConversionManager
    {
        // Method to determine if a conversion is safe
        public static bool IsSafeConversion(NarrowingLevel level)
        {
            return level == NarrowingLevel.None;
        }

        // Method to retrieve description of narrowing level
        public static string GetNarrowingDescription(NarrowingLevel level)
        {
            switch (level)
            {
                case NarrowingLevel.None:
                    return "No risk of data loss.";
                case NarrowingLevel.One:
                    return "Preferred narrowing conversion, low risk.";
                case NarrowingLevel.Two:
                    return "Moderate risk of data loss.";
                case NarrowingLevel.Three:
                    return "Significant risk of data loss.";
                case NarrowingLevel.All:
                    return "Unsafe conversion, high risk of data loss.";
                default:
                    throw new ArgumentOutOfRangeException(nameof(level), "Invalid narrowing level.");
            }
        }

        // Example of method overload resolution based on narrowing levels
        public void ConvertUsingNarrowing(NarrowingLevel level)
        {
            Console.WriteLine($"Attempting conversion with level: {level}");
            if (IsSafeConversion(level))
            {
                Console.WriteLine("Conversion is safe.");
            }
            else
            {
                Console.WriteLine(GetNarrowingDescription(level));
                // Additional logic for conversions could be implemented here
            }
        }
    }

    class Finder
    {
        static void Main(string[] args)
        {
            ConversionManager manager = new ConversionManager();

            // Demonstrate conversion handling
            manager.ConvertUsingNarrowing(NarrowingLevel.None); // Safe
            manager.ConvertUsingNarrowing(NarrowingLevel.One);  // Preferred

