    public class DefaultDbContext : IdentityDbContext<IdentityUser>
    {
        private readonly string _connectionString;

        public DefaultDbContext(string connectionString) : base(new DbContextOptionsBuilder<DefaultDbContext>().UseMySql(connectionString,
            new MySqlServerVersion(new Version(8, 0, 21))).Options)
        {
            _connectionString = connectionString;
        }

        public DbSet<Ban> Bans { get; set; }
        public DbSet<Character> Characters { get; set; }
        public DbSet<Group> Groups { get; set; }
        public DbSet<GroupMember> GroupMembers { get; set; }
        public DbSet<Property> Properties { get; set; }
        public DbSet<Job> Jobs { get; set; }
        public DbSet<Vehicle> Vehicles { get; set; }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);

            modelBuilder.Entity<GroupMember>()
                .HasKey(gm => new { gm.GroupId, gm.UserId });

            modelBuilder.Entity<GroupMember>()
                .HasOne(gm => gm.Group)
                .WithMany(g => g.GroupMembers)
                .HasForeignKey(gm => gm.GroupId);

            modelBuilder.Entity<GroupMember>()
                .HasOne(gm => gm.User)
                .WithMany(u => u.GroupMembers)
                .HasForeignKey(gm => gm.UserId);

            modelBuilder.Entity<Ban>()
                .HasOne(b => b.User)
                .WithMany(u => u.Bans)
                .HasForeignKey(b => b.UserId);
        }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            if (!optionsBuilder.IsConfigured)
            {
                optionsBuilder.UseMySql(_connectionString, new MySqlServerVersion(new Version(8, 0, 21)));
            }
        }
    }

