namespace CRC32Example
{
    // An abstract base class for computing CRC32 hash values.
    public abstract class CRC32 : HashAlgorithm
    {
        // The CRC32 uses a 32-bit hash.
        protected CRC32()
        {
            HashSizeValue = 32;
            // Set default CRC32 parameters.
            Polynomial = 0xEDB88320;
            InitialValue = 0xFFFFFFFF;
            FinalXorValue = 0xFFFFFFFF;
        }

        // Polynomial used in CRC calculation.
        public uint Polynomial { get; protected set; }
        // Initial value before any processing.
        public uint InitialValue { get; protected set; }
        // Final XOR value applied to resulting CRC.
        public uint FinalXorValue { get; protected set; }

        // Factory method creating a default managed CRC32 instance.
        public static CRC32 Create()
        {
            return new CRC32Managed();
        }

        // Factory method allowing a custom polynomial for CRC32.
        public static CRC32 Create(uint customPolynomial)
        {
            return new CRC32Managed(customPolynomial);
        }
    }

    // A managed implementation for computing the CRC32 hash.
    public class CRC32Managed : CRC32
    {
        // Buffer for CRC lookup table.
        private readonly uint[] table;
        // Current computed CRC value.
        private uint currentCrc;

        // Default constructor using the standard polynomial.
        public CRC32Managed() : this(0xEDB88320)
        {
        }

        // Constructor that accepts a custom polynomial.
        public CRC32Managed(uint customPolynomial)
        {
            Polynomial = customPolynomial;
            currentCrc = InitialValue;
            table = InitializeTable(Polynomial);
        }

        // Initializes the CRC lookup table based on the polynomial.
        private static uint[] InitializeTable(uint poly)
        {
            uint[] tbl = new uint[256];
            for (uint i = 0; i < 256; i++)
            {
                uint crc = i;
                for (int j = 0; j < 8; j++)
                {
                    if ((crc & 1) != 0)
                    {
                        crc = (crc >> 1) ^ poly;
                    }
                    else
                    {
                        crc >>= 1;
                    }
                }
                tbl[i] = crc;
            }
            return tbl;
        }

        // Resets the current CRC value for a new hashing operation.

using System;

namespace Gem.Infrastructure.Functional
{
    public static class PipelineExtensions
    {

        public static Pipeline<TValue> Catch<TValue>(this Pipeline<TValue> pendingResult, Func<Exception, Result<TValue>> exceptionHandler)
        {
            pendingResult.ExceptionHandler = exceptionHandler;
            return pendingResult;
        }

        public static Pipeline Catch(this Pipeline pendingResult, Func<Exception, Result> exceptionHandler)
        {
            pendingResult.ExceptionHandler = exceptionHandler;
            return pendingResult;
        }

        public static Pipeline<TValue> ContinueWith<TValue>(
            this Pipeline<TValue> future,
            Func<TValue, Result<TValue>> func)
        {
            return new Pipeline<TValue>(() =>
            {
                var res = future.PendingResult();
                return
                (res.Success)
                ? func(res.Value)
                : res;
            });
        }

        public static Pipeline<TNext> ContinueWithNew<TValue, TNext>(
            this Pipeline<TValue> future,
            Func<TValue, Result<TNext>> func)
        {
            return new Pipeline<TNext>(() =>
            {
                var res = future.PendingResult();
                return
                (res.Success)
                ? func(res.Value)
                : Result.Fail<TNext>(res.Error);
            });
        }

        public static Pipeline ContinueWith(
            this Pipeline future,
            Action action)
        {
            return new Pipeline(() =>
            {
                var res = future.PendingResult();
                if (res.Success)
                {
                    action();
                    return Result.Ok();
                }
                return res;
            });
        }

    }
}

