        {
            [Fact]
            public void ShouldSetTheDefineWhenTheValueIsAString()
            {
                using (var image = new MagickImage())
                {
                    image.Settings.SetDefine(MagickFormat.Jpeg, "test", "1");
                    Assert.Equal("1", image.Settings.GetDefine(MagickFormat.Jpeg, "test"));
                }
            }

            [Fact]
            public void ShouldSetTheDefineWhenTheValueIsABool()
            {
                using (var image = new MagickImage())
                {
                    image.Settings.SetDefine(MagickFormat.Jpeg, "test", true);
                    Assert.Equal("true", image.Settings.GetDefine(MagickFormat.Jpeg, "test"));
                }
            }

            [Fact]
            public void ShouldSetTheDefineWhenTheValueIsAnInteger()
            {
                using (var image = new MagickImage())
                {
                    image.Settings.SetDefine(MagickFormat.Jp2, "test", 1);
                    Assert.Equal("1", image.Settings.GetDefine(MagickFormat.Jp2, "test"));
                }
            }
            [Fact]
            public void ShouldSetTheDefineWhenTheFormatIsUnknown()
            {
                using (var image = new MagickImage())
                {
                    image.Settings.SetDefine(MagickFormat.Unknown, "testkey", "testval");
                    Assert.Equal("testval", image.Settings.GetDefine(MagickFormat.Unknown, "testkey"));
                }
            }

            [Fact]
            public void ShouldSetDefineForGenericKey()
            {
                using (var image = new MagickImage())
                {
                    image.Settings.SetDefine("testkey", "testval");
                    Assert.Equal("testval", image.Settings.GetDefine("testkey"));
                }
            }
        }
    }
