public static string Caesar(string text, int shift)
{
    return text.ToUpper().Replace(new Regex("[^A-Z]"), "").Replace(".", match =>
    {
        return ((char)(65 + (match.Value[0] - 65 + shift) % 26)).ToString();
    });
}

