using UnityEngine;

public class ShipModulesDropTarget : MonoBehaviour
{
    public ShipModulesController modulesController;

    private void Awake()
    {
        // Initialization if needed
    }

    public void OnDropCargoItem(ShipModuleController droppedModule)
    {
        if (CanAddModule(droppedModule))
        {
            PlaceModule(droppedModule);
        }
        else
        {
            PlayerNotifications.SendError("No available slots for this module.");
        }
    }

    public void OnDropHardpointModule(ShipModuleController droppedModule)
    {
        if (CanSwapModule(droppedModule))
        {
            SwapModule(droppedModule);
        }
        else
        {
            PlayerNotifications.SendError("Cannot swap module in this slot.");
        }
    }

    private bool CanAddModule(ShipModuleController module)
    {
        return modulesController.HasAvailableSlot(module.ModuleType);
    }

    private void PlaceModule(ShipModuleController module)
    {
        int slotIndex = modulesController.GetAvailableSlotIndex(module.ModuleType);
        if (slotIndex != -1)
        {
            modulesController.AddModuleToSlot(module, slotIndex);
            PlayerNotifications.SendInfo("Module added successfully.");
        }
    }

    private bool CanSwapModule(ShipModuleController module)
    {
        return modulesController.CanSwapModule(module);
    }

    private void SwapModule(ShipModuleController module)
    {
        int slotIndex = modulesController.GetOccupiedSlotIndex(module);
        if (slotIndex != -1)
        {
            ShipModuleController existingModule = modulesController.GetModuleInSlot(slotIndex);
            modulesController.SwapModules(existingModule, module, slotIndex);
            PlayerNotifications.SendInfo("Modules swapped successfully.");
        }
    }
}

