namespace YahooSearch
{
    class YahooResult
    {
        public string title;
        public string url;
        public string content;
        public override string ToString()
        {
            return string.Format("Title  : {0}\nUrl    : {1}\nContent: {2}\n", title, url, content);
        }
    }
 
    class YahooSearch
    {
        private string query;
        private int page;
        private Regex rx;
        public YahooSearch(string query, int page)
        {
            this.query = query;
            this.page = page;
            rx = new Regex(@"<h3 class=""title""><a class=.*?href=""(.*?)"".*?>(.*?)</a></h3>.*?<div class=""compText aAbs"" ><p class=.*?>(.*?)</p></div>");
        }
        public List<YahooResult> results()
        {
            string search = string.Format("http://search.yahoo.com/search?p={0}&b={1}", query, page * 10 + 1);
            WebRequest request = WebRequest.Create(search);
            WebResponse response = request.GetResponse();
            StreamReader reader = new StreamReader(response.GetResponseStream());
            string s = reader.ReadToEnd();
            reader.Close();
            response.Close();
            List<YahooResult> results = new List<YahooResult>();
            foreach (Match m in rx.Matches(s))
            {
                YahooResult yr = new YahooResult();
                yr.title = Regex.Replace(Regex.Replace(m.Groups[2].Value, "<b>", ""), "</b>", "");
                yr.url = m.Groups[1].Value;
                yr.content = Regex.Replace(Regex.Replace(m.Groups[3].Value, "<b>", ""), "</b>", "");
                results.Add(yr);
            }
            return results;
        }
        public YahooSearch nextPage()
        {
            return new YahooSearch(query, page + 1);
        }
    }
 
    class Runner
    {
        static void Main(string[] args)
        {
            YahooSearch ys = new YahooSearch("rosettacode", 0);
            // Limit output to first 5 entries, say, from pages 1 and 2.
            Console.WriteLine("PAGE 1 =>\n");
            foreach (YahooResult res in ys.results().Take(5))
            {
                Console.WriteLine(res);
            }
            Console.WriteLine("PAGE 2 =>\n");
            foreach (YahooResult res in ys.nextPage().results().Take(5))
            {
                Console.WriteLine(res);
            }
        }
    }
}

