namespace MianChowla
{
    class Handler
    {
        const int n = 100;
        const int nn = (n * (n + 1)) >> 1;
 
        static bool Contains(int[] lst, int item, int size)
        {
            for (int i = size - 1; i >= 0; i--)
                if (item == lst[i]) return true;
            return false;
        }
 
        static int[] MianChowla()
        {
            int[] mc = new int[n]; mc[0] = 1;
            int[] sums = new int[nn]; sums[0] = 2;
            int sum, le, ss = 1;
            for (int i = 1; i < n; i++)
            {
                le = ss;
                for (int j = mc[i - 1] + 1; ; j++)
                {
                    mc[i] = j;
                    for (int k = 0; k <= i; k++)
                    {
                        sum = mc[k] + j;
                        if (Contains(sums, sum, ss))
                        {
                            ss = le; goto nxtJ;
                        }
                        sums[ss++] = sum;
                    }
                    break;
                nxtJ:;
                }
            }
            return mc;
        }
 
        static void Main(string[] args)
        {
            Stopwatch sw = new Stopwatch();
            sw.Start();
            int[] mc = MianChowla();
            sw.Stop();
            Console.WriteLine("The first 30 terms of the Mian-Chowla sequence are:");
            for (int i = 0; i < 30; i++) Console.Write("{0} ", mc[i]);
            Console.WriteLine("\n\nTerms 91 to 100 of the Mian-Chowla sequence are:");
            for (int i = 90; i < 100; i++) Console.Write("{0} ", mc[i]);
            Console.WriteLine("\n\nComputation time was {0} seconds.", sw.Elapsed.TotalSeconds);
        }
    }
}

