        {
            if (HttpContext?.Request?.Url == null)
                return string.Empty;

            string path = HttpContext.Request.Url.AbsolutePath;
            return System.IO.Path.GetFileNameWithoutExtension(path);
        }
    }

    public class ClientDataCollection
    {
        private readonly Dictionary<string, object> _dataStore = new Dictionary<string, object>();

        public void Add(string key, object value)
        {
            lock (_dataStore)
            {
                _dataStore[key] = value;
            }
        }

        public T Get<T>(string key)
        {
            lock (_dataStore)
            {
                return _dataStore.TryGetValue(key, out object value) ? (T)value : default;
            }
        }

        public void Clear()
        {
            lock (_dataStore)
            {
                _dataStore.Clear();
            }
        }
    }

    public abstract class SessionBase
    {
        public abstract object this[string key] { get; set; }
        public abstract void Clear();
    }

