public class Fade : MonoBehaviour
{
    public Image UIImage; // The UI Image component for the fade effect
    public string ToLevel = "MainScene"; // The scene to transition to
    public float FadeSpeed = 0.8f; // Speed of the fade effect
    public int DrawDepth = -1000; // Depth at which the UI is drawn
    private float Alpha = 1.0f; // Alpha value of the image
    private int FadeDir = -1; // Direction of the fade (-1 for fade out, 1 for fade in)
    private float FadeTime = 0.0f; // Time elapsed during the fade

    void Start()
    {
        UIImage.color = new Color(UIImage.color.r, UIImage.color.g, UIImage.color.b, Alpha);
        UIImage.transform.SetSiblingIndex(DrawDepth);
        StartCoroutine(BeginFade(-1));
    }

    void OnGUI()
    {
        Alpha += FadeDir * FadeSpeed * Time.deltaTime;
        Alpha = Mathf.Clamp01(Alpha);
        UIImage.color = new Color(UIImage.color.r, UIImage.color.g, UIImage.color.b, Alpha);

        if (FadeTime > 1.0f && FadeDir == 1)
        {
            OnLevelWasLoaded(SceneManager.GetActiveScene().buildIndex);
        }
        FadeTime += Time.deltaTime;
    }

    IEnumerator BeginFade(int direction)
    {
        FadeDir = direction;
        Alpha = (FadeDir == -1) ? 1 : 0;
        FadeTime = 0.0f;

        while (!Mathf.Approximately(UIImage.color.a, (FadeDir == -1) ? 0 : 1))
        {
            Alpha += FadeDir * FadeSpeed * Time.deltaTime;
            Alpha = Mathf.Clamp01(Alpha);
            UIImage.color = new Color(UIImage.color.r, UIImage.color.g, UIImage.color.b, Alpha);
            yield return null;
        }

        if (FadeDir == -1)
        {
            FadeToLevel(ToLevel);
        }
    }

    void OnLevelWasLoaded(int level)
    {
        StartCoroutine(BeginFade(1));
    }

    public void ChangeLevel(string levelName)
    {
        StartCoroutine(FadeToLevel(levelName));
    }

    public void ResetLevel()
    {
        StartCoroutine(FadeToLevel(SceneManager.GetActiveScene().name));
    }

    IEnumerator FadeToLevel(int level)
    {
        yield return StartCoroutine(BeginFade(-1));
        SceneManager.LoadScene(level);
    }

    IEnumerator FadeToLevel(string levelName)
    {
        yield return StartCoroutine(BeginFade(-1));
        SceneManager.LoadScene(levelName);
    }

