using System;
using System.Threading.Tasks;

public struct Result<T>
{
    public bool IsSuccess { get; }
    public T Value { get; }
    public string Error { get; }

    private Result(T value, bool isSuccess, string error)
    {
        Value = value;
        IsSuccess = isSuccess;
        Error = error;
    }

    public static Result<T> Success(T value) => new Result<T>(value, true, null);
    public static Result<T> Failure(string error) => new Result<T>(default, false, error);
}

public static class PipelineExtensions
{
    public static Pipeline<T> Catch<T>(this Pipeline<T> pipeline, Func<Exception, Result<T>> errorHandler)
    {
        return pipeline.ContinueWith((res, _) =>
        {
            if (res.IsSuccess)
                return res;
            return errorHandler(new Exception(res.Error));
        });
    }

    public static Pipeline<T> Catch<T>(this Pipeline<T> pipeline, Func<Exception, Task<Result<T>>> errorHandler)
    {
        return pipeline.ContinueWith(async (res, _) =>
        {
            if (res.IsSuccess)
                return res;
            return await errorHandler(new Exception(res.Error));
        });
    }

    public static Pipeline<T> ContinueWith<T>(this Pipeline<T> pipeline, Func<Result<T>, T, Result<T>> nextStep)
    {
        return pipeline.ContinueWith((res, state) =>
        {
            if (res.IsSuccess)
                return nextStep(res, state);
            return res;
        });
    }

    public static Pipeline<T> ContinueWith<T>(this Pipeline<T> pipeline, Func<Result<T>, T, Task<Result<T>>> nextStep)
    {
        return pipeline.ContinueWith(async (res, state) =>
        {
            if (res.IsSuccess)
                return await nextStep(res, state);
            return res;
        });
    }

    public static Pipeline<TNew> ContinueWithNew<T, TNew>(this Pipeline<T> pipeline, Func<Result<T>, T, Result<TNew>> nextStep)
    {
        return pipeline.ContinueWith((res, state) =>
        {
            if (res.IsSuccess)
                return nextStep(res, state);
            return Result<TNew>.Failure(res.Error);
        });
    }

    public static Pipeline<TNew> ContinueWithNew<T, TNew>(this Pipeline<T> pipeline, Func<Result<T>, T, Task<Result<TNew>>> nextStep)
    {
        return pipeline.ContinueWith(async (res, state) =>
        {
            if (res.IsSuccess)
                return await nextStep(res, state);
            return Result<TNew>.Failure(res.Error);
        });
    }

