namespace Builder
{
    class Vector
    {
        static void Main(string[] args)
        {
            evalRPN("3 4 2 * 1 5 - 2 3 ^ ^ / +");
        }

        private static void evalRPN(string expr)
        {
            LinkedList<double> stack = new LinkedList<double>();
            Console.WriteLine("Input\tOperation\tStack after");
            foreach (string token in expr.Split(' '))
            {
                Console.Write(token + "\t");
                if (token.Equals("*"))
                {
                    Console.Write("Operate\t\t");
                    double secondOperand = stack.Pop();
                    double firstOperand = stack.Pop();
                    stack.Push(firstOperand * secondOperand);
                }
                else if (token.Equals("/"))
                {
                    Console.Write("Operate\t\t");
                    double secondOperand = stack.Pop();
                    double firstOperand = stack.Pop();
                    stack.Push(firstOperand / secondOperand);
                }
                else if (token.Equals("-"))
                {
                    Console.Write("Operate\t\t");
                    double secondOperand = stack.Pop();
                    double firstOperand = stack.Pop();
                    stack.Push(firstOperand - secondOperand);
                }
                else if (token.Equals("+"))
                {
                    Console.Write("Operate\t\t");
                    double secondOperand = stack.Pop();
                    double firstOperand = stack.Pop();
                    stack.Push(firstOperand + secondOperand);
                }
                else if (token.Equals("^"))
                {
                    Console.Write("Operate\t\t");
                    double secondOperand = stack.Pop();
                    double firstOperand = stack.Pop();
                    stack.Push(Math.Pow(firstOperand, secondOperand));
                }
                else
                {
                    Console.Write("Push\t\t");
                    try
                    {
                        stack.Push(Double.Parse(token));
                    }
                    catch (FormatException e)
                    {
                        Console.WriteLine("\nError: invalid token " + token);
                        return;
                    }
                }
                Console.WriteLine(stack);
            }

