using UnityEngine;
using System.Collections.Generic;

public class ShipSpriteController : MonoBehaviour
{
    private Dictionary<object, GameObject> objectGameObjectMap = new Dictionary<object, GameObject>();
    private World world;
    private SpriteManager spriteManager;

    void Start()
    {
        world = FindObjectOfType<World>();
        spriteManager = FindObjectOfType<SpriteManager>();

        if (world != null && world.ShipManager != null)
        {
            world.ShipManager.ShipCreated += OnCreated;
            world.ShipManager.ShipChanged += OnChanged;
            world.ShipManager.ShipRemoved += OnRemoved;
        }
    }

    void OnDestroy()
    {
        if (world != null && world.ShipManager != null)
        {
            world.ShipManager.ShipCreated -= OnCreated;
            world.ShipManager.ShipChanged -= OnChanged;
            world.ShipManager.ShipRemoved -= OnRemoved;
        }
    }

    private void OnCreated(object ship)
    {
        if (ship == null) return;

        GameObject shipGameObject = new GameObject("Ship");
        SpriteRenderer spriteRenderer = shipGameObject.AddComponent<SpriteRenderer>();
        Sprite shipSprite = spriteManager.GetSpriteForShip(ship);

        spriteRenderer.sprite = shipSprite;
        spriteRenderer.sortingLayerName = "Characters";

        UpdateShipPosition(ship, shipGameObject);
        UpdateShipVisibility(ship, shipGameObject);

        objectGameObjectMap[ship] = shipGameObject;
    }

    private void OnChanged(object ship)
    {
        if (ship == null || !objectGameObjectMap.ContainsKey(ship)) return;

        GameObject shipGameObject = objectGameObjectMap[ship];
        UpdateShipPosition(ship, shipGameObject);
        UpdateShipVisibility(ship, shipGameObject);
    }

    private void OnRemoved(object ship)
    {
        if (ship == null || !objectGameObjectMap.ContainsKey(ship)) return;

        GameObject shipGameObject = objectGameObjectMap[ship];
        Destroy(shipGameObject);
        objectGameObjectMap.Remove(ship);
    }

    private void UpdateShipPosition(object ship, GameObject shipGameObject)
    {
        Vector3 position = world.ShipManager.GetPosition(ship);
        shipGameObject.transform.position = position;
    }

    private void UpdateShipVisibility(object ship, GameObject shipGameObject)
    {
        bool isVisible = world.ShipManager.IsVisible(ship);
        shipGameObject.SetActive(isVisible);
    }
}

