public class Fade : MonoBehaviour
{
    // The UI Image component used for the fade overlay.
    public Image fadeImage;

    // Controls the speed of the fade transition.
    public float fadeSpeed = 0.8f;

    // Determines the rendering order of the fade overlay.
    public int drawDepth = -1000;

    // The target scene index for absolute transitions.
    private int toLevel = 0;

    // The current alpha value of the fade overlay.
    private float alpha = 1.0f;

    // Direction of the fade:
    // -1: fading in (decreasing alpha), 1: fading out (increasing alpha).
    private int fadeDir = -1;

    // Duration of the fade effect based on current parameters.
    private float fadeTime = 0f;

    // Called on script initialization.
    void Start()
    {
        // Try to auto-assign the fadeImage if not set.
        if (fadeImage == null)
        {
            fadeImage = GetComponent<Image>();
        }

        // Ensure the fade overlay renders above all other UI elements.
        if (fadeImage != null)
        {
            fadeImage.rectTransform.SetAsLastSibling();
            // Set initial color with current alpha.
            Color col = fadeImage.color;
            col.a = alpha;
            fadeImage.color = col;
        }
    }

    // Updates the fade effect every frame.
    void OnGUI()
    {
        // Update alpha based on the fade direction, speed and frame time.
        alpha += fadeDir * fadeSpeed * Time.deltaTime;
        // Clamp the alpha value between 0 and 1.
        alpha = Mathf.Clamp01(alpha);

        // Set the new color on the fade overlay.
        if (fadeImage != null)
        {
            Color col = fadeImage.color;
            col.a = alpha;
            fadeImage.color = col;
        }
    }

    // Begins the fade effect in a specified direction.
    // direction: 1 for fade out, -1 for fade in.
    public float BeginFade(int direction)
    {
        fadeDir = direction;
        // Calculate time required to complete the fade based on current alpha.
        fadeTime = Mathf.Abs(alpha - (direction < 0 ? 0f : 1f)) / fadeSpeed;
        return fadeTime;
    }

    // Initiates a scene change using an absolute scene index.
    public void FadeToLevel(int levelIndex)
    {
        toLevel = levelIndex;
        StartCoroutine(ChangeLevel());
    }

    // Initiates a scene change using a scene name.
    public void FadeToLevel(string sceneName)
    {

