public class ShipModuleController : MonoBehaviour
{
    private ShipModulesController _modulesController;
    private ModuleItemType _currentModule;
    private int _slotIndex;

    private void Awake()
    {
        _modulesController = GetComponentInParent<ShipModulesController>();
        _slotIndex = transform.GetSiblingIndex();
    }

    public void OnDropCargoItem(CargoHoldListItem cargoItem)
    {
        if (!ValidateCargoDrop(cargoItem, out ModuleItemType newModule)) return;

        if (_currentModule != null && !MoveExistingModuleToCargo()) return;

        EquipNewModule(cargoItem, newModule);
    }

    public void OnDropHardpointModule(ShipModuleController sourceModule)
    {
        if (!ValidateModuleSwap(sourceModule)) return;

        _modulesController.SwapModules(_slotIndex, sourceModule._slotIndex);
        SwapModuleVisuals(sourceModule);
    }

    private bool ValidateCargoDrop(CargoHoldListItem cargoItem, out ModuleItemType newModule)
    {
        newModule = cargoItem?.Module;

        if (newModule == null || !_modulesController.IsValidModuleType(newModule, _slotIndex))
        {
            _modulesController.ShowError("Invalid module type for this slot");
            return false;
        }
        return true;
    }

    private bool MoveExistingModuleToCargo()
    {
        if (!_modulesController.AddModuleToCargo(_currentModule))
        {
            _modulesController.ShowError("Cargo full - cannot replace module");
            return false;
        }
        _currentModule = null;
        return true;
    }

    private void EquipNewModule(CargoHoldListItem cargoItem, ModuleItemType newModule)
    {
        if (_modulesController.EquipModuleToSlot(newModule, _slotIndex))
        {
            cargoItem.RemoveFromCargo();
            _currentModule = newModule;
        }
        else
        {
            _modulesController.ShowError("Equipment failed - slot conflict");
        }
    }

    private bool ValidateModuleSwap(ShipModuleController sourceModule)
    {
        if (sourceModule == null || sourceModule._currentModule == null) return false;

        bool validSwap = _modulesController.IsValidModuleType(sourceModule._currentModule, _slotIndex) &&
                        _modulesController.IsValidModuleType(_currentModule, sourceModule._slotIndex);

        if (!validSwap) _modulesController.ShowError("Incompatible module types for swap");
        return validSwap;
    }

