namespace DynamicMappingDemo
{
    public class FieldMapping
    {
        // Base field mapping functionality can be defined here.
    }

    public abstract class DynamicFieldMapping : FieldMapping
    {
        public PropertyInfo Property { get; protected set; }

        protected DynamicFieldMapping(PropertyInfo property)
        {
            Property = property;
        }

        public static DynamicFieldMapping CreateDynamicFieldMapping(PropertyInfo property)
        {
            if (property == null)
                throw new ArgumentNullException(nameof(property));

            Type propertyType = property.PropertyType;

            // Reject unsupported types: arrays, generic parameters, or generic type definitions.
            if (propertyType.IsArray || propertyType.IsGenericParameter || propertyType.IsGenericTypeDefinition)
            {
                throw new NotSupportedException(
                    $"Property '{property.Name}' type '{propertyType.FullName}' is not supported.");
            }

            // Handle nullable types by extracting the underlying type.
            Type underlyingType = Nullable.GetUnderlyingType(propertyType);
            if (underlyingType != null)
            {
                propertyType = underlyingType;
            }

            // Select mapping based on whether the type is an enum.
            if (propertyType.IsEnum)
            {
                return new DynamicEnumFieldMapping(property);
            }

            // Default to primitive mapping for supported types.
            return new DynamicPrimitiveFieldMapping(property);
        }
    }

    public class DynamicEnumFieldMapping : DynamicFieldMapping
    {
        public DynamicEnumFieldMapping(PropertyInfo property)
            : base(property)
        {
            // Initialization specific to enum field mapping.
        }
    }

    public class DynamicPrimitiveFieldMapping : DynamicFieldMapping
    {
        public DynamicPrimitiveFieldMapping(PropertyInfo property)
            : base(property)
        {
            // Initialization specific to primitive field mapping.
        }
    }

