public class CellInfo
{
    public int Cost { get; set; }
    public bool Walkable { get; set; }
}

public class CellLayer<T>
{
    private T[,] grid;
    public int Width { get; }
    public int Height { get; }

    public CellLayer(int width, int height)
    {
        Width = width;
        Height = height;
        grid = new T[width, height];
    }

    public T this[int x, int y]
    {
        get => grid[x, y];
        set => grid[x, y] = value;
    }

    public void Clear(T defaultValue)
    {
        for (int x = 0; x < Width; x++)
        {
            for (int y = 0; y < Height; y++)
            {
                grid[x, y] = defaultValue;
            }
        }
    }
}

public class CellInfoLayerPool
{
    private Stack<CellLayer<CellInfo>> pool;
    private CellLayer<CellInfo> defaultLayer;
    private readonly object lockObject = new object();
    private const int MaxPoolSize = 4;

    public CellInfoLayerPool(int width, int height)
    {
        pool = new Stack<CellLayer<CellInfo>>(MaxPoolSize);
        defaultLayer = new CellLayer<CellInfo>(width, height);
        InitializeDefaultLayer();
    }

    private void InitializeDefaultLayer()
    {
        for (int x = 0; x < defaultLayer.Width; x++)
        {
            for (int y = 0; y < defaultLayer.Height; y++)
            {
                defaultLayer[x, y] = new CellInfo { Cost = 1, Walkable = true };
            }
        }
    }

    public CellLayer<CellInfo> GetLayer()
    {
        lock (lockObject)
        {
            if (pool.Count > 0)
            {
                var layer = pool.Pop();
                return layer;
            }
            else
            {
                var newLayer = new CellLayer<CellInfo>(defaultLayer.Width, defaultLayer.Height);
                newLayer.Clear(defaultLayer[0, 0]);
                return newLayer;
            }
        }
    }

    public void ReturnLayer(CellLayer<CellInfo> layer)
    {
        lock (lockObject)
        {
            if (pool.Count < MaxPoolSize)
            {
                layer.Clear(defaultLayer[0, 0]);
                pool.Push(layer);
            }
        }
    }
}

