                new KnapsackItem("map", 9, 150),
                new KnapsackItem("compass", 13, 35),
                new KnapsackItem("water", 153, 200),
                new KnapsackItem("sandwich", 50, 160),
                new KnapsackItem("glucose", 15, 60),
                new KnapsackItem("tin", 68, 45),
                new KnapsackItem("banana", 27, 60),
                new KnapsackItem("apple", 39, 40),
                new KnapsackItem("cheese", 23, 30),
                new KnapsackItem("beer", 52, 10),
                new KnapsackItem("suntan cream", 11, 70),
                new KnapsackItem("camera", 32, 30),
                new KnapsackItem("t-shirt", 24, 15),
                new KnapsackItem("trousers", 48, 10),
                new KnapsackItem("umbrella", 73, 40),
                new KnapsackItem("waterproof trousers", 42, 70),
                new KnapsackItem("waterproof overclothes", 43, 75),
                new KnapsackItem("note-case", 22, 80),
                new KnapsackItem("sunglasses", 7, 20),
                new KnapsackItem("towel", 18, 12),
                new KnapsackItem("socks", 4, 50),
                new KnapsackItem("book", 30, 10),
            };
            int knapsack_capacity = 400;

            var maxval = potential_items.PowerSet().GroupBy(subset =>
            {
                int weight = subset.Sum(elem => elem.weight);
                return weight > knapsack_capacity? 0 : subset.Sum(elem => elem.value);
            }).Max();

            var solutions = potential_items.PowerSet().GroupBy(subset =>
            {
                int weight = subset.Sum(elem => elem.weight);
                return weight > knapsack_capacity? 0 : subset.Sum(elem => elem.value);
            }).Where(x => x.Key == maxval);

            Console.WriteLine("value: {0}", maxval);
            foreach (var set in solutions)
            {
                int wt = 0;
                List<string> items = new List<string>();
                foreach (var elem in set)
                {
                    wt += elem.weight;
                    items.Add(elem.name);
                }
                Console.WriteLine("weight: {0}", wt);
                Console.WriteLine("items: {0}", string.Join(",", items));
            }
        }
    }

