public class HttpSendTransportProvider : ISendTransportProvider
{
    private readonly IEnumerable<IHttpHost> _hosts;
    private readonly IPipe<SendContext> _receivePipe;
    private readonly IReceiveObserver _receiveObserver;
    private readonly IEndpointTopology _topology;
    private readonly HttpClientCache _httpClientCache;

    public HttpSendTransportProvider(IEnumerable<IHttpHost> hosts, IPipe<SendContext> receivePipe, IReceiveObserver receiveObserver, IEndpointTopology topology)
    {
        _hosts = hosts;
        _receivePipe = receivePipe;
        _receiveObserver = receiveObserver;
        _topology = topology;
        _httpClientCache = new HttpClientCache();
    }

    public Task<ISendTransport> GetSendTransport(Uri address)
    {
        var host = SelectHost(address);
        var sendSettings = ParseSendSettings(address);

        return Task.FromResult<ISendTransport>(new HttpSendTransport(
            host,
            sendSettings,
            _httpClientCache,
            _receivePipe,
            _receiveObserver,
            _topology));
    }

    private IHttpHost SelectHost(Uri address)
    {
        foreach (var host in _hosts)
        {
            if (host.Matches(address))
            {
                return host;
            }
        }
        throw new ArgumentException("No suitable host found for the given address.");
    }

    private SendSettings ParseSendSettings(Uri address)
    {
        // Parse URI to extract send settings
        return new SendSettings
        {
            Timeout = TimeSpan.FromSeconds(30),
            Method = "POST"
        };
    }
}

