    public HttpSendTransport(IHttpHost host, SendSettings sendSettings, HttpClientCache httpClientCache, IPipe<SendContext> receivePipe, IReceiveObserver receiveObserver, IEndpointTopology topology)
    {
        _host = host;
        _sendSettings = sendSettings;
        _httpClientCache = httpClientCache;
        _receivePipe = receivePipe;
        _receiveObserver = receiveObserver;
        _topology = topology;
