public class PDEditorHelper : MonoBehaviour
{
    public Texture2D icon;
    public PDPlayer pdPlayer;
    public List<PDEditorModule> audioModules = new List<PDEditorModule>();

    private void OnDrawGizmos()
    {
        if (pdPlayer == null || audioModules == null) return;

        foreach (var module in audioModules)
        {
            if (module.Source == null) continue;

            Vector3 position = module.Source.transform.position;
            Gizmos.color = Color.cyan;
            Gizmos.DrawWireSphere(position, module.MinDistance);
            Gizmos.color = Color.yellow;
            Gizmos.DrawWireSphere(position, module.MaxDistance);
        }
    }

    [InitializeOnLoadMethod]
    private static void Initialize()
    {
        EditorApplication.hierarchyWindowItemOnGUI += OnHierarchyWindowItemGUI;
    }

    private static void OnHierarchyWindowItemGUI(int instanceID, Rect selectionRect)
    {
        GameObject gameObject = EditorUtility.InstanceIDToObject(instanceID) as GameObject;
        if (gameObject == null) return;

        PDPlayer player = gameObject.GetComponent<PDPlayer>();
        if (player == null) return;

        PDEditorHelper helper = player.GetComponent<PDEditorHelper>();
        if (helper == null || helper.icon == null) return;

        Rect iconRect = new Rect(selectionRect.x + selectionRect.width - 20, selectionRect.y, 16, 16);
        GUI.DrawTexture(iconRect, helper.icon);
    }
}

