using NUnit.Framework;
using StructureMap;
using StructureMap.Testing;

public class ThreadLocalStorageLifecycleTester_with_nested_containers
{
    private Container container;
    private IContainer nestedContainer;
    private ThreadLocalStorageLifecycle lifecycle;

    [SetUp]
    public void SetUp()
    {
        lifecycle = new ThreadLocalStorageLifecycle();
        container = new Container(cfg =>
        {
            cfg.For<Rule>().LifecycleIs(lifecycle).Use<ColorRule>();
        });

        nestedContainer = container.GetNestedContainer();
        nestedContainer.Configure(cfg =>
        {
            cfg.For<Rule>().LifecycleIs(new TransientLifecycle()).Use<ColorRule>();
        });
    }

    [Test]
    public void Overrides_Lifecycle()
    {
        var ruleFromMainContainer = container.GetInstance<Rule>();
        var ruleFromNestedContainer = nestedContainer.GetInstance<Rule>();

        Assert.AreNotSame(ruleFromMainContainer, ruleFromNestedContainer, "Objects should be different due to different lifecycles.");
    }

    [Test]
    public void Does_not_cache_item()
    {
        var rule1 = container.GetInstance<Rule>();
        var rule2 = container.GetInstance<Rule>();

        Assert.AreSame(rule1, rule2, "Objects should be the same due to lifecycle caching.");

        lifecycle.DisposeAndClear();

        var rule3 = container.GetInstance<Rule>();
        Assert.AreNotSame(rule1, rule3, "Objects should be different after lifecycle is cleared.");
    }
}

public abstract class Rule { }
public class ColorRule : Rule { }

using System;
using static System.Linq.Enumerable;
 
public class Sorter
{
    static void Main()
    {
        SqueezeAndPrint("", ' ');
        SqueezeAndPrint("\"If I were two-faced, would I be wearing this one?\" --- Abraham Lincoln ", '-');
        SqueezeAndPrint("..1111111111111111111111111111111111111111111111111111111111111117777888", '7');
        SqueezeAndPrint("I never give 'em hell, I just tell the truth, and they think it's hell. ", '.');
        string s = "                                                    --- Harry S Truman  ";
        SqueezeAndPrint(s, ' ');
        SqueezeAndPrint(s, '-');
        SqueezeAndPrint(s, 'r');
    }
 
    static void SqueezeAndPrint(string s, char c) {
        Console.WriteLine($"squeeze: '{c}'");
        Console.WriteLine($"old: {s.Length} «««{s}»»»");
        s = Squeeze(s, c);
        Console.WriteLine($"new: {s.Length} «««{s}»»»");
    }
 
    static string Squeeze(string s, char c) => string.IsNullOrEmpty(s) ? "" :
        s[0] + new string(Range(1, s.Length - 1).Where(i => s[i] != c || s[i] != s[i - 1]).Select(i => s[i]).ToArray());
}

