using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class SelectelClient
{
    private readonly HttpClient _httpClient;
    public string StorageUrl { get; private set; }
    public string CDNUrl { get; private set; }
    public string AuthToken { get; private set; }
    public DateTime ExpireAuthToken { get; private set; }

    public SelectelClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<bool> AuthorizeAsync(string username, string password, string proxyUrl = null)
    {
        if (!string.IsNullOrEmpty(proxyUrl))
        {
            var webProxy = new WebProxy(proxyUrl);
            _httpClient.DefaultProxy = webProxy;
        }

        var authRequest = new AuthRequest { Username = username, Password = password };
        var response = await ExecuteAsync("https://api.selectel.ru/v1/auth", authRequest);

        if (response.IsSuccessStatusCode)
        {
            var responseBody = await response.Content.ReadAsStringAsync();
            // Assume here we're setting the storageUrl and AuthToken from responseBody
            StorageUrl = "https://storage.selectel.ru"; // Should come from response.
            AuthToken = "token_from_response"; // Should come from response.
            CDNUrl = $"{StorageUrl}/cdn"; // Example of building CDN URL
            ExpireAuthToken = DateTime.UtcNow.AddHours(1); // Token expiration time
            return true;
        }

        return false;
    }

    public bool Authorize(string username, string password, string proxyUrl = null)
    {
        return AuthorizeAsync(username, password, proxyUrl).GetAwaiter().GetResult();
    }

    public async Task<HttpResponseMessage> ExecuteAsync(string url, BaseRequest<string> request)
    {
        CheckTokenNotNull();

        var requestJson = new StringContent(request.ToJson(), Encoding.UTF8, "application/json");
        _httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", AuthToken);
        return await _httpClient.PostAsync(url, requestJson);
    }

    private void CheckTokenNotNull()
    {
        if (string.IsNullOrEmpty(AuthToken) || DateTime.UtcNow >= ExpireAuthToken)
        {
            throw new InvalidOperationException("Authorization token is missing or expired.");
        }
    }
}

public class AuthRequest
{
    public string Username { get; set; }
    public string Password { get; set; }
}

public abstract class BaseRequest<T>
{
    public abstract string ToJson();
}

using System;

namespace NCDK.FaulonSignatures
{
    public class InvariantIntStringPair : IComparable<InvariantIntStringPair>
    {
        private readonly string stringValue;
        private readonly int value;
        private readonly int originalIndex;

        public InvariantIntStringPair(string stringValue, int value, int originalIndex)
        {
            this.stringValue = stringValue;
            this.value = value;
            this.originalIndex = originalIndex;
        }

        public int GetOriginalIndex()
        {
            return originalIndex;
        }

        public bool Equals(string stringValue, int value)
        {
            return this.stringValue == stringValue && this.value == value;
        }

        public bool Equals(InvariantIntStringPair other)
        {
            if (other == null) return false;
            return stringValue == other.stringValue && value == other.value;
        }

        public int CompareTo(InvariantIntStringPair other)
        {
            if (other == null) return 1;

            int stringComparison = string.Compare(stringValue, other.stringValue, StringComparison.Ordinal);
            if (stringComparison != 0)
            {
                return stringComparison;
            }

            return value.CompareTo(other.value);
        }

        public override bool Equals(object obj)
        {
            if (obj is InvariantIntStringPair other)
            {
                return Equals(other);
            }
            return false;
        }

        public override int GetHashCode()
        {
            return (stringValue, value).GetHashCode();
        }

        public override string ToString()
        {
            return $"String: {stringValue}, Value: {value}, OriginalIndex: {originalIndex}";
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ShipsServer.Common;
using ShipsServer.Enums;

public class Battle
{
    public int Id { get; private set; }
    public BattleStatus Status { get; private set; } = BattleStatus.Initial;
    private List<Player> _players = new List<Player>();

    public Battle(int id)
    {
        Id = id;
    }

    public void AddPlayer(Session session, Board board)
    {
        if (_players.Count >= Constants.MAX_BATTLE_PLAYERS)
            throw new InvalidOperationException("Maximum number of players reached.");

        var player = new Player(session, board);
        _players.Add(player);
    }

    public Player GetPlayer(int idx)
    {
        if (idx < 0 || idx >= _players.Count)
            throw new ArgumentOutOfRangeException(nameof(idx), "Invalid player index.");

        return _players[idx];
    }

    public Player GetPlayerBySession(Session session)
    {
        return _players.FirstOrDefault(p => p.Session.AccountId == session.AccountId);
    }

    public Player GetOponentPlayer(Session session)
    {
        return _players.FirstOrDefault(p => p.Session.AccountId != session.AccountId);
    }

    public void Finish(Player winner, Player loser)
    {
        if (Status == BattleStatus.Done)
            throw new InvalidOperationException("Battle is already finished.");

        Status = BattleStatus.Done;

        winner.Session.BattleStatistics.Wins++;
        loser.Session.BattleStatistics.Losses++;

        winner.Session.BattleStatistics.LastBattleTimestamp = Time.UnixTimeNow();
        loser.Session.BattleStatistics.LastBattleTimestamp = Time.UnixTimeNow();
    }
}

public class Player
{
    public Session Session { get; }
    public Board Board { get; }

    public Player(Session session, Board board)
    {
        Session = session;
        Board = board;
    }
}

public class Session
{
    public int AccountId { get; set; }
    public BattleStatistics BattleStatistics { get; set; } = new BattleStatistics();
}

public class BattleStatistics
{
    public int Wins { get; set; }
    public int Losses { get; set; }
    public long LastBattleTimestamp { get; set; }
}

