        private string onlineListCSV
        {
            get
            {
                StringBuilder sb = new StringBuilder();
                sb.Append(clients.Count).Append(" user(s) online: ");
                for (int i = 0; i < clients.Count; i++)
                {
                    sb.Append(i > 0? ", " : "").Append(clients[i].clientName);
                }
                return sb.ToString();
            }
        }

        public ChatServer(int port)
        {
            this.port = port;
        }

        public void run()
        {
            try
            {
                TcpListener ss = new TcpListener(IPAddress.Any, port);
                ss.Start();
                while (true)
                {
                    TcpClient s = ss.AcceptTcpClient();
                    Task.Run(() => new Client(s).run());
                }
            }
            catch (Exception e)
            {
                e.printStackTrace();
            }
        }

        private bool registerClient(Client client)
        {
            foreach (Client otherClient in clients)
            {
                if (otherClient.clientName.Equals(client.clientName, StringComparison.CurrentCultureIgnoreCase))
                {
                    return false;
                }
            }
            clients.Add(client);
            return true;
        }

        private void deRegisterClient(Client client)
        {
            bool wasRegistered = false;
            lock (this)
            {
                wasRegistered = clients.Remove(client);
            }
            if (wasRegistered)
            {
                broadcast(client, "--- " + client.clientName + " left ---");
            }
        }

