            // The pattern is constructed in 5 segments:
            // 1. Centered horizontal asterisk line at the top.
            // 2. Upper expanding section.
            // 3. Full border row.
            // 4. Lower contracting section.
            // 5. Concluding centered horizontal asterisk line at the bottom.

            // Segment 1: Top centered horizontal asterisk line.
            int topDots = 2 * n;
            Console.WriteLine(new string('.', topDots) + new string('*', n) + new string('.', topDots));

            // Segment 2: Upper Expanding Section.
            // For each row in this section, the side dots decrease and inner dot gaps increase.
            for (int row = 0; row < n; row++)
            {
                // Left padding dots
                int leftDots = 2 * n - 1 - row;
                // Inner padding for the two inner sections (they expand as row increases)
                int innerDots = row;
                // The center section has fixed dots count: (n - 2) dots remains constant.
                int centerDots = n - 2;

                // Build the pattern for the current row.
                // The pattern: leftDots + "*" + innerDots + "*" + centerDots + "*" + innerDots + "*" + leftDots
                string line = new string('.', leftDots) +
                              "*" +
                              new string('.', innerDots) +
                              "*" +
                              new string('.', centerDots) +
                              "*" +
                              new string('.', innerDots) +
                              "*" +
                              new string('.', leftDots);
                Console.WriteLine(line);
            }

            // Segment 3: Full-line border of asterisks.
            Console.WriteLine(new string('*', width));

            // Segment 4: Lower Contracting Section.
            // This is a mirror of the Upper Expanding Section.
            for (int row = n - 1; row >= 0; row--)
            {
                int leftDots = 2 * n - 1 - row;
                int innerDots = row;
                int centerDots = n - 2;

