using System;
using System.Collections.Generic;
 
namespace LoopsWithMultipleRanges
{
    class LoopsWithMultipleRanges
    {
        private static long sum = 0;
        private static long prod = 1;
 
        static void Main(string[] args)
        {
            long x = 5;
            long y = -5;
            long z = -2;
            long one = 1;
            long three = 3;
            long seven = 7;
 
            List<long> jList = new List<long>();
            for (long j = -three; j <= Math.Pow(3, 3); j += three) jList.Add(j);
            for (long j = -seven; j <= seven; j += x) jList.Add(j);
            for (long j = 555; j <= 550 - y; j += 1) jList.Add(j);
            for (long j = 22; j >= -28; j += -three) jList.Add(j);
            for (long j = 1927; j <= 1939; j += 1) jList.Add(j);
            for (long j = x; j >= y; j += z) jList.Add(j);
            for (long j = Math.Pow(11, x); j <= Math.Pow(11, x) + one; j += 1) jList.Add(j);
 
            List<long> prodList = new List<long>();
            foreach (long j in jList)
            {
                sum += Math.Abs(j);
                if (Math.Abs(prod) < Math.Pow(2, 27) && j!= 0)
                {
                    prodList.Add(j);
                    prod *= j;
                }
            }
 
            Console.WriteLine(" sum        = {0,10:N0}", sum);
            Console.WriteLine("prod        = {0,10:N0}", prod);
            Console.WriteLine("j values    = {0}", string.Join(", ", jList));
            Console.WriteLine("prod values = {0}", string.Join(", ", prodList));
        }
    }
}

