namespace TributacaoTest
{
    [TestClass]
    public class CalculoPisTest
    {
        [TestMethod]
        public void CalculoPis()
        {
            // Arrange
            var produto = new Produto
            {
                PercentualPis = 0.65M,
                ValorProduto = 100.00M,
                QuantidadeProduto = 10
            };

            var facade = new FacadeCalculadoraTributacao();
            var resultado = facade.CalculaPis(produto);

            // Assert
            Assert.AreEqual(65.00M, resultado.Valor, "O valor do PIS está incorreto.");
            Assert.AreEqual(1000.00M, resultado.BaseCalculo, "A base de cálculo do PIS está incorreta.");
        }

        [TestMethod]
        public void CalculoPisComIpi()
        {
            // Arrange
            var produto = new Produto
            {
                PercentualPis = 0.65M,
                ValorProduto = 100.00M,
                QuantidadeProduto = 10,
                ValorIpi = 150.00M
            };

            var facade = new FacadeCalculadoraTributacao();
            var resultado = facade.CalculaPis(produto);

            // Assert
            Assert.AreEqual(81.50M, resultado.Valor, "O valor do PIS está incorreto.");
            Assert.AreEqual(1150.00M, resultado.BaseCalculo, "A base de cálculo do PIS está incorreta.");
        }

        [TestMethod]
        public void CalculoPisComIpiZero()
        {
            // Arrange
            var produto = new Produto
            {
                PercentualPis = 0.65M,
                ValorProduto = 100.00M,
                QuantidadeProduto = 10,
                ValorIpi = 0.00M
            };

            var facade = new FacadeCalculadoraTributacao();
            var resultado = facade.CalculaPis(produto);

            // Assert
            Assert.AreEqual(65.00M, resultado.Valor, "O valor do PIS está incorreto.");
            Assert.AreEqual(1000.00M, resultado.BaseCalculo, "A base de cálculo do PIS está incorreta.");
        }
    }

    public class Produto : IProduto
    {
        public decimal PercentualPis { get; set; }
        public decimal ValorProduto { get; set; }
        public decimal QuantidadeProduto { get; set; }
        public decimal? ValorIpi { get; set; }

        public decimal ValorTotal => ValorProduto * QuantidadeProduto;
        public decimal BaseCalculo => ValorTotal + (ValorIpi ?? 0);
    }
