using System;
using NUnit.Framework;
using StructureMap;
using StructureMap.Pipeline;

[TestFixture]
public class ThreadLocalStorageLifecycleTests
{
    private IContainer _container;

    [SetUp]
    public void SetUp()
    {
        _container = new Container(config =>
        {
            config.For<ColorRule>().LifecycleIs<ThreadLocalStorageLifecycle>();
            config.For<IColorService>().Use<ColorService>();
        });
    }

    [Test]
    public void VerifyThreadLocalStorageBehaviorInNestedContainer()
    {
        // Primary container instance
        var primaryColorRule = _container.GetInstance<ColorRule>();
        Assert.IsNotNull(primaryColorRule);

        // Create nested container
        using (var nestedContainer = _container.CreateChildContainer())
        {
            nestedContainer.Configure(config =>
            {
                config.For<ColorRule>().Use(() => new ColorRule("Red"));
            });

            var nestedColorRule = nestedContainer.GetInstance<ColorRule>();
            Assert.IsNotNull(nestedColorRule);

            // Compare instances across containers
            Assert.AreNotSame(primaryColorRule, nestedColorRule);
            Assert.AreEqual("Red", nestedColorRule.Color);
        }
    }

    [Test]
    public void TestThreadLocalCachingMechanisms()
    {
        // Validate thread-local instance consistency
        var firstInstance = _container.GetInstance<ColorRule>();
        var secondInstance = _container.GetInstance<ColorRule>();

        Assert.AreSame(firstInstance, secondInstance);
    }

    [Test]
    public void EvaluateNestedContainerScopingStrategies()
    {
        using (var nestedContainer = _container.CreateChildContainer())
        {
            nestedContainer.Configure(config =>
            {
                config.For<ColorRule>().LifecycleIs(new TransientLifecycle());
            });

            var firstNestedRule = nestedContainer.GetInstance<ColorRule>();
            var secondNestedRule = nestedContainer.GetInstance<ColorRule>();

            Assert.AreNotSame(firstNestedRule, secondNestedRule);
        }
    }
}

