// Purpose:
//   Defines an enumeration that specifies the strategies for processing UDP packets
//   on a server. This enumeration enables selection between sequential and parallel
//   processing, influencing both the order of packet handling and concurrency behavior.
//
// Description:
//   - Sequential processing ensures that one UDP packet is completely handled before
//     initiating the processing of the next. This can help maintain order and reduce
//     concurrency issues in environments where packet order integrity is critical.
//   - Parallel processing allows UDP packets to be processed concurrently, potentially
//     improving performance in high-load scenarios, but at the risk of introducing
//     race conditions and requiring careful synchronization.
//
// Notes:
//   This enumeration is intended to be part of the UDP server framework and can be
//   used for external configuration or runtime decision-making regarding packet handling.
//------------------------------------------------------------------------------

using System;

namespace UdpServerLibrary
{
    /// <summary>
    /// Enumeration that defines the processing mode for incoming UDP packets.
    /// </summary>
    public enum UdpPacketProcessingMode
    {
        /// <summary>
        /// Sequential Processing:
        /// Processes UDP packets one after another in the order they are received.
        /// This mode guarantees that each packet has been completely processed before
        /// handling the next one, ensuring strict ordering and consistency.
        /// </summary>
        Sequential = 0,

        /// <summary>
        /// Parallel Processing:
        /// Allows UDP packets to be processed concurrently.
        /// This mode can improve performance under heavy loads by processing multiple
        /// packets simultaneously. However, it requires careful management of shared
        /// resources to avoid race conditions and other concurrency issues.
        /// </summary>
        Parallel = 1
    }

