using NUnit.Framework;
using StructureMap.Pipeline;
using StructureMap.Testing.Widget;

namespace StructureMap.Testing
{
    [TestFixture]
    public class ThreadLocalStorageLifecycleTester_with_nested_containers
    {
        private Container container;
        private Container nestedContainer;
        private ILifecycle lifecycle;
        private int count;

        [SetUp]
        public void SetUp()
        {
            count = 0;
            lifecycle = new ThreadLocalStorageLifecycle();

            container = new Container(x =>
            {
                x.For<Rule>().LifecycleIs(lifecycle).Use<ColorRule>()
                    .Ctor<int>().Is(() => count++);
            });

            nestedContainer = container.GetNestedContainer();
            nestedContainer.Configure(x =>
            {
                x.For<Rule>().Use<ColorRule>()
                    .Ctor<int>().Is(() => count++);
            });
        }

        [Test]
        public void Overrides_Lifecycle()
        {
            var ruleFromMain = container.GetInstance<Rule>();
            var ruleFromNested = nestedContainer.GetInstance<Rule>();

            ruleFromMain.ShouldBeOfType<ColorRule>();
            ruleFromNested.ShouldBeOfType<ColorRule>();

            ruleFromMain.ShouldNotBeTheSameAs(ruleFromNested);
        }

        [Test]
        public void Does_not_cache_item()
        {
            var ruleFromMain = container.GetInstance<Rule>();
            var ruleFromNested = nestedContainer.GetInstance<Rule>();

            var cache = lifecycle.GetCacheFor<ColorRule>(container.Model);

            cache.Has(typeof(ColorRule)).ShouldBeFalse();
        }

        public class ColorRule : Rule
        {
            public ColorRule(int id)
            {
                Id = id;
            }

            public int Id { get; }
        }

        public abstract class Rule { }
    }
}

using CastleMaster.Graphics;
using CastleMaster.Guis;
using CastleMaster.Players;
using CastleMaster.World;

public class UnitStore : GameBuilding
{
    private const int COINS_FOR_LUMBER = 5;
    private const int MAX_LUMBER_TRANSFER = 100;

    private Sprite buildingSprite;
    private GuiStoreMenu menu;
    private RenderHelper renderHelper;
    private float spriteX, spriteY;
    private bool isFocused;

    public UnitStore(PlayerContext owner, Vector2 position)
    {
        Owner = owner;
        Position = position;
        Health = 500;
        InitializeRendering();
        SetupStoreMenu();
    }

    private void InitializeRendering()
    {
        buildingSprite = AssetManager.LoadSprite("store_building");
        spriteX = Position.X - buildingSprite.Width / 2;
        spriteY = Position.Y - buildingSprite.Height;
        renderHelper = new RenderHelper(buildingSprite);
    }

    private void SetupStoreMenu()
    {
        menu = new GuiStoreMenu(this);
        menu.AddResourceConverter(ResourceType.Lumber, ResourceType.Coins, COINS_FOR_LUMBER);
    }

    public void SellWood(int lumberAmount)
    {
        int clampedAmount = Math.Min(lumberAmount, MAX_LUMBER_TRANSFER);

        if (Owner.Resources.CanSubtract(ResourceType.Lumber, clampedAmount))
        {
            Owner.Resources.Subtract(ResourceType.Lumber, clampedAmount);
            int coinEarned = clampedAmount * COINS_FOR_LUMBER;
            Owner.Resources.Add(ResourceType.Coins, coinEarned);
        }
    }

    public void OnFocus()
    {
        if (!isFocused)
        {
            isFocused = true;
            menu.Open();
            renderHelper.HighlightBuilding();
        }
    }

    public void OnFocusLost()
    {
        if (isFocused)
        {
            isFocused = false;
            menu.Close();
            renderHelper.ResetHighlight();
        }
    }

    public void Render(Viewport viewport)
    {
        renderHelper.DrawSprite(spriteX, spriteY);

        if (isFocused)
        {
            renderHelper.DrawFocusIndicator();
        }
    }

    public void Remove()
    {
        Owner.RemoveBuilding(this);
        renderHelper.Dispose();
        menu.Close();
    }

    public override void Update(GameTime gameTime)
    {
        base.Update(gameTime);
        CheckStructuralIntegrity();
    }

    private void CheckStructuralIntegrity()
    {
        if (Health <= 0)
        {
            Remove();
        }
    }
}

