            while (!testCompleted && currentScenarioIndex < testScenarios.Count)
            {
                var currentScenario = testScenarios[currentScenarioIndex];
                bool scenarioPassed = EvaluateHitObject(currentScenario);

                if (!scenarioPassed)
                {
                    return false;
                }

                currentScenarioIndex++;
            }

            testCompleted = true;
            return true;
        }

