    public void FirstWithAttributeConstraint_ShouldRetrieveElementWithSpecifiedId()
    {
        ExecuteTest(browser =>
        {
            var elements = browser.Elements.Filter(Find.ByTag("button"));
            var element = elements.FirstWithAttributeConstraint(Find.ById("helloid"));

            Assert.IsNotNull(element, "Element with ID 'helloid' not found");
            Assert.IsInstanceOf<Button>(element, "Retrieved element is not a button");
            Assert.AreEqual("helloid", element.Id, "Element ID mismatch");
        });
    }

    [Test]
    public void First_ShouldReturnInitialElementInCollection()
    {
        ExecuteTest(browser =>
        {
            var buttons = browser.Buttons;
            var firstElement = buttons.First();

            Assert.IsNotNull(firstElement, "No elements found in collection");
            Assert.IsTrue(firstElement.Exists, "Element should exist in DOM");
            Assert.AreEqual("popupid", firstElement.Id, "Unexpected first element ID");
        });
    }

