    {
        ExecuteTest(browser =>
        {
            var constraint = Find.ById("helloid") && Find.ByClass("interactive");
            var element = browser.Elements.FirstWithAttributeConstraint(constraint);

            Assert.IsNotNull(element, "Element with combined constraints not found");
            Assert.AreEqual("button", element.TagName.ToLower(), "Element tag mismatch");
        });
