public class HttpSendTransportProvider : ISendTransportProvider
{
    private readonly BusHostCollection<HttpHost> _hosts;
    private readonly IReceivePipe _receivePipe;
    private readonly IReceiveObserver _receiveObserver;
    private readonly IReceiveEndpointTopology _topology;
    private readonly HttpClientCache _httpClientCache;

    public HttpSendTransportProvider(
        BusHostCollection<HttpHost> hosts,
        IReceivePipe receivePipe,
        IReceiveObserver receiveObserver,
        IReceiveEndpointTopology topology,
        HttpClientCache httpClientCache)
    {
        _hosts = hosts ?? throw new ArgumentNullException(nameof(hosts));
        _receivePipe = receivePipe ?? throw new ArgumentNullException(nameof(receivePipe));
        _receiveObserver = receiveObserver ?? throw new ArgumentNullException(nameof(receiveObserver));
        _topology = topology ?? throw new ArgumentNullException(nameof(topology));
        _httpClientCache = httpClientCache ?? throw new ArgumentNullException(nameof(httpClientCache));
    }

    public async Task<ISendTransport> GetSendTransport(Uri address)
    {
        if (address == null)
            throw new ArgumentNullException(nameof(address));

        var hostSettings = _hosts.GetHostSettings(address);
        if (hostSettings == null)
            throw new EndpointNotFoundException($"Host not found for address: {address}");

        var httpClient = _httpClientCache.GetClient(hostSettings);

        var transport = new HttpSendTransport(
            httpClient,
            _receivePipe,
            _receiveObserver,
            _topology,
            hostSettings);

        return transport;
    }
}

