namespace Builder
{
    class Checker
    {
        static void Main(string[] args)
        {
            var f = File.Open("rc.fasta", FileMode.Open);
            var s = new StreamReader(f);
            var headerFound = false;
            while (!s.EndOfStream)
            {
                var line = s.ReadLine();
                switch (line)
                {
                    case "":
                        continue;
                    case var _ when line[0]!= '>':
                        if (!headerFound)
                        {
                            Console.WriteLine("missing header");
                            return;
                        }
                        Console.Write(line);
                        break;
                    case var _ when headerFound:
                        Console.WriteLine();
                        goto case "";
                    default:
                        Console.WriteLine($"{line.Substring(1)}: ");
                        headerFound = true;
                        break;
                }
            }
            if (headerFound)
            {
                Console.WriteLine();
            }
            s.Close();
            f.Close();
        }
    }
}

