public class Manager
{
    public static void Main()
    {
        var res = Enumerable.Range(1, 20000).Select(n => n.ProperDivisors().Sum()).Select(n => n.CompareTo(n)).GroupBy(n => n).ToDictionary(n => n.Key, n => n.Count());
        Console.WriteLine("Deficient: {0}   Perfect: {1}   Abundant: {2}", res[-1], res[0], res[1]);
    }
