namespace ModularAppEntryPoint {
    static class Task {
        /// <summary>
        /// The main entry point for the application.
        /// </summary>
        [STAThread]
        static void Main() {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);

            try {
                // Create instance of the custom WinApplication
                MyWinApplication application = new MyWinApplication();

                // Dynamic connection string setup using configuration file
                string connectionString = ConfigurationManager.ConnectionStrings["MyDatabaseConnection"]?.ConnectionString;
                if (!string.IsNullOrEmpty(connectionString)) {
                    application.ConnectionString = connectionString;
                }
                else {
                    throw new Exception("Connection string 'MyDatabaseConnection' not found in configuration.");
                }

                // If debugging, automatically grant permissions for rapid development/testing
                if (Debugger.IsAttached) {
                    application.Security = new SecurityStrategyComplex(typeof(object), typeof(AuthenticationStandard), null);
                }

#if AUTOMATED_TESTING
                // Any additional setup for automated tests can be initialized here
                application.Setup();
                application.TestMode = true;
#else
                // Normal runtime setup
                application.Setup();
#endif

                // Validate database schema if needed when debugger is attached
                if (Debugger.IsAttached && ConfigurationManager.AppSettings["AlwaysUpdateDatabase"] == "true") {
                    application.DatabaseUpdateMode = DatabaseUpdateMode.UpdateDatabaseAlways;
                }
                else {
                    application.DatabaseUpdateMode = DatabaseUpdateMode.NeverUpdateDatabase;
                }

                // Start the application
                application.Start();
            }
            catch (Exception ex) {
                // Log error and show message box for graceful shutdown
                MessageBox.Show("Error during application initialization: " + ex.Message, "Initialization Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }

using UnityEngine;
using UnityEngine.UI;
using System.Collections;
using System.Collections.Generic;
using System.Threading.Tasks;

public class EndScreenController : MonoBehaviour
{
    [SerializeField] private Text winnerText;
    [SerializeField] private Text player1Text;
    [SerializeField] private Text player2Text;
    [SerializeField] private Text pointsText;
    [SerializeField] private Text nextMatchesText;

    [SerializeField] private GameObject loadingPanel;
    [SerializeField] private GameObject errorPanel;

    private MatchInfo currentMatchInfo;
    private List<Bot> nextLeftPlayers;
    private List<Bot> nextRightPlayers;

    private const int MAX_RETRY_ATTEMPTS = 3;

    private void OnEnable()
    {
        StartCoroutine(InitializeEndScreen());
    }

    private IEnumerator InitializeEndScreen()
    {
        loadingPanel.SetActive(true);
        errorPanel.SetActive(false);

        yield return StartCoroutine(DownloadMatchResults());
        yield return StartCoroutine(DownloadUpcomingMatches());

        UpdateEndScreenUI();
        loadingPanel.SetActive(false);
    }

    private IEnumerator DownloadMatchResults()
    {
        int retryCount = 0;
        while (retryCount < MAX_RETRY_ATTEMPTS)
        {
            Task<MatchInfo> matchInfoTask = DownloadMatchInfoAsync();
            yield return new WaitUntil(() => matchInfoTask.IsCompleted);

            if (matchInfoTask.Status == TaskStatus.RanToCompletion)
            {
                currentMatchInfo = matchInfoTask.Result;
                break;
            }

            retryCount++;
            yield return new WaitForSeconds(2f);
        }

        if (currentMatchInfo == null)
        {
            errorPanel.SetActive(true);
        }
    }

    private IEnumerator DownloadUpcomingMatches()
    {
        int retryCount = 0;
        while (retryCount < MAX_RETRY_ATTEMPTS)
        {
            Task<List<Bot>> leftPlayersTask = DownloadLeftPlayersAsync();
            Task<List<Bot>> rightPlayersTask = DownloadRightPlayersAsync();

            yield return new WaitUntil(() => leftPlayersTask.IsCompleted && rightPlayersTask.IsCompleted);

            if (leftPlayersTask.Status == TaskStatus.RanToCompletion &&
                rightPlayersTask.Status == TaskStatus.RanToCompletion)
            {
                nextLeftPlayers = leftPlayersTask.Result;
                nextRightPlayers = rightPlayersTask.Result;
                break;
            }

            retryCount++;
            yield return new WaitForSeconds(2f);
        }
    }

