    {
        [XmlElement("TextRepresentation")]
        public string TextRepresentation { get; set; }

        [XmlElement("Comment")]
        public string Comment { get; set; }

        public abstract string GetCodeType();
    }

    public class Sharp : Code
    {
        public override string GetCodeType() => "C#";
    }

    public class IL : Code
    {
        public override string GetCodeType() => "IL";
    }

    public class Asm : Code
    {
        public override string GetCodeType() => "Assembly";
    }

    [XmlRoot("DisassembledMethod")]
    public class DisassembledMethod
    {
        [XmlElement("Name")]
        public string Name { get; set; }

        [XmlElement("StartAddress")]
        public string StartAddress { get; set; }

        [XmlElement("EndAddress")]
        public string EndAddress { get; set; }

        [XmlElement("NativeCode")]
        public string NativeCode { get; set; }

        [XmlElement("Problem")]
        public string Problem { get; set; }

        [XmlArray("Maps")]
        [XmlArrayItem("Map")]
        public List<Map> Maps { get; set; }

        public DisassembledMethod()
        {
            Maps = new List<Map>();
        }

        public static DisassembledMethod Empty()
        {
            return new DisassembledMethod
            {
                Name = "Unknown",
                StartAddress = "0x0",
                EndAddress = "0x0",
                NativeCode = string.Empty,
                Problem = string.Empty
            };
        }
    }

    [XmlRoot("Map")]
    public class Map
    {
        [XmlElement("FilePath")]
