namespace UDPProcessing
{
    /// <summary>
    /// Defines the processing modes for handling UDP packets.
    /// </summary>
    public enum UDP_ProcessMode
    {
        /// <summary>
        /// Processes packets in the order they are received, ensuring that
        /// the sequence of packets is preserved.
        /// </summary>
        Sequential,

        /// <summary>
        /// Processes packets concurrently, allowing for multiple packets
        /// to be handled simultaneously, potentially improving performance.
        /// </summary>
        Parallel
    }

    /// <summary>
    /// A class that manages UDP packet processing strategies based on the chosen mode.
    /// </summary>
    public class UDPProcessor
    {
        private UDP_ProcessMode processMode;

        public UDPProcessor(UDP_ProcessMode mode)
        {
            processMode = mode;
        }

        /// <summary>
        /// Starts processing the incoming UDP packets according to the specified mode.
        /// </summary>
        public void StartProcessing()
        {
            Console.WriteLine($"Starting UDP processing in '{processMode}' mode.");
            // Simulated packet reception
            for (int i = 0; i < 10; i++)
            {
                ProcessPacket(i);
            }
        }

        /// <summary>
        /// Processes a single UDP packet based on the current processing mode.
        /// </summary>
        /// <param name="packetId">The identifier of the packet to process.</param>
        private void ProcessPacket(int packetId)
        {
            if (processMode == UDP_ProcessMode.Sequential)
            {
                Console.WriteLine($"Processing packet {packetId} sequentially.");
                // Simulate processing delay
                System.Threading.Thread.Sleep(100);
            }
            else if (processMode == UDP_ProcessMode.Parallel)
            {
                // In a real implementation, this would likely involve a task or thread
                Console.WriteLine($"Processing packet {packetId} in parallel.");
                // Simulate processing with Task
                System.Threading.Tasks.Task.Run(() =>
                {
                    System.Threading.Thread.Sleep(100);
                    Console.WriteLine($"Packet {packetId} processed.");
                });
            }
        }
    }

