using System.IO;

public class ReadBlockStream : Stream
{
    private readonly Stream _stream;
    private long _position;

    public ReadBlockStream(Stream stream)
    {
        _stream = stream ?? throw new ArgumentNullException(nameof(stream));
        if (!_stream.CanRead)
            throw new ArgumentException("Stream must support reading.");
    }

    public override bool CanRead => true;

    public override bool CanSeek => false;

    public override bool CanWrite => false;

    public override long Length
    {
        get
        {
            return _stream.Length;
        }
    }

    public override long Position
    {
        get => _position;
        set => throw new NotSupportedException("Setting position is not supported.");
    }

    public override void Flush()
    {
        throw new NotSupportedException("Flushing is not supported.");
    }

    public override long Seek(long offset, SeekOrigin origin)
    {
        throw new NotSupportedException("Seeking is not supported.");
    }

    public override void SetLength(long value)
    {
        throw new NotSupportedException("Setting length is not supported.");
    }

    public override int Read(byte[] buffer, int offset, int count)
    {
        if (buffer == null) throw new ArgumentNullException(nameof(buffer));
        if (offset < 0 || count < 0 || offset + count > buffer.Length)
            throw new ArgumentOutOfRangeException();

        int totalBytesRead = 0;

        while (totalBytesRead < count)
        {
            int bytesRead = _stream.Read(buffer, offset + totalBytesRead, count - totalBytesRead);
            if (bytesRead == 0) break; // End of stream reached.

            totalBytesRead += bytesRead;
            _position += bytesRead;
        }

        return totalBytesRead;
    }

    public override void Write(byte[] buffer, int offset, int count)
    {
        throw new NotSupportedException("Writing is not supported.");
    }
}

