using System;
using System.Diagnostics;

namespace TextProcessing
{
    [DebuggerDisplay("{Value} ({Type}) [{FromColumn}-{ToColumn}]")]
    public class Token : IEquatable<Token>
    {
        private readonly string _value;
        private readonly int _fromColumn;

        public Token(string value, int fromColumn) : this(value, TokenType.Text, fromColumn) { }

        public Token(char value, int fromColumn) : this(value.ToString(), TokenType.Text, fromColumn) { }

        public Token(string value, TokenType type, int fromColumn)
        {
            _value = value ?? throw new ArgumentNullException(nameof(value));
            _fromColumn = fromColumn >= 0 ? fromColumn : throw new ArgumentOutOfRangeException(nameof(fromColumn));
            Type = type;
        }

        public string Value => _value;
        public TokenType Type { get; }
        public int FromColumn => _fromColumn;
        public int ToColumn => _fromColumn + _value.Length - 1;
        public int Length => _value.Length;
        public object Sentence { get; set; }

        public override string ToString() => _value;

        public static implicit operator string(Token token) => token?._value ?? string.Empty;

        public bool Equals(Token other) =>
            !(other is null) &&
            string.Equals(_value, other._value, StringComparison.OrdinalIgnoreCase) &&
            Type == other.Type;

        public override bool Equals(object obj) =>
            obj switch
            {
                Token t => Equals(t),
                string s => string.Equals(_value, s, StringComparison.OrdinalIgnoreCase),
                _ => false
            };

        public override int GetHashCode() =>
            HashCode.Combine(StringComparer.OrdinalIgnoreCase.GetHashCode(_value), Type);

        public static bool operator ==(Token left, Token right) =>
            ReferenceEquals(left, right) || (!(left is null) && left.Equals(right));

        public static bool operator !=(Token left, Token right) => !(left == right);
    }

    public enum TokenType
    {
        Text,
        Symbol,
        Numeric,
        Whitespace,
        Keyword,
        Identifier,
        Operator,
        Punctuation,
        Comment,
        StringLiteral,
        Boolean,
        Null
    }
}

