    public class DarkTextBox : TextBox
    {
        public struct ComponentInfo
        {
            public Color BackColor;
            public Color ForeColor;
            public float FontSize;
            public FontStyle Style;
        }

        private List<EventHandler> clickHandlers = new List<EventHandler>();

        public DarkTextBox()
        {
            InitializeDarkTheme();
        }

        public DarkTextBox(ComponentInfo info)
        {
            BackColor = info.BackColor;
            ForeColor = info.ForeColor;
            Font = new Font(Font.FontFamily, info.FontSize, info.Style);
        }

        private void InitializeDarkTheme()
        {
            BackColor = Color.FromArgb(30, 30, 30);
            ForeColor = Color.White;
            Font = new Font(Font.FontFamily, 12, FontStyle.Regular);
        }

        protected override void OnClick(EventArgs e)
        {
            base.OnClick(e);
            foreach (var handler in clickHandlers)
            {
                handler(this, e);
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            // Custom painting logic if needed
        }

        protected override void OnPaintBackground(PaintEventArgs e)
        {
            // Custom background painting logic if needed
        }

        protected override void OnGotFocus(EventArgs e)
        {
            base.OnGotFocus(e);
            // Change border or other focus indication
        }

        protected override void OnForeColorChanged(EventArgs e)
        {
            base.OnForeColorChanged(e);
            // Additional logic if needed when foreground color changes
        }

        public DarkTextBox clone(ComponentInfo info)
        {
            DarkTextBox newTextBox = new DarkTextBox(info);
            newTextBox.BackColor = BackColor;
            newTextBox.ForeColor = ForeColor;
            newTextBox.Font = Font;
            return newTextBox;
        }

        public void AddClickHandler(EventHandler handler)
        {
            clickHandlers.Add(handler);
        }

        public void RemoveClickHandler(EventHandler handler)
        {
            clickHandlers.Remove(handler);
        }
    }
}

using System;
using System.Collections.Generic;
using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;

public interface IOption<T> { bool HasValue { get; } }

public sealed class Some<T> : IOption<T>
{
    public T Value { get; }
    public Some(T value) { Value = value; }
    public bool HasValue => true;
}

public sealed class None<T> : IOption<T>
{
    public bool HasValue => false;
}

public static class Option
{
    public static IOption<T> Create<T>(T value) { return value != null ? new Some<T>(value) : new None<T>(); }
    public static IOption<U> Map<T, U>(this IOption<T> option, Func<T, U> mapper) { return option is Some<T> some ? Create(mapper(some.Value)) : new None<U>(); }
    public static IOption<U> FlatMap<T, U>(this IOption<T> option, Func<T, IOption<U>> mapper) { return option is Some<T> some ? mapper(some.Value) : new None<U>(); }
    public static R Match<T, R>(this IOption<T> option, Func<T, R> some, Func<R> none) { return option is Some<T> s ? some(s.Value) : none(); }
    public static T Get<T>(this IOption<T> option) { return option is Some<T> s ? s.Value : throw new InvalidOperationException("No value present"); }
    public static T GetOrElse<T>(this IOption<T> option, T alternative) { return option is Some<T> s ? s.Value : alternative; }
    public static IOption<T> OrElse<T>(this IOption<T> option, IOption<T> alternative) { return option is Some<T> ? option : alternative; }
    public static IEnumerable<T> ToEnumerable<T>(this IOption<T> option) { if (option is Some<T> s) yield return s.Value; }
}

