namespace CustomStreamWrapper
{
    public class FullBlockReadStream : Stream
    {
        private readonly Stream _baseStream;
        private long _position;
        public FullBlockReadStream(Stream baseStream)
        {
            if (baseStream == null)
                throw new ArgumentNullException(nameof(baseStream));
            if (!baseStream.CanRead)
                throw new ArgumentException("The provided stream must support reading.", nameof(baseStream));
            _baseStream = baseStream;
            _position = 0;
        }
        public override bool CanRead => true;
        public override bool CanSeek => false;
        public override bool CanWrite => false;
        public override long Length => throw new NotSupportedException("Length property is not supported.");
        public override long Position
        {
            get => _position;
            set => throw new NotSupportedException("Setting position is not supported.");
        }
        public override void Flush()
        {
            throw new NotSupportedException("Flush is not supported on a read-only stream.");
        }
        public override int Read(byte[] buffer, int offset, int count)
        {
            if (buffer == null)
                throw new ArgumentNullException(nameof(buffer));
            if (offset < 0 || offset >= buffer.Length)
                throw new ArgumentOutOfRangeException(nameof(offset));
            if (count < 0 || (offset + count) > buffer.Length)
                throw new ArgumentOutOfRangeException(nameof(count));
            int totalBytesRead = 0;
            while (totalBytesRead < count)
            {
                int bytesRead = _baseStream.Read(buffer, offset + totalBytesRead, count - totalBytesRead);
                if (bytesRead == 0)
                    break;
                totalBytesRead += bytesRead;
            }
            _position += totalBytesRead;
            Debug.WriteLine($"Read {totalBytesRead} bytes, new position: {_position}");
            return totalBytesRead;
        }
        public override long Seek(long offset, SeekOrigin origin)
        {
            throw new NotSupportedException("Seek is not supported.");
        }
        public override void SetLength(long value)
        {
            throw new NotSupportedException("SetLength is not supported.");
        }
        public override void Write(byte[] buffer, int offset, int count)
        {
            throw new NotSupportedException("Write is not supported.");
        }

