class Timer
{
    private static State mrb;

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);

        mrb = new State();

        // Define a C# function callable from Ruby
        DefineCliMethod(mrb, "greet", new Func<string, string>(Greet));

        // Execute Ruby code
        Do(mrb, @"
            a = [1, 2, 3, 4, 5]
            h = { name: 'Alice', age: 30 }
            puts greet('World')
            puts a.inspect
            puts h.inspect
        ");

        // Access Ruby objects
        var a = ToArray(mrb, Do(mrb, "a"));
        var h = ToDictionary(mrb, Do(mrb, "h"));

        // Output results to console
        Console.WriteLine("Array: " + string.Join(", ", a));
        Console.WriteLine("Hash: " + string.Join(", ", h.Select(kv => $"{kv.Key}: {kv.Value}")));

        // Display message box
        MessageBox.Show("Ruby array: " + string.Join(", ", a) + "\nRuby hash: " + string.Join(", ", h.Select(kv => $"{kv.Key}: {kv.Value}")));
    }

    static void DefineCliMethod(State mrb, string name, Delegate func)
    {
        var args = func.Method.GetParameters().Select(p => p.ParameterType).ToArray();
        var del = Delegate.CreateDelegate(typeof(Func<State, Value[], Value>), (Func<State, Value[], Value>)((mrb, args) =>
        {
            var convertedArgs = args.Select(arg => ConvertToCSharp(mrb, arg)).ToArray();
            var result = func.DynamicInvoke(convertedArgs);
            return ConvertToRuby(mrb, result);
        }));

        mrb.DefineCliMethod(name, del);
    }

    static Value Do(State mrb, string code)
    {
        return mrb.LoadString(code).Run();
    }

    static string ToString(State mrb, Value value)
    {
        return mrb.ToString(value);
    }

    static object[] ToArray(State mrb, Value value)
    {
        var array = new System.Collections.Generic.List<object>();
        var length = mrb.ArrayLen(value);
        for (int i = 0; i < length; i++)
        {
            array.Add(ConvertToCSharp(mrb, mrb.ArrayGet(value, i)));
        }
        return array.ToArray();
    }

