        var dict = new System.Collections.Generic.Dictionary<object, object>();
        var keys = mrb.HashKeys(value);
        foreach (var key in keys)
        {
            var k = ConvertToCSharp(mrb, key);

public class EqualityExpression : IExpression
{
    public RelationalExpression Left { get; private set; }
    public EqualityExpressionTail Tail { get; private set; }

    public EqualityExpression(TokenReader reader)
    {
        Left = new RelationalExpression(reader);
        Tail = ParseTail(reader);
    }

    private EqualityExpressionTail ParseTail(TokenReader reader)
    {
        if (!IsEqualityOperator(reader.Current))
            return null;

        var equalityOperator = reader.Current;
        reader.Advance();

        var rightExpression = new RelationalExpression(reader);
        var nextTail = ParseTail(reader);

        return new EqualityExpressionTail(
            equalityOperator,
            rightExpression,
            nextTail
        );
    }

    private bool IsEqualityOperator(Token token)
    {
        return token.Type == TokenType.EqualEqual ||
               token.Type == TokenType.NotEqual;
    }

    public ExpressionType Evaluate()
    {
        ExpressionType result = Left.Evaluate();

        if (Tail != null)
        {
            ExpressionType currentResult = result;
            var currentTail = Tail;

            while (currentTail != null)
            {
                var rightValue = currentTail.RightExpression.Evaluate();

                result = currentTail.Operator.Type == TokenType.EqualEqual
                    ? EvaluateEqualityComparison(currentResult, rightValue)
                    : EvaluateInequalityComparison(currentResult, rightValue);

                currentTail = currentTail.NextTail;
                currentResult = result;
            }
        }

        return result;
    }

    private ExpressionType EvaluateEqualityComparison(ExpressionType left, ExpressionType right)
    {
        return left.Equals(right)
            ? new BooleanExpressionType(true)
            : new BooleanExpressionType(false);
    }

    private ExpressionType EvaluateInequalityComparison(ExpressionType left, ExpressionType right)
    {
        return !left.Equals(right)
            ? new BooleanExpressionType(true)
            : new BooleanExpressionType(false);
    }
}

public class EqualityExpressionTail
{
    public Token Operator { get; private set; }
    public RelationalExpression RightExpression { get; private set; }
    public EqualityExpressionTail NextTail { get; private set; }

    public EqualityExpressionTail(
        Token equalityOperator,
        RelationalExpression rightExpression,
        EqualityExpressionTail nextTail = null)
    {
        Operator = equalityOperator;

