                environ["wsgi.run_once"] = false;
                environ["REQUEST_METHOD"] = request.HttpMethod;
                environ["SCRIPT_NAME"] = "";
                environ["PATH_INFO"] = request.Url.LocalPath;
                environ["QUERY_STRING"] = request.Url.Query;
                environ["CONTENT_TYPE"] = request.ContentType;
                environ["CONTENT_LENGTH"] = request.ContentLength;
                environ["SERVER_NAME"] = request.Url.Host;
                environ["SERVER_PORT"] = request.Url.Port;
                environ["SERVER_PROTOCOL"] = request.ProtocolVersion.ToString();
                environ["wsgi.input"] = request.InputStream;
