                {
                    environ["HTTP_" + header.Replace("-", "_").ToUpper()] = request.Headers[header];
                }
                var start_response = new Action<string, List<Tuple<string, string>>>(
                    (status, headers) =>
                    {
                        response.StatusCode = int.Parse(status.Split(' ')[0]);
                        response.StatusDescription = status.Split(' ')[1];

using System.Collections.Generic;
using UnityEngine;

public class ShipSpriteController : MonoBehaviour
{
    private Dictionary<Ship, GameObject> objectGameObjectMap = new Dictionary<Ship, GameObject>();
    private Transform parentTransform;

    void Awake()
    {
        parentTransform = new GameObject("ShipSprites").transform;
    }

    public void Subscribe(ShipManager shipManager)
    {
        shipManager.OnShipCreated += OnCreated;
        shipManager.OnShipChanged += OnChanged;
        shipManager.OnShipRemoved += OnRemoved;
    }

    private void OnCreated(Ship ship)
    {
        GameObject shipObject = new GameObject(ship.Name);
        SpriteRenderer spriteRenderer = shipObject.AddComponent<SpriteRenderer>();
        spriteRenderer.sprite = SpriteManager.Instance.GetShipSprite(ship.Type);
        spriteRenderer.sortingLayerName = "Ships";

        shipObject.transform.SetParent(parentTransform);
        UpdateShipPosition(shipObject.transform, ship.Position);

        objectGameObjectMap[ship] = shipObject;
    }

    private void OnChanged(Ship ship)
    {
        if (objectGameObjectMap.TryGetValue(ship, out GameObject shipObject))
        {
            SpriteRenderer spriteRenderer = shipObject.GetComponent<SpriteRenderer>();
            spriteRenderer.sprite = SpriteManager.Instance.GetShipSprite(ship.Type);
            UpdateShipPosition(shipObject.transform, ship.Position);
        }
    }

    private void OnRemoved(Ship ship)
    {
        if (objectGameObjectMap.TryGetValue(ship, out GameObject shipObject))
        {
            Destroy(shipObject);
            objectGameObjectMap.Remove(ship);
        }
    }

    private void UpdateShipPosition(Transform shipTransform, Vector3 position)
    {
        shipTransform.position = position;
    }

    private void OnDestroy()
    {
        if (objectGameObjectMap != null)
        {
            foreach (var keyValue in objectGameObjectMap)
            {
                Destroy(keyValue.Value);
            }
            objectGameObjectMap.Clear();
        }
    }
}

public class Ship
{
    public string Name { get; set; }
    public ShipType Type { get; set; }
    public Vector3 Position { get; set; }
}

