using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Product
{
    class Handler
    {
        static void Main(string[] args)
        {
            var input = "3 4 2 * 1 5 - 2 3 ^ ^ / +";
            Console.WriteLine("For postfix {0}", input);
            Console.WriteLine("\nToken            Action            Stack");
            var stack = new List<double>();
            foreach (var tok in input.Split(' '))
            {
                var action = "Apply op to top of stack";
                switch (tok)
                {
                    case "+":
                        stack[stack.Count - 2] += stack[stack.Count - 1];
                        stack.RemoveAt(stack.Count - 1);
                        break;
                    case "-":
                        stack[stack.Count - 2] -= stack[stack.Count - 1];
                        stack.RemoveAt(stack.Count - 1);
                        break;
                    case "*":
                        stack[stack.Count - 2] *= stack[stack.Count - 1];
                        stack.RemoveAt(stack.Count - 1);
                        break;
                    case "/":
                        stack[stack.Count - 2] /= stack[stack.Count - 1];
                        stack.RemoveAt(stack.Count - 1);
                        break;
                    case "^":
                        stack[stack.Count - 2] = Math.Pow(stack[stack.Count - 2], stack[stack.Count - 1]);
                        stack.RemoveAt(stack.Count - 1);
                        break;
                    default:
                        action = "Push num onto top of stack";
                        stack.Add(double.Parse(tok));
                        break;
                }
                Console.WriteLine("{0,3}    {1,-26}  {2}", tok, action, string.Join(",", stack));
            }
            Console.WriteLine("\nThe final value is {0}", stack[0]);
        }
    }
}

using Microsoft.Azure.Batch;

public class ListTaskFileOptions : TaskOperationOptions
{
    // Property to specify the name of a single task file to retrieve
    public string TaskFileName { get; set; }

    // Property to represent an OData filter for querying task files
    public string Filter { get; set; }

    // Property to limit the number of task files returned
    public int? MaxCount { get; set; }

    // Property to determine whether to perform a recursive search for files
    public bool Recursive { get; set; }

    // Constructor to initialize the class with context and task-related parameters
    public ListTaskFileOptions(string jobId, string taskId, string taskFileName = null, string filter = null, int? maxCount = null, bool recursive = false)
        : base(jobId, taskId)
    {
        TaskFileName = taskFileName;
        Filter = filter;
        MaxCount = maxCount;
        Recursive = recursive;
    }

    // Method to validate the options before executing the query
    public void Validate()
    {
        if (string.IsNullOrEmpty(JobId))
        {
            throw new ArgumentException("JobId cannot be null or empty.");
        }

        if (string.IsNullOrEmpty(TaskId))
        {
            throw new ArgumentException("TaskId cannot be null or empty.");
        }

        if (MaxCount.HasValue && MaxCount.Value <= 0)
        {
            throw new ArgumentException("MaxCount must be greater than zero.");
        }
    }

    // Method to generate the OData query string based on the provided options
    public string GenerateODataQuery()
    {
        var queryParameters = new List<string>();

        if (!string.IsNullOrEmpty(Filter))
        {
            queryParameters.Add($"$filter={Filter}");
        }

        if (MaxCount.HasValue)
        {
            queryParameters.Add($"$top={MaxCount.Value}");
        }

        return queryParameters.Any() ? string.Join("&", queryParameters) : null;
    }
}

using System;
using System.Linq.Expressions;

using Vulpecula.Scripting.Lexer;

namespace Vulpecula.Scripting.Parser.Expressions
{
    // Parsing Script
    // RelationalExpression
    // EqualityExpression "==" RelationalExpression
    // EqualityExpression "!=" RelationalExpression
    internal class EqualityExpression : ExpressionBase
    {

        public override void Parse(TokenReader reader)
        {
            if (!VerifyAheadKeywords(reader, "==", "!="))
            {
                // Relational
                var expr1 = new RelationalExpression();
                expr1.Parse(reader);
                Children.Add(expr1);
            }
            else
            {
                // -> EqualityTail
                var expr2 = new EqualityExpressionTail();
                expr2.Parse(reader);
                Children.Add(expr2);
            }
        }

        public override Expression AsExpressionTree()
        {
            throw new NotImplementedException();
        }

    }

    // "==" RelationalExpression EqualityExpressionTail
    // "!=" RelationalExpression EqualityExpressionTail
    internal class EqualityExpressionTail : ExpressionBase
    {
        private int _type = 0;

        public override void Parse(TokenReader reader)
        {
            var token = AssertKeywordOr(reader, "==", "!=");
            _type = token.TokenString == "==" ? 0 : 1;

            // Relational
            var expr1 = new RelationalExpression();
            expr1.Parse(reader);
            Children.Add(expr1);

            // EqualityTail
            var expr2 = new EqualityExpressionTail();
            expr2.Parse(reader);
            Children.Add(expr2);
        }

        public override Expression AsExpressionTree()
        {
            throw new NotImplementedException();
        }

    }
}

using System;
using System.Collections.Generic;

using NCrawler.HtmlProcessor;
using NCrawler.Interfaces;

namespace NCrawler.Demo
{
    public class IndexerDemo : IPipelineStep
    {

        public void Process(Crawler crawler, PropertyBag propertyBag)
        {
            string textContent = propertyBag.Text; // Filtered text content

            // Here you can send downloaded filtered content to an index, database, filesystem or whatever
            Console.Out.WriteLine(textContent);
        }

        public static void Run()
        {
            NCrawlerModule.Setup();
            Console.Out.WriteLine("\nSimple indexer demo");

            // Setup crawler to crawl/index http://ncrawler.codeplex.com
            //  * Step 1 - The Html Processor, parses and extracts links, text and more from html
            //  * Step 2 - Custom step, that is supposed to send content to an Index or Database
            using (Crawler c = new Crawler(new Uri("http://ncrawler.codeplex.com"),
                new HtmlDocumentProcessor( // Process html, filter links and content
                // Setup filter that removed all the text between <body and </body>
                // This can be custom tags like <!--BeginTextFiler--> and <!--EndTextFiler-->
                // or whatever you prefer. This way you can control what text is extracted on every page
                // Most cases you want just to filter the header information or menu text
                    new Dictionary<string, string>
                        {
                            {"<body", "</body>"}
                        },
                // Setup filter that tells the crawler not to follow links between tags
                // that start with <head and ends with </head>. This can be custom tags like
                // <!--BeginNoFollow--> and <!--EndNoFollow--> or whatever you prefer.
                // This was you can control what links the crawler should not follow
                    new Dictionary<string, string>
                        {
                            {"<head", "</head>"}
                        }),
                new IndexerDemo())
                {
                    MaximumThreadCount = 2
                }) // Custom Step to send filtered content to index
            {
                // Begin crawl
                c.Crawl();
            }
        }

    }
}

using System;
using System.ComponentModel.DataAnnotations;
using System.Threading.Tasks;
using CorePoker.Data;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace CorePoker.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    public class TableController : ControllerBase
    {
        private readonly CorePokerContext db;

        public TableController(CorePokerContext db)
        {
            this.db = db;
        }

        public class TablePayload
        {
            [Required]
            public string Name { get; set; }
            [Required]
            public string PlayerName { get; set; }
        }

        [HttpGet("{id}")]
        public async Task<IActionResult> Get(string id)
        {
            var table = await db.Tables.FirstOrDefaultAsync(t => t.PublicId == id);
            if (table == null)
            {
                return NotFound();
            }

            return Ok(table);
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody]TablePayload table)
        {
            var player = await db.Players.FirstOrDefaultAsync(p => p.Nickname == table.PlayerName);

            if (player == null)
            {
                return NotFound("Player not found");
            }

            var newTable = new Table
            {
                Name = table.Name,
                Owner = player,
                PublicId = Guid.NewGuid().ToString()
            };

            newTable.TablePlayers.Add(new TablePlayer { Player = player });
            db.Tables.Add(newTable);
            await db.SaveChangesAsync();

            return Ok(newTable.PublicId);
        }
    }
}

using System;
using System.Linq;

namespace ClosedXML.Excel
{
    using System.Collections.Generic;

    internal class XLFilterColumn : IXLFilterColumn
    {
        private readonly XLAutoFilter _autoFilter;
        private readonly Int32 _column;

        public XLFilterColumn(XLAutoFilter autoFilter, Int32 column)
        {
            _autoFilter = autoFilter;
            _column = column;
        }

        public void Clear()
        {
            if (_autoFilter.Filters.ContainsKey(_column))
                _autoFilter.Filters.Remove(_column);
        }

        public IXLFilteredColumn AddFilter<T>(T value) where T : IComparable<T>
        {
            if (typeof(T) == typeof(String))
            {
                ApplyCustomFilter(value, XLFilterOperator.Equal,
                                  v =>
                                  v.ToString().Equals(value.ToString(), StringComparison.InvariantCultureIgnoreCase),
                                  XLFilterType.Regular);
            }
            else
            {
                ApplyCustomFilter(value, XLFilterOperator.Equal,
                                  v => v.CastTo<T>().CompareTo(value) == 0, XLFilterType.Regular);
            }
            return new XLFilteredColumn(_autoFilter, _column);
        }

        public IXLDateTimeGroupFilteredColumn AddDateGroupFilter(DateTime date, XLDateTimeGrouping dateTimeGrouping)
        {
            Func<Object, Boolean> condition = date2 => XLDateTimeGroupFilteredColumn.IsMatch(date, (DateTime)date2, dateTimeGrouping);

            _autoFilter.Enabled = true;

            if (_autoFilter.Filters.TryGetValue(_column, out List<XLFilter> filterList))
                filterList.Add(
                    new XLFilter
                    {
                        Value = date,
                        Operator = XLFilterOperator.Equal,
                        Connector = XLConnector.Or,
                        Condition = condition,
                        DateTimeGrouping = dateTimeGrouping
                    }
                );
            else
            {
                _autoFilter.Filters.Add(
                    _column,
                    new List<XLFilter>
                    {
                        new XLFilter
                        {
                            Value = date,
                            Operator = XLFilterOperator.Equal,
                            Connector = XLConnector.Or,
                            Condition = condition,
                            DateTimeGrouping = dateTimeGrouping
                        }

using System;
using System.Data;
using System.Linq;
using Afrodite.Abstract;
using Afrodite.Common;
using CsvHelper;
using System.Collections.Generic;
using Afrodite.Concrete;

namespace Afrodite.Concrete
{
    public class DatabaseStateLogger<T> : IStateLogger<T>, IDisposable
    {
        private readonly IDbConnection connection;
        private IComponentState<T> state;
        private IDbCommand cmd;
        private IDbDataParameter param;

        public DatabaseStateLogger(IDbConnection connection)
        {
            this.connection = connection;
        }

        public void SaveState<T1>(IComponentState<T1> state)
        {
            if (!connection.TableExists("ComponentState"))
            {
                return;
            }

            using (this.cmd = connection.CreateCommand())
            {
                cmd.CommandText =
                    @"INSERT INTO ComponentState (MachineId, CpuUsage, AvailableMemory, FreeDiskSpace, Time)
                      VALUES (@MachineId, @CpuUsage, @AvailableMemory, @FreeDiskSpace, @Time)";

                this.param = cmd.CreateParameter();
                param.ParameterName = "@MachineId";
                param.Value = state.MachineId;
                cmd.Parameters.Add(param);

                param = cmd.CreateParameter();
                param.ParameterName = "@CpuUsage";
                param.Value = state.CpuUsage;
                cmd.Parameters.Add(param);

                param = cmd.CreateParameter();
                param.ParameterName = "@AvailableMemory";
                param.Value = state.AvailableMemory;
                cmd.Parameters.Add(param);

                param = cmd.CreateParameter();
                param.ParameterName = "@FreeDiskSpace";
                param.Value = state.FreeDiskSpace;
                cmd.Parameters.Add(param);

                param = cmd.CreateParameter();
                param.ParameterName = "@Time";
                param.Value = state.Time;
                cmd.Parameters.Add(param);

                cmd.ExecuteNonQuery();
            }
        }

        public IEnumerable<IComponentState<T>> GetAllStates()
        {
            throw new NotImplementedException();
        }

        public void Dispose()
        {
            connection?.Dispose();
        }
    }
}
